export default function HolidaysPage() {
  const { t } = useTranslation();
  const user = useAuthUser();
  const organizationId = useSelectedOrganization() as Id<'organizations'> | undefined;

  const [showCreate, setShowCreate] = useState(false);
  const [editingHoliday, setEditingHoliday] = useState<Doc<'holidays'> | null>(null);
  const [form, setForm] = useState({
    name: '',
    date: '',
    type: 'public' as 'public' | 'internal',
    isRecurring: false,
    description: '',
  });

  const holidays = useQuery(
    api.leaveSettings.getHolidays,
    organizationId ? { organizationId } : 'skip',
  );
  const createHoliday = useMutation(api.leaveSettings.createHoliday);
  const updateHoliday = useMutation(api.leaveSettings.updateHoliday);
  const deleteHoliday = useMutation(api.leaveSettings.deleteHoliday);

  if (!organizationId || !user) return <ShieldLoader />;

  const resetForm = () => {
    setForm({ name: '', date: '', type: 'public', isRecurring: false, description: '' });
    setEditingHoliday(null);
  };

  const handleSubmit = async () => {
    if (!form.name || !form.date) {
      toast.error(t('admin.holidays.required', 'Name and date are required'));
      return;
    }
    try {
      if (editingHoliday) {
        await updateHoliday({
          holidayId: editingHoliday._id,
          name: form.name,
          date: form.date,
          type: form.type,
          isRecurring: form.isRecurring,
          description: form.description || undefined,
        });
        toast.success(t('admin.holidays.updated', 'Holiday updated'));
      } else {
        await createHoliday({
          organizationId,
          name: form.name,
          date: form.date,
          type: form.type,
          isRecurring: form.isRecurring,
          description: form.description || undefined,
        });
        toast.success(t('admin.holidays.created', 'Holiday created'));
      }
      resetForm();
      setShowCreate(false);
    } catch (e) {
      toast.error(String(e));
    }
  };

  const handleEdit = (holiday: Doc<'holidays'>) => {
    setEditingHoliday(holiday);
    setForm({
      name: holiday.name,
      date: holiday.date,
      type: holiday.type,
      isRecurring: holiday.isRecurring,
      description: holiday.description || '',
    });
    setShowCreate(true);
  };

  const handleDelete = async (holidayId: Id<'holidays'>) => {
    try {
      await deleteHoliday({ holidayId });
      toast.success(t('admin.holidays.deleted', 'Holiday deleted'));
    } catch (e) {
      toast.error(String(e));
    }
  };

  const groupedHolidays = {
    public: holidays?.filter((h) => h.type === 'public') ?? [],
    internal: holidays?.filter((h) => h.type === 'internal') ?? [],
  };

  return (
    <div className="space-y-6">
      <div className="sticky top-0 z-10 -mx-4 sm:-mx-6 lg:-mx-8 px-4 sm:px-6 lg:px-8 py-4 bg-(--background)/95 backdrop-blur border-b border-(--border) flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">{t('admin.holidays.title', 'Holiday Management')}</h1>
          <p className="text-sm text-(--text-muted) mt-1">
            {t('admin.holidays.subtitle', 'Manage public holidays and internal non-working days')}
          </p>
        </div>
        <Button
          onClick={() => {
            resetForm();
            setShowCreate(true);
          }}
        >
          <Plus className="w-4 h-4 mr-1" /> {t('admin.holidays.add', 'Add Holiday')}
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Public Holidays */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <span>🏛️</span> {t('admin.holidays.public', 'Public Holidays')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {groupedHolidays.public.length === 0 ? (
              <p className="text-sm text-(--text-muted) text-center py-8">
                {t('admin.holidays.noHolidays', 'No public holidays configured')}
              </p>
            ) : (
              <div className="space-y-2">
                {groupedHolidays.public.map((h) => (
                  <div
                    key={h._id}
                    className="flex items-center justify-between p-3 rounded-xl bg-(--background-subtle) border border-(--border)"
                  >
                    <div>
                      <p className="font-medium text-sm">{h.name}</p>
                      <p className="text-xs text-(--text-muted)">
                        {new Date(h.date).toLocaleDateString()}
                        {h.isRecurring && ` (${t('admin.holidays.recurring', 'Recurring')})`}
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button size="icon-sm" variant="ghost" onClick={() => handleEdit(h)}>
                        <Pencil className="w-4 h-4" />
                      </Button>
                      <Button
                        size="icon-sm"
                        variant="ghost"
                        className="text-red-500"
                        onClick={() => handleDelete(h._id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Internal Holidays */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <span>🏢</span> {t('admin.holidays.internal', 'Internal Non-Working Days')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {groupedHolidays.internal.length === 0 ? (
              <p className="text-sm text-(--text-muted) text-center py-8">
                {t('admin.holidays.noInternal', 'No internal non-working days configured')}
              </p>
            ) : (
              <div className="space-y-2">
                {groupedHolidays.internal.map((h) => (
                  <div
                    key={h._id}
                    className="flex items-center justify-between p-3 rounded-xl bg-(--background-subtle) border border-(--border)"
                  >
                    <div>
                      <p className="font-medium text-sm">{h.name}</p>
                      <p className="text-xs text-(--text-muted)">
                        {new Date(h.date).toLocaleDateString()}
                        {h.isRecurring && ` (${t('admin.holidays.recurring', 'Recurring')})`}
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button size="icon-sm" variant="ghost" onClick={() => handleEdit(h)}>
                        <Pencil className="w-4 h-4" />
                      </Button>
                      <Button
                        size="icon-sm"
                        variant="ghost"
                        className="text-red-500"
                        onClick={() => handleDelete(h._id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Create/Edit Dialog */}
      <Dialog open={showCreate} onOpenChange={setShowCreate}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>
              {editingHoliday
                ? t('admin.holidays.edit', 'Edit Holiday')
                : t('admin.holidays.create', 'Create Holiday')}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>{t('admin.holidays.name', 'Holiday Name')}</Label>
              <Input
                value={form.name}
                onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
              />
            </div>
            <div>
              <Label>{t('admin.holidays.date', 'Date')}</Label>
              <Input
                type="date"
                value={form.date}
                onChange={(e) => setForm((p) => ({ ...p, date: e.target.value }))}
              />
            </div>
            <div>
              <Label>{t('admin.holidays.type', 'Type')}</Label>
              <Select
                value={form.type}
                onValueChange={(v) => setForm((p) => ({ ...p, type: v as 'public' | 'internal' }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="public">
                    {t('admin.holidays.public', 'Public Holiday')}
                  </SelectItem>
                  <SelectItem value="internal">
                    {t('admin.holidays.internal', 'Internal Non-Working Day')}
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex items-center gap-2">
              <Switch
                checked={form.isRecurring}
                onCheckedChange={(v) => setForm((p) => ({ ...p, isRecurring: v }))}
              />
              <Label>{t('admin.holidays.recurring', 'Recurring yearly')}</Label>
            </div>
            <div>
              <Label>{t('admin.holidays.description', 'Description (optional)')}</Label>
              <Input
                value={form.description}
                onChange={(e) => setForm((p) => ({ ...p, description: e.target.value }))}
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  resetForm();
                  setShowCreate(false);
                }}
              >
                {t('common.cancel', 'Cancel')}
              </Button>
              <Button onClick={handleSubmit}>
                {editingHoliday ? t('common.save', 'Save') : t('common.create', 'Create')}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation } from '@/lib/convex-typed';
import { api } from '../../../../../convex/_generated/api';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import { useAuthUser } from '@/store/useAuthStore';
import type { Doc, Id } from '../../../../../convex/_generated/dataModel';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { toast } from 'sonner';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Search, Pencil } from 'lucide-react';

interface EmployeeBalance {
  _id: string;
  name: string;
  email: string;
  department?: string;
  position?: string;
  employeeType?: string;
  balances: Record<string, number>;
}

type BalanceKey =
  | 'paidLeaveBalance'
  | 'sickLeaveBalance'
  | 'familyLeaveBalance'
  | 'dayOffBalance'
  | 'studyLeaveBalance'
  | 'maternityLeaveBalance';

const BALANCE_FIELDS: {
  key: BalanceKey;
  labelKey: string;
  label: string;
  icon: string;
  color: string;
}[] = [
  {
    key: 'paidLeaveBalance',
    labelKey: 'leaveTypes.paid',
    label: 'Paid Vacation',
    icon: '💰',
    color: '#2563eb',
  },
  {
    key: 'sickLeaveBalance',
    labelKey: 'leaveTypes.sick',
    label: 'Sick Leave',
    icon: '🤒',
    color: '#ef4444',
  },
  {
    key: 'familyLeaveBalance',
    labelKey: 'leaveTypes.family',
    label: 'Family Leave',
    icon: '👨‍👩‍👧‍👦',
    color: '#10b981',
  },
  {
    key: 'dayOffBalance',
    labelKey: 'leaveTypes.day_off',
    label: 'Day Off',
    icon: '🎯',
    color: '#8b5cf6',
  },
  {
    key: 'studyLeaveBalance',
    labelKey: 'leaveTypes.study',
    label: 'Study Leave',
    icon: '📚',
    color: '#a855f7',
  },
  {
    key: 'maternityLeaveBalance',
    labelKey: 'leaveTypes.maternity',
    label: 'Maternity Leave',
    icon: '👶',
    color: '#ec4899',
  },
];

export default function LeaveBalancesPage() {
  const { t } = useTranslation();
  const user = useAuthUser();
  const organizationId = useSelectedOrganization() as Id<'organizations'> | undefined;

  const [search, setSearch] = useState('');
  const [editingEmployee, setEditingEmployee] = useState<EmployeeBalance | null>(null);
  const [editBalances, setEditBalances] = useState<Record<string, number>>({});
  const [editReason, setEditReason] = useState('');
  const [saving, setSaving] = useState(false);

  const employees = useQuery(
    api.leaveSettings.getEmployeeLeaveBalances,
    organizationId ? { organizationId } : 'skip',
  );
  const updateBalance = useMutation(api.leaveSettings.updateLeaveBalance);

  if (!organizationId || !user) return <ShieldLoader />;

  const filtered =
    employees?.filter(
      (e) =>
        e.name.toLowerCase().includes(search.toLowerCase()) ||
        e.email.toLowerCase().includes(search.toLowerCase()),
    ) ?? [];

  const handleEditEmployee = (emp: EmployeeBalance) => {
    setEditingEmployee(emp);
    setEditBalances({ ...emp.balances });
    setEditReason('');
  };

  const handleSaveBalances = async () => {
    if (!editingEmployee || !editReason.trim()) {
      toast.error(
        t('admin.leaveBalances.reasonRequired', 'Please provide a reason for the adjustment'),
      );
      return;
    }
    // Validate everything before writing so we never apply a partial update.
    const changes: { key: BalanceKey; value: number }[] = [];
    for (const field of BALANCE_FIELDS) {
      const newValue = editBalances[field.key];
      const oldValue = editingEmployee.balances[field.key] ?? 0;
      if (newValue === undefined || !Number.isFinite(newValue)) {
        toast.error(t('admin.leaveBalances.invalid', 'Balances must be valid numbers'));
        return;
      }
      if (newValue < 0) {
        toast.error(t('admin.leaveBalances.negative', 'Balances cannot be negative'));
        return;
      }
      if (newValue !== oldValue) changes.push({ key: field.key, value: newValue });
    }
    if (changes.length === 0) {
      setEditingEmployee(null);
      return;
    }

    setSaving(true);
    try {
      for (const change of changes) {
        await updateBalance({
          userId: editingEmployee._id as Id<'users'>,
          field: change.key,
          value: change.value,
          reason: editReason,
        });
      }
      toast.success(t('admin.leaveBalances.saved', 'Balances updated successfully'));
      setEditingEmployee(null);
    } catch (e) {
      toast.error(String(e));
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="sticky top-0 z-10 -mx-4 sm:-mx-6 lg:-mx-8 px-4 sm:px-6 lg:px-8 py-4 bg-(--background)/95 backdrop-blur border-b border-(--border)">
        <h1 className="text-2xl font-bold">{t('admin.leaveBalances.title', 'Leave Balances')}</h1>
        <p className="text-sm text-(--text-muted) mt-1">
          {t('admin.leaveBalances.subtitle', 'View and edit employee leave balances')}
        </p>
        <div className="relative mt-3 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-(--text-muted)" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={t('common.search', 'Search employees...')}
            className="pl-9"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 gap-3">
        {filtered.map((emp) => (
          <Card key={emp._id} className="hover:shadow-sm transition-shadow">
            <CardContent className="p-4">
              <div className="flex items-center justify-between mb-3">
                <div>
                  <p className="font-medium">{emp.name}</p>
                  <p className="text-xs text-(--text-muted)">
                    {emp.department || emp.position
                      ? `${emp.department ?? ''} ${emp.position ?? ''}`.trim()
                      : emp.email}
                    <Badge variant="outline" className="ml-2 text-[10px]">
                      {emp.employeeType}
                    </Badge>
                  </p>
                </div>
                <Button size="sm" variant="outline" onClick={() => handleEditEmployee(emp)}>
                  <Pencil className="w-4 h-4 mr-1" /> {t('common.edit', 'Edit')}
                </Button>
              </div>
              <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
                {BALANCE_FIELDS.map((bf) => (
                  <div key={bf.key} className="text-center p-2 rounded-lg bg-(--background-subtle)">
                    <p className="text-lg font-bold" style={{ color: bf.color }}>
                      {emp.balances[bf.key] ?? 0}
                    </p>
                    <p className="text-[10px] text-(--text-muted) truncate">
                      {t(bf.labelKey, bf.label)}
                    </p>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        ))}
        {filtered.length === 0 && (
          <p className="text-center text-(--text-muted) py-12">
            {t('admin.leaveBalances.noEmployees', 'No employees found')}
          </p>
        )}
      </div>

      {/* Edit Dialog */}
      <Dialog open={!!editingEmployee} onOpenChange={() => setEditingEmployee(null)}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>
              {t('admin.leaveBalances.editTitle', 'Edit Balances')} — {editingEmployee?.name}
            </DialogTitle>
          </DialogHeader>
          {editingEmployee && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                {BALANCE_FIELDS.map((bf) => (
                  <div key={bf.key}>
                    <Label className="text-xs flex items-center gap-1">
                      <span>{bf.icon}</span> {t(bf.labelKey, bf.label)}
                    </Label>
                    <Input
                      type="number"
                      min={0}
                      value={editBalances[bf.key] ?? 0}
                      onChange={(e) =>
                        setEditBalances((prev) => ({
                          ...prev,
                          [bf.key]: Number(e.target.value),
                        }))
                      }
                      className="mt-1"
                      style={{ borderColor: bf.color }}
                    />
                  </div>
                ))}
              </div>
              <div>
                <Label>{t('admin.leaveBalances.reason', 'Reason for adjustment *')}</Label>
                <Textarea
                  value={editReason}
                  onChange={(e) => setEditReason(e.target.value)}
                  placeholder={t(
                    'admin.leaveBalances.reasonPlaceholder',
                    'e.g. Annual balance accrual, correction',
                  )}
                  rows={2}
                  className="mt-1"
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button
                  variant="outline"
                  disabled={saving}
                  onClick={() => setEditingEmployee(null)}
                >
                  {t('common.cancel', 'Cancel')}
                </Button>
                <Button onClick={handleSaveBalances} disabled={saving || !editReason.trim()}>
                  {saving ? t('common.saving', 'Saving...') : t('common.save', 'Save Changes')}
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

