                      <Icon className="w-4 h-4 sm:w-5 sm:h-5" />
                    </div>
                    <div className="flex-1 sm:hidden">
                      <div className="flex items-center justify-between">
                        <span
                          className="font-semibold text-sm"
                          style={{ color: 'var(--text-primary)' }}
