                        />
                      </div>
                    </div>
                  </div>
                  <div className="flex-1 w-full sm:w-auto">
                    <div className="hidden sm:flex items-center gap-2 mb-1">
                      <span className="font-semibold" style={{ color: 'var(--text-primary)' }}>
                        {t(feature.titleKey)}
                      </span>
                      {feature.critical && (
                        <span
                          className="text-xs px-2 py-0.5 rounded"
                          style={{ background: 'rgba(37,99,235,0.12)', color: 'var(--primary)' }}
                        >
                          {t('superadmin.security.criticalBadge')}
                        </span>
                      )}
                      {!enabled && (
                        <span
                          className="text-xs px-2 py-0.5 rounded"
                          style={{ background: 'var(--muted)', color: 'var(--text-muted)' }}
                        >
                          {t('superadmin.security.disable')}
                        </span>
                      )}
                    </div>
                    <div className="flex sm:hidden items-center gap-2 mb-2">
                      {feature.critical && (
                        <span
                          className="text-xs px-2 py-0.5 rounded"
                          style={{ background: 'rgba(37,99,235,0.12)', color: 'var(--primary)' }}
                        >
                          {t('superadmin.security.criticalBadge')}
                        </span>
                      )}
                      {!enabled && (
                        <span
                          className="text-xs px-2 py-0.5 rounded"
                          style={{ background: 'var(--muted)', color: 'var(--text-muted)' }}
                        >
                          {t('superadmin.security.disable')}
                        </span>
                      )}
                    </div>
                    <p className="text-xs sm:text-sm" style={{ color: 'var(--text-muted)' }}>
                      {t(feature.descKey)}
                    </p>
                    {savedAt && (
                      <p
                        className="text-[10px] sm:text-xs mt-1"
                        style={{ color: 'var(--text-disabled)' }}
                      >
                        Last changed: {new Date(savedAt).toLocaleString()}
                      </p>
                    )}
                  </div>
                  <div className="hidden sm:flex items-center gap-3 shrink-0">
                    <span
                      className="text-sm font-medium"
                      style={{ color: enabled ? 'var(--success)' : 'var(--text-disabled)' }}
                    >
                      {enabled ? 'ON' : 'OFF'}
                    </span>
                    <Toggle
                      enabled={enabled}
                      onToggle={() => handleToggle(feature.key, enabled)}
                      loading={isLoading}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* ── TAB: Blocked Users ── */}
        {activeTab === 'blocked' && (
          <div>
            <p className="text-sm mb-4" style={{ color: 'var(--text-muted)' }}>
              {t('superadmin.security.currentlySuspendedUsers')}
            </p>
            {!suspendedUsers?.length ? (
              <div className="text-center py-16" style={{ color: 'var(--text-muted)' }}>
                <ShieldCheck
                  className="w-12 h-12 mx-auto mb-3"
                  style={{ color: 'var(--success)' }}
                />
                {t('superadmin.security.noSuspendedUsers')}
              </div>
            ) : (
              <div className="space-y-3">
                {suspendedUsers.map((user) => {
                  const isAutoBlocked = user.suspendedReason?.includes('AUTO-BLOCKED');
                  const hoursLeft = Math.max(
                    0,
                    Math.ceil((user.suspendedUntil! - Date.now()) / (1000 * 60 * 60)),
                  );

                  return (
                    <div
                      key={user._id}
                      className="rounded-lg sm:rounded-xl p-3 sm:p-5 border hover:shadow-md transition-all cursor-pointer"
                      style={{ background: 'var(--card)', borderColor: 'var(--border)' }}
                      onClick={() => router.push(`/superadmin/security/alert/${user._id}`)}
                    >
                      <div className="flex flex-col sm:flex-row items-start justify-between gap-3">
                        <div className="flex items-start gap-4 flex-1">
                          {/* Avatar */}
                          <div className="shrink-0">
                            {user.avatarUrl ? (
                              <img
                                src={user.avatarUrl}
                                alt={user.name}
                                className="w-10 h-10 sm:w-12 sm:h-12 rounded-full"
                              />
                            ) : (
                              <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-linear-to-br from-red-500 to-orange-600 flex items-center justify-center text-white text-base sm:text-lg font-bold">
                                {user.name.charAt(0)}
                              </div>
                            )}
                          </div>

                          {/* User Info */}
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1 flex-wrap">
                              <h3
                                className="font-semibold text-base sm:text-lg"
                                style={{ color: 'var(--text-primary)' }}
                              >
                                {user.name}
                              </h3>
                              {isAutoBlocked && (
                                <span className="text-[10px] sm:text-xs font-bold bg-red-600 text-white px-1.5 sm:px-2 py-0.5 rounded">
                                  AUTO-BLOCKED
                                </span>
                              )}
                            </div>
                            <p
                              className="text-xs sm:text-sm mb-2"
                              style={{ color: 'var(--text-muted)' }}
                            >
                              {user.email} • {user.role}
                            </p>

                            <div className="space-y-1 text-xs sm:text-sm">
                              <p style={{ color: 'var(--text-muted)' }}>
                                <span
                                  className="font-medium"
                                  style={{ color: 'var(--text-primary)' }}
                                >
                                  {t('superadmin.security.reason')}:
                                </span>{' '}
                                {user.suspendedReason}
                              </p>
                              <div
                                className="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-4 text-[10px] sm:text-xs"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                <span>
                                  <Clock className="w-3 h-3 inline mr-1" />
                                  Expires in {hoursLeft}h
                                </span>
                                <span className="hidden sm:inline">
                                  Until{' '}
                                  {user.suspendedUntil
                                    ? new Date(user.suspendedUntil).toLocaleString()
                                    : ''}
                                </span>
                              </div>
                            </div>
                          </div>
                        </div>

                        {/* Action Button */}
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            router.push(`/superadmin/security/alert/${user._id}`);
                          }}
                          className="px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg font-medium text-xs sm:text-sm transition-colors flex items-center gap-1 sm:gap-2 w-full sm:w-auto justify-center"
                          style={{
                            background: 'rgba(37,99,235,0.1)',
                            color: 'var(--primary)',
                          }}
                        >
                          <span className="hidden sm:inline">
                            {t('superadmin.security.reviewAndUnsuspend')}
                          </span>
                          <span className="sm:hidden">{t('superadmin.security.review')}</span>
                          <ChevronRight className="w-3 h-3 sm:w-4 sm:h-4" />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ── TAB: Login Attempts ── */}
        {activeTab === 'attempts' && (
          <div>
            <p className="text-sm mb-4" style={{ color: 'var(--text-muted)' }}>
              {t('superadmin.security.recentSuspiciousLogins')}
            </p>
            {!loginStats?.suspicious?.length ? (
              <div className="text-center py-16" style={{ color: 'var(--text-muted)' }}>
                <ShieldCheck
                  className="w-12 h-12 mx-auto mb-3"
                  style={{ color: 'var(--success)' }}
                />
                {t('superadmin.security.noSuspiciousActivity')}
              </div>
            ) : (
              <div className="space-y-2">
                {loginStats.suspicious.map((attempt, i: number) => (
                  <div
                    key={i}
                    className="rounded-lg p-3 sm:p-4 flex flex-col sm:flex-row items-start sm:items-center gap-3 sm:gap-4 border"
                    style={{ background: 'var(--card)', borderColor: 'var(--border)' }}
                  >
                    <div className="shrink-0">
                      {attempt.success ? (
                        <CheckCircle
                          className="w-4 h-4 sm:w-5 sm:h-5"
                          style={{ color: 'var(--success)' }}
                        />
                      ) : (
                        <XCircle
                          className="w-4 h-4 sm:w-5 sm:h-5"
                          style={{ color: 'var(--destructive)' }}
                        />
                      )}
                    </div>
                    <div className="flex-1 min-w-0 w-full">
                      <div className="flex items-center gap-2 mb-1 flex-wrap">
                        <span
                          className="font-medium truncate text-sm sm:text-base"
                          style={{ color: 'var(--text-primary)' }}
                        >
                          {attempt.email}
                        </span>
                        <span
                          className="text-[10px] sm:text-xs capitalize px-1.5 sm:px-2 py-0.5 rounded"
                          style={{ background: 'var(--muted)', color: 'var(--text-muted)' }}
                        >
                          {attempt.method}
                        </span>
                        {attempt.riskScore !== undefined && <RiskBadge score={attempt.riskScore} />}
                      </div>
                      <div
                        className="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-3 text-[10px] sm:text-xs"
                        style={{ color: 'var(--text-muted)' }}
                      >
                        <span>
                          {t('superadmin.security.ip')}: {attempt.ip ?? '—'}
                        </span>
                        {attempt.riskFactors && attempt.riskFactors.length > 0 && (
                          <span style={{ color: 'var(--warning)' }}>
                            ⚠ {attempt.riskFactors.join(', ')}
                          </span>
                        )}
                        {attempt.blockedReason && (
                          <span style={{ color: 'var(--destructive)' }}>
                            🔒 {attempt.blockedReason}
                          </span>
                        )}
                      </div>
                    </div>
                    <div
                      className="text-[10px] sm:text-xs shrink-0 self-end sm:self-auto"
                      style={{ color: 'var(--text-muted)' }}
                    >
                      {new Date(attempt.createdAt).toLocaleTimeString()}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ── TAB: Audit Logs ── */}
        {activeTab === 'logs' && (
          <div>
            <p className="text-sm mb-4" style={{ color: 'var(--text-muted)' }}>
              {t('superadmin.security.allSecurityActions')}
            </p>
            {!auditLogs?.length ? (
              <div className="text-center py-16" style={{ color: 'var(--text-muted)' }}>
                <Eye className="w-12 h-12 mx-auto mb-3" style={{ color: 'var(--text-disabled)' }} />
                {t('superadmin.security.noAuditLogs')}
              </div>
            ) : (
              <div className="space-y-2">
                {auditLogs.map((log) => (
                  <div
                    key={log._id}
                    className="rounded-lg p-4 flex items-center gap-4 border"
                    style={{ background: 'var(--card)', borderColor: 'var(--border)' }}
                  >
                    <div
                      className="w-2 h-2 rounded-full shrink-0"
                      style={{ background: 'var(--primary)' }}
                    />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-0.5">
                        <span
                          className="font-medium text-sm"
                          style={{ color: 'var(--text-primary)' }}
                        >
                          {log.userName}
                        </span>
                        <span className="text-xs" style={{ color: 'var(--text-muted)' }}>
                          {log.userEmail}
                        </span>
                      </div>
                      <div className="text-sm truncate" style={{ color: 'var(--text-secondary)' }}>
                        <span
                          className="font-mono text-xs px-1.5 py-0.5 rounded mr-2 inline-block shrink-0"
                          style={{ background: 'rgba(37,99,235,0.12)', color: 'var(--primary)' }}
                        >
                          {log.action}
                        </span>
                        <span className="truncate">{log.details}</span>
                      </div>
                      {log.ip && (
                        <div className="text-xs mt-0.5" style={{ color: 'var(--text-disabled)' }}>
                          {t('superadmin.security.ip')}: {log.ip}
                        </div>
                      )}
                    </div>
                    <div className="text-xs shrink-0" style={{ color: 'var(--text-muted)' }}>
                      {new Date(log.createdAt).toLocaleString()}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </ErrorBoundary>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import {
  DollarSign,
  Users,
  TrendingUp,
  AlertCircle,
  RefreshCw,
  Calendar,
  CreditCard,
  ShieldAlert,
  CheckCircle,
  XCircle,
  Clock,
  ArrowUpRight,
  ArrowDownRight,
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';

const SUPERADMIN_EMAIL = (process.env.NEXT_PUBLIC_BOOTSTRAP_SUPERADMIN_EMAIL ?? '').toLowerCase();

interface StripeMetrics {
  totalSubscriptions: number;
  active: number;
  trialing: number;
  canceled: number;
  pastDue: number;
  mrr: number;
  totalRevenue: number;
  last30DaysRevenue: number;
  growth: string;
  trialEnding: number;
}

interface StripeSubscription {
  id: string;
  status: string;
  plan: string;
  amount: number;
  customer: { email: string; name: string };
  currentPeriodEnd: number;
  currentPeriodStart: number;
  cancelAtPeriodEnd: boolean;
  trialEnd?: number;
  created: number;
}

interface StripeTransaction {
  id: string;
  amount: number;
  currency: string;
  status: string;
  customer: string;
  date: string;
  description: string;
}

interface StripeData {
  metrics: StripeMetrics;
  subscriptions: StripeSubscription[];
  recentTransactions: StripeTransaction[];
}

export default function StripeDashboardPage() {
  const { t, i18n } = useTranslation();
  const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';
  const router = useRouter();
  const { user: currentUser } = useAuthStore();
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [data, setData] = useState<StripeData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fetchStripeData = async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/stripe/transactions');
      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || 'Failed to fetch data');
      }

      setData(result);
      if (isRefresh) {
        toast.success(t('stripeDashboard.dataUpdated'));
      }
    } catch (err: any) {
      setError(err.message);
      if (isRefresh) {
        toast.error(t('stripeDashboard.updateError'));
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    let mounted = true;
    if (currentUser) {
      fetchStripeData();
    } else {
      setLoading(false);
    }
    return () => {
      mounted = false;
    };
  }, [currentUser]);

  if (!currentUser) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <ShieldLoader size="lg" />
      </div>
    );
  }

  const isSuperAdmin =
    currentUser.email?.toLowerCase() === SUPERADMIN_EMAIL || currentUser.role === 'superadmin';

  if (!isSuperAdmin) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Card className="w-full max-w-md">
          <CardHeader>
            <div className="flex items-center gap-2 text-red-500">
              <ShieldAlert className="w-6 h-6" />
              <CardTitle>{t('stripe.accessDenied')}</CardTitle>
            </div>
            <CardDescription>{t('stripe.accessDeniedDesc')}</CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-sm text-muted-foreground">{t('stripe.restrictedAccess')}</p>
