        </Card>
      </div>

      {/* Revenue Summary */}
      <Card>
        <CardHeader>
          <CardTitle>{t('stripeDashboard.totalRevenue')}</CardTitle>
          <CardDescription>{t('stripeDashboard.totalRevenueDesc')}</CardDescription>
