                </thead>
                <tbody>
                  {subscriptions
                    .filter((s) => s.status === 'active')
                    .map((sub) => (
                      <tr key={sub.id} className="border-b hover:bg-muted/50 transition-colors">
                        <td className="py-3">
                          <div className="flex items-center gap-2">
                            <CreditCard className="w-4 h-4 text-muted-foreground" />
