import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { jwtVerify } from 'jose';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { logger } from '@/lib/logger';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL!;

async function convexMutation(name: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path: name, args }),
  });
  const data = await res.json();
  if (data.status === 'error') throw new Error(data.errorMessage ?? 'Convex error');
  return data.value;
}

/**
 * Verify the user is a superadmin.
 */
async function verifySuperadmin(): Promise<{ userId: string; role: string } | null> {
  try {
    const cookieStore = await cookies();
    const sessionCookie = cookieStore.get('oauth-session');
    if (!sessionCookie) return null;

    const jwtSecret = process.env.JWT_SECRET;
    if (!jwtSecret) return null;

    const secret = new TextEncoder().encode(jwtSecret);
    const { payload } = await jwtVerify(sessionCookie.value, secret);

    if (payload.role !== 'superadmin') {
      logger.warn('[Approve-All] Non-superadmin access attempt:', payload.role);
      return null;
    }

    return { userId: payload.sub as string, role: payload.role as string };
  } catch {
    return null;
  }
}

export const POST = withCsrfProtection(async () => {
  // SECURITY: Require superadmin authentication
  const user = await verifySuperadmin();
  if (!user) {
    return NextResponse.json(
      { error: 'Unauthorized. Superadmin access required.' },
      { status: 401 },
    );
  }

  try {
    const result = await convexMutation('migrations:approveAllExistingUsers', {});
    return NextResponse.json({ success: true, result });
  } catch (error) {
    return NextResponse.json(
      { success: false, error: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 },
    );
  }
});

import { NextRequest, NextResponse } from 'next/server';
import { signJWT } from '@/lib/jwt';
import { jwtVerify } from 'jose';

/**
 * SECURITY: Verify that the requester is already authenticated before
 * creating a new session. This prevents unauthorized session creation.
 */
async function verifyExistingAuth(req: NextRequest): Promise<boolean> {
  try {
    const token = req.cookies.get('hr-auth-token') || req.cookies.get('oauth-session');
    if (!token) return false;

    const jwtSecret = process.env.JWT_SECRET;
    if (!jwtSecret) return false;

    const secret = new TextEncoder().encode(jwtSecret);
    await jwtVerify(token.value, secret);
    return true;
  } catch {
    return false;
  }
}

export async function POST(request: NextRequest) {
  try {
    // SECURITY: Require existing authentication before creating a new session
    if (!(await verifyExistingAuth(request))) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { userId, name, email, role, department, position, employeeType, avatar } = body;

    if (!userId || !email) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    // Create JWT token
    const jwt = await signJWT({
      userId,
      name,
      email,
      role,
      department,
      position,
      employeeType,
      avatar,
    });

    // Create session token
    const sessionToken = crypto.randomUUID();

    // Set cookies with secure settings
    const response = NextResponse.json({ success: true });
    response.cookies.set('hr-auth-token', jwt, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });
    response.cookies.set('hr-session-token', sessionToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });

    return response;
  } catch (error) {
    console.error('Error creating session:', error);
    return NextResponse.json({ error: 'Failed to create session' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { signJWT } from '@/lib/jwt';
import { log } from '@/lib/logger';
import { applyRateLimit, FACE_LOGIN_RATE_LIMIT } from '@/lib/rate-limit';

// SECURITY: Face descriptor matching is CPU-bound and uses bcrypt-adjacent
// primitives; keep on Node runtime, not Edge.
export const runtime = 'nodejs';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL;

if (!CONVEX_URL) {
  throw new Error('NEXT_PUBLIC_CONVEX_URL environment variable is not set');
}

async function convexMutation(name: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path: name, args }),
    cache: 'no-store',
  });
  const data = await res.json();
  if (data.status === 'error') throw new Error(data.errorMessage ?? 'Convex error');
  return data.value;
}

async function convexQuery(name: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/query`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path: name, args }),
    cache: 'no-store',
  });
  const data = await res.json();
  if (data.status === 'error') return null;
  return data.value;
}

function getClientIp(request: NextRequest): string {
  return (
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ??
    request.headers.get('x-real-ip') ??
    'unknown'
  );
}

export async function POST(request: NextRequest) {
  // Rate limit: 10 attempts per 15 min per IP
  const rateLimitResponse = await applyRateLimit(request, FACE_LOGIN_RATE_LIMIT, 'face-login');
  if (rateLimitResponse) return rateLimitResponse;

  try {
    const body = (await request.json()) as {
      email?: string;
      faceDescriptor?: number[];
    };
    const { email, faceDescriptor } = body;
    const ip = getClientIp(request);
    const userAgent = request.headers.get('user-agent') ?? undefined;

    if (!email || typeof email !== 'string') {
      return NextResponse.json({ error: 'Email is required' }, { status: 400 });
    }

    if (!Array.isArray(faceDescriptor) || faceDescriptor.length !== 128) {
      return NextResponse.json(
        { error: 'Valid face descriptor (128 floats) is required' },
        { status: 400 },
      );
    }

    // Reject obviously malformed descriptors (all zeros, non-finite, etc)
    if (
      !faceDescriptor.every((n) => typeof n === 'number' && Number.isFinite(n) && Math.abs(n) < 10)
    ) {
      return NextResponse.json({ error: 'Malformed face descriptor' }, { status: 400 });
    }

    // Step 1 — server-side face matching → issues short-lived verification token
    let verification;
    try {
      verification = await convexMutation('faceRecognition:loginWithFace', {
        email,
        faceDescriptor,
        ip,
        userAgent,
      });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Face verification failed';
      log.warn('Face verification failed', { email, ip });
      return NextResponse.json({ error: msg }, { status: 401 });
    }

    const faceVerificationToken: string = verification.faceVerificationToken;

    // Step 2 — exchange token for session
    const sessionToken = crypto.randomUUID();
    const sessionExpiry = Date.now() + 7 * 24 * 60 * 60 * 1000;

    const result = await convexMutation('auth:login', {
      email,
      password: '', // Not used when faceVerificationToken is valid
      sessionToken,
      sessionExpiry,
      isFaceLogin: true,
      faceVerificationToken,
    });

    // Maintenance mode check — block non-superadmin login
    if (result.role !== 'superadmin' && result.organizationId) {
      const maintenanceData = await convexQuery('admin:getMaintenanceMode', {
        organizationId: result.organizationId,
      });
      if (maintenanceData?.isActive && maintenanceData.startTime <= Date.now()) {
        return NextResponse.json(
          { error: 'maintenance', organizationId: result.organizationId },
          { status: 503 },
        );
      }
    }

    // Issue app JWT
    const jwt = await signJWT({
      userId: result.userId,
      name: result.name,
      email: result.email,
      role: result.role,
      organizationId: result.organizationId,
      organizationSlug: result.organizationSlug,
      organizationName: result.organizationName,
      isApproved: result.isApproved,
      department: result.department,
      position: result.position,
      employeeType: result.employeeType,
      avatar: result.avatarUrl,
    });

    const secure = process.env.NODE_ENV === 'production';

    log.info('Face Login successful', { userId: result.userId, email });

    const response = NextResponse.json({
      success: true,
      session: {
        userId: result.userId,
        name: result.name,
        email: result.email,
        role: result.role,
        organizationId: result.organizationId,
        department: result.department,
        position: result.position,
        employeeType: result.employeeType,
        avatar: result.avatarUrl,
      },
    });

    response.cookies.set('hr-auth-token', jwt, {
      httpOnly: true,
      secure,
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });
    response.cookies.set('hr-session-token', sessionToken, {
      httpOnly: true,
      secure,
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });

    return response;
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : 'Login failed';
    log.error('Face Login API error', error as Error);
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

