                <p style="color: #6b7280; font-size: 12px; margin: 0; line-height: 1.6;">
                  If the button doesn't work, copy and paste this link:<br>
                  <a href="${resetLink}" style="color: #2563eb; word-break: break-all;">${resetLink}</a>
                </p>
              </div>

              <!-- Footer -->
              <p style="text-align: center; color: #4b5563; font-size: 12px; margin-top: 24px;">
                © ${new Date().getFullYear()} Strata • From Strategy to Results
              </p>
            </div>
          </body>
          </html>
        `,
      });
      logger.log('Resend result:', JSON.stringify(sendResult));
      if (sendResult.error) {
        console.error('Resend error:', sendResult.error);
        // Don't throw — token is still saved, user can try again or admin can resend
      }
    }

    return NextResponse.json({ success: true });
  } catch (err) {
    console.error('Forgot password error:', err);
    const msg = err instanceof Error ? err.message : 'Something went wrong';
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { signJWT } from '@/lib/jwt';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL;

/**
 * imID OAuth callback — Convex HTTP action redirects here after a successful
 * authentication. This route:
 *   1. Verifies the session token via Convex `auth:verifySession`
 *   2. Signs a proper JWT with user info
 *   3. Sets hr-auth-token (JWT) + hr-session-token (UUID) cookies
 *   4. Redirects to /dashboard
 *
 * We need this bridge because the Convex HTTP runtime has no access to
 * JWT_SECRET (it's a Next.js env var) and cannot sign a JWT directly.
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = request.nextUrl;
    const sessionToken = searchParams.get('sessionToken');
    const isNewUser = searchParams.get('welcome') === 'true';
    const needsApproval = searchParams.get('pending_approval') === 'true';

    if (!sessionToken) {
      const loc = new URL('/login?error=imid_missing_token', request.url);
      return NextResponse.redirect(loc);
    }

    // ── Handle needsApproval before calling Convex ──────────────────────────
    // When imidUpsertUser creates a user that is not the first org member, it
    // does NOT save the sessionToken on the user record (because the account
    // is pending admin approval). The verifySession call would fail, so skip
    // it and redirect to login with the pending_approval hint instead.
    if (needsApproval) {
      const loc = new URL('/login?pending_approval=true', request.url);
      return NextResponse.redirect(loc);
    }

    if (!CONVEX_URL) {
      console.error('[imid-callback] CONVEX_URL is not set');
      const loc = new URL('/login?error=imid_config_error', request.url);
      return NextResponse.redirect(loc);
    }

    // ── 1. Verify the session token via Convex ─────────────────────────────
    const res = await fetch(`${CONVEX_URL}/api/query`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        path: 'auth:verifySession',
        args: { sessionToken },
        format: 'json',
      }),
      cache: 'no-store',
    });

    if (!res.ok) {
      console.error('[imid-callback] Convex query failed:', res.status);
      const loc = new URL('/login?error=imid_verify_failed', request.url);
      return NextResponse.redirect(loc);
    }

    const data = await res.json();
    if (data.status === 'error' || !data.value) {
      console.error('[imid-callback] Session verification failed:', data.errorMessage);
      const loc = new URL('/login?error=imid_session_expired', request.url);
      return NextResponse.redirect(loc);
    }

    const user = data.value as {
      userId: string;
      name: string;
      email: string;
      role: string;
      organizationId: string;
      organizationName?: string;
      organizationSlug?: string;
      department?: string;
      position?: string;
      employeeType?: string;
      avatarUrl?: string;
      isApproved?: boolean;
    };

    // ── 2. Sign a proper JWT ──────────────────────────────────────────────
    const jwt = await signJWT({
      userId: user.userId,
      name: user.name,
      email: user.email,
      role: user.role as 'admin' | 'supervisor' | 'employee' | 'superadmin' | 'driver',
      organizationId: user.organizationId,
      organizationSlug: user.organizationSlug,
      organizationName: user.organizationName,
      department: user.department,
      position: user.position,
      employeeType: (user.employeeType as 'staff' | 'contractor') ?? 'staff',
      avatar: user.avatarUrl,
      isApproved: user.isApproved,
    });

    // ── 3. Build redirect target ──────────────────────────────────────────
    // Note: needsApproval is handled by the early return above (line ~35),
    // because unapproved users have no sessionToken stored on their record
    // and cannot be verified. So at this point we always redirect to dashboard.
    const params = new URLSearchParams();
    if (isNewUser) params.set('welcome', 'true');
    const qs = params.toString();
    const redirectTarget = qs ? `/dashboard?${qs}` : '/dashboard';

    const response = NextResponse.redirect(new URL(redirectTarget, request.url));

    // ── 4. Set cookies ────────────────────────────────────────────────────
    response.cookies.set('hr-auth-token', jwt, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });

    // Also set the hr-session-token (UUID) matching the pattern used by
    // loginAction — some backend code references it by this cookie name.
    response.cookies.set('hr-session-token', sessionToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });

    return response;
  } catch (error) {
    console.error('[imid-callback] Unexpected error:', error);
    const loc = new URL('/login?error=imid_unexpected', request.url);
    return NextResponse.redirect(loc);
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { verifyJWT, signJWT } from '@/lib/jwt';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL;

async function convexMutation(path: string, args: Record<string, unknown>) {
  if (!CONVEX_URL) {
    throw new Error('NEXT_PUBLIC_CONVEX_URL environment variable is not set');
  }

  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, args }),
    cache: 'no-store',
  });

  const data = await res.json();
  if (!res.ok || data.status === 'error') {
    throw new Error(data.errorMessage ?? `HTTP ${res.status}`);
  }

  return data.value;
}

export async function POST(req: NextRequest) {
  try {
    const jwt = req.cookies.get('hr-auth-token')?.value;
    if (!jwt) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const payload = await verifyJWT(jwt);
    if (!payload) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Idempotent exit: if impersonation metadata is already absent,
    // treat this as an already-ended session and return current user session.
    if (!payload.impersonation?.active) {
      return NextResponse.json({
        success: true,
        session: {
          userId: payload.userId,
          name: payload.name,
          email: payload.email,
          role: payload.role,
          organizationId: payload.organizationId,
          organizationSlug: payload.organizationSlug,
          organizationName: payload.organizationName,
          isApproved: payload.isApproved,
          department: payload.department,
          position: payload.position,
          employeeType: payload.employeeType,
          avatar: payload.avatar,
        },
      });
    }

    const restoredSessionToken = crypto.randomUUID();
    const restoredSessionExpiry = Date.now() + 7 * 24 * 60 * 60 * 1000;

    const result = await convexMutation('superadmin:endImpersonationWithToken', {
      sessionId: payload.impersonation.sessionId,
      token: payload.impersonation.sessionToken,
      restoredSessionToken,
      restoredSessionExpiry,
    });

    const superadmin = result.superadmin;
    if (!superadmin?.id || !superadmin?.email) {
      return NextResponse.json({ error: 'Invalid superadmin account' }, { status: 500 });
    }

    const restoredJwt = await signJWT({
      userId: String(superadmin.id),
      name: superadmin.name,
      email: superadmin.email,
      role: superadmin.role,
      organizationId: superadmin.organizationId,
      organizationSlug: superadmin.organizationSlug,
      organizationName: superadmin.organizationName,
      isApproved: superadmin.isApproved,
      department: superadmin.department,
      position: superadmin.position,
      employeeType: superadmin.employeeType,
      avatar: superadmin.avatar,
    });

    const response = NextResponse.json({
      success: true,
      session: {
        userId: String(superadmin.id),
        name: superadmin.name,
        email: superadmin.email,
        role: superadmin.role,
        organizationId: superadmin.organizationId,
        organizationSlug: superadmin.organizationSlug,
        organizationName: superadmin.organizationName,
        isApproved: superadmin.isApproved,
        department: superadmin.department,
        position: superadmin.position,
        employeeType: superadmin.employeeType,
        avatar: superadmin.avatar,
      },
    });

    const sevenDays = 7 * 24 * 60 * 60;
    response.cookies.set('hr-auth-token', restoredJwt, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: sevenDays,
      path: '/',
    });

    response.cookies.set('hr-session-token', restoredSessionToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: sevenDays,
      path: '/',
    });

    response.cookies.set('session_expiry', String(Date.now() + sevenDays * 1000), {
      maxAge: sevenDays,
      path: '/',
    });

    return response;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    console.error('Impersonation end error:', error);
    return NextResponse.json(
      { error: error?.message || 'Failed to end impersonation' },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { verifyJWT, signJWT } from '@/lib/jwt';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL;

async function convexMutation(path: string, args: Record<string, unknown>) {
  if (!CONVEX_URL) {
    throw new Error('NEXT_PUBLIC_CONVEX_URL environment variable is not set');
  }

  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, args }),
    cache: 'no-store',
  });

  const data = await res.json();
  if (!res.ok || data.status === 'error') {
    throw new Error(data.errorMessage ?? `HTTP ${res.status}`);
  }

  return data.value;
}

export async function POST(req: NextRequest) {
  try {
    const jwt = req.cookies.get('hr-auth-token')?.value;
    if (!jwt) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const payload = await verifyJWT(jwt);
    if (!payload || payload.role !== 'superadmin' || payload.impersonation?.active) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const body = await req.json();
    const sessionId = body?.sessionId as string | undefined;
    const token = body?.token as string | undefined;

    if (!sessionId || !token) {
      return NextResponse.json({ error: 'sessionId and token are required' }, { status: 400 });
    }

    const targetSessionToken = crypto.randomUUID();
    const targetSessionExpiry = Date.now() + 7 * 24 * 60 * 60 * 1000;

    const activation = await convexMutation('superadmin:activateImpersonationSession', {
      sessionId,
      token,
      superadminId: payload.userId,
      targetSessionToken,
      targetSessionExpiry,
    });

    const target = activation.targetUser;
    if (!target?.id || !target?.email) {
      return NextResponse.json({ error: 'Invalid target user' }, { status: 500 });
    }

    const impersonationPayload = {
      active: true as const,
      sessionId: String(activation.sessionId),
      sessionToken: String(activation.token),
      expiresAt: Number(activation.expiresAt),
      superadmin: {
        userId: payload.userId,
        name: payload.name,
        email: payload.email,
        role: 'superadmin' as const,
        organizationId: payload.organizationId,
        organizationSlug: payload.organizationSlug,
        organizationName: payload.organizationName,
        department: payload.department,
        position: payload.position,
        employeeType: payload.employeeType,
        avatar: payload.avatar,
        isApproved: payload.isApproved,
      },
    };

    const impersonationJwt = await signJWT({
      userId: String(target.id),
      name: target.name,
      email: target.email,
      role: target.role,
      organizationId: target.organizationId,
      organizationSlug: target.organizationSlug,
      organizationName: target.organizationName,
      isApproved: target.isApproved,
      department: target.department,
      position: target.position,
      employeeType: target.employeeType,
      avatar: target.avatar,
      impersonation: impersonationPayload,
    });

    const response = NextResponse.json({
      success: true,
      session: {
        userId: String(target.id),
        name: target.name,
        email: target.email,
        role: target.role,
        organizationId: target.organizationId,
        organizationSlug: target.organizationSlug,
        organizationName: target.organizationName,
        isApproved: target.isApproved,
        department: target.department,
        position: target.position,
        employeeType: target.employeeType,
        avatar: target.avatar,
        impersonation: {
          active: true,
          sessionId: String(activation.sessionId),
          expiresAt: Number(activation.expiresAt),
          superadminName: payload.name,
          superadminEmail: payload.email,
        },
      },
    });

    const sevenDays = 7 * 24 * 60 * 60;
    response.cookies.set('hr-auth-token', impersonationJwt, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: sevenDays,
      path: '/',
    });

    response.cookies.set('hr-session-token', targetSessionToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: sevenDays,
      path: '/',
    });

    response.cookies.set('session_expiry', String(Date.now() + sevenDays * 1000), {
      maxAge: sevenDays,
      path: '/',
    });

    return response;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    console.error('Impersonation start error:', error);
    return NextResponse.json(
      { error: error?.message || 'Failed to start impersonation' },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { signJWT } from '@/lib/jwt';
import { calculateRiskScore } from '@/lib/riskScore';
import { withTracing, addSpanAttributes } from '@/lib/tracing';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL;

async function convexMutation(path: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, args }),
  });
  const data = await res.json();
  if (data.status === 'error') throw new Error(data.errorMessage ?? 'Convex error');
  return data.value;
}

async function convexQuery(path: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/query`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, args }),
  });
  const data = await res.json();
  if (data.status === 'error') return null;
  return data.value;
}

export async function POST(req: NextRequest) {
  return withTracing('auth.login', async () => {
    const ip =
      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ??
      req.headers.get('x-real-ip') ??
      'unknown';
    const userAgent = req.headers.get('user-agent') ?? undefined;

    let email = '';

    try {
      const body = await req.json();
      email = body.email ?? '';
      const { password, deviceFingerprint, keystrokeSample } = body;

      // Add tracing attributes
      addSpanAttributes({
        'auth.email': email,
        'auth.has_device_fingerprint': !!deviceFingerprint,
        'client.ip': ip,
      });

      if (!email || !password) {
        return NextResponse.json({ error: 'Email and password are required' }, { status: 400 });
      }
      if (!CONVEX_URL) {
        return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
      }

      // ── Check if audit_logging is enabled ────────────────────────────────────
      const auditEnabled = await convexQuery('security:getSetting', { key: 'audit_logging' });
      const adaptiveEnabled = await convexQuery('security:getSetting', { key: 'adaptive_auth' });

      // ── Get recent failed attempts for risk score ─────────────────────────────
      const fifteenMinAgo = Date.now() - 15 * 60 * 1000;
      let recentFailedAttempts = 0;
      const isKnownDevice = false;
      const isTrustedDevice = false;
      let lastLoginDaysAgo: number | undefined;
      let keystrokeSimilarity: number | undefined;

      // We'll check these after we find the user — for now fetch by email first
      // (we do a pre-check via loginAttempts by email)
      const recentByEmail = await convexQuery('security:getLoginStats', {
        hours: 0.25, // last 15 min
      });
      if (recentByEmail) {
        const suspicious = (recentByEmail.suspicious ?? []) as Array<{
          email?: string;
          success?: boolean;
        }>;
        const emailFails = suspicious.filter((a) => a.email === email && !a.success);
        recentFailedAttempts = emailFails.length;
      }

      // ── Calculate risk score ─────────────────────────────────────────────────
      const riskResult = calculateRiskScore({
        ip,
        userAgent,
        deviceFingerprint,
        email,
        method: 'password',
        isKnownDevice,
        isTrustedDevice,
        recentFailedAttempts,
        currentHour: new Date().getHours(),
        keystrokeSimilarity,
        lastLoginDaysAgo,
      });

      // ── Block high-risk if adaptive auth is on ───────────────────────────────
      if (
        adaptiveEnabled &&
        riskResult.action === 'block' &&
        riskResult.factors.includes('multiple_failed_attempts')
      ) {
        if (auditEnabled) {
          await convexMutation('security:logLoginAttempt', {
            email,
            success: false,
            method: 'password',
            ip,
            userAgent,
            deviceFingerprint,
            riskScore: riskResult.score,
            riskFactors: riskResult.factors,
            blockedReason: 'Too many failed attempts — account locked',
          });
        }
        return NextResponse.json(
          {
            error:
              'Account temporarily locked due to multiple failed attempts. Contact your administrator.',
          },
          { status: 429 },
        );
      }

      // ── Proceed with login ───────────────────────────────────────────────────
      const sessionToken = crypto.randomUUID();
      const sessionExpiry = Date.now() + 7 * 24 * 60 * 60 * 1000;

      const res = await fetch(`${CONVEX_URL}/api/mutation`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          path: 'auth:login',
          args: { email, password, sessionToken, sessionExpiry, isFaceLogin: false },
        }),
      });

      const data = await res.json();

      if (data.status === 'error') {
        // Log failed attempt
        if (auditEnabled) {
          await convexMutation('security:logLoginAttempt', {
            email,
            success: false,
            method: 'password',
            ip,
            userAgent,
            deviceFingerprint,
            riskScore: riskResult.score,
            riskFactors: riskResult.factors,
          });
        }
        return NextResponse.json({ error: data.errorMessage || 'Login failed' }, { status: 401 });
      }

      const result = data.value;

      // ── Check if 2FA is enabled ─────────────────────────────────────────────
      if (result.totpEnabled) {
        // Generate short-lived temp token (5 minutes)
        const tempToken = await signJWT(
          {
            userId: result.userId,
            name: result.name,
            email: result.email,
            role: result.role,
            organizationId: result.organizationId,
            organizationSlug: result.organizationSlug,
            organizationName: result.organizationName,
            department: result.department,
            position: result.position,
            employeeType: result.employeeType,
            avatar: result.avatarUrl,
            type: '2fa-pending',
          },
          '5m',
        );
        return NextResponse.json({
          requiresTwoFactor: true,
          tempToken,
        });
      }

      // ── Check maintenance mode — block non-superadmin login ──────────────────
      if (result.role !== 'superadmin' && result.organizationId) {
        const maintenanceData = await convexQuery('admin:getMaintenanceMode', {
          organizationId: result.organizationId,
        });
        if (maintenanceData?.isActive && maintenanceData.startTime <= Date.now()) {
          return NextResponse.json(
            { error: 'maintenance', organizationId: result.organizationId },
            { status: 503 },
          );
        }
      }

      // ── Register device fingerprint ──────────────────────────────────────────
      if (deviceFingerprint && result.userId) {
        const deviceResult = await convexMutation('security:registerDevice', {
          userId: result.userId,
          fingerprint: deviceFingerprint,
          userAgent,
        });

        // If new device and feature enabled — notify admin
        const newDeviceAlertEnabled = await convexQuery('security:getSetting', {
          key: 'new_device_alert',
        });
        if (newDeviceAlertEnabled && deviceResult?.isNew) {
          // Notify org admins about new device login
          await convexMutation('security:logLoginAttempt', {
            email,
            userId: result.userId,
            organizationId: result.organizationId,
            success: true,
            method: 'password',
            ip,
            userAgent,
            deviceFingerprint,
            riskScore: riskResult.score + 30, // boost score for new device
            riskFactors: [...riskResult.factors, 'new_device'],
          });
        }
      }

      // ── Log successful attempt ───────────────────────────────────────────────
      if (auditEnabled) {
        await convexMutation('security:logLoginAttempt', {
          email,
          userId: result.userId,
          organizationId: result.organizationId,
          success: true,
          method: 'password',
          ip,
          userAgent,
          deviceFingerprint,
          riskScore: riskResult.score,
          riskFactors: riskResult.factors,
        });
      }

      // ── Save keystroke profile if available ──────────────────────────────────
      if (keystrokeSample && result.userId) {
        const keystrokeEnabled = await convexQuery('security:getSetting', {
          key: 'keystroke_dynamics',
        });
        if (keystrokeEnabled) {
          await convexMutation('security:saveKeystrokeProfile', {
            userId: result.userId,
            ...keystrokeSample,
          });
        }
      }

      // ── Create JWT ───────────────────────────────────────────────────────────
      const jwt = await signJWT({
        userId: result.userId,
        name: result.name,
        email: result.email,
        role: result.role,
        organizationId: result.organizationId,
        organizationSlug: result.organizationSlug,
        organizationName: result.organizationName,
        isApproved: result.isApproved,
        department: result.department,
        position: result.position,
        employeeType: result.employeeType,
        avatar: result.avatarUrl,
      });

      const response = NextResponse.json({
        success: true,
        riskLevel: riskResult.level,
        session: {
          userId: result.userId,
          name: result.name,
          email: result.email,
          role: result.role,
          organizationId: result.organizationId,
          organizationSlug: result.organizationSlug,
          organizationName: result.organizationName,
          isApproved: result.isApproved,
          department: result.department,
          position: result.position,
          employeeType: result.employeeType,
          avatar: result.avatarUrl,
        },
      });

      response.cookies.set('hr-auth-token', jwt, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 7 * 24 * 60 * 60,
        path: '/',
      });
      response.cookies.set('hr-session-token', sessionToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 7 * 24 * 60 * 60,
        path: '/',
      });

      return response;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      console.error('Login error:', error);
      // Log server error attempt
      try {
        await convexMutation('security:logLoginAttempt', {
          email,
          success: false,
          method: 'password',
          ip,
          userAgent,
          blockedReason: `Server error: ${error.message}`,
        });
      } catch {}
      return NextResponse.json(
        { error: error.message || 'Internal server error' },
        { status: 500 },
      );
    }
  });
}

