import { NextRequest, NextResponse } from 'next/server';

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const code = searchParams.get('code');

  if (!code) {
    return NextResponse.json({ error: 'No authorization code' }, { status: 400 });
  }

  const clientId = process.env.GOOGLE_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
  const origin = request.nextUrl.origin;
  const redirectUri = `${origin}/api/calendar/google/auth`;

  if (!clientId || !clientSecret) {
    return NextResponse.json({ error: 'Google OAuth not configured' }, { status: 500 });
  }

  try {
    // Exchange code for access token
    const tokenResponse = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        code,
        client_id: clientId,
        client_secret: clientSecret,
        redirect_uri: redirectUri,
        grant_type: 'authorization_code',
      }),
    });

    if (!tokenResponse.ok) {
      throw new Error('Failed to exchange code for token');
    }

    const tokenData = await tokenResponse.json();

    // Store tokens (you should implement secure storage)
    // For now, redirect back with success
    const response = NextResponse.redirect(
      new URL('/dashboard?google_calendar=connected', request.url),
    );

    // Set HTTP-only cookie with access token (short-lived)
    response.cookies.set('google_access_token', tokenData.access_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 3600, // 1 hour
    });

    // Set HTTP-only cookie with refresh token (long-lived)
    if (tokenData.refresh_token) {
      response.cookies.set('google_refresh_token', tokenData.refresh_token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 30 * 24 * 60 * 60, // 30 days
      });
    }

    return response;
  } catch (error) {
    console.error('Google OAuth error:', error);
    return NextResponse.redirect(new URL('/dashboard?error=google_auth_failed', request.url));
  }
}

import { NextRequest, NextResponse } from 'next/server';

export async function GET(request: NextRequest) {
  const accessToken = request.cookies.get('google_access_token')?.value;
  const refreshToken = request.cookies.get('google_refresh_token')?.value;

  let token = accessToken;

  // Try refresh if access token missing
  if (!token && refreshToken) {
    const clientId = process.env.GOOGLE_CLIENT_ID;
    const clientSecret = process.env.GOOGLE_CLIENT_SECRET;

    if (clientId && clientSecret) {
      try {
        const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            client_id: clientId,
            client_secret: clientSecret,
            refresh_token: refreshToken,
            grant_type: 'refresh_token',
          }),
        });

        if (tokenRes.ok) {
          const tokens = await tokenRes.json();
          token = tokens.access_token;
        }
      } catch {
        // refresh failed
      }
    }
  }

  if (!token) {
    return NextResponse.json({ events: [], connected: false });
  }

  const { searchParams } = request.nextUrl;
  const timeMin = searchParams.get('timeMin');
  const timeMax = searchParams.get('timeMax');

  if (!timeMin || !timeMax) {
    return NextResponse.json({ error: 'timeMin and timeMax are required' }, { status: 400 });
  }

  try {
    const params = new URLSearchParams({
      timeMin,
      timeMax,
      singleEvents: 'true',
      orderBy: 'startTime',
      maxResults: '250',
    });

    const res = await fetch(
      `https://www.googleapis.com/calendar/v3/calendars/primary/events?${params}`,
      {
        headers: { Authorization: `Bearer ${token}` },
      },
    );

    if (!res.ok) {
      if (res.status === 401) {
        return NextResponse.json({ events: [], connected: false });
      }
      throw new Error(`Google API error: ${res.status}`);
    }

    const data = await res.json();

    const events = (data.items || []).map((item: any) => ({
      id: item.id,
      title: item.summary || '(No title)',
      description: item.description || '',
      startDate: item.start?.date || item.start?.dateTime?.split('T')[0] || '',
      endDate: item.end?.date || item.end?.dateTime?.split('T')[0] || '',
      startTime: item.start?.dateTime || null,
      endTime: item.end?.dateTime || null,
      allDay: !!item.start?.date,
      location: item.location || '',
      htmlLink: item.htmlLink || '',
    }));

    // Set refreshed token cookie if we refreshed
    const response = NextResponse.json({ events, connected: true });
    if (!accessToken && token) {
      response.cookies.set('google_access_token', token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 3600,
      });
    }
    return response;
  } catch (error) {
    console.error('Google Calendar events fetch error:', error);
    return NextResponse.json({ events: [], connected: true, error: 'fetch_failed' });
  }
}

import { NextRequest, NextResponse } from 'next/server';

export async function GET(request: NextRequest) {
  const accessToken = request.cookies.get('google_access_token')?.value;
  const refreshToken = request.cookies.get('google_refresh_token')?.value;

  if (!accessToken && !refreshToken) {
    return NextResponse.json({ connected: false });
  }

  // If we have an access token, verify it's still valid
  if (accessToken) {
    try {
      const res = await fetch('https://www.googleapis.com/oauth2/v1/userinfo?alt=json', {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (res.ok) {
        const profile = await res.json();
        return NextResponse.json({
          connected: true,
          email: profile.email,
        });
      }
    } catch {
      // Token might be expired, fall through to refresh
    }
  }

  // Try to refresh the token
  if (refreshToken) {
    const clientId = process.env.GOOGLE_CLIENT_ID;
    const clientSecret = process.env.GOOGLE_CLIENT_SECRET;

    if (clientId && clientSecret) {
      try {
        const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            client_id: clientId,
            client_secret: clientSecret,
            refresh_token: refreshToken,
            grant_type: 'refresh_token',
          }),
        });

        if (tokenRes.ok) {
          const tokens = await tokenRes.json();
          const response = NextResponse.json({ connected: true });
          response.cookies.set('google_access_token', tokens.access_token, {
            httpOnly: true,
            secure: process.env.NODE_ENV === 'production',
            sameSite: 'lax',
            maxAge: tokens.expires_in || 3600,
          });
          return response;
        }
      } catch {
        // Refresh failed
      }
    }
  }

  return NextResponse.json({ connected: false });
}

import { NextRequest, NextResponse } from 'next/server';
import { createGoogleCalendarEvent } from '@/lib/calendar-sync';
import { withCsrfProtection } from '@/lib/csrf-middleware';

export const POST = withCsrfProtection(async (request: NextRequest) => {
  try {
    const accessToken = request.cookies.get('google_access_token')?.value;

    if (!accessToken) {
      return NextResponse.json(
        { error: 'Not authenticated with Google Calendar' },
        { status: 401 },
      );
    }

    const { events } = await request.json();

    if (!Array.isArray(events)) {
      return NextResponse.json({ error: 'Invalid events data' }, { status: 400 });
    }

    // Create events in Google Calendar
    const results = [];
    for (const event of events) {
      try {
        const result = await createGoogleCalendarEvent(accessToken, event);
        results.push({ success: true, eventId: event.id, googleEventId: result.id });
      } catch (error) {
        results.push({ success: false, eventId: event.id, error: String(error) });
      }
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      message: `Synced ${successCount} events, ${failureCount} failed`,
      results,
    });
  } catch (error) {
    console.error('Google Calendar sync error:', error);
    return NextResponse.json({ error: 'Failed to sync with Google Calendar' }, { status: 500 });
  }
});

import { NextRequest, NextResponse } from 'next/server';
import { validateRestrictedOrgFromRequest } from '@/lib/restricted-org';

export async function GET(request: NextRequest) {
  const validation = await validateRestrictedOrgFromRequest(request);

  if (!validation.allowed) {
    return NextResponse.json(validation.body, { status: validation.status });
  }

  const searchParams = request.nextUrl.searchParams;
  const code = searchParams.get('code');

  if (!code) {
    return NextResponse.json({ error: 'No authorization code' }, { status: 400 });
  }

  const clientId = process.env.MICROSOFT_CLIENT_ID;
  const clientSecret = process.env.MICROSOFT_CLIENT_SECRET;
  const redirectUri = `${process.env.NEXT_PUBLIC_APP_URL}/api/calendar/outlook/auth`;

  if (!clientId || !clientSecret) {
    return NextResponse.json({ error: 'Microsoft OAuth not configured' }, { status: 500 });
  }

  try {
    // Exchange code for access token
    const tokenResponse = await fetch(
      'https://login.microsoftonline.com/common/oauth2/v2.0/token',
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          code,
          client_id: clientId,
          client_secret: clientSecret,
          redirect_uri: redirectUri,
          grant_type: 'authorization_code',
        }),
      },
    );

    if (!tokenResponse.ok) {
      const error = await tokenResponse.text();
      console.error('Token exchange failed:', error);
      throw new Error('Failed to exchange code for token');
    }

    const tokenData = await tokenResponse.json();

    // Redirect back with success
    const response = NextResponse.redirect(
      new URL('/dashboard?outlook_calendar=connected', request.url),
    );

    // Set HTTP-only cookie with access token
    response.cookies.set('outlook_access_token', tokenData.access_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 3600, // 1 hour
    });

    // Set HTTP-only cookie with refresh token
    if (tokenData.refresh_token) {
      response.cookies.set('outlook_refresh_token', tokenData.refresh_token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 30 * 24 * 60 * 60, // 30 days
      });
    }

    return response;
  } catch (error) {
    console.error('Microsoft OAuth error:', error);
    return NextResponse.redirect(new URL('/dashboard?error=outlook_auth_failed', request.url));
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createOutlookCalendarEvent } from '@/lib/calendar-sync';
import { validateRestrictedOrgFromRequest } from '@/lib/restricted-org';
import { withCsrfProtection } from '@/lib/csrf-middleware';

export const POST = withCsrfProtection(async (request: NextRequest) => {
  try {
    const validation = await validateRestrictedOrgFromRequest(request);

    if (!validation.allowed) {
      return NextResponse.json(validation.body, { status: validation.status });
    }

    const accessToken = request.cookies.get('outlook_access_token')?.value;

    if (!accessToken) {
      return NextResponse.json(
        { error: 'Not authenticated with Outlook Calendar' },
        { status: 401 },
      );
    }

    const { events } = await request.json();

    if (!Array.isArray(events)) {
      return NextResponse.json({ error: 'Invalid events data' }, { status: 400 });
    }

    // Create events in Outlook Calendar
    const results = [];
    for (const event of events) {
      try {
        const result = await createOutlookCalendarEvent(accessToken, event);
        results.push({ success: true, eventId: event.id, outlookEventId: result.id });
      } catch (error) {
        results.push({ success: false, eventId: event.id, error: String(error) });
      }
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      message: `Synced ${successCount} events, ${failureCount} failed`,
      results,
    });
  } catch (error) {
    console.error('Outlook Calendar sync error:', error);
    return NextResponse.json({ error: 'Failed to sync with Outlook Calendar' }, { status: 500 });
  }
});

