    };

    return NextResponse.json(context);
  } catch (error) {
    console.error('Context error:', error);
    return NextResponse.json({ error: 'Failed to get context' }, { status: 500 });
  }
}

/**
 * AI Task Creation API with Conflict Detection
 *
 * Проверяет конфликты при создании задачи:
 * - Дедлайн во время отпуска исполнителя
 * - Задача назначена человеку в отпуске
 * - Пересечение с другими задачами
 *
 * Возвращает human-readable сообщения для AI
 */

import { NextRequest, NextResponse } from 'next/server';
import { ConvexHttpClient } from 'convex/browser';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { getServerConvexAuth } from '@/lib/server-convex-auth';
import { logger } from '@/lib/logger';

export const POST = withCsrfProtection(async (req: NextRequest) => {
  try {
    const auth = await getServerConvexAuth();
    if (!auth) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { title, description, assignedTo, priority, deadline, tags } = await req.json();

    // Creator identity comes from the trusted session, never the request body
    const assignedBy = auth.payload.userId as Id<'users'>;
    const organizationId = auth.payload.organizationId as Id<'organizations'> | undefined;

    logger.log('[create-task] Request:', {
      assignedBy,
      organizationId,
      title,
      assignedTo,
      deadline,
    });

    if (!organizationId || !title || !assignedTo || !priority) {
      return NextResponse.json(
        {
          error: 'Missing required fields: title, assignedTo, priority',
        },
        { status: 400 },
      );
    }

    const convex = new ConvexHttpClient(process.env.NEXT_PUBLIC_CONVEX_URL!);
    convex.setAuth(auth.token);

    // ═══════════════════════════════════════════════════════════════
    // CONFLICT DETECTION — Check task conflicts
    // ═══════════════════════════════════════════════════════════════
    let conflictResult: {
      hasCritical: boolean;
      hasWarnings: boolean;
      conflicts: Array<{
        severity?: string;
        title?: string;
        message?: string;
        suggestion?: string;
      }>;
    } = {
      hasCritical: false,
      hasWarnings: false,
      conflicts: [],
    };

    if (deadline) {
      // Проверяем конфликты задачи с отпусками
      const conflictData: {
        hasCritical: boolean;
        hasWarnings?: boolean;
        conflicts: Array<{
          severity?: string;
          title?: string;
          message?: string;
          suggestion?: string;
        }>;
      } = await convex.query(api.conflicts.checkConflictsForRequest, {
        organizationId: organizationId,
        requestType: 'task' as const,
        userId: assignedTo as Id<'users'>,
        startDate: Date.now(),
        endDate: new Date(deadline).getTime(),
        metadata: {
          assigneeId: assignedTo as Id<'users'>,
          taskId: undefined,
        },
      });
      // Merge conflict data
      conflictResult = {
        hasCritical: conflictData.hasCritical || false,
        hasWarnings: conflictData.hasWarnings || false,
        conflicts: conflictData.conflicts || [],
      };
    }

    // Если есть критические конфликты — предупреждаем, но не блокируем
    const warnings: string[] = [];
    if (conflictResult.conflicts.length > 0) {
      conflictResult.conflicts.forEach((c) => {
        warnings.push(`${c.title}: ${c.message}`);
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // CREATE TASK
    // ═══════════════════════════════════════════════════════════════
    const taskId = await convex.mutation(api.tasks.createTask, {
      title,
      description: description || '',
      assignedTo: assignedTo as Id<'users'>,
      assignedBy: assignedBy as Id<'users'>,
      priority: priority as 'low' | 'medium' | 'high' | 'urgent',
      deadline: deadline ? new Date(deadline).getTime() : undefined,
      tags: tags || [],
    });

    logger.log('[create-task] Task created:', taskId);

    // Формируем ответ с учётом предупреждений
    let message = `✅ Task "${title}" has been created and assigned.`;

    if (warnings.length > 0) {
      message += `\n\n⚠️ **Potential conflicts detected**:\n`;
      warnings.forEach((w) => {
        message += `\n• ${w}`;
      });
      message += `\n\n💡 Consider adjusting the deadline or reassigning the task.`;
    }

    return NextResponse.json({
      success: true,
      taskId,
      message,
      hasWarnings: warnings.length > 0,
      warnings,
      conflicts: conflictResult.conflicts,
    });
  } catch (error: unknown) {
    console.error('[create-task] Error:', error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to create task' },
      { status: 500 },
    );
  }
});

/**
 * GET endpoint for quick task conflict check
 */
export async function GET(req: NextRequest) {
  try {
    const auth = await getServerConvexAuth();
    if (!auth) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(req.url);
    const userId = searchParams.get('userId');
    const organizationId = searchParams.get('organizationId');
    const assigneeId = searchParams.get('assigneeId');
    const deadline = searchParams.get('deadline');

    if (!userId || !organizationId || !assigneeId || !deadline) {
      return NextResponse.json({ error: 'Missing required query params' }, { status: 400 });
    }

    const convex = new ConvexHttpClient(process.env.NEXT_PUBLIC_CONVEX_URL!);
    convex.setAuth(auth.token);

    const conflictResult = await convex.query(api.conflicts.checkConflictsForRequest, {
      organizationId: organizationId as Id<'organizations'>,
      requestType: 'task' as const,
      userId: userId as Id<'users'>,
      startDate: Date.now(),
      endDate: parseInt(deadline),
      metadata: {
        assigneeId: assigneeId as Id<'users'>,
      },
    });

    const aiFriendlyMessage = formatTaskConflictsForAI(conflictResult.conflicts);

    return NextResponse.json({
      success: true,
      hasConflicts: conflictResult.conflicts.length > 0,
      hasCriticalConflicts: conflictResult.hasCritical,
      conflictCount: conflictResult.conflicts.length,
      aiMessage: aiFriendlyMessage,
      conflicts: conflictResult.conflicts,
    });
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Failed to check conflicts';
    console.error('[task-conflict-check] Error:', msg);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}

/**
 * Форматирует конфликты задач в human-readable сообщения для AI
 */
function formatTaskConflictsForAI(
  conflicts: Array<{ severity?: string; title?: string; message?: string; suggestion?: string }>,
): string {
  if (conflicts.length === 0) {
    return '✅ Конфликтов не обнаружено. Задачу можно создавать.';
  }

  let message = '⚠️ **Обнаружены потенциальные конфликты**:\n\n';

  conflicts.forEach((c, i) => {
    message += `${i + 1}. **${c.title}**\n`;
    message += `   ${c.message}\n`;
    message += `   💡 ${c.suggestion}\n\n`;
  });

  message += '\n📋 **Рекомендация AI**: ';
  message += 'Рассмотрите возможность переноса дедлайна или назначения другого исполнителя.';

  return message;
}

import { NextResponse } from 'next/server';
import { fetchMutation, fetchQuery } from 'convex/nextjs';
import { api } from '../../../../../convex/_generated/api';
import type { Id } from '../../../../../convex/_generated/dataModel';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { cookies } from 'next/headers';
import { getServerTranslation } from '@/lib/i18n/server-translation';
import { getServerConvexAuth } from '@/lib/server-convex-auth';

export const POST = withCsrfProtection(async (req: Request) => {
  try {
    const cookieStore = await cookies();
    const locale = cookieStore.get('i18nextLng')?.value || 'en';
    const { t } = await getServerTranslation('common', locale);

    const auth = await getServerConvexAuth();
    if (!auth) {
      return NextResponse.json({ success: false, message: 'Not authenticated' }, { status: 401 });
    }
    const requesterId = auth.payload.userId;
    const convexAuth = { token: auth.token };

    const body = await req.json();
    const leaveId: string = body.leaveId ?? '';
    const searchEmployeeName: string = body.employeeName ?? '';
    const searchStartDate: string = body.startDate ?? '';
    const searchEndDate: string = body.endDate ?? '';
    const searchLeaveType: string = body.leaveType ?? '';

    // Fetch all data
    const allLeaves = await fetchQuery(api.leaves.getAllLeaves, {}, convexAuth);
    const allUsers = await fetchQuery(api.users.queries.getAllUsers, {}, convexAuth);

    // Find leave by ID first
    let targetLeave = allLeaves.find((l) => l._id === leaveId);

    // If not found by ID — search by employee name + dates
    if (!targetLeave) {
      targetLeave = allLeaves.find((l) => {
        const leaveUser = allUsers.find((u) => u._id === l.userId);
        const nameOk = searchEmployeeName
          ? leaveUser?.name?.toLowerCase().includes(searchEmployeeName.toLowerCase())
          : true;
        const startOk = searchStartDate ? l.startDate === searchStartDate : true;
        const endOk = searchEndDate ? l.endDate === searchEndDate : true;
        const typeOk = searchLeaveType ? l.type === searchLeaveType : true;
        return nameOk && startOk && endOk && typeOk;
      });
    }

    if (!targetLeave) {
      const preview = allLeaves
        .slice(0, 5)
        .map((l) => {
          const u = allUsers.find((u) => u._id === l.userId);
          return `${u?.name ?? '?'}: ${l.type} ${l.startDate}→${l.endDate} [${l._id}]`;
        })
        .join(', ');
      return NextResponse.json({
        success: false,
        message: t('aiMessages.leaveNotFound', { preview }),
      });
    }

    // Find requester
    const requester = allUsers.find((u) => u._id === requesterId);
    if (!requester) {
      return NextResponse.json({ success: false, message: 'Requester not found' });
    }

    const isAdmin = requester.role === 'admin';
    const isOwner = targetLeave.userId === requesterId;

    if (!isAdmin && !isOwner) {
      return NextResponse.json({
        success: false,
        message: '❌ You can only delete your own leave requests.',
      });
    }

    const ownerUser = allUsers.find((u) => u._id === targetLeave.userId);
    const ownerName = ownerUser?.name ?? 'Employee';

    await fetchMutation(
      api.leaves.deleteLeave,
      {
        leaveId: targetLeave._id as Id<'leaveRequests'>,
      },
      convexAuth,
    );

    return NextResponse.json({
      success: true,
      message: t('aiMessages.leaveDeleted', {
        owner: isAdmin && !isOwner ? ownerName : '',
        type: targetLeave.type,
        start: targetLeave.startDate,
        end: targetLeave.endDate,
        balanceNote: targetLeave.status === 'approved' ? t('aiMessages.leaveDeletedBalance') : '',
      }),
    });
  } catch (error: unknown) {
    return NextResponse.json({
      success: false,
      message: error instanceof Error ? error.message : 'Failed to delete leave',
    });
  }
});

import { NextResponse } from 'next/server';
import { fetchMutation, fetchQuery } from 'convex/nextjs';
import { api } from '../../../../../convex/_generated/api';
import type { Id } from '../../../../../convex/_generated/dataModel';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { cookies } from 'next/headers';
import { getServerTranslation } from '@/lib/i18n/server-translation';
import { getServerConvexAuth } from '@/lib/server-convex-auth';

export const POST = withCsrfProtection(async (req: Request) => {
  try {
    const cookieStore = await cookies();
    const locale = cookieStore.get('i18nextLng')?.value || 'en';
    const { t } = await getServerTranslation('common', locale);

    const auth = await getServerConvexAuth();
    if (!auth) {
      return NextResponse.json({ success: false, message: 'Not authenticated' }, { status: 401 });
    }
    const requesterId = auth.payload.userId;
    const convexAuth = { token: auth.token };

    const { leaveId, startDate, endDate, days, reason, type } = await req.json();

    if (!leaveId) {
      return NextResponse.json({ success: false, message: 'Missing leaveId' }, { status: 400 });
    }

    // Get the leave to validate
    const leaves = await fetchQuery(api.leaves.getAllLeaves, {}, convexAuth);
    const leave = leaves.find((l) => l._id === leaveId);

    if (!leave) {
      return NextResponse.json({ success: false, message: 'Leave request not found' });
    }

    // Get requester
    const users = await fetchQuery(api.users.queries.getAllUsers, {}, convexAuth);
    const requester = users.find((u) => u._id === requesterId);

    if (!requester) {
      return NextResponse.json({ success: false, message: 'User not found' });
    }

    const isAdmin = requester.role === 'admin';
    const isOwner = leave.userId === requesterId;

    if (!isAdmin && !isOwner) {
      return NextResponse.json({
        success: false,
        message:
          "❌ You can only edit your own leave requests. You don't have permission to edit other employees' leaves.",
      });
    }

    if (!isAdmin && leave.status !== 'pending') {
      return NextResponse.json({
        success: false,
        message: t('aiMessages.leaveCannotEdit', { status: leave.status }),
      });
    }

    await fetchMutation(
      api.leaves.updateLeave,
      {
        leaveId: leaveId as Id<'leaveRequests'>,
        ...(startDate && { startDate }),
        ...(endDate && { endDate }),
        ...(days && { days }),
        ...(reason && { reason }),
        ...(type && { type }),
      },
      convexAuth,
    );

    return NextResponse.json({
      success: true,
      message: t('aiMessages.leaveUpdated', {
        adminNote: isAdmin && !isOwner ? t('aiMessages.leaveUpdatedAdmin') : '',
      }),
    });
  } catch (error: unknown) {
    return NextResponse.json({
      success: false,
      message: error instanceof Error ? error.message : 'Failed to update leave request',
    });
  }
});

