    workbook.creator = 'HR System';
    workbook.created = new Date();

    const worksheet = workbook.addWorksheet('Payroll Report', {
      properties: { tabColor: { argb: '2563EB' } },
    });

    worksheet.columns = [
      { header: 'Employee', key: 'employee', width: 25 },
      { header: 'Email', key: 'email', width: 30 },
      { header: 'Period', key: 'period', width: 15 },
      { header: 'Base Salary', key: 'baseSalary', width: 15 },
      { header: 'Gross Salary', key: 'grossSalary', width: 15 },
      { header: 'Net Salary', key: 'netSalary', width: 15 },
      { header: 'Bonuses', key: 'bonuses', width: 12 },
      { header: 'Overtime Pay', key: 'overtimePay', width: 15 },
      { header: 'Income Tax', key: 'incomeTax', width: 12 },
      { header: 'Social Security', key: 'socialSecurity', width: 15 },
      { header: 'Total Deductions', key: 'totalDeductions', width: 15 },
      { header: 'Status', key: 'status', width: 12 },
      { header: 'Created At', key: 'createdAt', width: 20 },
    ];

    const headerRow = worksheet.getRow(1);
    headerRow.font = { bold: true, color: { argb: 'FFFFFF' } };
    headerRow.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: '2563EB' },
    };
    headerRow.alignment = { vertical: 'middle', horizontal: 'center' };

    records.forEach((record) => {
      worksheet.addRow({
        employee: record.user?.name || 'Unknown',
        email: record.user?.email || '',
        period: record.period,
        baseSalary: record.baseSalary,
        grossSalary: record.grossSalary,
        netSalary: record.netSalary,
        bonuses: record.bonuses || 0,
        overtimePay: record.overtimePay || 0,
        incomeTax: record.deductions?.incomeTax || 0,
        socialSecurity: record.deductions?.socialSecurity || 0,
        totalDeductions: record.deductions?.total || 0,
        status: record.status,
        createdAt: new Date(record.createdAt).toLocaleDateString(),
      });
    });

    worksheet.eachRow((row, rowNumber) => {
      if (rowNumber > 1) {
        row.eachCell((cell) => {
          cell.border = {
            top: { style: 'thin' },
            left: { style: 'thin' },
            bottom: { style: 'thin' },
            right: { style: 'thin' },
          };
        });
      }
    });

    const totalGross = records.reduce((sum: number, r) => sum + r.grossSalary, 0);
    const totalNet = records.reduce((sum: number, r) => sum + r.netSalary, 0);
    const totalDeductions = records.reduce((sum: number, r) => sum + (r.deductions?.total || 0), 0);

    worksheet.addRow([]);
    const totalsRow = worksheet.addRow({ employee: 'TOTALS' });
    totalsRow.font = { bold: true };
    totalsRow.getCell('grossSalary').value = totalGross;
    totalsRow.getCell('grossSalary').font = { bold: true };
    totalsRow.getCell('netSalary').value = totalNet;
    totalsRow.getCell('netSalary').font = { bold: true };
    totalsRow.getCell('totalDeductions').value = totalDeductions;
    totalsRow.getCell('totalDeductions').font = { bold: true };

    const buffer = await workbook.xlsx.writeBuffer();

    const filename = `payroll-report-${period || 'all'}-${new Date().toISOString().slice(0, 10)}.xlsx`;

    return new NextResponse(buffer, {
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="${filename}"`,
      },
    });
  } catch (error) {
    console.error('Payroll export error:', error);
    return NextResponse.json({ error: 'Failed to export payroll data' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { auth } from '@/auth';
import { signJWT, verifyJWT, type JWTPayload } from '@/lib/jwt';
import { cookies } from 'next/headers';
import { withCsrfProtection } from '@/lib/csrf-middleware';

export const POST = withCsrfProtection(async (request: NextRequest) => {
  try {
    const { userId, name, email } = await request.json();

    if (!userId || !name || !email) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    const cookieStore = await cookies();
    let jwt = cookieStore.get('hr-auth-token')?.value;

    if (!jwt) {
      const session = await auth();

      if (!session?.user) {
        return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
      }

      jwt = await signJWT({
        userId: session.user.id || userId,
        name: session.user.name || name,
        email: session.user.email || email,
        role: (session.user.role as JWTPayload['role']) || 'employee',
        department: session.user.department,
        position: session.user.position,
        employeeType: session.user.employeeType as JWTPayload['employeeType'],
        avatar: session.user.avatar,
      });
    }

    if (!jwt) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
    }

    const payload = await verifyJWT(jwt);

    if (!payload) {
      return NextResponse.json({ error: 'Invalid token' }, { status: 401 });
    }

    const newJwt = await signJWT({
      userId: payload.userId,
      name,
      email,
      role: payload.role,
      department: payload.department,
      position: payload.position,
      employeeType: payload.employeeType,
      avatar: payload.avatar,
    });

    const response = NextResponse.json({ success: true });

    response.cookies.set('hr-auth-token', newJwt, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60,
      path: '/',
    });

    return response;
  } catch (error) {
    console.error('[/api/profile/update] Error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
});

import { NextRequest, NextResponse } from 'next/server';
import { getServerConvexAuth } from '@/lib/server-convex-auth';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL!;

async function convexQuery(path: string, args: Record<string, unknown>, token?: string) {
  const res = await fetch(`${CONVEX_URL}/api/query`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: JSON.stringify({ path, args }),
  });
  const data = await res.json();
  if (data.status === 'error') return null;
  return data.value;
}

function euclideanDistance(a: number[], b: number[]): number {
  if (a.length !== b.length) return 999;
  return Math.sqrt(a.reduce((sum, v, i) => sum + (v - (b[i] ?? 0)) ** 2, 0));
}

export async function POST(req: NextRequest) {
  // SECURITY: Require authentication — user can only verify their own face
  const auth = await getServerConvexAuth();
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }
  const authenticatedUserId = auth.payload.userId;

  try {
    const { userId, descriptor } = await req.json();

    if (!userId || !descriptor) {
      return NextResponse.json({ error: 'Missing userId or descriptor' }, { status: 400 });
    }

    // SECURITY: Users can only verify their own face data
    if (userId !== authenticatedUserId) {
      return NextResponse.json(
        { error: 'Forbidden. You can only verify your own face data.' },
        { status: 403 },
      );
    }

    // Get stored face descriptor
    const profile = await convexQuery('faceRecognition:getFaceDescriptor', { userId }, auth.token);

    if (!profile?.faceDescriptor) {
      // No face registered → skip verification (allow)
      return NextResponse.json({ match: true, reason: 'no_face_registered' });
    }

    const distance = euclideanDistance(descriptor, profile.faceDescriptor);
    const THRESHOLD = 0.5; // lower = stricter. 0.4-0.6 is typical

    return NextResponse.json({
      match: distance <= THRESHOLD,
      distance,
      threshold: THRESHOLD,
    });
  } catch (err: unknown) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : String(err) },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { jwtVerify } from 'jose';
import { withCsrfProtection } from '@/lib/csrf-middleware';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL!;

async function convexMutation(path: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, args }),
  });
  const data = await res.json();
  if (data.status === 'error') throw new Error(data.errorMessage ?? 'Convex error');
  return data.value;
}

/**
 * Verify JWT auth token.
 */
async function verifyAuth(): Promise<{ userId: string; role: string } | null> {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get('hr-auth-token') || cookieStore.get('oauth-session');
    if (!token) return null;

    const jwtSecret = process.env.JWT_SECRET;
    if (!jwtSecret) return null;

    const secret = new TextEncoder().encode(jwtSecret);
    const { payload } = await jwtVerify(token.value, secret);
    return { userId: payload.sub as string, role: (payload.role as string) || 'employee' };
  } catch {
    return null;
  }
}

export const POST = withCsrfProtection(async (req: NextRequest) => {
  // SECURITY: Require authentication
  const auth = await verifyAuth();
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId, event, details } = await req.json();
    if (!userId || !event) {
      return NextResponse.json({ error: 'Missing userId or event' }, { status: 400 });
    }

    await convexMutation('security:logLoginAttempt', {
      email: '',
      userId,
      success: false,
      method: 'password',
      blockedReason: `${event}: ${details ?? ''}`,
      ip: req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown',
      userAgent: req.headers.get('user-agent') ?? undefined,
      riskScore: 90,
      riskFactors: [event],
    });

    return NextResponse.json({ success: true });
  } catch (err: unknown) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : String(err) },
      { status: 500 },
    );
  }
});

