import { NextRequest, NextResponse } from 'next/server';
import { ConvexHttpClient } from 'convex/browser';
import { api } from '@/convex/_generated/api';
import { Id } from '@/convex/_generated/dataModel';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { getServerConvexAuth } from '@/lib/server-convex-auth';

/**
 * Quick Security Action API
 * Allows superadmin to quickly suspend/unsuspend users from notifications
 */
export const POST = withCsrfProtection(async (req: NextRequest) => {
  try {
    const auth = await getServerConvexAuth();
    if (!auth) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
    }

    const convex = new ConvexHttpClient(process.env.NEXT_PUBLIC_CONVEX_URL!);
    convex.setAuth(auth.token);

    const { action, userId, reason, duration } = await req.json();

    if (!action || !userId) {
      return NextResponse.json(
        { error: 'Missing required fields: action, userId' },
        { status: 400 },
      );
    }

    // Validate action type
    if (!['suspend', 'unsuspend'].includes(action)) {
      return NextResponse.json(
        { error: "Invalid action. Must be 'suspend' or 'unsuspend'" },
        { status: 400 },
      );
    }

    let result;

    if (action === 'suspend') {
      if (!reason) {
        return NextResponse.json({ error: 'Reason is required for suspension' }, { status: 400 });
      }

      result = await convex.mutation(api.users.admin.suspendUser, {
        userId: userId as Id<'users'>,
        reason,
        duration: duration || 24, // Default 24 hours
      });

      return NextResponse.json({
        success: true,
        message: `User suspended for ${duration || 24} hours`,
        data: result,
      });
    } else {
      // unsuspend
      result = await convex.mutation(api.users.admin.unsuspendUser, {
        userId: userId as Id<'users'>,
      });

      return NextResponse.json({
        success: true,
        message: 'User unsuspended successfully',
        data: result,
      });
    }
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Failed to perform action';
    console.error('[Quick Action API Error]:', msg);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
});

import { NextRequest, NextResponse } from 'next/server';
import { refreshSharePointToken } from '@/lib/sharepoint-sync';
import { validateRestrictedOrgFromRequest } from '@/lib/restricted-org';

export async function GET(request: NextRequest) {
  const validation = await validateRestrictedOrgFromRequest(request);

  if (!validation.allowed) {
    return NextResponse.json(validation.body, { status: validation.status });
  }

  const accessToken = request.cookies.get('sharepoint_access_token')?.value;
  const refreshToken = request.cookies.get('sharepoint_refresh_token')?.value;

  if (!accessToken && !refreshToken) {
    return NextResponse.json({ connected: false });
  }

  // Verify access token by calling Graph API
  if (accessToken) {
    try {
      const res = await fetch('https://graph.microsoft.com/v1.0/me', {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (res.ok) {
        const profile = await res.json();
        return NextResponse.json({
          connected: true,
          email: profile.mail || profile.userPrincipalName,
        });
      }
    } catch {
      // Token might be expired, fall through to refresh
    }
  }

  // Try to refresh the token
  if (refreshToken) {
    try {
      const tokens = await refreshSharePointToken(refreshToken);
      const response = NextResponse.json({ connected: true });

      response.cookies.set('sharepoint_access_token', tokens.access_token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: tokens.expires_in || 3600,
      });

      if (tokens.refresh_token) {
        response.cookies.set('sharepoint_refresh_token', tokens.refresh_token, {
          httpOnly: true,
          secure: process.env.NODE_ENV === 'production',
          sameSite: 'lax',
          maxAge: 60 * 60 * 24 * 365,
        });
      }

      return response;
    } catch {
      // Refresh failed
    }
  }

  return NextResponse.json({ connected: false });
}

import { NextRequest, NextResponse } from 'next/server';
import { fetchSharePointListItems, refreshSharePointToken } from '@/lib/sharepoint-sync';
import type { SharePointSyncResult } from '@/lib/sharepoint-sync';
import { validateRestrictedOrgFromRequest } from '@/lib/restricted-org';
import { withCsrfProtection } from '@/lib/csrf-middleware';

const CONVEX_URL = process.env.NEXT_PUBLIC_CONVEX_URL;

async function convexMutation(path: string, args: Record<string, unknown>) {
  const res = await fetch(`${CONVEX_URL}/api/mutation`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, args }),
  });
  const data = await res.json();
  if (data.status === 'error') throw new Error(data.errorMessage ?? 'Convex error');
  return data.value;
}

export const POST = withCsrfProtection(async (request: NextRequest) => {
  try {
    const validation = await validateRestrictedOrgFromRequest(request);

    if (!validation.allowed) {
      return NextResponse.json(validation.body, { status: validation.status });
    }

    const { adminId, organizationId } = await request.json();

    if (!adminId || !organizationId) {
      return NextResponse.json(
        { error: 'adminId and organizationId are required' },
        { status: 400 },
      );
    }

    // Get access token from cookies (try refresh if expired)
    let accessToken = request.cookies.get('sharepoint_access_token')?.value;
    const refreshToken = request.cookies.get('sharepoint_refresh_token')?.value;

    if (!accessToken && !refreshToken) {
      return NextResponse.json({ error: 'Not connected to SharePoint' }, { status: 401 });
    }

    // Try to refresh token if access token is missing
    let newTokens: {
      access_token: string;
      refresh_token?: string;
      expires_in?: number;
    } | null = null;
    if (!accessToken && refreshToken) {
      try {
        newTokens = await refreshSharePointToken(refreshToken);
        accessToken = newTokens.access_token;
      } catch {
        return NextResponse.json(
          { error: 'SharePoint token expired, please reconnect' },
          { status: 401 },
        );
      }
    }

    // Fetch employees from SharePoint
    const employees = await fetchSharePointListItems(accessToken!);

    const result: SharePointSyncResult = {
      created: 0,
      updated: 0,
      deactivated: 0,
      errors: [],
    };

    // Upsert each employee
    for (const emp of employees) {
      try {
        const upsertResult = await convexMutation('sharepointSync:upsertSharePointUser', {
          adminId,
          organizationId,
          email: emp.email,
          name: emp.name,
          department: emp.department,
          position: emp.position,
          phone: emp.phone,
          location: emp.location,
          employeeType: emp.employeeType,
        });

        if (upsertResult.action === 'created') {
          result.created++;
        } else {
          result.updated++;
        }
      } catch (err) {
        result.errors.push(
          `Failed to sync ${emp.email}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }

    // Deactivate users no longer in SharePoint
    try {
      const activeEmails = employees.map((e) => e.email);
      const deactivateResult = await convexMutation('sharepointSync:deactivateSharePointUsers', {
        adminId,
        organizationId,
        activeEmails,
      });
      result.deactivated = deactivateResult.deactivated;
    } catch (err) {
      result.errors.push(
        `Failed to deactivate: ${err instanceof Error ? err.message : String(err)}`,
      );
    }

    // Log the sync
    try {
      await convexMutation('sharepointSync:logSync', {
        organizationId,
        triggeredBy: adminId,
        created: result.created,
        updated: result.updated,
        deactivated: result.deactivated,
        errors: result.errors.length,
      });
    } catch {
      // Non-critical — don't fail the sync if logging fails
    }

    // Build response (optionally set refreshed cookies)
    const response = NextResponse.json(result);

    if (newTokens) {
      response.cookies.set('sharepoint_access_token', newTokens.access_token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: newTokens.expires_in || 3600,
      });
      if (newTokens.refresh_token) {
        response.cookies.set('sharepoint_refresh_token', newTokens.refresh_token, {
          httpOnly: true,
          secure: process.env.NODE_ENV === 'production',
          sameSite: 'lax',
          maxAge: 60 * 60 * 24 * 365,
        });
      }
    }

    return response;
  } catch (error) {
    console.error('SharePoint sync error:', error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Sync failed' },
      { status: 500 },
    );
  }
});

import { NextRequest, NextResponse } from 'next/server';
import Stripe from 'stripe';
import { isValidEmail } from '@/lib/stripe-config';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { verifyJWT } from '@/lib/jwt';

async function verifyAdmin(req: NextRequest): Promise<boolean> {
  try {
    const cookieHeader = req.headers.get('cookie') || '';
    const jwtMatch = cookieHeader.match(/hr-auth-token=([^;]+)/);
    const jwt = jwtMatch ? jwtMatch[1] : null;
    if (!jwt) return false;
    const payload = await verifyJWT(jwt);
    if (!payload) return false;
    return payload.role === 'admin' || payload.role === 'superadmin';
  } catch {
    return false;
  }
}

function getStripe(): Stripe | null {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return null;
  return new Stripe(key, { apiVersion: '2026-02-25.clover' });
}

const PLANS: Record<string, { priceId: string; name: string }> = {
  starter: { priceId: process.env.STRIPE_PRICE_STARTER!, name: 'Starter' },
  professional: { priceId: process.env.STRIPE_PRICE_PROFESSIONAL!, name: 'Professional' },
  enterprise: { priceId: process.env.STRIPE_PRICE_ENTERPRISE!, name: 'Enterprise' },
};

export const POST = withCsrfProtection(async (req: NextRequest) => {
  if (!(await verifyAdmin(req))) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const stripe = getStripe();
  if (!stripe) {
    return NextResponse.json(
      { error: 'Stripe not configured', message: 'STRIPE_SECRET_KEY is not set' },
      { status: 503 },
    );
  }

  try {
    const { plan, email, organizationId } = await req.json();

    if (!plan || !PLANS[plan]) {
      return NextResponse.json({ error: 'Invalid plan' }, { status: 400 });
    }

    // Validate email if provided
    if (email && !isValidEmail(email)) {
      return NextResponse.json({ error: 'Invalid email format' }, { status: 400 });
    }

    const priceId = PLANS[plan].priceId;
    if (!priceId || priceId.startsWith('prod_')) {
      console.error(
        `[Stripe Checkout] Invalid price ID for plan "${plan}": "${priceId}". Must be a price_... ID, not a prod_... ID.`,
      );
      return NextResponse.json(
        {
          error: `Stripe price ID for plan "${plan}" is not configured correctly. Expected a price_... ID.`,
        },
        { status: 500 },
      );
    }

    const origin =
      req.headers.get('origin') ?? process.env.NEXT_PUBLIC_URL ?? 'http://localhost:3000';

    const session = await stripe.checkout.sessions.create({
      mode: 'subscription',
      payment_method_types: ['card'],
      line_items: [
        {
          price: PLANS[plan].priceId,
          quantity: 1,
        },
      ],
      customer_email: email ?? undefined,
      allow_promotion_codes: true,
      billing_address_collection: 'auto',
      subscription_data: {
        trial_period_days: 14,
        metadata: { plan, organizationId: organizationId ?? '' },
      },
      success_url: `${origin}/checkout/success?session_id={CHECKOUT_SESSION_ID}&plan=${plan}`,
      cancel_url: `${origin}/#pricing`,
      metadata: { plan, organizationId: organizationId ?? '' },
      client_reference_id: organizationId ?? undefined,
    });

    return NextResponse.json({ url: session.url });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Checkout failed';
    console.error('[Stripe Checkout]', msg);
    return NextResponse.json({ error: msg }, { status: 500 });
  }
});

/**
 * ⚠️ SECURITY: This endpoint previously executed shell commands via child_process.exec()
 * which is a Remote Code Execution vulnerability. It has been replaced with a safe
 * implementation that calls Node.js functions directly without shell execution.
 *
 * If you need to run npm scripts, do it via CI/CD or server-side deployment scripts,
 * NEVER through a web API endpoint.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { jwtVerify } from 'jose';
import { withCsrfProtection } from '@/lib/csrf-middleware';
import { logger } from '@/lib/logger';

const ALLOWED_SCRIPTS = [
  'stripe:view',
  'stripe:add-test-data',
  'stripe:export',
  'stripe:export-pdf',
  'stripe:growth-chart',
  'stripe:sync',
  'stripe:check-trials',
];

/**
 * Verify the user is a superadmin by checking the JWT session cookie.
 */
async function verifySuperadmin(): Promise<{ userId: string; role: string } | null> {
  try {
    const cookieStore = await cookies();
    const sessionCookie = cookieStore.get('oauth-session');
    if (!sessionCookie) return null;

    const jwtSecret = process.env.JWT_SECRET;
    if (!jwtSecret) return null;

    const secret = new TextEncoder().encode(jwtSecret);
    const { payload } = await jwtVerify(sessionCookie.value, secret);

    if (payload.role !== 'superadmin') {
      logger.warn('[Stripe Run-Script] Non-superadmin access attempt:', payload.role);
      return null;
    }

    return { userId: payload.sub as string, role: payload.role as string };
  } catch {
    return null;
  }
}

