                <FileText className="h-4 w-4 mr-1" />
                {t('onboarding.newTemplate', 'New Template')}
              </Button>
              <Button
                size="sm"
                onClick={() => {
                  const mainEl = mainRef.current;
                  if (mainEl) {
                    mainEl.scrollTo({ top: 0, behavior: 'smooth' });
