                      {/* Task stats */}
                      {obj.taskCount > 0 && (
                        <div className="mt-1.5 flex items-center gap-2 text-[10px] text-muted-foreground">
                          <span>
                            📋 {obj.completedTaskCount}/{obj.taskCount}{' '}
                            {t('tasks.title').toLowerCase()}
                          </span>
