                    )}
                    {r.improvements && (
                      <div>
                        <strong>{t('performance.fields.improvements')}:</strong> {r.improvements}
                      </div>
                    )}
                    {r.generalComments && (
                      <div>
                        <strong>{t('performance.fields.generalComments')}:</strong>{' '}
                        {r.generalComments}
