              {results.peerReviews.map((r, i) => (
                <Card key={i} className="mb-2">
                  <CardContent className="p-3 text-sm space-y-1">
                    <div>
                      <strong>{t('performance.fields.score')}:</strong> {r.overallScore}/5
                    </div>
