  const pendingAssignments =
    myAssignments?.filter((a) => a.status === 'pending' || a.status === 'in_progress') || [];

  const statusBadge = (status: string) => {
    const map: Record<
      string,
      { variant: 'default' | 'secondary' | 'destructive' | 'outline'; label: string }
