'use client';

import { createContext, useContext, useEffect, useState, useCallback, type ReactNode } from 'react';

type Theme = 'light' | 'dark' | 'system';
type ResolvedTheme = 'light' | 'dark';

interface ThemeContextValue {
  theme: Theme;
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

const STORAGE_KEY = 'theme';
const COOKIE_NAME = 'next-theme';

function getSystemTheme(): ResolvedTheme {
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function getStoredTheme(): Theme | null {
  try {
    // Try cookie first (SSR-set)
    const match = document.cookie.match(new RegExp(`(^| )${COOKIE_NAME}=([^;]+)`));
    if (match && match[2]) {
      return match[2] as Theme;
    }
    // Fall back to localStorage
    return (localStorage.getItem(STORAGE_KEY) as Theme) || null;
  } catch {
    return null;
  }
}

function applyTheme(theme: Theme) {
  const resolved = theme === 'system' ? getSystemTheme() : theme;
  const root = document.documentElement;

  if (resolved === 'dark') {
    root.classList.add('dark');
    root.classList.remove('light');
  } else {
    root.classList.add('light');
    root.classList.remove('dark');
  }
}

interface ThemeProviderProps {
  children: ReactNode;
  attribute?: string;
  defaultTheme?: Theme;
  enableSystem?: boolean;
  disableTransitionOnChange?: boolean;
}

export function ThemeProvider({
  children,
  defaultTheme = 'system',
  disableTransitionOnChange = false,
}: ThemeProviderProps) {
  const [theme, setThemeState] = useState<Theme>(defaultTheme);
  const [resolvedTheme, setResolvedTheme] = useState<ResolvedTheme>('light');

  useEffect(() => {
    const stored = getStoredTheme();
    if (stored) {
      setThemeState(stored);
      setResolvedTheme(stored === 'system' ? getSystemTheme() : stored);
    } else {
      setResolvedTheme(defaultTheme === 'system' ? getSystemTheme() : defaultTheme);
    }

    // Apply theme immediately
    const activeTheme = stored || defaultTheme;
    applyTheme(activeTheme);
  }, [defaultTheme]);

  // Listen for system theme changes
  useEffect(() => {
    if (theme !== 'system') return;

    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = () => {
      setResolvedTheme(getSystemTheme());
      applyTheme('system');
    };

    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [theme]);

  const setTheme = useCallback(
    (newTheme: Theme) => {
      setThemeState(newTheme);
      const resolved = newTheme === 'system' ? getSystemTheme() : newTheme;
      setResolvedTheme(resolved);

      if (disableTransitionOnChange) {
        const el = document.createElement('style');
        el.setAttribute('data-theme-transition', 'disabled');
        el.textContent = '*{transition:none!important;animation:none!important;}';
        document.head.appendChild(el);
        applyTheme(newTheme);
        // Defer reflow to not block main thread during page load
        // Use double rAF to ensure style has been applied before reading offsetHeight
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            document.documentElement.offsetHeight;
            el.remove();
          });
        });
      } else {
        applyTheme(newTheme);
      }

      try {
        localStorage.setItem(STORAGE_KEY, newTheme);
        document.cookie = `${COOKIE_NAME}=${newTheme};path=/;max-age=31536000;samesite=lax`;
      } catch {
        // Storage unavailable
      }
    },
    [disableTransitionOnChange],
  );

  return (
    <ThemeContext.Provider value={{ theme, resolvedTheme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (!ctx) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return ctx;
}

'use client';

import { useTranslation } from 'react-i18next';
import { useState, useEffect } from 'react';
import { useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Calendar, Download, ExternalLink, CheckCircle2, Lock } from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { toast } from 'sonner';
import {
  generateICalendar,
  downloadICalFile,
  getGoogleCalendarAuthUrl,
  getOutlookAuthUrl,
} from '@/lib/calendar-sync';
import { useUpgradeModal } from '@/components/subscription/PlanGate';
import { usePlanFeatures } from '@/hooks/usePlanFeatures';

interface HolidayCalendarSyncProps {
  organizationId?: string;
}

export default function HolidayCalendarSync({ organizationId }: HolidayCalendarSyncProps) {
  const { t } = useTranslation();
  const [isExporting, setIsExporting] = useState(false);
  const [isSyncingGoogle, setIsSyncingGoogle] = useState(false);
  const [isSyncingOutlook, setIsSyncingOutlook] = useState(false);
  const [googleConnected, setGoogleConnected] = useState(false);
  const [outlookConnected, setOutlookConnected] = useState(false);
  const calendarData = useQuery(api.admin.getCalendarExportData, {
    organizationId: organizationId as Id<'organizations'> | undefined,
  });

  // Plan gating
  const { canAccess } = usePlanFeatures();
  const hasCalendarSync = canAccess('calendarSync');
  const { openModal, modal: upgradeModal } = useUpgradeModal();

  // Check connection status on mount
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('google_calendar') === 'connected') {
      setGoogleConnected(true);
      toast.success(t('calendarSync.googleSuccess'));
      // Clean URL
      window.history.replaceState({}, '', window.location.pathname);
    }
    if (params.get('outlook_calendar') === 'connected') {
      setOutlookConnected(true);
      toast.success(t('calendarSync.outlookSuccess'));
      // Clean URL
      window.history.replaceState({}, '', window.location.pathname);
    }
    if (params.get('error')) {
      toast.error(t('calendarSync.connectionFailed', 'Failed to connect to calendar'));
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, []);

  const handleExportICS = async () => {
    if (!calendarData) return;

    setIsExporting(true);
    try {
      const icsContent = generateICalendar(calendarData);
      const filename = t('calendarSync.icsFilename', {
        date: new Date().toISOString().split('T')[0],
      });
      downloadICalFile(icsContent, filename);
      toast.success(t('calendarSync.icalDownloadSuccess', 'iCal file downloaded successfully'));
    } catch (error) {
      console.error('Export error:', error);
      toast.error(t('calendarSync.exportFailed', 'Failed to export calendar'));
    } finally {
      setIsExporting(false);
    }
  };

  const handleGoogleCalendar = async () => {
    if (googleConnected) {
      // Already connected, sync events
      if (!calendarData || calendarData.length === 0) {
        toast.info(t('calendarSync.noEventsToSync', 'No events to sync'));
        return;
      }

      setIsSyncingGoogle(true);
      try {
        const response = await fetch('/api/calendar/google/sync', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ events: calendarData }),
        });

        if (!response.ok) {
          throw new Error('Sync failed');
        }

        const result = await response.json();
        toast.success(result.message);
      } catch (error) {
        console.error('Google sync error:', error);
        toast.error(t('calendarSync.googleSyncFailed', 'Failed to sync with Google Calendar'));
        setGoogleConnected(false);
      } finally {
        setIsSyncingGoogle(false);
      }
    } else {
      // Need to authenticate
      try {
        const redirectUri = `${window.location.origin}/api/calendar/google/callback`;
        const authUrl = getGoogleCalendarAuthUrl(redirectUri);
        window.location.href = authUrl;
      } catch (error) {
        console.error('Google auth error:', error);
        toast.error(t('calendarSync.googleNotConfigured', 'Google Calendar is not configured'));
      }
    }
  };

  const handleOutlook = async () => {
    if (outlookConnected) {
      // Already connected, sync events
      if (!calendarData || calendarData.length === 0) {
        toast.info(t('calendarSync.noEventsToSync', 'No events to sync'));
        return;
      }

      setIsSyncingOutlook(true);
      try {
        const response = await fetch('/api/calendar/outlook/sync', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ events: calendarData }),
        });

        if (!response.ok) {
          throw new Error('Sync failed');
        }

        const result = await response.json();
        toast.success(result.message);
      } catch (error) {
        console.error('Outlook sync error:', error);
        toast.error(t('calendarSync.outlookSyncFailed', 'Failed to sync with Outlook Calendar'));
        setOutlookConnected(false);
      } finally {
        setIsSyncingOutlook(false);
      }
    } else {
      // Need to authenticate
      try {
        const redirectUri = `${window.location.origin}/api/calendar/outlook/callback`;
        const authUrl = getOutlookAuthUrl(redirectUri);
        window.location.href = authUrl;
      } catch (error) {
        console.error('Outlook auth error:', error);
        toast.error(t('calendarSync.outlookNotConfigured', 'Outlook Calendar is not configured'));
      }
    }
  };

  if (!calendarData) {
    return (
      <Card className="border-(--border)">
        <CardContent className="flex items-center justify-center p-8">
          <ShieldLoader size="lg" />
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      {upgradeModal}
      <Card className="border-(--border)">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5 text-blue-500" />
            {t('calendarSync.title')}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Stats */}
          <div className="rounded-lg bg-linear-to-br from-blue-500/10 to-cyan-500/10 p-4">
            <p className="text-sm text-(--text-secondary)">{t('calendarSync.upcomingLeaves')}</p>
            <p className="text-3xl font-bold text-(--text-primary)">{calendarData.length}</p>
          </div>

          {/* Export Options */}
          <div className="space-y-2">
            <h4 className="mb-2 text-sm font-semibold text-(--text-primary)">
              {t('calendarSync.exportCalendar')}
            </h4>

            <Button
              onClick={handleExportICS}
              disabled={isExporting || calendarData.length === 0}
              className="w-full justify-start"
              variant="outline"
            >
              {isExporting ? (
                <ShieldLoader size="xs" variant="inline" className="mr-2" />
              ) : (
                <Download className="mr-2 h-4 w-4" />
              )}
              {t('calendarSync.downloadIcal')}
            </Button>

            <div className="relative">
              <Button
                onClick={() => {
                  if (!hasCalendarSync) {
                    openModal({
                      featureTitle: t('calendarSync.googleCalendarSync'),
                      featureDescription: t('calendarSync.googleCalendarSyncDesc'),
                      recommendedPlan: 'professional',
                    });
                    return;
                  }
                  handleGoogleCalendar();
                }}
                className="w-full justify-start"
                variant="outline"
                disabled={isSyncingGoogle || calendarData.length === 0}
              >
                {isSyncingGoogle ? (
                  <ShieldLoader size="xs" variant="inline" className="mr-2" />
                ) : !hasCalendarSync ? (
                  <Lock className="mr-2 h-4 w-4 text-(--text-muted)" />
                ) : googleConnected ? (
                  <CheckCircle2 className="mr-2 h-4 w-4 text-green-500" />
                ) : (
                  <ExternalLink className="mr-2 h-4 w-4" />
                )}
                {googleConnected && hasCalendarSync
                  ? t('calendarSync.syncWithGoogle')
                  : t('calendarSync.connectGoogle')}
              </Button>
              {googleConnected && hasCalendarSync && (
                <Badge
                  variant="secondary"
                  className="absolute -right-2 -top-2 bg-green-500 text-white"
                >
                  {t('calendarSync.connected')}
                </Badge>
              )}
              {!hasCalendarSync && (
                <Badge
                  variant="secondary"
                  className="absolute -right-2 -top-2 bg-linear-to-r from-amber-500 to-orange-500 text-white text-[10px]"
                >
                  {t('calendarSync.pro')}
                </Badge>
              )}
            </div>

            <div className="relative">
              <Button
                onClick={() => {
                  if (!hasCalendarSync) {
                    openModal({
                      featureTitle: t('calendarSync.outlookCalendarSync'),
                      featureDescription: t('calendarSync.outlookCalendarSyncDesc'),
                      recommendedPlan: 'professional',
                    });
                    return;
                  }
                  handleOutlook();
                }}
                className="w-full justify-start"
                variant="outline"
                disabled={isSyncingOutlook || calendarData.length === 0}
              >
                {isSyncingOutlook ? (
                  <ShieldLoader size="xs" variant="inline" className="mr-2" />
                ) : !hasCalendarSync ? (
                  <Lock className="mr-2 h-4 w-4 text-(--text-muted)" />
                ) : outlookConnected ? (
                  <CheckCircle2 className="mr-2 h-4 w-4 text-green-500" />
                ) : (
                  <ExternalLink className="mr-2 h-4 w-4" />
                )}
                {outlookConnected && hasCalendarSync
                  ? t('calendarSync.syncWithOutlook')
                  : t('calendarSync.connectOutlook')}
              </Button>
              {outlookConnected && hasCalendarSync && (
                <Badge
                  variant="secondary"
                  className="absolute -right-2 -top-2 bg-green-500 text-white"
                >
                  {t('calendarSync.connected')}
                </Badge>
              )}
              {!hasCalendarSync && (
                <Badge
                  variant="secondary"
                  className="absolute -right-2 -top-2 bg-linear-to-r from-amber-500 to-orange-500 text-white text-[10px]"
                >
                  {t('calendarSync.pro')}
                </Badge>
              )}
            </div>
          </div>

          {calendarData.length === 0 && (
            <p className="text-center text-sm text-(--text-secondary)">
              {t('calendarSync.noUpcoming')}
            </p>
          )}
        </CardContent>
      </Card>
    </>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { AlertTriangle, Power, PowerOff } from 'lucide-react';
import { cn } from '@/lib/utils';
import { ShieldLoader } from '@/components/ui/ShieldLoader';

interface MaintenanceModeManagerProps {
  organizationId?: Id<'organizations'> | string;
  userId?: Id<'users'> | string;
}

export function MaintenanceModeManager({ organizationId, userId }: MaintenanceModeManagerProps) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';
  const [disabling, setDisabling] = useState(false);
  const maintenance = useQuery(
    api.admin.getMaintenanceMode,
    organizationId && userId ? { organizationId: organizationId as Id<'organizations'> } : 'skip',
  );
  const disableMaintenanceMode = useMutation(api.admin.disableMaintenanceMode);

  if (maintenance === undefined) {
    return null; // Loading
  }

  if (!maintenance?.isActive) {
    return null; // No active maintenance
  }

  const handleDisable = async () => {
    if (!organizationId || !userId) return;
    setDisabling(true);
    try {
      await disableMaintenanceMode({
        organizationId: organizationId as Id<'organizations'>,
        userId: userId as Id<'users'>,
      });
    } finally {
      setDisabling(false);
    }
  };

  const startTime = new Date(maintenance.startTime);
  const endTime = maintenance.endTime ? new Date(maintenance.endTime) : null;

  return (
    <Card className="border-destructive/30 bg-destructive/10">
      <CardHeader>
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-6 h-6 text-destructive mt-0.5" />
            <div>
              <CardTitle className="text-destructive">{t('maintenance.siteMaintenance')}</CardTitle>
              <CardDescription>{maintenance.title}</CardDescription>
            </div>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Status Message */}
        <div className="bg-destructive/10 p-3 rounded-lg border border-destructive/20">
          <p className="text-sm text-destructive">{maintenance.message}</p>
        </div>

        {/* Timeline */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <p className="text-xs text-muted-foreground font-medium">
              {t('maintenance.maintenanceStarted')}
            </p>
            <p className="text-sm font-semibold">{startTime.toLocaleString(locale)}</p>
          </div>

          {maintenance.estimatedDuration && (
            <div>
              <p className="text-xs text-muted-foreground font-medium">
                {t('maintenance.estimatedDuration')}
              </p>
              <p className="text-sm font-semibold">{maintenance.estimatedDuration}</p>
            </div>
          )}

          {endTime && (
            <div>
              <p className="text-xs text-muted-foreground font-medium">
                {t('maintenance.expectedEnd')}
              </p>
              <p className="text-sm font-semibold">{endTime.toLocaleString(locale)}</p>
            </div>
          )}
        </div>

        {/* Warning */}
        <div className="bg-warning/10 p-3 rounded-lg border border-warning/20">
          <p className="text-xs text-warning">{t('maintenance.warning')}</p>
        </div>

        {/* Action Button */}
        <Button
          onClick={handleDisable}
          disabled={disabling}
          className="w-full bg-success hover:bg-success/90 text-white gap-2"
        >
          {disabling ? (
            <>
              <ShieldLoader size="xs" variant="inline" />
              {t('maintenance.enablingSite')}
            </>
          ) : (
            <>
              <PowerOff className="w-4 h-4" />
              {t('maintenance.enableSite')}
            </>
          )}
        </Button>

        <p className="text-xs text-muted-foreground text-center">
          {t('maintenance.siteWillBeAvailable')}
        </p>
      </CardContent>
    </Card>
  );
}

'use client';

import { useTranslation } from 'react-i18next';
import { useTheme } from '@/components/ThemeProvider';
import { useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Clock, TrendingUp, AlertTriangle, CheckCircle2, XCircle, Activity } from 'lucide-react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from '@/lib/dynamic-imports';

interface SLAStatsProps {
  startDate?: number;
  endDate?: number;
  organizationId?: string;
}

function ResponseTimeSLA({ startDate, endDate, organizationId }: SLAStatsProps) {
  const { t, i18n } = useTranslation();
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';
  const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';

  const tooltipBg = isDark ? '#0f172a' : '#ffffff';
  const tooltipBorder = isDark ? 'rgba(148, 163, 184, 0.3)' : 'rgba(0, 0, 0, 0.1)';
  const tooltipColor = isDark ? '#ffffff' : '#0f172a';
  const tooltipShadow = isDark ? '0 4px 12px rgba(0, 0, 0, 0.5)' : '0 4px 12px rgba(0, 0, 0, 0.1)';
  const textColor = isDark ? '#ffffff' : '#0f172a';
  const gridStroke = isDark ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.1)';
  const axisTickFill = isDark ? 'rgba(255,255,255,0.8)' : 'rgba(0,0,0,0.6)';
  const stats = useQuery(api.sla.getSLAStats, {
    startDate,
    endDate,
    organizationId: organizationId as Id<'organizations'> | undefined,
  });
  const trend = useQuery(api.sla.getSLATrend, {
    days: 30,
    organizationId: organizationId as Id<'organizations'> | undefined,
  });
  const pendingWithSLA = useQuery(api.sla.getPendingWithSLA, {
    organizationId: organizationId as Id<'organizations'> | undefined,
  });

  if (!stats) {
    return (
      <div className="space-y-4 my-6">
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          {[1, 2, 3, 4].map((i) => (
            <Card key={i} className="animate-pulse">
              <CardHeader className="pb-2">
                <div className="h-4 bg-(--background-subtle) rounded w-24"></div>
              </CardHeader>
              <CardContent>
                <div className="h-8 bg-(--background-subtle) rounded w-16"></div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  const complianceColor =
    stats.complianceRate >= 95
      ? 'text-success'
      : stats.complianceRate >= 80
        ? 'text-warning'
        : 'text-destructive';

  return (
    <div className="space-y-6 my-6">
      {/* Key Metrics */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        {/* Compliance Rate */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">{t('responseSLA.compliance')}</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-(--text-muted)" />
          </CardHeader>
          <CardContent>
            <div className={`text-2xl font-bold ${complianceColor}`}>{stats.complianceRate}%</div>
            <p className="text-xs text-(--text-muted)">{t('responseSLA.target95')}</p>
            <Progress value={stats.complianceRate} className="mt-2" />
          </CardContent>
        </Card>

        {/* Average Response Time */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              {t('responseSLA.avgResponseTime')}
            </CardTitle>
            <Clock className="h-4 w-4 text-(--text-muted)" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.avgResponseTime}h</div>
            <p className="text-xs text-(--text-muted)">
              {t('responseSLA.target', { hours: stats.targetResponseTime })}
            </p>
            <Progress
              value={(stats.avgResponseTime / stats.targetResponseTime) * 100}
              className="mt-2"
            />
          </CardContent>
        </Card>

        {/* SLA Score */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">{t('responseSLA.avgScore')}</CardTitle>
            <TrendingUp className="h-4 w-4 text-(--text-muted)" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.avgSLAScore}/100</div>
            <p className="text-xs text-(--text-muted)">
              {t('responseSLA.onTimeBreachedShort', {
                onTime: stats.onTime,
                breached: stats.breached,
              })}
            </p>
            <Progress value={stats.avgSLAScore} className="mt-2" />
          </CardContent>
        </Card>

        {/* Alerts */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">{t('responseSLA.activeAlerts')}</CardTitle>
            <AlertTriangle className="h-4 w-4 text-(--text-muted)" />
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-sm text-(--text-muted)">{t('responseSLA.critical')}</span>
                <Badge variant="destructive">{stats.criticalCount}</Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-(--text-muted)">{t('responseSLA.warning')}</span>
                <Badge variant="secondary">{stats.warningCount}</Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Trend Chart */}
      {trend && trend.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>{t('responseSLA.performanceTrend')}</CardTitle>
            <CardDescription>{t('responseSLA.responseTimeCompliance')}</CardDescription>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={trend}>
                <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                <XAxis
                  dataKey="date"
                  tick={{ fontSize: 12, fill: axisTickFill }}
                  tickFormatter={(value) =>
                    new Date(value).toLocaleDateString(locale, { month: 'short', day: 'numeric' })
                  }
                />
                <YAxis yAxisId="left" tick={{ fill: axisTickFill }} />
                <YAxis yAxisId="right" orientation="right" tick={{ fill: axisTickFill }} />
                <Tooltip
                  labelFormatter={(value) => new Date(value).toLocaleDateString(locale)}
                  contentStyle={{
                    background: tooltipBg,
                    border: `1px solid ${tooltipBorder}`,
                    borderRadius: '8px',
                    color: tooltipColor,
                    boxShadow: tooltipShadow,
                  }}
                  itemStyle={{ color: tooltipColor }}
                  labelStyle={{ color: tooltipColor }}
                />
                <Legend wrapperStyle={{ color: textColor }} />
                <Line
                  yAxisId="left"
                  type="monotone"
                  dataKey="avgResponseTime"
                  stroke="#8884d8"
                  name={t('responseSLA.avgResponseTime')}
                  strokeWidth={2}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="complianceRate"
                  stroke="#82ca9d"
                  name={t('responseSLA.complianceRate')}
                  strokeWidth={2}
                />
              </LineChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      )}

      {/* On-Time vs Breached Chart */}
      {trend && trend.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>{t('responseSLA.slaStatusDistribution')}</CardTitle>
            <CardDescription>{t('responseSLA.onTimeVsBreached')}</CardDescription>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={trend}>
                <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                <XAxis
                  dataKey="date"
                  tick={{ fontSize: 12, fill: axisTickFill }}
                  tickFormatter={(value) =>
                    new Date(value).toLocaleDateString(locale, { month: 'short', day: 'numeric' })
                  }
                />
                <YAxis tick={{ fill: axisTickFill }} />
                <Tooltip
                  labelFormatter={(value) => new Date(value).toLocaleDateString(locale)}
                  contentStyle={{
                    background: tooltipBg,
                    border: `1px solid ${tooltipBorder}`,
                    borderRadius: '8px',
                    color: tooltipColor,
                    boxShadow: tooltipShadow,
                  }}
                  itemStyle={{ color: tooltipColor }}
                  labelStyle={{ color: tooltipColor }}
                />
                <Legend wrapperStyle={{ color: textColor }} />
                <Bar dataKey="onTime" fill="#10b981" name={t('responseSLA.onTime')} stackId="a" />
                <Bar
                  dataKey="breached"
                  fill="#ef4444"
                  name={t('responseSLA.breached')}
                  stackId="a"
                />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      )}

      {/* Pending Requests with SLA Status */}
      {pendingWithSLA && pendingWithSLA.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>{t('responseSLA.pendingRequests')}</CardTitle>
            <CardDescription>
              {t('responseSLA.requestsAwaiting', { count: pendingWithSLA.length })}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {pendingWithSLA.map((request) => {
                const statusConfig = {
                  normal: {
                    color: 'bg-success/10 text-success',
                    icon: Activity,
                    label: t('responseSLA.normal'),
                  },
                  warning: {
                    color: 'bg-warning/10 text-warning',
                    icon: Clock,
                    label: t('responseSLA.warning'),
                  },
                  critical: {
                    color: 'bg-warning/10 text-warning',
                    icon: AlertTriangle,
                    label: t('responseSLA.critical'),
                  },
                  breached: {
                    color: 'bg-destructive/10 text-destructive',
                    icon: XCircle,
                    label: t('responseSLA.breached'),
                  },
                } as const;

                const config = statusConfig[request.sla.status as keyof typeof statusConfig];
                const StatusIcon = config.icon;

                return (
                  <div
                    key={request._id}
                    className="flex items-center justify-between p-4 border rounded-lg hover:bg-(--card-hover) transition-colors"
                  >
                    <div className="flex items-center gap-4 flex-1">
                      <div className={`p-2 rounded-full ${config.color}`}>
                        <StatusIcon className="h-4 w-4" />
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <p className="font-medium">{request.userName}</p>
                          <Badge variant="outline">{request.type}</Badge>
                        </div>
                        <p className="text-sm text-(--text-muted)">
                          {request.startDate} → {request.endDate} ({request.days}{' '}
                          {t('responseSLA.days')})
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-4">
                      <div className="text-right">
                        <p className="text-sm font-medium">
                          {request.sla.elapsedHours}
                          {t('common.hoursShort')} / {request.sla.targetHours}
                          {t('common.hoursShort')}
                        </p>
                        <p className="text-xs text-(--text-muted)">
                          {request.sla.remainingHours > 0
                            ? t('responseSLA.remaining', { hours: request.sla.remainingHours })
                            : t('responseSLA.overdueBy', {
                                hours: Math.abs(request.sla.remainingHours),
                              })}
                        </p>
                      </div>
                      <div className="w-24">
                        <Progress value={request.sla.progressPercent} />
                      </div>
                      <Badge className={config.color}>{config.label}</Badge>
                    </div>
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Summary Stats */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-green-600">
              {t('responseSLA.onTime')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold">{stats.onTime}</div>
            <p className="text-xs text-(--text-muted)">
              {stats.total > 0 ? Math.round((stats.onTime / stats.total) * 100) : 0}%{' '}
              {t('responseSLA.ofTotal')}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-blue-600">
              {t('responseSLA.pending')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold">{stats.pending}</div>
            <p className="text-xs text-(--text-muted)">
              {stats.total > 0 ? Math.round((stats.pending / stats.total) * 100) : 0}%{' '}
              {t('responseSLA.ofTotal')}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-red-600">
              {t('responseSLA.breached')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold">{stats.breached}</div>
            <p className="text-xs text-(--text-muted)">
              {stats.total > 0 ? Math.round((stats.breached / stats.total) * 100) : 0}%{' '}
              {t('responseSLA.ofTotal')}
            </p>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

export default ResponseTimeSLA;

