/**
 * 📊 SLA Dashboard Component
 *
 * Displays SLA metrics for leave request response times
 * - Average response time
 * - On-time vs breached percentage
 * - Warning/Critical alerts
 * - Trend over time
 */

'use client';

import { useTranslation } from 'react-i18next';
import { useQuery } from 'convex/react';
import { api } from '@/../convex/_generated/api';
import type { Id } from '@/../convex/_generated/dataModel';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import {
  Clock,
  CheckCircle2,
  AlertTriangle,
  AlertCircle,
  TrendingUp,
  TrendingDown,
  Calendar,
  Timer,
} from 'lucide-react';

interface SLAMetric {
  _id: string;
  leaveRequestId: string;
  submittedAt: number;
  respondedAt?: number;
  responseTimeHours?: number;
  targetResponseTimeHours: number;
  status: 'pending' | 'on_time' | 'breached';
  warningTriggered: boolean;
  criticalTriggered: boolean;
  slaScore?: number;
  createdAt: number;
}

interface SLADashboardProps {
  organizationId?: string;
}

function SLADashboard({ organizationId }: SLADashboardProps) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';
  const slaMetricsRaw = useQuery(api.sla.getSLAStats, {
    organizationId: organizationId as Id<'organizations'> | undefined,
  });
  const slaMetrics = Array.isArray(slaMetricsRaw) ? slaMetricsRaw : [];
  const slaConfig = useQuery(api.sla.getSLAConfig);

  // Calculate statistics
  const totalMetrics = slaMetrics.length;
  const pendingMetrics = slaMetrics.filter((m: SLAMetric) => m.status === 'pending').length;
  const onTimeMetrics = slaMetrics.filter((m: SLAMetric) => m.status === 'on_time').length;
  const breachedMetrics = slaMetrics.filter((m: SLAMetric) => m.status === 'breached').length;

  // Calculate average response time (only for responded requests)
  const respondedMetrics = slaMetrics.filter((m: SLAMetric) => m.responseTimeHours !== undefined);
  const avgResponseTime =
    respondedMetrics.length > 0
      ? respondedMetrics.reduce(
          (sum: number, m: SLAMetric) => sum + (m.responseTimeHours || 0),
          0,
        ) / respondedMetrics.length
      : 0;

  // Calculate SLA compliance percentage
  const complianceRate = totalMetrics > 0 ? (onTimeMetrics / totalMetrics) * 100 : 100;

  // Calculate warning and critical counts
  const warningCount = slaMetrics.filter(
    (m: SLAMetric) => m.warningTriggered && !m.criticalTriggered,
  ).length;
  const criticalCount = slaMetrics.filter((m: SLAMetric) => m.criticalTriggered).length;

  // Trend calculation (compare last 7 days vs previous 7 days)
  const now = Date.now();
  const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;
  const fourteenDaysAgo = now - 14 * 24 * 60 * 60 * 1000;

  const recentMetrics = slaMetrics.filter((m: SLAMetric) => m.createdAt >= sevenDaysAgo);
  const previousMetrics = slaMetrics.filter(
    (m: SLAMetric) => m.createdAt >= fourteenDaysAgo && m.createdAt < sevenDaysAgo,
  );

  const recentCompliance =
    recentMetrics.length > 0
      ? (recentMetrics.filter((m: SLAMetric) => m.status === 'on_time').length /
          recentMetrics.length) *
        100
      : 100;

  const previousCompliance =
    previousMetrics.length > 0
      ? (previousMetrics.filter((m: SLAMetric) => m.status === 'on_time').length /
          previousMetrics.length) *
        100
      : 100;

  const trend = recentCompliance - previousCompliance;
  const isImproving = trend > 0;

  // Target response time from config
  const targetHours = slaConfig?.targetResponseTimeHours || 24;

  if (slaMetricsRaw === undefined)
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin h-6 w-6 border-2 border-primary border-t-transparent rounded-full" />
      </div>
    );

  return (
    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
      {/* Average Response Time */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">{t('slaDashboard.avgResponseTime')}</CardTitle>
          <Timer className="h-4 w-4 text-(--text-muted)" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">
            {avgResponseTime.toFixed(1)}
            {t('common.hoursShort')}
          </div>
          <p className="text-xs text-muted-foreground">
            {t('slaDashboard.targetHours', { hours: targetHours })}
          </p>
          {avgResponseTime <= targetHours ? (
            <div className="flex items-center text-success text-xs mt-1">
              <CheckCircle2 className="h-3 w-3 mr-1" />
              {t('slaDashboard.withinTarget')}
            </div>
          ) : (
            <div className="flex items-center text-destructive text-xs mt-1">
              <AlertCircle className="h-3 w-3 mr-1" />
              {t('slaDashboard.aboveTarget')}
            </div>
          )}
        </CardContent>
      </Card>

      {/* SLA Compliance Rate */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">{t('slaDashboard.slaCompliance')}</CardTitle>
          <CheckCircle2 className="h-4 w-4 text-(--text-muted)" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{complianceRate.toFixed(1)}%</div>
          <Progress value={complianceRate} className="mt-2" />
          <div
            className={`flex items-center text-xs mt-1 ${isImproving ? 'text-success' : 'text-destructive'}`}
          >
            {isImproving ? (
              <TrendingUp className="h-3 w-3 mr-1" />
            ) : (
              <TrendingDown className="h-3 w-3 mr-1" />
            )}
            {t('slaDashboard.vsLastWeek', { trend: Math.abs(trend).toFixed(1) })}
          </div>
        </CardContent>
      </Card>

      {/* Pending Requests */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">{t('slaDashboard.pendingRequests')}</CardTitle>
          <Clock className="h-4 w-4 text-(--text-muted)" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{pendingMetrics}</div>
          <p className="text-xs text-muted-foreground">
            {t('slaDashboard.onTimeBreached', { onTime: onTimeMetrics, breached: breachedMetrics })}
          </p>
          {pendingMetrics > 0 && (
            <Badge variant="secondary" className="mt-2">
              {t('slaDashboard.needsAttention')}
            </Badge>
          )}
        </CardContent>
      </Card>

      {/* Alerts */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">{t('slaDashboard.alerts')}</CardTitle>
          <AlertTriangle className="h-4 w-4 text-(--text-muted)" />
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-4">
            <div>
              <div className="text-2xl font-bold text-warning">{warningCount}</div>
              <p className="text-xs text-muted-foreground">{t('slaDashboard.warnings')}</p>
            </div>
            <div>
              <div className="text-2xl font-bold text-destructive">{criticalCount}</div>
              <p className="text-xs text-muted-foreground">{t('slaDashboard.critical')}</p>
            </div>
          </div>
          {(warningCount > 0 || criticalCount > 0) && (
            <Badge variant="destructive" className="mt-2">
              {t('slaDashboard.actionRequired')}
            </Badge>
          )}
        </CardContent>
      </Card>

      {/* Detailed SLA Breakdown */}
      <Card className="md:col-span-2 lg:col-span-4 my-6">
        <CardHeader>
          <CardTitle>{t('slaDashboard.performanceBreakdown')}</CardTitle>
          <CardDescription>{t('slaDashboard.responseTimeDistribution')}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* On-time requests */}
            <div className="flex items-center gap-4">
              <div className="w-32 text-sm font-medium">{t('slaDashboard.onTime')}</div>
              <div className="flex-1">
                <Progress value={complianceRate} className="h-2" />
              </div>
              <div className="w-20 text-right text-sm">
                {onTimeMetrics} ({complianceRate.toFixed(0)}%)
              </div>
              <CheckCircle2 className="h-5 w-5 text-success" />
            </div>

            {/* Breached requests */}
            <div className="flex items-center gap-4">
              <div className="w-32 text-sm font-medium">{t('slaDashboard.breached')}</div>
              <div className="flex-1">
                <Progress value={100 - complianceRate} className="h-2 [&>div]:bg-destructive" />
              </div>
              <div className="w-20 text-right text-sm">
                {breachedMetrics} ({(100 - complianceRate).toFixed(0)}%)
              </div>
              <AlertCircle className="h-5 w-5 text-destructive" />
            </div>

            {/* Pending requests */}
            <div className="flex items-center gap-4">
              <div className="w-32 text-sm font-medium">{t('slaDashboard.pending')}</div>
              <div className="flex-1">
                <Progress
                  value={(pendingMetrics / totalMetrics) * 100}
                  className="h-2 [&>div]:bg-muted-foreground"
                />
              </div>
              <div className="w-20 text-right text-sm">
                {pendingMetrics} (
                {totalMetrics > 0 ? ((pendingMetrics / totalMetrics) * 100).toFixed(0) : 0}%)
              </div>
              <Clock className="h-5 w-5 text-muted-foreground" />
            </div>
          </div>

          {/* SLA Config Info */}
          {slaConfig && (
            <div className="mt-6 p-4 bg-(--background-subtle) rounded-lg">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium">{t('slaDashboard.slaConfiguration')}</p>
                  <p className="text-xs text-muted-foreground">
                    {t('slaDashboard.targetResponseTime', {
                      hours: slaConfig.targetResponseTimeHours,
                    })}
                  </p>
                </div>
                <Badge variant="outline">{t('slaDashboard.fullTime')}</Badge>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default SLADashboard;

'use client';

import React, { useState, useMemo } from 'react';
import { useMutation, useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { CustomSelect } from '@/components/ui/CustomSelect';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import {
  AlertCircle,
  CheckCircle,
  Clock,
  Power,
  Users,
  MessageSquare,
  Calendar,
  Send,
  ChevronRight,
  ChevronLeft,
  Check,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { useTranslation } from 'react-i18next';

interface ServiceBroadcastDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizationId?: Id<'organizations'> | string;
  userId?: Id<'users'> | string;
}

const BROADCAST_ICONS = [
  { icon: 'ℹ️', label: 'Information', color: '#3b82f6' },
  { icon: '⚠️', label: 'Warning', color: '#f59e0b' },
  { icon: '🔧', label: 'Maintenance', color: '#6b7280' },
  { icon: '🚨', label: 'Urgent', color: '#ef4444' },
  { icon: '🎉', label: 'Announcement', color: '#8b5cf6' },
  { icon: '🔒', label: 'Security', color: '#10b981' },
  { icon: '📢', label: 'Broadcast', color: '#ec4899' },
  { icon: '🔄', label: 'Update', color: '#06b6d4' },
];

type StepId = 'audience' | 'message' | 'schedule' | 'review';

export function ServiceBroadcastDialog({
  open,
  onOpenChange,
  organizationId,
  userId,
}: ServiceBroadcastDialogProps) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';

  const DURATION_OPTIONS = [
    { label: t('broadcastDialog.duration30min'), value: '30 minutes' },
    { label: t('broadcastDialog.duration1h'), value: '1 hour' },
    { label: t('broadcastDialog.duration2h'), value: '2 hours' },
    { label: t('broadcastDialog.duration3h'), value: '3 hours' },
    { label: t('broadcastDialog.duration4h'), value: '4 hours' },
    { label: t('broadcastDialog.durationUnknown'), value: undefined },
  ];

  const STEPS = [
    { id: 'audience' as StepId, label: t('broadcastDialog.audience'), icon: Users },
    { id: 'message' as StepId, label: t('broadcastDialog.message'), icon: MessageSquare },
    { id: 'schedule' as StepId, label: t('broadcastDialog.schedule'), icon: Calendar },
    { id: 'review' as StepId, label: t('broadcastDialog.review'), icon: Send },
  ];

  const [currentStep, setCurrentStep] = useState<StepId>('audience');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [selectedIcon, setSelectedIcon] = useState('⚠️');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');

  // Schedule & Maintenance
  const [scheduleDateTime, setScheduleDateTime] = useState('');
  const [estimatedDuration, setEstimatedDuration] = useState<string | undefined>();
  const [scheduleMaintenance, setScheduleMaintenance] = useState(false);

  // Organization selection
  const [broadcastScope, setBroadcastScope] = useState<'all' | 'specific'>('specific');
  const [selectedOrgId, setSelectedOrgId] = useState<string>(organizationId as string);

  const organizations = useQuery(
    api.organizations.getAllOrganizations,
    userId ? { superadminUserId: userId as Id<'users'> } : 'skip',
  );

  const sendBroadcast = useMutation(api.admin.sendServiceBroadcast);
  const enableMaintenanceMode = useMutation(api.admin.enableMaintenanceMode);

  const currentStepIndex = STEPS.findIndex((s) => s.id === currentStep);

  const selectedOrg = organizations?.find((o) => o._id === selectedOrgId);
  const targetOrgCount = broadcastScope === 'all' ? (organizations?.length ?? 0) : 1;

  const canProceed = useMemo(() => {
    switch (currentStep) {
      case 'audience':
        return broadcastScope === 'all' || (broadcastScope === 'specific' && selectedOrgId);
      case 'message':
        return title.trim().length > 0 && content.trim().length > 0;
      case 'schedule':
        return !scheduleMaintenance || (scheduleMaintenance && scheduleDateTime);
      case 'review':
        return true;
      default:
        return true;
    }
  }, [
    currentStep,
    broadcastScope,
    selectedOrgId,
    title,
    content,
    scheduleMaintenance,
    scheduleDateTime,
  ]);

  const nextStep = () => {
    const idx = STEPS.findIndex((s) => s.id === currentStep);
    const nextStepData = STEPS[idx + 1];
    if (idx >= 0 && nextStepData) setCurrentStep(nextStepData.id);
  };

  const prevStep = () => {
    const idx = STEPS.findIndex((s) => s.id === currentStep);
    const prevStepData = STEPS[idx - 1];
    if (idx > 0 && prevStepData) setCurrentStep(prevStepData.id);
  };

  const handleSend = async () => {
    if (!title.trim() || !content.trim()) {
      setStatus('error');
      setErrorMessage(t('broadcastDialog.fillTitleAndMessage'));
      return;
    }

    if (scheduleMaintenance && !scheduleDateTime) {
      setStatus('error');
      setErrorMessage(t('broadcastDialog.specifyMaintenanceTime'));
      return;
    }

    if (!userId) {
      setStatus('error');
      setErrorMessage(t('broadcastDialog.userNotLoaded'));
      return;
    }

    setLoading(true);
    setStatus('idle');

    try {
      const targetOrgs =
        broadcastScope === 'all'
          ? (organizations?.map((o) => o._id) ?? [])
          : [selectedOrgId as Id<'organizations'>];

      const now = Date.now();
      const scheduledTime = scheduleDateTime ? new Date(scheduleDateTime).getTime() : now;

      let broadcastContent = content.trim();
      if (scheduleMaintenance && scheduleDateTime) {
        const scheduledDate = new Date(scheduledTime);
        const timeStr = scheduledDate.toLocaleString(locale, {
          hour: '2-digit',
          minute: '2-digit',
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        });
        broadcastContent = `${content.trim()}\n\n⏰ ${t('broadcastDialog.maintenanceStartsAtContent', { time: timeStr })}`;
        if (estimatedDuration) {
          broadcastContent += `\n⏱️ ${t('broadcastDialog.estimatedDurationContent')}: ${estimatedDuration}`;
        }
      }

      for (const orgId of targetOrgs) {
        await sendBroadcast({
          organizationId: orgId,
          userId: userId as Id<'users'>,
          title: title.trim(),
          content: broadcastContent,
          icon: selectedIcon,
        });
      }

      if (scheduleMaintenance && scheduleDateTime) {
        for (const orgId of targetOrgs) {
          await enableMaintenanceMode({
            organizationId: orgId,
            userId: userId as Id<'users'>,
            title: title.trim(),
            message: broadcastContent,
            startTime: scheduledTime,
            estimatedDuration: estimatedDuration,
            icon: selectedIcon,
          });
        }
      }

      setStatus('success');
      setTitle('');
      setContent('');
      setSelectedIcon('⚠️');
      setScheduleDateTime('');
      setEstimatedDuration(undefined);
      setScheduleMaintenance(false);
      setBroadcastScope('specific');
      setSelectedOrgId(organizationId as string);

      setTimeout(() => {
        onOpenChange(false);
        setStatus('idle');
        setCurrentStep('audience');
      }, 2500);
    } catch (error) {
      setStatus('error');
      setErrorMessage(error instanceof Error ? error.message : t('broadcastDialog.sendError'));
    } finally {
      setLoading(false);
    }
  };

  const now = new Date();

  const resetState = () => {
    setCurrentStep('audience');
    setStatus('idle');
    setErrorMessage('');
  };

  // ── Step 1: Audience ────────────────────────────────────────────
  const renderAudienceStep = () => (
    <div className="space-y-6">
      <div className="text-center mb-6">
        <div className="w-16 h-16 rounded-2xl bg-linear-to-br from-blue-500/20 to-purple-500/20 flex items-center justify-center mx-auto mb-3">
          <Users className="w-8 h-8 text-blue-400" />
        </div>
        <h3 className="text-lg font-semibold">{t('broadcastDialog.whoGetsMessage')}</h3>
        <p className="text-sm text-(--text-muted) mt-1">{t('broadcastDialog.selectAudience')}</p>
      </div>

      <div className="space-y-3">
        {/* All organizations */}
        <button
          onClick={() => setBroadcastScope('all')}
          className={cn(
            'w-full p-4 rounded-xl border-2 transition-all text-left',
            broadcastScope === 'all'
              ? 'border-blue-500 bg-blue-500/10'
              : 'border-(--border) hover:border-(--border-hover,var(--border))',
          )}
        >
          <div className="flex items-center gap-3">
            <div
              className={cn(
                'w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all',
                broadcastScope === 'all' ? 'border-blue-500 bg-blue-500' : 'border-(--border)',
              )}
            >
              {broadcastScope === 'all' && <Check className="w-3 h-3 text-white" />}
            </div>
            <div className="flex-1">
              <p className="font-medium text-sm">📢 {t('broadcastDialog.allOrganizations')}</p>
              <p className="text-xs text-(--text-muted)">
                {t('broadcastDialog.orgCount', { count: organizations?.length ?? 0 })}
              </p>
            </div>
          </div>
        </button>

        {/* Specific organization */}
        <button
          onClick={() => setBroadcastScope('specific')}
          className={cn(
            'w-full p-4 rounded-xl border-2 transition-all text-left',
            broadcastScope === 'specific'
              ? 'border-blue-500 bg-blue-500/10'
              : 'border-(--border) hover:border-(--border-hover,var(--border))',
          )}
        >
          <div className="flex items-center gap-3">
            <div
              className={cn(
                'w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all',
                broadcastScope === 'specific' ? 'border-blue-500 bg-blue-500' : 'border-(--border)',
              )}
            >
              {broadcastScope === 'specific' && <Check className="w-3 h-3 text-white" />}
            </div>
            <div className="flex-1">
              <p className="font-medium text-sm">🏢 {t('broadcastDialog.specificOrganization')}</p>
              <p className="text-xs text-(--text-muted)">{t('broadcastDialog.selectOneOrg')}</p>
            </div>
          </div>
        </button>

        {broadcastScope === 'specific' && organizations && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            className="ml-2"
          >
            <CustomSelect
              value={selectedOrgId as string}
              onChange={setSelectedOrgId}
              fullWidth
              options={organizations.map((org) => ({
                value: org._id,
                label: `${org.name} (${t('broadcastDialog.employeeCount', {
                  count: org.activeEmployees ?? org.memberCount ?? 0,
                })} ${t('broadcastDialog.employees', { defaultValue: 'employees' })})`,
              }))}
              triggerClassName="w-full px-4 py-3 rounded-xl border text-sm focus:outline-none focus:ring-2 focus:ring-blue-400"
              dropdownClassName="border-[var(--border)] bg-[var(--background-subtle)] text-[var(--text-primary)]"
            />{' '}
            {selectedOrg && (
              <div className="mt-2 p-3 rounded-lg bg-(--background-subtle) border border-(--border)">
                <p className="text-xs text-(--text-muted)">
                  📊 {selectedOrg.activeEmployees ?? selectedOrg.memberCount ?? 0}{' '}
                  {t('broadcastDialog.activeUsersWillReceive')}
                </p>
              </div>
            )}
          </motion.div>
        )}
      </div>
    </div>
  );

  // ── Step 2: Message ─────────────────────────────────────────────
  const renderMessageStep = () => (
    <div className="space-y-6">
      <div className="text-center mb-6">
        <div className="w-16 h-16 rounded-2xl bg-linear-to-br from-purple-500/20 to-pink-500/20 flex items-center justify-center mx-auto mb-3">
          <MessageSquare className="w-8 h-8 text-purple-400" />
        </div>
        <h3 className="text-lg font-semibold">{t('broadcastDialog.messageContent')}</h3>
        <p className="text-sm text-(--text-muted) mt-1">{t('broadcastDialog.writeTitleAndText')}</p>
      </div>

      {/* Icon Selection */}
      <div>
        <label className="text-sm font-medium block mb-3">{t('broadcastDialog.messageIcon')}</label>
        <div className="grid grid-cols-4 gap-2">
          {BROADCAST_ICONS.map(({ icon, label, color }) => (
            <button
              key={icon}
              onClick={() => setSelectedIcon(icon)}
              className={cn(
                'p-3 rounded-xl border-2 transition-all text-2xl hover:scale-105 relative',
                selectedIcon === icon
                  ? 'border-transparent'
                  : 'border-transparent hover:border-(--border)',
              )}
              style={{
                backgroundColor: selectedIcon === icon ? `${color}20` : 'var(--background-subtle)',
              }}
              title={label}
            >
              {icon}
              {selectedIcon === icon && (
                <div
                  className="absolute -top-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: color }}
                >
                  <Check className="w-3 h-3 text-white" />
                </div>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Title */}
      <div>
        <label className="text-sm font-medium block mb-2">{t('broadcastDialog.title')}</label>
        <Input
          placeholder={t('broadcastDialog.titlePlaceholder')}
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          disabled={loading}
          className="text-base"
        />
      </div>

      {/* Content */}
      <div>
        <label className="text-sm font-medium block mb-2">{t('broadcastDialog.messageText')}</label>
        <Textarea
          placeholder={t('broadcastDialog.messagePlaceholder')}
          value={content}
          onChange={(e) => setContent(e.target.value)}
          disabled={loading}
          rows={5}
          className="resize-none text-sm"
        />
        <div className="flex items-center justify-between mt-1">
          <p className="text-xs text-(--text-muted)">
            {t('broadcastDialog.allActiveUsersWillReceive')}
          </p>
          <p className="text-xs text-(--text-muted)">
            {content.length} {t('broadcastDialog.characters')}
          </p>
        </div>
      </div>
    </div>
  );

  // ── Step 3: Schedule ────────────────────────────────────────────
  const renderScheduleStep = () => (
    <div className="space-y-6">
      <div className="text-center mb-6">
        <div className="w-16 h-16 rounded-2xl bg-linear-to-br from-orange-500/20 to-red-500/20 flex items-center justify-center mx-auto mb-3">
          <Calendar className="w-8 h-8 text-orange-400" />
        </div>
        <h3 className="text-lg font-semibold">{t('broadcastDialog.maintenanceSchedule')}</h3>
        <p className="text-sm text-(--text-muted) mt-1">
          {t('broadcastDialog.scheduleMaintenanceDesc')}
        </p>
      </div>

      {/* Toggle */}
      <button
        onClick={() => setScheduleMaintenance(!scheduleMaintenance)}
        className={cn(
          'w-full p-4 rounded-xl border-2 transition-all text-left',
          scheduleMaintenance
            ? 'border-orange-500 bg-orange-500/10'
            : 'border-(--border) hover:border-(--border-hover,var(--border))',
        )}
      >
        <div className="flex items-center gap-3">
          <div
            className={cn(
              'w-10 h-6 rounded-full transition-all flex items-center',
              scheduleMaintenance ? 'bg-orange-500 justify-end' : 'bg-(--border) justify-start',
            )}
          >
            <div className="w-5 h-5 rounded-full bg-white shadow-sm mx-0.5" />
          </div>
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <Power
                className="w-4 h-4"
                style={{ color: scheduleMaintenance ? '#f97316' : 'var(--text-muted)' }}
              />
              <p
                className="font-medium text-sm"
                style={{ color: scheduleMaintenance ? '#f97316' : undefined }}
              >
                {t('broadcastDialog.scheduleMaintenanceToggle')}
              </p>
            </div>
            <p className="text-xs text-(--text-muted) mt-0.5">
              {t('broadcastDialog.sendNowScheduleLater')}
            </p>
          </div>
        </div>
      </button>

      <AnimatePresence>
        {scheduleMaintenance && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="space-y-4"
          >
