  useEffect(() => {
    try {
      const handoff = sessionStorage.getItem('ai-chat-handoff');
      if (handoff) {
        setMessages(JSON.parse(handoff));
        sessionStorage.removeItem('ai-chat-handoff');
      }
    } catch {}
  }, []);
  const isMobile = useMediaQuery('(max-width: 768px)');
  const [sidebarOpen, setSidebarOpen] = useState(!isMobile);
  const [activeConversationId, setActiveConversationId] = useState<string | null>(null);
  const [showScrollButton, setShowScrollButton] = useState(false);
  const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
  const [editingTitle, setEditingTitle] = useState('');
  const [selectedAgent, setSelectedAgent] = useState<AgentType>('general');
  const [lastDetectedAgent, setLastDetectedAgent] = useState<AgentType>('general');
  const _isListening = false;

  // Update sidebar state when screen size changes
  useEffect(() => {
    setSidebarOpen(!isMobile);
  }, [isMobile]);

  // Handle conversation selection - close sidebar on mobile
  const handleSelectConversation = (conversationId: string) => {
    setActiveConversationId(conversationId);
    if (isMobile) setSidebarOpen(false);
  };

  // Convex queries
  const {
    results: savedConversations,
    loadMore: loadMoreConversations,
    status: convsStatus,
  } = usePaginatedQuery(api.aiChat.listConversationsPaginated, userId ? { userId } : 'skip', {
    initialNumItems: 30,
  });

  // Load messages for active conversation
  const savedMessages = useQuery(
    api.aiChat.getMessages,
    activeConversationId
      ? { conversationId: activeConversationId as Id<'aiConversations'> }
      : 'skip',
  );

  // Convex mutations
  const createConversation = useMutation(api.aiChatMutations.createConversation);
  const updateConversationTitle = useMutation(api.aiChatMutations.updateConversationTitle);
  const deleteConversation = useMutation(api.aiChatMutations.deleteConversation);
  const addMessage = useMutation(api.aiChatMutations.addMessage);
  const autoRenameConversation = useMutation(api.aiChatMutations.autoRenameConversation);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Scroll to bottom
  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading, scrollToBottom]);

  // Scroll button visibility
  useEffect(() => {
    const container = messagesContainerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const scrollTop = container.scrollTop;
      const scrollHeight = container.scrollHeight;
      const clientHeight = container.clientHeight;
      setShowScrollButton(scrollHeight - scrollTop - clientHeight > 200);
    };

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, []);

  // Load conversations from Convex
  const [conversations, setConversations] = useState<Conversation[]>([]);

  useEffect(() => {
    if (savedConversations) {
      const convs = savedConversations.map((c) => ({
        _id: c._id,
        title: c.title,
        date: new Date(c.createdAt),
      }));
      setConversations(convs);

      // Auto-select first conversation if none selected
      if (convs.length > 0 && !activeConversationId) {
        setActiveConversationId(convs[0]!._id);
      }
    }
  }, [savedConversations, activeConversationId]);

  // Load messages when conversation selected
  useEffect(() => {
    if (savedMessages && activeConversationId) {
      const loadedMessages: Message[] = savedMessages.map((m) => ({
        _id: m._id,
        id: m._id,
        role: m.role,
        content: m.content,
        timestamp: new Date(m.createdAt),
        actions: [],
        suggestions: [],
      }));
      setMessages(loadedMessages);
    }
  }, [savedMessages, activeConversationId]);

  // Auto-focus input
  useEffect(() => {
    if (textareaRef.current) {
      const timer = setTimeout(() => {
        textareaRef.current?.focus();
      }, 300);
      return () => clearTimeout(timer);
    }
  }, []);

  // ✅ Load CSRF token once
  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const r = await fetch('/api/csrf-token', { method: 'GET' });
        if (!r.ok) throw new Error(`CSRF endpoint error: ${r.status}`);
        const data = (await r.json()) as CsrfPair;
        if (!cancelled) setCsrf(data);
      } catch (e) {
        console.error('[CSRF] Failed to fetch CSRF token:', e);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  // ═══════════════════════════════════════════════════════════════
  // Create new conversation
  // ═══════════════════════════════════════════════════════════════
  const handleNewConversation = async () => {
    if (!userId) return;

    try {
      const { conversationId } = await createConversation({
        userId,
        title: t('aiChat.newChat') || 'New Chat',
      });

      setActiveConversationId(conversationId);
      setMessages([]);
      setConversations((prev) => [
        {
          _id: conversationId,
          title: t('aiChat.newChat') || 'New Chat',
          date: new Date(),
        },
        ...prev,
      ]);

      toast.success(t('aiChat.newChatCreated') || 'New chat created');
      setTimeout(() => textareaRef.current?.focus(), 100);
    } catch (error) {
      console.error('[Create conversation error]:', error);
      toast.error(t('aiChat.createError') || 'Failed to create chat');
    }
  };

  // ═══════════════════════════════════════════════════════════════
  // Delete conversation with animation
  // ═══════════════════════════════════════════════════════════════
  const handleDeleteConversation = async (conversationId: string, e: React.MouseEvent) => {
    e.stopPropagation();

    try {
      await deleteConversation({ conversationId: conversationId as Id<'aiConversations'> });

      setConversations((prev) => prev.filter((c) => c._id !== conversationId));

      if (activeConversationId === conversationId) {
        setMessages([]);
        setActiveConversationId(null);
      }

      toast.success(t('aiChat.chatDeleted') || 'Chat deleted');
    } catch (error) {
      console.error('[Delete conversation error]:', error);
      toast.error(t('aiChat.deleteError') || 'Failed to delete chat');
    }
  };

  // ═══════════════════════════════════════════════════════════════
  // Start editing title
  // ═══════════════════════════════════════════════════════════════
  const startEditingTitle = (conv: Conversation, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingTitleId(conv._id);
    setEditingTitle(conv.title);
  };

  // ═══════════════════════════════════════════════════════════════
  // Save edited title
  // ═══════════════════════════════════════════════════════════════
  const saveEditedTitle = async (conversationId: string) => {
    try {
      await updateConversationTitle({
        conversationId: conversationId as Id<'aiConversations'>,
        title: editingTitle,
      });

      setConversations((prev) =>
        prev.map((c) => (c._id === conversationId ? { ...c, title: editingTitle } : c)),
      );
      setEditingTitleId(null);
      toast.success(t('aiChat.titleUpdated') || 'Title updated');
    } catch (error) {
      console.error('[Update title error]:', error);
      toast.error(t('aiChat.updateError') || 'Failed to update title');
    }
  };

  const cancelEditingTitle = () => {
    setEditingTitleId(null);
    setEditingTitle('');
  };

  // ═══════════════════════════════════════════════════════════════
  // Send message - FULL LOGIC from ChatWidget
  // ═══════════════════════════════════════════════════════════════
  const handleSend = async () => {
    if (!input.trim() || !userId || isLoading) return;

    // ✅ CSRF check FIRST (до optimistic UI и до Convex)
    if (!csrf) {
      toast.error('CSRF token is not ready yet');
      return;
    }

    const lang = detectLanguage(input);
    const userMessageContent = input.trim();

    // If no active conversation, create one
    let currentConvId = activeConversationId;
    if (!currentConvId) {
      try {
        const { conversationId } = await createConversation({
          userId,
          title: userMessageContent.slice(0, 50),
        });
        currentConvId = conversationId;
        setActiveConversationId(conversationId);
        setConversations((prev) => [
          {
            _id: conversationId,
            title: userMessageContent.slice(0, 50),
            date: new Date(),
          },
          ...prev,
        ]);
      } catch (error) {
        console.error('[Create conversation error]:', error);
        toast.error(t('toasts.conversationCreateFailed'));
        return;
      }
    }

    // Create optimistic user message
    const userMessage: Message = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: userMessageContent,
      timestamp: new Date(),
      isNew: true,
    };

    // Add to UI immediately (optimistic update)
    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    // Save user message to Convex
    try {
      await addMessage({
        conversationId: currentConvId as Id<'aiConversations'>,
        role: 'user',
        content: userMessage.content,
      });
    } catch (error) {
      console.error('[Save message error]:', error);
    }

    try {
      logger.log('🤖 [AI Chat Page] Sending message to AI:', {
        userId,
        message: userMessageContent,
      });

      // Auto-detect agent if not manually set
      const effectiveAgent =
        selectedAgent !== 'general'
          ? selectedAgent
          : routeToAgent(userMessageContent, (user?.role as UserRole) || 'employee');

      // Sync displayed agent in UI (doesn't affect future auto-detection)
      if (selectedAgent === 'general') {
        setLastDetectedAgent(effectiveAgent);
      }

      const payload = {
        messages: [...messages, userMessage].map((m) => ({ role: m.role, content: m.content })),
        userId,
        lang,
        agent: effectiveAgent,
      };

      let res = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf.token,
          'X-CSRF-Token-Signature': csrf.signature,
        },
        body: JSON.stringify(payload),
      });

      // ✅ retry 1 раз при 403 (обновим CSRF и повторим)
      if (res.status === 403) {
        try {
          const r2 = await fetch('/api/csrf-token', { method: 'GET' });
          if (r2.ok) {
            const nextCsrf = (await r2.json()) as CsrfPair;
            setCsrf(nextCsrf);

            res = await fetch('/api/chat', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': nextCsrf.token,
                'X-CSRF-Token-Signature': nextCsrf.signature,
              },
              body: JSON.stringify(payload),
            });
          }
        } catch (e) {
          console.error('[CSRF refresh failed]', e);
        }
      }

      if (!res.ok) {
        const errData = (await res.json().catch(() => ({}))) as { error?: string };
        const errorMessage = errData.error || `Server error ${res.status}`;
        throw new Error(errorMessage);
      }

      const reader = res.body?.getReader();
      const decoder = new TextDecoder();
      let fullContent = '';

      const assistantId = `ai-${Date.now()}`;
      setMessages((prev) => [
        ...prev,
        {
          id: assistantId,
          role: 'assistant',
          content: '',
          timestamp: new Date(),
          actions: [],
          suggestions: [],
          isNew: true,
        },
      ]);

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          fullContent += decoder.decode(value, { stream: true });
          const { cleanContent } = parseActions(fullContent);
          setMessages((prev) =>
            prev.map((m) => (m.id === assistantId ? { ...m, content: cleanContent } : m)),
          );
        }
      }

      const { cleanContent, actions } = parseActions(fullContent);
      const suggestions = getFollowUpSuggestions(cleanContent, user?.role || 'employee', t);

      // Check for navigation tags in response
      const navMatch = fullContent.match(/<NAVIGATE>(.*?)<\/NAVIGATE>/);
      if (navMatch && navMatch[1]) {
        const route = navMatch[1] as string;
        setTimeout(() => {
          router.push(route);
        }, 800);
      }

      // Save AI message to Convex
      try {
        await addMessage({
          conversationId: currentConvId as Id<'aiConversations'>,
          role: 'assistant',
          content: cleanContent.replace(/<NAVIGATE>.*?<\/NAVIGATE>/g, '').trim(),
        });
      } catch (error) {
        console.error('[Save AI message error]:', error);
      }

      // Auto-rename if first message
      if (savedMessages && savedMessages.length === 0 && currentConvId) {
        try {
          await autoRenameConversation({
            conversationId: currentConvId as Id<'aiConversations'>,
            firstMessage: userMessage.content,
          });
          setConversations((prev) =>
            prev.map((c) =>
              c._id === currentConvId ? { ...c, title: userMessage.content.slice(0, 50) } : c,
            ),
          );
        } catch (error) {
          console.error('[Auto-rename error]:', error);
        }
      }

      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantId
            ? {
                ...m,
                content: cleanContent.replace(/<NAVIGATE>.*?<\/NAVIGATE>/g, '').trim(),
                actions,
                suggestions,
              }
            : m,
        ),
      );
    } catch (error) {
      console.error('[AI Chat Page] Error:', error);
      toast.error(t('aiChat.error') || 'Failed to get response');

      setMessages((prev) => [
        ...prev,
        {
          id: `error-${Date.now()}`,
          role: 'assistant',
          content: '❌ ' + (error instanceof Error ? error.message : 'Unknown error'),
          timestamp: new Date(),
          isNew: true,
        },
      ]);
    } finally {
      setIsLoading(false);
      setTimeout(() => textareaRef.current?.focus(), 100);
    }
  };

  const handleSuggestion = (suggestion: string) => {
    const clean = suggestion.replace(/^[\p{Emoji}\s]+/u, '').trim();
    setInput(clean);
    setTimeout(() => handleSend(), 50);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast.success(t('aiChat.copied') || 'Copied!');
  };

  const roleBasedSuggestions = getRoleSuggestions((user?.role as UserRole) || 'employee', t);

  const initialSuggestions = roleBasedSuggestions.slice(0, 4).map((suggestion) => {
    const cleanSuggestion = suggestion.replace(/^[\p{Emoji}\s]+/u, '').trim();
    let icon = <Calendar className="w-4 h-4" />;

    if (
      cleanSuggestion.includes('задачи') ||
      cleanSuggestion.includes('tasks') ||
      cleanSuggestion.includes('задач')
    ) {
      icon = <ClipboardList className="w-4 h-4" />;
    } else if (
      cleanSuggestion.includes('команд') ||
      cleanSuggestion.includes('сотрудник') ||
      cleanSuggestion.includes('employees') ||
      cleanSuggestion.includes('team')
    ) {
      icon = <Users className="w-4 h-4" />;
    } else if (cleanSuggestion.includes('посещаемость') || cleanSuggestion.includes('attendance')) {
      icon = <TrendingUp className="w-4 h-4" />;
    } else if (
      cleanSuggestion.includes('аналитик') ||
      cleanSuggestion.includes('analytics') ||
      cleanSuggestion.includes('статистик')
    ) {
      icon = <TrendingUp className="w-4 h-4" />;
    } else if (cleanSuggestion.includes('организац') || cleanSuggestion.includes('organization')) {
      icon = <Users className="w-4 h-4" />;
    } else if (cleanSuggestion.includes('безопасн') || cleanSuggestion.includes('security')) {
      icon = <Zap className="w-4 h-4" />;
    }

    return {
      icon,
      label: suggestion,
      query: cleanSuggestion,
    };
  });

  return (
    <div
      className="flex h-full bg-linear-to-br from-(--background) via-(--background) to-(--primary)/2"
      style={{ contain: 'layout' }}
    >
      {/* Sidebar */}
      {isMobile && sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 backdrop-blur-sm"
          onClick={() => setSidebarOpen(false)}
        />
      )}
      <aside
        className={`fixed md:relative z-50 h-full bg-(--card) border-r border-(--border) shrink-0 overflow-hidden ${
          isMobile ? 'w-full' : ''
        }`}
        style={{
          position: isMobile ? 'fixed' : 'relative',
          top: 0,
          left: 0,
          height: '100%',
          width: sidebarOpen ? (isMobile ? '100vw' : 300) : 0,
          transform: isMobile ? `translateX(${sidebarOpen ? '0' : '-100%'})` : 'none',
          opacity: sidebarOpen ? 1 : 0,
          willChange: 'width, opacity',
          pointerEvents: sidebarOpen || !isMobile ? 'auto' : 'none',
          transition: isMobile
            ? 'transform 300ms ease-in-out, opacity 300ms ease-in-out'
            : sidebarOpen
              ? `width 600ms cubic-bezier(0.34, 1.56, 0.64, 1), opacity 600ms cubic-bezier(0.34, 1.56, 0.64, 1)`
              : `width 600ms cubic-bezier(0.4, 0, 0.2, 1), opacity 600ms cubic-bezier(0.4, 0, 0.2, 1)`,
        }}
      >
        <div className="p-4 h-full flex flex-col" style={{ width: '100%' }}>
          {/* Mobile close button */}
          {isMobile && (
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-semibold text-(--text-primary) flex items-center gap-2 truncate">
                <MessageSquare className="w-4 h-4 shrink-0" />
                <span className="truncate">{t('aiChat.conversations') || 'Conversations'}</span>
              </h2>
              <Button
                variant="ghost"
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  setSidebarOpen(false);
                }}
                className="h-8 w-8 p-0 shrink-0 z-50 relative"
              >
                <X className="w-4 h-4" />
              </Button>
            </div>
          )}

          {/* Desktop header */}
          {!isMobile && (
            <div className="flex items-center justify-between mb-6">
              <h2 className="font-semibold text-(--text-primary) flex items-center gap-2 truncate">
                <MessageSquare className="w-4 h-4 shrink-0" />
                <span className="truncate">{t('aiChat.conversations') || 'Conversations'}</span>
              </h2>
              <Button
                variant="ghost"
                size="sm"
                onClick={handleNewConversation}
                className="h-8 w-8 p-0 shrink-0"
              >
                <Plus className="w-4 h-4" />
              </Button>
            </div>
          )}

          {/* Mobile new chat button */}
          {isMobile && (
            <Button variant="secondary" onClick={handleNewConversation} className="w-full mb-4">
              <Plus className="w-4 h-4 mr-2" />
              {t('aiChat.newChat') || 'New Chat'}
            </Button>
          )}

          <div className="flex-1 overflow-y-auto space-y-1 min-h-0">
            <AnimatePresence>
              {conversations.length === 0 ? (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="text-center py-8 text-(--text-muted) text-sm"
                >
                  {t('aiChat.noConversations') || 'No conversations yet'}
                </motion.div>
              ) : (
                conversations.map((conv) => (
                  <div
                    key={conv._id}
                    className={`group relative flex items-center gap-2 p-3 rounded-lg cursor-pointer transition-all ${
                      activeConversationId === conv._id
                        ? 'bg-(--primary)/10 text-(--primary) border border-(--primary)/20'
                        : 'hover:bg-(--background-subtle) border border-transparent'
                    }`}
                    onClick={() => handleSelectConversation(conv._id)}
                  >
                    <MessageSquare className="w-4 h-4 shrink-0" />

                    {editingTitleId === conv._id ? (
                      <div
                        className="flex-1 flex items-center gap-1"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <input
                          type="text"
                          value={editingTitle}
                          onChange={(e) => setEditingTitle(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') saveEditedTitle(conv._id);
                            if (e.key === 'Escape') cancelEditingTitle();
                          }}
                          className="flex-1 min-w-0 bg-transparent border-b border-(--primary) outline-none text-sm"
                          autoFocus
                        />
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-6 w-6 p-0 text-green-600"
                          onClick={() => saveEditedTitle(conv._id)}
                        >
                          <Check className="w-3 h-3" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-6 w-6 p-0 text-red-600"
                          onClick={cancelEditingTitle}
                        >
                          <X className="w-3 h-3" />
                        </Button>
                      </div>
                    ) : (
                      <>
                        <span className="flex-1 text-sm truncate block" title={conv.title}>
                          {conv.title}
                        </span>

                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 w-6 p-0"
                            onClick={(e) => startEditingTitle(conv, e)}
                          >
                            <Edit2 className="w-3 h-3" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 w-6 p-0 hover:bg-destructive/10 hover:text-destructive"
                            onClick={(e) => handleDeleteConversation(conv._id, e)}
                          >
                            <Trash2 className="w-3 h-3" />
                          </Button>
                        </div>
                      </>
                    )}
                  </div>
                ))
              )}
            </AnimatePresence>
          </div>
        </div>
      </aside>

      {/* Main Chat */}
      <main
        className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${
          !isMobile && !sidebarOpen ? 'md:ml-0' : ''
        }`}
      >
        {/* Header */}
        <header className="flex items-center justify-between p-4 border-b border-(--border) bg-(--card)/50 backdrop-blur shrink-0">
          <div className="flex items-center gap-3 min-w-0">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setSidebarOpen(!sidebarOpen)}
              className="h-9 w-9 p-0 shrink-0"
            >
              {sidebarOpen ? (
                <PanelLeftClose className="w-4 h-4" />
              ) : (
                <ChevronRight className="w-4 h-4" />
              )}
            </Button>
            <div className="flex items-center gap-2 min-w-0">
              <div className="w-8 h-8 rounded-lg btn-gradient flex items-center justify-center shrink-0">
                <Bot className="w-5 h-5 text-white" />
              </div>
              <div className="min-w-0">
                <h1 className="font-semibold text-(--text-primary) truncate">
                  {t('aiChat.title') || 'Shield HR AI'}
                </h1>
                <p className="text-xs text-(--text-muted) truncate">
                  {user?.role === 'superadmin'
                    ? `👑 ${t('roles.superadmin')}`
                    : user?.role === 'admin'
                      ? `🛡️ ${t('roles.admin')}`
                      : `👤 ${t('roles.employee')}`}
                </p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2 shrink-0">
            <AgentSelector
              selectedAgent={selectedAgent !== 'general' ? selectedAgent : lastDetectedAgent}
              onSelect={setSelectedAgent}
              disabled={isLoading}
            />
            <Badge variant="secondary" className="gap-1 shrink-0">
              <Zap className="w-3 h-3" />
              {t('aiChat.aiPowered')}
            </Badge>
          </div>
        </header>

        {/* Messages */}
        <div ref={messagesContainerRef} className="flex-1 overflow-y-auto p-0">
          {messages.length === 0 ? (
            <div className="h-full flex items-center justify-center overflow-hidden px-4">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-center w-full max-w-2xl"
              >
                <div className="hidden md:flex w-16 h-16 rounded-2xl btn-gradient items-center justify-center mx-auto mb-6 shadow-lg shadow-(--primary)/20">
                  <Sparkles className="w-8 h-8 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-(--text-primary) mb-2">
                  {t('aiChat.welcomeTitle') || 'Welcome!'} {user?.name}
                </h2>
                <p className="text-(--text-muted) mb-8">
                  {t('aiChat.welcomeSubtitle') || "I'm your AI assistant. How can I help?"}
                </p>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3 my-4">
                  {initialSuggestions.map((suggestion, index) => (
                    <button
                      key={index}
                      onClick={() => handleSuggestion(suggestion.query)}
                      className="flex flex-col items-center gap-2 p-3 sm:p-4 rounded-xl border border-(--border) hover:bg-(--background-subtle) hover:border-(--primary)/30 hover:shadow-lg hover:shadow-(--primary)/10 transition-all group min-w-0"
                    >
                      <div className="p-2 rounded-lg bg-(--primary)/10 group-hover:bg-(--primary)/20 transition-colors">
                        {suggestion.icon}
                      </div>
                      <span className="text-xs sm:text-sm font-medium text-center break-words">
                        {suggestion.label}
                      </span>
                    </button>
                  ))}
                </div>
              </motion.div>
            </div>
          ) : (
            <div className="space-y-4 max-w-200 mx-auto mt-6 px-4 sm:px-6 lg:px-8">
              {messages.map((message, index) => (
                <motion.div
                  key={message.id}
                  initial={{ opacity: 0, y: message.isNew ? 20 : 0 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.3, delay: message.isNew ? index * 0.05 : 0 }}
                  className={`flex gap-3 ${message.role === 'user' ? 'flex-row-reverse' : ''}`}
                >
                  <Avatar className="w-8 h-8 shrink-0">
                    <AvatarFallback
                      className={
                        message.role === 'user'
                          ? 'bg-(--primary) text-white'
                          : 'btn-gradient text-white'
                      }
                    >
                      {message.role === 'user' ? (
                        <User className="w-4 h-4" />
                      ) : (
                        <Bot className="w-4 h-4" />
                      )}
                    </AvatarFallback>
                  </Avatar>

                  <div
                    className={`max-w-[85%] sm:max-w-[100%] ${message.role === 'user' ? 'text-right' : ''}`}
                  >
                    <Card
                      className={`p-4 border-0 shadow-sm ${
                        message.role === 'user'
                          ? 'btn-gradient text-white'
                          : 'bg-(--card) border-(--border)'
                      }`}
                    >
                      <MarkdownMessage content={message.content} isUser={message.role === 'user'} />
                    </Card>

                    <div
                      className={`flex items-center gap-2 mt-1 ${message.role === 'user' ? 'justify-end' : ''}`}
                    >
                      <span className="text-xs text-(--text-muted)">
                        {message.timestamp
                          ? new Date(message.timestamp).toLocaleTimeString([], {
                              hour: '2-digit',
                              minute: '2-digit',
                            })
                          : ''}
                      </span>

                      {message.role === 'assistant' && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-6 w-6 p-0"
                          onClick={() => copyToClipboard(message.content)}
                        >
                          <Copy className="w-3 h-3" />
                        </Button>
                      )}
                    </div>

                    {/* Follow-up suggestions */}
                    {message.role === 'assistant' &&
                      message.suggestions &&
                      message.suggestions.length > 0 && (
                        <div className="flex flex-wrap gap-2 mt-3">
                          {message.suggestions.map((suggestion, i) => (
                            <button
                              key={i}
                              onClick={() => handleSuggestion(suggestion)}
                              className="text-xs px-3 py-1.5 rounded-full bg-(--background-subtle) hover:bg-(--primary)/10 hover:text-(--primary) transition-colors border border-(--border) hover:border-(--primary)/30"
                            >
                              {suggestion}
                            </button>
                          ))}
                        </div>
                      )}
                  </div>
                </motion.div>
              ))}

              {isLoading && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="flex items-center gap-3"
                >
                  <Avatar className="w-8 h-8">
                    <AvatarFallback className="btn-gradient text-white">
                      <Bot className="w-4 h-4" />
                    </AvatarFallback>
                  </Avatar>
                  <Card className="flex items-center justify-center p-2 h-5 bg-(--card) border-(--border)">
                    <div className="flex gap-1">
                      <span
                        className="w-1 h-1 rounded-full btn-gradient animate-bounce"
                        style={{ animationDelay: '0ms' }}
                      />
                      <span
                        className="w-1 h-1 rounded-full btn-gradient animate-bounce"
                        style={{ animationDelay: '150ms' }}
                      />
                      <span
                        className="w-1 h-1 rounded-full btn-gradient animate-bounce"
                        style={{ animationDelay: '300ms' }}
                      />
                    </div>
                  </Card>
                </motion.div>
              )}

              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input */}
        <div className="p-4 border-t border-(--border) bg-(--card)/50 backdrop-blur shrink-0">
          <div className="relative max-w-4xl h-14 mx-auto">
            <textarea
              ref={textareaRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder={
                _isListening
                  ? t('chatWidget.listening')
                  : t('aiChat.inputPlaceholder') || 'Ask anything...'
              }
              className="flex-1 resize-none bg-(--background) border border-(--border) rounded-xl py-4 pl-4 pr-14 text-sm text-(--text-primary) outline-none focus:border-(--primary) focus:ring-2 focus:ring-(--primary)/20 min-h-14 max-h-50 w-full"
              rows={1}
            />
            <Button
              onClick={handleSend}
              disabled={!input.trim() || isLoading}
              className="absolute! right-2 top-1/2 -translate-y-1/2 w-9 h-9 rounded-lg p-0"
              size="sm"
            >
              <Send className="w-4 h-4" />
            </Button>
          </div>

          <p className="text-xs text-center text-(--text-muted) mt-3">
            {t('aiChat.disclaimer') || 'AI may make mistakes. Please verify important information.'}
          </p>
        </div>
      </main>

      {/* Scroll button */}
      <AnimatePresence>
        {showScrollButton && (
          <motion.button
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.8 }}
            onClick={scrollToBottom}
            className="absolute bottom-28 right-6 p-3 rounded-full btn-gradient text-white shadow-lg hover:shadow-xl transition-shadow"
          >
            <ArrowDown className="w-4 h-4" />
          </motion.button>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation } from 'convex/react';
import { api } from '@/convex/_generated/api';
import { useAuthStore } from '@/store/useAuthStore';
import type { Id } from '@/convex/_generated/dataModel';
import { formatRelativeTime } from '@/lib/date-format';
import {
  Shield,
  ShieldCheck,
  Activity,
  Eye,
  Clock,
  XCircle,
  Bot,
  Filter,
  Lock,
  Sliders,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';

type TabId = 'overview' | 'agents' | 'guardrails' | 'audit' | 'policies';
type AgentId = 'general' | 'recruitment' | 'policy' | 'analytics' | 'kpi';

const TABS: { id: TabId; labelKey: string; icon: typeof Shield }[] = [
  { id: 'overview', labelKey: 'aiGovernance.overview', icon: Activity },
  { id: 'agents', labelKey: 'aiGovernance.agents', icon: Bot },
  { id: 'guardrails', labelKey: 'aiGovernance.guardrails', icon: Shield },
  { id: 'audit', labelKey: 'aiGovernance.audit', icon: Eye },
  { id: 'policies', labelKey: 'aiGovernance.policies', icon: Lock },
];

/** Static agent catalog (config, not telemetry) — usage/status come from real data. */
const AGENT_CATALOG: { id: AgentId; icon: string; nameKey: string; descKey: string }[] = [
  {
    id: 'general',
    icon: '🤖',
    nameKey: 'aiGovernance.agentGeneral',
    descKey: 'aiGovernance.generalAgentDesc',
  },
  {
    id: 'recruitment',
    icon: '📋',
    nameKey: 'aiGovernance.agentRecruitment',
    descKey: 'aiGovernance.recruitmentAgentDesc',
  },
  {
    id: 'policy',
    icon: '📜',
    nameKey: 'aiGovernance.agentPolicy',
    descKey: 'aiGovernance.policyAgentDesc',
  },
  {
    id: 'analytics',
    icon: '📊',
    nameKey: 'aiGovernance.agentAnalytics',
    descKey: 'aiGovernance.analyticsAgentDesc',
  },
  { id: 'kpi', icon: '🎯', nameKey: 'aiGovernance.agentKpi', descKey: 'aiGovernance.kpiAgentDesc' },
];

const GUARDRAIL_KEYS = [
  'inputFiltering',
  'outputFiltering',
  'piiDetection',
  'rateLimiting',
  'humanApprovalRequired',
] as const;

export default function AIGovernancePanel() {
  const { t, i18n } = useTranslation();
  const { user } = useAuthStore();
  const [activeTab, setActiveTab] = useState<TabId>('overview');
  const [auditFilter, setAuditFilter] = useState<AgentId | 'all'>('all');

  const organizationId = user?.organizationId as Id<'organizations'> | undefined;
  const userId = user?.id as Id<'users'> | undefined;
  const queryArgs = organizationId && userId ? { organizationId, userId } : 'skip';

  // ── Real data ──
  const stats = useQuery(api.aiGovernance.getStats, queryArgs);
  const recentActivity = useQuery(api.aiGovernance.getRecentActivity, queryArgs);
  const agentHealth = useQuery(api.aiGovernance.getAgentHealth, queryArgs);
  const auditLog = useQuery(
    api.aiGovernance.getAuditLog,
    organizationId && userId
      ? { organizationId, userId, agent: auditFilter === 'all' ? undefined : auditFilter }
      : 'skip',
  );
  const guardrails = useQuery(api.aiGovernance.getGuardrails, queryArgs);
  const updateGuardrail = useMutation(api.aiGovernance.updateGuardrail);

  const agentLabel = (id: string): string => {
    const entry = AGENT_CATALOG.find((a) => a.id === id);
    return entry ? t(entry.nameKey) : id;
  };

  const statCards = [
    {
      id: 'totalRequests',
      label: t('aiGovernance.totalRequests', 'Total AI Requests'),
      value: stats ? stats.total.toLocaleString() : '—',
      icon: Activity,
      color: '#3b82f6',
    },
    {
      id: 'blockedRequests',
      label: t('aiGovernance.blockedRequests', 'Blocked Requests'),
      value: stats ? stats.blocked.toLocaleString() : '—',
      icon: XCircle,
      color: '#ef4444',
    },
    {
      id: 'activeAgents',
      label: t('aiGovernance.activeAgents', 'Active Agents'),
      value: stats ? String(stats.activeAgents) : '—',
      icon: Bot,
      color: '#10b981',
    },
    {
      id: 'avgResponseTime',
      label: t('aiGovernance.avgResponseTime', 'Avg Response'),
      value: stats ? `${(stats.avgLatencyMs / 1000).toFixed(1)}s` : '—',
      icon: Clock,
      color: '#f59e0b',
    },
  ];

  return (
    <div className="space-y-6">
      {/* Stats cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {statCards.map((stat) => {
          const Icon = stat.icon;
          return (
            <Card key={stat.id} className="p-4 border border-(--border) bg-(--card)">
              <div className="flex items-center justify-between mb-2">
                <div
                  className="w-9 h-9 rounded-lg flex items-center justify-center"
                  style={{ backgroundColor: `${stat.color}15` }}
                >
                  <Icon className="w-4 h-4" style={{ color: stat.color }} />
                </div>
              </div>
              <div className="text-2xl font-bold text-(--text-primary)">{stat.value}</div>
              <div className="text-xs text-(--text-muted) mt-0.5">{stat.label}</div>
            </Card>
          );
        })}
      </div>

      {/* Tabs */}
      <div className="flex gap-1 border-b border-(--border) overflow-x-auto">
        {TABS.map((tab) => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-1.5 px-4 py-2.5 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
                activeTab === tab.id
                  ? 'text-blue-500 border-blue-500'
                  : 'text-(--text-muted) border-transparent hover:text-(--text-primary)'
              }`}
            >
              <Icon className="w-4 h-4" />
              {t(tab.labelKey, tab.labelKey.replace('.', ' » '))}
            </button>
          );
        })}
      </div>

      {/* Tab content */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Recent activity */}
          <Card className="p-5 border border-(--border) bg-(--card)">
            <h3 className="font-semibold text-(--text-primary) mb-4 flex items-center gap-2">
              <Activity className="w-4 h-4 text-blue-500" />
              {t('aiGovernance.recentActivity', 'Recent Activity')}
            </h3>
            <div className="space-y-3">
              {recentActivity === undefined ? (
                <p className="text-sm text-(--text-muted) py-4">
                  {t('common.loading', 'Loading…')}
                </p>
              ) : recentActivity.length === 0 ? (
                <p className="text-sm text-(--text-muted) py-4">
                  {t('aiGovernance.noActivity', 'No AI activity yet')}
                </p>
              ) : (
                recentActivity.map((item) => (
                  <div
                    key={item.id}
                    className="flex items-center justify-between py-2 border-b border-(--border)/50 last:border-0"
                  >
                    <div className="flex items-center gap-3">
                      <div
                        className={`w-2 h-2 rounded-full ${item.status === 'blocked' ? 'bg-red-500' : 'bg-emerald-500'}`}
                      />
                      <div>
                        <p className="text-sm font-medium text-(--text-primary)">
                          {agentLabel(item.agent)} · {item.action}
                        </p>
                        <p className="text-xs text-(--text-muted)">
                          {item.user} · {formatRelativeTime(item.createdAt, i18n.language)}
                        </p>
                      </div>
                    </div>
                    <Badge
                      variant={item.status === 'blocked' ? 'destructive' : 'default'}
                      className="text-xs"
                    >
                      {item.status === 'blocked'
                        ? t('aiGovernance.statusBlocked', 'blocked')
                        : t('aiGovernance.statusAllowed', 'allowed')}
                    </Badge>
                  </div>
                ))
              )}
            </div>
          </Card>

          {/* Agent health */}
          <Card className="p-5 border border-(--border) bg-(--card)">
            <h3 className="font-semibold text-(--text-primary) mb-4 flex items-center gap-2">
              <Bot className="w-4 h-4 text-emerald-500" />
              {t('aiGovernance.agentHealth', 'Agent Health')}
            </h3>
            <div className="space-y-3">
              {agentHealth === undefined ? (
                <p className="text-sm text-(--text-muted) py-4">
                  {t('common.loading', 'Loading…')}
                </p>
              ) : agentHealth.length === 0 ? (
                <p className="text-sm text-(--text-muted) py-4">
                  {t('aiGovernance.noAgentData', 'No agent traffic yet')}
                </p>
              ) : (
                agentHealth.map((agent) => (
                  <div
                    key={agent.agent}
                    className="flex items-center justify-between py-2 border-b border-(--border)/50 last:border-0"
                  >
                    <div className="flex items-center gap-2">
                      <div
                        className={`w-2 h-2 rounded-full ${agent.status === 'degraded' ? 'bg-amber-500' : 'bg-emerald-500'}`}
                      />
                      <span className="text-sm text-(--text-primary)">
                        {agentLabel(agent.agent)}
                      </span>
                    </div>
                    <div className="flex items-center gap-4 text-xs text-(--text-muted)">
                      <span>{agent.uptime}%</span>
                      <span>
                        {agent.requests} {t('aiGovernance.reqUnit', 'req')}
                      </span>
                      <Badge
                        variant={agent.status === 'degraded' ? 'warning' : 'default'}
                        className="text-[10px] px-1.5"
                      >
                        {agent.status === 'degraded'
                          ? t('aiGovernance.statusDegraded', 'degraded')
                          : t('aiGovernance.statusHealthy', 'healthy')}
                      </Badge>
                    </div>
                  </div>
                ))
              )}
            </div>
          </Card>
        </div>
      )}

      {activeTab === 'guardrails' && (
        <Card className="p-5 border border-(--border) bg-(--card)">
          <h3 className="font-semibold text-(--text-primary) mb-4 flex items-center gap-2">
            <Shield className="w-4 h-4 text-blue-500" />
            {t('aiGovernance.guardrailSettings', 'Guardrail Settings')}
          </h3>
          <div className="space-y-4">
            {GUARDRAIL_KEYS.map((key) => {
              const label = t(`aiGovernance.${key}`);
              const desc = t(`aiGovernance.${key}Desc`);
              const enabled = guardrails?.[key] ?? false;
              return (
                <div
                  key={key}
                  className="flex items-center justify-between p-4 rounded-lg bg-(--background-subtle) border border-(--border)"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <p className="text-sm font-medium text-(--text-primary)">{label}</p>
                      {enabled && (
                        <Badge
                          variant="default"
                          className="text-[10px] bg-emerald-500/10 text-emerald-600 border-emerald-500/20"
                        >
                          {t('common.active', 'Active')}
                        </Badge>
                      )}
                    </div>
                    <p className="text-xs text-(--text-muted) mt-0.5">{desc}</p>
                  </div>
                  <Switch
                    checked={enabled}
                    disabled={guardrails === undefined || !organizationId || !userId}
                    onCheckedChange={(checked) => {
                      if (!organizationId || !userId) return;
                      void updateGuardrail({ organizationId, userId, key, enabled: checked });
                    }}
                  />
                </div>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'agents' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {AGENT_CATALOG.map((agent) => {
            const health = agentHealth?.find((h) => h.agent === agent.id);
            const totalReq = agentHealth?.reduce((s, h) => s + h.requests, 0) ?? 0;
            const usage =
              health && totalReq > 0 ? `${Math.round((health.requests / totalReq) * 100)}%` : '0%';
            const status = health?.status ?? 'idle';
            return (
              <Card
                key={agent.id}
                className="p-4 border border-(--border) bg-(--card) hover:shadow-md transition-shadow"
              >
                <div className="flex items-start justify-between mb-3">
                  <span className="text-2xl">{agent.icon}</span>
                  <Badge
                    variant={status === 'degraded' ? 'warning' : 'default'}
                    className="text-[10px]"
                  >
                    {status === 'degraded'
                      ? t('aiGovernance.statusDegraded', 'degraded')
                      : status === 'idle'
                        ? t('aiGovernance.statusIdle', 'idle')
                        : t('aiGovernance.statusActive', 'active')}
                  </Badge>
                </div>
                <h4 className="font-semibold text-sm text-(--text-primary) mb-1">
                  {t(agent.nameKey)}
                </h4>
                <p className="text-xs text-(--text-muted) mb-3">{t(agent.descKey)}</p>
                <div className="flex items-center justify-between text-xs text-(--text-muted)">
                  <span>
                    {t('aiGovernance.usage', 'Usage')}: {usage}
                  </span>
                  <Button variant="ghost" size="sm" className="h-7 text-xs">
                    {t('common.details', 'Details')}
                  </Button>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {activeTab === 'audit' && (
        <Card className="p-5 border border-(--border) bg-(--card)">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-(--text-primary) flex items-center gap-2">
              <Eye className="w-4 h-4 text-blue-500" />
              {t('aiGovernance.auditLog', 'AI Audit Log')}
            </h3>
            <div className="flex items-center gap-2">
              <div className="relative">
                <Filter className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-(--text-muted)" />
                <select
                  value={auditFilter}
                  onChange={(e) => setAuditFilter(e.target.value as AgentId | 'all')}
                  className="pl-8 pr-3 py-1.5 rounded-lg text-xs bg-(--background) border border-(--border) text-(--text-primary) appearance-none cursor-pointer"
                >
                  <option value="all">{t('aiGovernance.allAgents', 'All Agents')}</option>
                  {AGENT_CATALOG.map((a) => (
                    <option key={a.id} value={a.id}>
                      {t(a.nameKey)}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>
          <div className="space-y-2">
            {auditLog === undefined ? (
              <p className="text-sm text-(--text-muted) py-4">{t('common.loading', 'Loading…')}</p>
            ) : auditLog.length === 0 ? (
              <p className="text-sm text-(--text-muted) py-4">
                {t('aiGovernance.noAuditEntries', 'No audit entries yet')}
              </p>
            ) : (
              auditLog.map((entry) => (
                <div
                  key={entry.id}
                  className="flex items-center justify-between py-2.5 px-3 rounded-lg hover:bg-(--background-subtle) transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <Badge variant="outline" className="text-[10px] font-mono w-24 justify-center">
                      {agentLabel(entry.agent)}
                    </Badge>
                    <div>
                      <p className="text-sm text-(--text-primary)">{entry.action}</p>
                      <p className="text-xs text-(--text-muted)">{entry.user}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-xs text-(--text-muted)">
                    <span>{formatRelativeTime(entry.createdAt, i18n.language)}</span>
                    <span>
                      {entry.tokens} {t('aiGovernance.tokUnit', 'tok')}
                    </span>
                    <span>{entry.latencyMs} ms</span>
                  </div>
                </div>
              ))
            )}
          </div>
        </Card>
      )}

      {activeTab === 'policies' && (
        <Card className="p-5 border border-(--border) bg-(--card)">
          <h3 className="font-semibold text-(--text-primary) mb-4 flex items-center gap-2">
            <Lock className="w-4 h-4 text-blue-500" />
            {t('aiGovernance.governancePolicies', 'Governance Policies')}
          </h3>
          <div className="space-y-3">
            {[
              {
                title: t('aiGovernance.policy1Title', 'Data Privacy Policy'),
                status: 'enforced',
                desc: t(
                  'aiGovernance.policy1Desc',
                  'AI agents must not access or expose personal data without authorization',
                ),
              },
              {
                title: t('aiGovernance.policy2Title', 'Scope Limitation'),
                status: 'enforced',
                desc: t(
                  'aiGovernance.policy2Desc',
                  'Agents are restricted to their domain and may not cross boundaries',
                ),
              },
              {
                title: t('aiGovernance.policy3Title', 'Human Approval Required'),
                status: 'draft',
                desc: t(
                  'aiGovernance.policy3Desc',
                  'Modifications to employee records, payroll, or approvals require human-in-the-loop',
                ),
              },
              {
                title: t('aiGovernance.policy4Title', 'Audit Trail Requirement'),
                status: 'enforced',
                desc: t(
                  'aiGovernance.policy4Desc',
                  'Every AI interaction must be logged with full context for compliance reviews',
                ),
              },
            ].map((policy) => (
              <div
                key={policy.title}
                className="flex items-center justify-between p-4 rounded-lg bg-(--background-subtle) border border-(--border)"
              >
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium text-(--text-primary)">{policy.title}</p>
                    <Badge
                      variant={policy.status === 'enforced' ? 'default' : 'warning'}
                      className="text-[10px]"
                    >
                      {policy.status === 'enforced'
                        ? t('aiGovernance.statusEnforced', 'enforced')
                        : t('aiGovernance.statusDraft', 'draft')}
                    </Badge>
                  </div>
                  <p className="text-xs text-(--text-muted) mt-0.5">{policy.desc}</p>
                </div>
                <Sliders className="w-4 h-4 text-(--text-muted) cursor-pointer hover:text-(--text-primary) transition-colors" />
              </div>
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

