                      <ul className="space-y-1">
                        {insights.teamConflicts.map((c, i) => (
                          <li
                            key={i}
                            className="text-sm text-(--text-primary) flex items-start gap-2"
                          >
                            <span className="text-blue-500 mt-0.5">•</span>
