'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { usePathname } from 'next/navigation';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { X, Sparkles, Mic } from 'lucide-react';
import { useUpgradeModal } from '@/components/subscription/PlanGate';
import { usePlanFeatures } from '@/hooks/usePlanFeatures';

/** Pulsing hint that appears every 15s when widget is docked */
function DockedPulse({ dockedSide, dockedY }: { dockedSide: 'left' | 'right'; dockedY: number }) {
  const { t } = useTranslation('chat');
  const [show, setShow] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setShow(true);
      setTimeout(() => setShow(false), 3000);
    }, 15000);
    return () => clearInterval(interval);
  }, []);

  if (!show) return null;

  const isRight = dockedSide === 'right';
  return (
    <div
      className="fixed z-50 flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium shadow-lg animate-pulse"
      style={{
        top: `${dockedY}%`,
        background: 'var(--primary)',
        color: 'white',
        ...(isRight
          ? { right: 36 }
          : { left: (typeof window !== 'undefined' && window.innerWidth >= 1024 ? 240 : 0) + 36 }),
      }}
    >
      <Sparkles className="w-3 h-3" />
      {t('chatWidget.imHere', { defaultValue: "I'm here to help!" })}
    </div>
  );
}

interface ChatWidgetButtonProps {
  isOpen: boolean;
  setIsOpen: (v: boolean | ((o: boolean) => boolean)) => void;
  wakeWordActive: boolean;
  docked: boolean;
  setDocked: (v: boolean) => void;
  dockedSide: 'right' | 'left';
  setDockedSide: (v: 'right' | 'left') => void;
  dockedY: number;
  setDockedY: (v: number) => void;
}

export function ChatWidgetButton({
  isOpen,
  setIsOpen,
  wakeWordActive,
  docked,
  setDocked,
  dockedSide,
  setDockedSide,
  dockedY,
  setDockedY,
}: ChatWidgetButtonProps) {
  const { t } = useTranslation();
  const pathname = usePathname();

  // Plan gating
  const { canAccess } = usePlanFeatures();
  const hasAiChat = canAccess('aiChat');
  const { openModal, modal: upgradeModal } = useUpgradeModal();

  // Drag state
  const dragging = useRef(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const hasDragged = useRef(false);
  const [dragPos, setDragPos] = useState<{ x: number; y: number } | null>(null);
  const [returning, setReturning] = useState(false);
  const [undocking, setUndocking] = useState(false);

  // AI button hint system
  const [hintIndex, setHintIndex] = useState(0);
  const [showHint, setShowHint] = useState(false);
  const [lastActivityTime, setLastActivityTime] = useState(Date.now());
  const [hintsShownCount, setHintsShownCount] = useState(0);
  const MAX_HINTS_PER_SESSION = 3;
  const HINT_INTERVAL_MS = 20000;
  const INACTIVITY_THRESHOLD_MS = 15000;

  const getHintText = useCallback(
    (index: number): string => {
      const hints = [
        t('dashboard.hints.help', { defaultValue: "Need help? I'm here! 💡" }),
        t('dashboard.hints.leaveRequest', { defaultValue: 'Try /leave to request time off' }),
        t('dashboard.hints.reports', { defaultValue: 'Ask me about team reports' }),
      ];
      return hints[index % hints.length] ?? '';
    },
    [t],
  );

  const trackActivity = useCallback(() => {
    setLastActivityTime(Date.now());
    setShowHint(false);
  }, []);

  useEffect(() => {
    if (isOpen || hintsShownCount >= MAX_HINTS_PER_SESSION) return;

    const checkInactivity = () => {
      const now = Date.now();
      const inactive = now - lastActivityTime > INACTIVITY_THRESHOLD_MS;

      if (inactive && !showHint) {
        setShowHint(true);
        setHintsShownCount((prev) => prev + 1);

        const hintTimer = setTimeout(() => {
          setShowHint(false);
          setHintIndex((prev) => (prev + 1) % 3);
        }, 5000);
        return () => clearTimeout(hintTimer);
      }
    };

    const interval = setInterval(checkInactivity, HINT_INTERVAL_MS);
    return () => {
      clearInterval(interval);
    };
  }, [isOpen, lastActivityTime, showHint, hintsShownCount]);

  useEffect(() => {
    const events = ['mousedown', 'keydown', 'scroll', 'touchstart'];
    const handler = trackActivity;

    events.forEach((event) => {
      window.addEventListener(event, handler, { passive: true });
    });

    return () => {
      events.forEach((event) => {
        window.removeEventListener(event, handler);
      });
    };
  }, [trackActivity]);

  // Touch drag handlers
  const handleBtnTouchStart = useCallback((e: React.TouchEvent) => {
    const t = e.touches[0]!;
    dragging.current = true;
    hasDragged.current = false;
    dragStart.current = { x: t.clientX, y: t.clientY };
  }, []);

  const handleBtnTouchMove = useCallback((e: React.TouchEvent) => {
    if (!dragging.current) return;
    const t = e.touches[0]!;
    if (
      Math.abs(t.clientX - dragStart.current.x) > 10 ||
      Math.abs(t.clientY - dragStart.current.y) > 10
    ) {
      hasDragged.current = true;
      setDragPos({ x: t.clientX, y: t.clientY });
    }
  }, []);

  const handleBtnTouchEnd = useCallback(
    (e: React.TouchEvent) => {
      if (!dragging.current) return;
      dragging.current = false;
      const t = e.changedTouches[0]!;
      if (!hasDragged.current) {
        setDragPos(null);
        return;
      }
      e.preventDefault();
      const sidebarEdge = window.innerWidth >= 1024 ? 240 : 0;
      if (t.clientX > window.innerWidth * 0.75) {
        setDragPos(null);
        setDocked(true);
        setDockedSide('right');
        setDockedY(Math.min(80, Math.max(20, (t.clientY / window.innerHeight) * 100)));
      } else if (t.clientX < sidebarEdge + 60) {
        setDragPos(null);
        setDocked(true);
        setDockedSide('left');
        setDockedY(Math.min(80, Math.max(20, (t.clientY / window.innerHeight) * 100)));
      } else {
        // Animate back: keep dragPos, enable transition, then clear
        setReturning(true);
        setTimeout(() => {
          setDragPos(null);
          setReturning(false);
        }, 400);
      }
    },
    [setDocked, setDockedSide, setDockedY],
  );

  // Mouse drag
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      dragging.current = true;
      hasDragged.current = false;
      dragStart.current = { x: e.clientX, y: e.clientY };
      const onMove = (ev: MouseEvent) => {
        if (!dragging.current) return;
        if (
          Math.abs(ev.clientX - dragStart.current.x) > 10 ||
          Math.abs(ev.clientY - dragStart.current.y) > 10
        ) {
          hasDragged.current = true;
          setDragPos({ x: ev.clientX, y: ev.clientY });
        }
      };
      const onUp = (ev: MouseEvent) => {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        dragging.current = false;
        if (!hasDragged.current) {
          setDragPos(null);
          return;
        }
        const sidebarEdge = window.innerWidth >= 1024 ? 240 : 0;
        if (ev.clientX > window.innerWidth * 0.75) {
          setDragPos(null);
          setDocked(true);
          setDockedSide('right');
          setDockedY(Math.min(80, Math.max(20, (ev.clientY / window.innerHeight) * 100)));
        } else if (ev.clientX < sidebarEdge + 60) {
          setDragPos(null);
          setDocked(true);
          setDockedSide('left');
          setDockedY(Math.min(80, Math.max(20, (ev.clientY / window.innerHeight) * 100)));
        } else {
          setReturning(true);
          setTimeout(() => {
            setDragPos(null);
            setReturning(false);
          }, 400);
        }
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    },
    [setDocked, setDockedSide, setDockedY],
  );

  if (pathname === '/ai-chat') return <>{upgradeModal}</>;

  return (
    <>
      {/* Wake word toast */}
      <AnimatePresence>
        {wakeWordActive && (
          <motion.div
            initial={{ opacity: 0, y: 10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 10, scale: 0.95 }}
            className="fixed bottom-24 right-6 z-50 px-4 py-2 rounded-xl bg-[#2563eb] text-white text-sm font-medium shadow-lg flex items-center gap-2"
          >
            <Mic className="w-4 h-4 animate-pulse" />
            Hey HR! I&apos;m listening…
          </motion.div>
        )}
      </AnimatePresence>

      {/* Upgrade modal */}
      {upgradeModal}

      {/* Docked indicator */}
      {docked && !isOpen && <DockedPulse dockedSide={dockedSide} dockedY={dockedY} />}
      {docked && !isOpen && (
        <button
          onClick={() => {
            if (!hasDragged.current) setIsOpen(true);
          }}
          onTouchStart={(e) => {
            const t = e.touches[0]!;
            dragging.current = true;
            hasDragged.current = false;
            dragStart.current = { x: t.clientX, y: t.clientY };
          }}
          onTouchMove={(e) => {
            if (!dragging.current) return;
            const t = e.touches[0]!;
            if (
              Math.abs(t.clientX - dragStart.current.x) > 5 ||
              Math.abs(t.clientY - dragStart.current.y) > 5
            ) {
              hasDragged.current = true;
              setDragPos({ x: t.clientX, y: t.clientY });
            }
          }}
          onTouchEnd={(e) => {
            if (!dragging.current) return;
            dragging.current = false;
            const t = e.changedTouches[0]!;
            if (!hasDragged.current) {
              setDragPos(null);
              return;
            }
            e.preventDefault();
            const sidebarEdge = window.innerWidth >= 1024 ? 240 : 0;
            if (t.clientX > window.innerWidth * 0.75) {
              setDragPos(null);
              setDockedSide('right');
              setDockedY(Math.min(80, Math.max(20, (t.clientY / window.innerHeight) * 100)));
            } else if (t.clientX < sidebarEdge + 60) {
              setDragPos(null);
              setDockedSide('left');
              setDockedY(Math.min(80, Math.max(20, (t.clientY / window.innerHeight) * 100)));
            } else {
              setUndocking(true);
              setTimeout(() => {
                setDragPos(null);
                setDocked(false);
                setUndocking(false);
              }, 400);
            }
          }}
          onMouseDown={(e) => {
            dragging.current = true;
            hasDragged.current = false;
            dragStart.current = { x: e.clientX, y: e.clientY };
            const onMove = (ev: MouseEvent) => {
              if (!dragging.current) return;
              if (
                Math.abs(ev.clientX - dragStart.current.x) > 5 ||
                Math.abs(ev.clientY - dragStart.current.y) > 5
              ) {
                hasDragged.current = true;
                setDragPos({ x: ev.clientX, y: ev.clientY });
              }
            };
            const onUp = (ev: MouseEvent) => {
              document.removeEventListener('mousemove', onMove);
              document.removeEventListener('mouseup', onUp);
              dragging.current = false;
              if (!hasDragged.current) {
                setDragPos(null);
                return;
              }
              const sidebarEdge = window.innerWidth >= 1024 ? 240 : 0;
              if (ev.clientX > window.innerWidth * 0.75) {
                setDragPos(null);
                setDockedSide('right');
                setDockedY(Math.min(80, Math.max(20, (ev.clientY / window.innerHeight) * 100)));
              } else if (ev.clientX < sidebarEdge + 60) {
                setDragPos(null);
                setDockedSide('left');
                setDockedY(Math.min(80, Math.max(20, (ev.clientY / window.innerHeight) * 100)));
              } else {
                setUndocking(true);
                setTimeout(() => {
                  setDragPos(null);
                  setDocked(false);
                  setUndocking(false);
                }, 400);
              }
            };
            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
          }}
          className="fixed z-50 flex items-center justify-center w-8 h-12 shadow-lg btn-gradient text-white cursor-grab active:cursor-grabbing transition-all duration-300 hover:w-10 hover:h-14 hover:shadow-[0_0_20px_rgba(37,99,235,0.5)]"
          style={{
            ...(undocking
              ? {
                  bottom: typeof window !== 'undefined' && window.innerWidth >= 1024 ? 24 : 96,
                  right: 24,
                  top: 'auto',
                  left: 'auto',
                  borderRadius: '9999px',
                  width: typeof window !== 'undefined' && window.innerWidth >= 640 ? 56 : 40,
                  height: typeof window !== 'undefined' && window.innerWidth >= 640 ? 56 : 40,
                  transition: 'all 0.4s cubic-bezier(0.34,1.56,0.64,1)',
                }
              : dragPos
                ? {
                    left: dragPos.x - 16,
                    top: dragPos.y - 24,
                    right: 'auto',
                    borderRadius: '0.5rem',
                    transition: 'none',
                  }
                : {
                    top: `${dockedY}%`,
                    ...(dockedSide === 'right'
                      ? {
                          right: 0,
                          borderTopLeftRadius: '0.5rem',
                          borderBottomLeftRadius: '0.5rem',
                          borderTopRightRadius: 0,
                          borderBottomRightRadius: 0,
                        }
                      : {
                          left:
                            typeof window !== 'undefined' && window.innerWidth >= 1024 ? 240 : 0,
                          borderTopRightRadius: '0.5rem',
                          borderBottomRightRadius: '0.5rem',
                          borderTopLeftRadius: 0,
                          borderBottomLeftRadius: 0,
                        }),
                  }),
          }}
          aria-label="Show AI assistant"
        >
          <Sparkles className="w-4 h-4" />
        </button>
      )}

      {/* Pulsing animation background */}
      {!docked && (
        <motion.div
          className="fixed bottom-24 lg:bottom-6 right-6 z-50 w-10 sm:w-14 h-10 sm:h-14 rounded-full bg-primary/20"
          animate={{
            scale: [1, 1.2, 1] as any,
            opacity: [0.7, 0, 0.7] as any,
          }}
          transition={{
            duration: 2,
            repeat: Infinity,
            ease: 'easeInOut',
          }}
        />
      )}

      {/* Rotating hints tooltip */}
      <AnimatePresence>
        {showHint && !docked && hintIndex < MAX_HINTS_PER_SESSION && (
          <motion.div
            initial={{ opacity: 0, x: 10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 10 }}
            className="fixed bottom-24 right-6 z-50 max-w-[200px] px-3 py-2 rounded-lg text-xs font-medium shadow-lg"
            style={{
              background: 'var(--card)',
              border: '1px solid var(--border)',
              color: 'var(--text-primary)',
            }}
          >
            {getHintText(hintIndex)}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main button */}
      {!docked && (
        <motion.button
          aria-label={t('chatWidget.openAssistant', { defaultValue: 'Open AI assistant' })}
          onClick={() => {
            if (hasDragged.current) return;
            if (!hasAiChat) {
              openModal({
                featureTitle: 'AI HR Assistant',
                featureDescription:
                  'AI-powered leave assistant, smart suggestions, and voice commands are available on the Professional plan.',
                recommendedPlan: 'professional',
              });
              return;
            }
            setIsOpen((o: boolean) => !o);
            setLastActivityTime(Date.now());
          }}
          className="fixed bottom-24 lg:bottom-6 right-6 z-50 w-10 sm:w-14 h-10 sm:h-14 rounded-full flex items-center gap-2 justify-center btn-gradient text-white font-medium shadow-md hover:shadow-[0_0_24px_rgba(37,99,235,0.6)] transition-shadow duration-300"
          style={
            dragPos && !returning
              ? {
                  position: 'fixed' as const,
                  left: dragPos.x - 28,
                  top: dragPos.y - 28,
                  right: 'auto',
                  bottom: 'auto',
                  transition: 'none',
                }
              : returning
                ? { transition: 'all 0.4s cubic-bezier(0.34,1.56,0.64,1)' }
                : undefined
          }
          whileHover={{ scale: 1.12 }}
          whileTap={{ scale: 0.95 }}
          onTouchStart={handleBtnTouchStart}
          onTouchMove={handleBtnTouchMove}
          onTouchEnd={handleBtnTouchEnd}
          onMouseDown={handleMouseDown}
        >
          <AnimatePresence mode="wait">
            {isOpen ? (
              <motion.div
                key="x"
                initial={{ rotate: -90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: 90, opacity: 0 }}
                transition={{ duration: 0.15 }}
              >
                <X className="w-6 h-6" />
              </motion.div>
            ) : (
              <motion.div
                key="chat"
                initial={{ rotate: 90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: -90, opacity: 0 }}
                transition={{ duration: 0.15 }}
              >
                <Sparkles className="w-4 sm:w-6 h-4 sm:h-6" />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>
      )}
    </>
  );
}

'use client';

import { useRef, useEffect, useCallback, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { usePathname } from 'next/navigation';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import {
  X,
  Send,
  Sparkles,
  CheckCircle,
  AlertCircle,
  Calendar,
  Pencil,
  Trash2,
  Mic,
  MicOff,
  Car,
  Maximize2,
  Database,
  Pin,
} from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { Button } from '@/components/ui/button';
import { formatMessageContent } from '@/components/ai/MarkdownTable';
import { type UserRole } from '@/lib/aiAssistant';
import type {
  Message,
  AnyAction,
  BookLeaveAction,
  DeleteLeaveAction,
  BookDriverAction,
  BackupOrgAction,
  BackupEmployeeAction,
  RestoreBackupAction,
} from './chatWidgetTypes';
import { LEAVE_TYPE_LABELS, getInitialSuggestions } from './chatWidgetUtils';
import {
  TypingStages,
  getMoodGreeting,
  getContextSuggestions,
  filterSlashCommands,
  MessageActions,
  SlashCommandDropdown,
  getPinnedMessages,
  togglePinMessage,
} from './chatWidgetEnhancements';

interface ChatWidgetWindowProps {
  isOpen: boolean;
  setIsOpen: (v: boolean) => void;
  docked: boolean;
  dockedSide?: 'right' | 'left';
  dockedY?: number;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  input: string;
  setInput: (v: string) => void;
  isLoading: boolean;
  error: string | null;
  isListening: boolean;
  inputRef: React.RefObject<HTMLInputElement | null>;
  user: any;
  sendMessage: (text: string, setIsOpen: (v: boolean) => void) => Promise<void>;
  handleAction: (messageId: string, action: AnyAction, actionIndex: number) => Promise<void>;
  startVoiceInput: () => void;
  router: any;
  t: (key: string, options?: any) => string;
  i18n: any;
}

export function ChatWidgetWindow({
  isOpen,
  setIsOpen,
  docked,
  dockedSide = 'right',
  dockedY = 50,
  messages,
  setMessages,
  input,
  setInput,
  isLoading,
  error,
  isListening,
  inputRef,
  user,
  sendMessage,
  handleAction,
  startVoiceInput,
  router,
  t,
  i18n,
}: ChatWidgetWindowProps) {
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const pathname = usePathname();
  const [pinnedIds, setPinnedIds] = useState<Set<string>>(
    () => new Set(getPinnedMessages().map((p) => p.id)),
  );
  const [showPinned, setShowPinned] = useState(false);
  const slashCommands = filterSlashCommands(input, t);
  const contextSuggestions = getContextSuggestions(pathname || '', t);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading, scrollToBottom]);

  useEffect(() => {
    if (isOpen) {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [isOpen, inputRef]);

  const handleSubmit = (e: React.FormEvent | React.KeyboardEvent) => {
    e.preventDefault();
    sendMessage(input, setIsOpen);
  };

  const handleSuggestion = (suggestion: string) => {
    const clean = suggestion.replace(/^[\p{Emoji}\s]+/u, '').trim();
    sendMessage(clean, setIsOpen);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {<div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />}
          <motion.div
            initial={{ opacity: 0, y: 24, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 24, scale: 0.95 }}
            transition={{ type: 'spring', stiffness: 400, damping: 30 }}
            className={`fixed z-50 w-[calc(100vw-1rem)] sm:w-[380px] max-h-[calc(100vh-12rem)] lg:max-h-[calc(100vh-8rem)] flex flex-col rounded-2xl border border-(--border) shadow-2xl overflow-hidden ${!docked ? 'bottom-36 lg:bottom-24 right-2 sm:right-6' : ''}`}
            style={{
              background: 'var(--card)',
              ...(docked
                ? {
                    top: `clamp(1rem, calc(${dockedY}% - 200px), calc(100vh - 450px))`,
                    ...(dockedSide === 'right' ? { right: '0.5rem' } : { left: '16.5rem' }),
                  }
                : {}),
            }}
          >
            {/* Header */}
            <div className="flex items-center gap-3 px-4 py-3 border-b border-(--border) shrink-0 bg-linear-to-r from-[#2563eb]/10 to-[#0ea5e9]/10">
              <div className="w-8 h-8 rounded-xl btn-gradient flex items-center justify-center shadow">
                <Sparkles className="w-4 h-4 text-white" />
              </div>
              <div>
                <p className="text-sm font-semibold text-(--text-primary)">
                  {t('aiChat.shieldHrAi')}
                </p>
                <p className="text-[10px] text-(--text-muted)">
                  {t('chatWidget.subtitle', { defaultValue: 'Your intelligent HR assistant' })}
                </p>
              </div>
              <div className="flex items-center gap-1 ml-auto">
                <button
                  onClick={() => setShowPinned(!showPinned)}
                  className={`p-1.5 rounded-lg hover:bg-(--background-subtle) transition-colors ${showPinned ? 'text-[#2563eb]' : ''}`}
                  aria-label="Pinned messages"
                  title="Pinned messages"
                >
                  <Pin className="w-4 h-4 text-(--text-muted)" />
                </button>
                <button
                  onClick={() => {
                    router.push('/ai-chat');
                    setIsOpen(false);
                  }}
                  className="p-1.5 rounded-lg hover:bg-(--background-subtle) transition-colors"
                  aria-label="Open full screen chat"
                  title="Открыть на весь экран"
                >
                  <Maximize2 className="w-4 h-4 text-(--text-muted)" />
                </button>
                <button
                  onClick={() => setIsOpen(false)}
                  className="p-1.5 rounded-lg hover:bg-(--background-subtle) transition-colors"
                  aria-label={t('chatWidget.closeChat', { defaultValue: 'Close chat' })}
                >
                  <X className="w-4 h-4 text-(--text-muted)" />
                </button>
              </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-0">
              {/* Initial suggestions */}
              {messages.length === 0 && (
                <motion.div
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-3"
                >
                  <p className="text-xs text-(--text-muted) text-center mb-1">
                    {getMoodGreeting(user?.name?.split(' ')[0] || 'there', t)}
                  </p>
                  <p className="text-[10px] text-(--text-muted)/70 text-center mb-2">
                    💡{' '}
                    {t('chatWidget.smartHint', {
                      defaultValue: 'I know everything about Shield HR — ask me anything!',
                    })}
                  </p>
                  <div className="grid grid-cols-2 gap-1.5">
                    {getInitialSuggestions(user?.role as UserRole, t).map((s) => (
                      <button
                        key={s}
                        onClick={() => handleSuggestion(s)}
                        disabled={isLoading}
                        className="text-left px-3 py-2 rounded-xl border border-(--border) bg-(--background-subtle) hover:border-[#2563eb]/50 hover:bg-[#2563eb]/5 hover:text-[#3b82f6] text-xs text-(--text-primary) transition-all duration-150 disabled:opacity-50"
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                  {/* Context-aware suggestions */}
                  {contextSuggestions.length > 0 && (
                    <div className="mt-2">
                      <p className="text-[10px] text-(--text-muted)/60 mb-1">
                        📍 {t('chatWidget.basedOnPage', { defaultValue: 'Based on this page:' })}
                      </p>
                      <div className="flex flex-wrap gap-1">
                        {contextSuggestions.map((s) => (
                          <button
                            key={s}
                            onClick={() => handleSuggestion(s)}
                            disabled={isLoading}
                            className="px-2 py-1 rounded-full border border-[#0ea5e9]/30 bg-[#0ea5e9]/5 hover:bg-[#0ea5e9]/15 text-[10px] text-[#0ea5e9] font-medium transition-all disabled:opacity-50"
                          >
                            {s}
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </motion.div>
              )}

              {/* Messages */}
              {messages.map((m) => {
                const isUser = m.role === 'user';
                return (
                  <div key={m.id} className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
                    <div
                      className={`max-w-[85%] space-y-2 ${isUser ? 'items-end' : 'items-start'} flex flex-col group`}
                    >
                      <div
                        className={`px-4 py-2.5 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap ${
                          isUser
                            ? 'bg-linear-to-br from-[#2563eb] to-[#0ea5e9] text-white rounded-br-sm'
                            : 'bg-(--background-subtle) text-(--text-primary) rounded-bl-sm'
                        }`}
                      >
                        {(() => {
                          const hasTable = m.content.includes('|') && m.content.includes('---');
                          const isLargeContent = !isUser && (hasTable || m.content.length > 500);
                          if (isLargeContent) {
                            const preview = hasTable
                              ? m.content
                                  .split('\n')
                                  .filter((l) => !l.includes('|') && !l.includes('---'))
                                  .slice(0, 3)
                                  .join('\n') || m.content.slice(0, 150)
                              : m.content.slice(0, 300) + '...';
                            return (
                              <>
                                <div>{formatMessageContent(preview)}</div>
                                <button
                                  onClick={() => {
                                    router.push('/ai-chat');
                                    setIsOpen(false);
                                  }}
                                  className="mt-2 flex items-center gap-1.5 text-xs font-medium text-[#2563eb] hover:text-[#1d4ed8] transition-colors"
                                >
                                  <Maximize2 className="w-3.5 h-3.5" />
                                  {t('chatWidget.viewFullScreen', {
                                    defaultValue: 'View full response',
                                  })}
                                </button>
                              </>
                            );
                          }
                          return formatMessageContent(m.content);
                        })()}
                      </div>

                      {/* Reactions, copy, TTS, pin for AI messages */}
                      {!isUser && (
                        <MessageActions
                          content={m.content}
                          isPinned={pinnedIds.has(m.id)}
                          onPin={() => {
                            const pinned = togglePinMessage(m.id, m.content);
                            setPinnedIds((prev) => {
                              const s = new Set(prev);
                              pinned ? s.add(m.id) : s.delete(m.id);
                              return s;
                            });
                          }}
                        />
                      )}

                      {/* Action cards */}
                      {m.actions && m.actions.length > 0 && (
                        <div className="w-full space-y-2">
                          {m.actions.map((action, idx) => {
                            const state = m.bookingStates?.[idx] ?? { status: 'pending' };
                            const isDelete = action.type === 'DELETE_LEAVE';
                            const isEdit = action.type === 'EDIT_LEAVE';
                            const isBookDriver = action.type === 'BOOK_DRIVER';
                            const isBackupOrg = action.type === 'BACKUP_ORG';
                            const isBackupEmployee = action.type === 'BACKUP_EMPLOYEE';
                            const isRestoreBackup = action.type === 'RESTORE_BACKUP';

                            return (
                              <motion.div
                                key={idx}
                                initial={{ opacity: 0, y: 4 }}
                                animate={{ opacity: 1, y: 0 }}
                                className={`rounded-xl border p-3 text-xs space-y-2 ${
                                  isDelete
                                    ? 'border-red-500/20 bg-red-500/5'
                                    : isEdit
                                      ? 'border-yellow-500/20 bg-yellow-500/5'
                                      : isBookDriver
                                        ? 'border-purple-500/20 bg-purple-500/5'
                                        : isBackupOrg || isBackupEmployee || isRestoreBackup
                                          ? 'border-emerald-500/20 bg-emerald-500/5'
                                          : 'border-[#2563eb]/20 bg-[#2563eb]/5'
                                }`}
                              >
                                <div className="flex items-center gap-2 font-semibold text-(--text-primary)">
                                  {isDelete ? (
                                    <Trash2 className="w-3.5 h-3.5 text-red-500" />
                                  ) : isEdit ? (
                                    <Pencil className="w-3.5 h-3.5 text-yellow-500" />
                                  ) : isBookDriver ? (
                                    <Car className="w-3.5 h-3.5 text-purple-500" />
                                  ) : isBackupOrg || isBackupEmployee || isRestoreBackup ? (
                                    <Database className="w-3.5 h-3.5 text-emerald-500" />
                                  ) : (
                                    <Calendar className="w-3.5 h-3.5 text-[#2563eb]" />
                                  )}
                                  {isDelete
                                    ? t('chatWidget.cancelLeave')
                                    : isEdit
                                      ? t('chatWidget.updateLeave')
                                      : isBookDriver
                                        ? t('chatWidget.bookDriver', 'Book Driver')
                                        : isBackupOrg
                                          ? `Backup: ${(action as BackupOrgAction).organizationName}`
                                          : isBackupEmployee
                                            ? `Backup: ${(action as BackupEmployeeAction).userName}`
                                            : isRestoreBackup
                                              ? `Restore: ${(action as RestoreBackupAction).employeeName}`
                                              : (LEAVE_TYPE_LABELS[
                                                  (action as BookLeaveAction).leaveType
                                                ] ?? t('chatWidget.leaveRequest'))}
                                </div>
                                <div className="text-(--text-muted) space-y-0.5">
                                  {isBackupOrg ? (
                                    <>
                                      <p>🏢 {(action as BackupOrgAction).organizationName}</p>
                                      <p>💾 Backing up all employees</p>
                                    </>
                                  ) : isBackupEmployee ? (
                                    <>
                                      <p>👤 {(action as BackupEmployeeAction).userName}</p>
                                      <p>💾 Backing up employee data</p>
                                    </>
                                  ) : isRestoreBackup ? (
                                    <>
                                      <p>👤 {(action as RestoreBackupAction).employeeName}</p>
                                      <p>🔄 Restoring from backup snapshot</p>
                                    </>
                                  ) : isBookDriver ? (
                                    <>
                                      <p>🚗 {(action as BookDriverAction).driverName}</p>
                                      <p>
                                        📅{' '}
                                        {new Date(
                                          (action as BookDriverAction).startTime,
                                        ).toLocaleString(
                                          i18n.language === 'ru'
                                            ? 'ru-RU'
                                            : i18n.language === 'hy'
                                              ? 'hy-AM'
                                              : 'en-US',
                                        )}
                                      </p>
                                      <p>
                                        📍 {(action as BookDriverAction).from} →{' '}
                                        {(action as BookDriverAction).to}
                                      </p>
                                      <p>
                                        👥 {(action as BookDriverAction).passengerCount} passengers
                                      </p>
                                      {(action as BookDriverAction).purpose && (
                                        <p>💼 {(action as BookDriverAction).purpose}</p>
                                      )}
                                    </>
                                  ) : action.type !== 'DELETE_LEAVE' ? (
                                    <>
                                      <p>
                                        📅 {action.startDate} → {action.endDate}
                                      </p>
                                      <p>
                                        ⏱️ {action.days} day{action.days !== 1 ? 's' : ''}
                                      </p>
                                      {(action as BookLeaveAction).reason && (
                                        <p>📝 {(action as BookLeaveAction).reason}</p>
                                      )}
                                    </>
                                  ) : (
                                    <>
                                      <p>👤 {(action as DeleteLeaveAction).employeeName}</p>
                                      <p>
                                        📅 {(action as DeleteLeaveAction).startDate} →{' '}
                                        {(action as DeleteLeaveAction).endDate}
                                      </p>
                                      <p className="text-red-500 font-medium">
                                        ⚠️ This action cannot be undone
                                      </p>
                                    </>
                                  )}
                                </div>

                                {state.status === 'pending' && (
                                  <button
                                    onClick={() => handleAction(m.id, action, idx)}
                                    className={`w-full py-2 px-3 text-white text-xs font-semibold rounded-lg hover:opacity-90 transition-opacity ${
                                      isDelete
                                        ? 'bg-linear-to-r from-red-500 to-red-600'
                                        : isEdit
                                          ? 'bg-linear-to-r from-yellow-500 to-orange-500'
                                          : 'bg-linear-to-r from-[#2563eb] to-[#0ea5e9]'
                                    }`}
                                  >
                                    {isDelete
                                      ? t('chatWidget.confirmDelete')
                                      : isEdit
                                        ? t('chatWidget.confirmUpdate')
                                        : t('chatWidget.confirmSend')}
                                  </button>
                                )}
                                {state.status === 'loading' && (
                                  <div className="flex items-center justify-center gap-2 py-2">
                                    <ShieldLoader size="xs" variant="inline" />
                                    <span className="text-xs text-(--text-muted)">
                                      {t('chatWidget.submitting')}
                                    </span>
                                  </div>
                                )}
                                {state.status === 'booked' && (
                                  <div className="flex items-start gap-2 p-2 bg-green-500/10 rounded-lg border border-green-500/20">
                                    <CheckCircle className="w-4 h-4 text-green-500 shrink-0 mt-0.5" />
                                    <p className="text-xs text-green-600 dark:text-green-400">
                                      {state.result}
                                    </p>
                                  </div>
                                )}
                                {state.status === 'conflict' && (
                                  <div className="flex items-start gap-2 p-2 bg-red-500/10 rounded-lg border border-red-500/20">
                                    <AlertCircle className="w-4 h-4 text-red-500 shrink-0 mt-0.5" />
                                    <div className="flex-1">
                                      <p className="text-xs text-red-600 dark:text-red-400 whitespace-pre-line">
                                        {state.result}
                                      </p>

                                      {state.conflicts && state.conflicts.length > 0 && (
                                        <div className="mt-2 space-y-1">
                                          {state.conflicts.map((conflict: any, idx: number) => (
                                            <div
                                              key={idx}
                                              className="text-xs text-red-700 dark:text-red-300 bg-red-500/5 p-2 rounded border border-red-500/10"
                                            >
                                              <p className="font-medium">{conflict.title}</p>
                                              <p className="mt-0.5 text-red-600 dark:text-red-400">
                                                {conflict.message}
                                              </p>
                                              <p className="mt-1 text-red-500 dark:text-red-300">
                                                💡 {conflict.suggestion}
                                              </p>
                                            </div>
                                          ))}
                                        </div>
                                      )}

                                      {state.alternativeDates &&
                                        state.alternativeDates.length > 0 && (
                                          <div className="mt-3">
                                            <p className="text-xs font-medium text-red-700 dark:text-red-300 mb-1">
                                              ✅ Доступные даты без конфликтов:
                                            </p>
                                            <div className="flex flex-wrap gap-1.5">
                                              {state.alternativeDates.map((dateRange, idx) => (
                                                <button
                                                  key={idx}
                                                  onClick={() => {
                                                    setInput(`Хочу отпуск ${dateRange}`);
                                                    setMessages((prev) =>
                                                      prev.map((msg) =>
                                                        msg.id === m.id
                                                          ? {
                                                              ...msg,
                                                              bookingStates: {
                                                                ...msg.bookingStates,
                                                                [idx]: { status: 'pending' },
                                                              },
                                                            }
                                                          : msg,
                                                      ),
                                                    );
                                                  }}
                                                  className="px-3 py-1.5 rounded-full border border-green-500/30 bg-green-500/10 hover:bg-green-500/20 text-xs text-green-700 dark:text-green-400 font-medium transition-all"
                                                >
                                                  📅 {dateRange}
                                                </button>
                                              ))}
                                            </div>
                                          </div>
                                        )}
                                    </div>
                                  </div>
                                )}
                              </motion.div>
                            );
                          })}
                        </div>
                      )}

                      {/* Follow-up suggestions */}
                      {!isUser && m.suggestions && m.suggestions.length > 0 && !isLoading && (
                        <motion.div
                          initial={{ opacity: 0, y: 4 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 0.3 }}
                          className="flex flex-wrap gap-1.5 mt-1"
                        >
                          {m.suggestions.map((s) => (
                            <button
                              key={s}
                              onClick={() => handleSuggestion(s)}
                              disabled={isLoading}
                              className="px-2.5 py-1 rounded-full border border-[#2563eb]/30 bg-[#2563eb]/5 hover:bg-[#2563eb]/15 hover:border-[#2563eb]/60 text-[10px] text-[#2563eb] font-medium transition-all duration-150 disabled:opacity-50"
                            >
                              {s}
                            </button>
                          ))}
                        </motion.div>
                      )}
                    </div>
                  </div>
                );
              })}

              {/* Loading indicator with stages */}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="bg-(--background-subtle) px-4 py-3 rounded-2xl rounded-bl-sm flex items-center gap-2">
                    <div className="flex gap-1">
                      <span
                        className="w-1.5 h-1.5 rounded-full bg-[#2563eb] animate-bounce"
                        style={{ animationDelay: '0ms' }}
                      />
                      <span
                        className="w-1.5 h-1.5 rounded-full bg-[#2563eb] animate-bounce"
                        style={{ animationDelay: '150ms' }}
                      />
                      <span
                        className="w-1.5 h-1.5 rounded-full bg-[#2563eb] animate-bounce"
                        style={{ animationDelay: '300ms' }}
                      />
                    </div>
                    <TypingStages />
                  </div>
                </div>
              )}

              <div ref={messagesEndRef} />
            </div>

            {/* Error */}
            {error && (
              <div className="px-4 py-2 bg-red-500/10 border-t border-red-500/20 shrink-0">
                <p className="text-xs text-red-500">⚠️ {error}</p>
              </div>
            )}

            {/* Pinned messages panel */}
            {showPinned && (
              <div className="px-4 py-2 border-t border-(--border) max-h-32 overflow-y-auto bg-(--background-subtle)">
                <p className="text-[10px] font-semibold text-(--text-muted) mb-1">📌 Pinned</p>
                {getPinnedMessages().length === 0 ? (
                  <p className="text-[10px] text-(--text-muted)">{t('aiChat.noPinnedMessages')}</p>
                ) : (
                  getPinnedMessages().map((p) => (
                    <div
                      key={p.id}
                      className="text-[10px] text-(--text-primary) py-1 border-b border-(--border) last:border-0 line-clamp-2"
                    >
                      {p.content.slice(0, 100)}
                      {p.content.length > 100 ? '...' : ''}
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Input */}
            <form onSubmit={handleSubmit} className="p-4 border-t border-(--border) shrink-0">
              <div className="relative">
                {/* Slash command autocomplete */}
                {slashCommands.length > 0 && (
                  <SlashCommandDropdown
                    commands={slashCommands}
                    onSelect={(cmd) => {
                      setInput(cmd + ' ');
                      inputRef.current?.focus();
                    }}
                  />
                )}
                <input
                  ref={inputRef}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={
                    isListening ? t('chatWidget.listening') : t('chatWidget.placeholder')
                  }
                  className={`w-full px-4 py-2.5 pr-20 bg-(--input) border rounded-xl text-(--text-primary) placeholder:text-(--text-muted) focus:outline-none focus:ring-2 focus:ring-[#2563eb] text-sm transition-colors ${
                    isListening ? 'border-[#2563eb] ring-2 ring-[#2563eb]/30' : 'border-(--border)'
                  }`}
                  disabled={isLoading}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSubmit(e);
                    }
                  }}
                />
                <div className="absolute right-1.5 top-1/2 -translate-y-1/2 flex items-center gap-1">
                  <button
                    type="button"
                    onClick={startVoiceInput}
                    disabled={isLoading}
                    title={isListening ? t('chatWidget.stopListening') : t('chatWidget.voiceInput')}
                    className={`p-1.5 rounded-lg transition-colors disabled:opacity-50 ${
                      isListening
                        ? 'text-[#2563eb] animate-pulse'
                        : 'text-(--text-muted) hover:text-[#3b82f6]'
                    }`}
                  >
                    {isListening ? <MicOff className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
                  </button>
                  <Button
                    type="submit"
                    disabled={isLoading || !input.trim()}
                    className="btn-gradient disabled:opacity-50 h-8 w-8 p-0 rounded-lg"
                    size="sm"
                  >
                    {isLoading ? (
                      <ShieldLoader size="xs" variant="inline" />
                    ) : (
                      <Send className="w-4 h-4" />
                    )}
                  </Button>
                </div>
              </div>
            </form>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import { useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { usePlanFeatures } from '@/hooks/usePlanFeatures';
import { useSubscription } from '@/hooks/useSubscription';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import {
  Send,
  Sparkles,
  Code2,
  Palette,
  Layout,
  Zap,
  History,
  AlertCircle,
  Crown,
  Undo2,
  CheckCircle2,
  FileCode2,
  RefreshCw,
} from 'lucide-react';
import { toast } from 'sonner';
import { useTranslation } from 'react-i18next';
import { formatDateTime } from '@/lib/date-format';
import { useRouter } from 'next/navigation';
import { logger } from '@/lib/logger';
import { ErrorBoundary } from '@/components/error/ErrorBoundary';

// ─── Types ────────────────────────────────────────────────────────────────────

interface AppliedFile {
  filePath: string;
  timestamp: number;
  description: string;
}

interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
  editType?: 'design' | 'content' | 'layout' | 'logic' | 'full_control';
  timestamp: number;
  appliedFiles?: AppliedFile[];
}

interface BackupMeta {
  originalPath: string;
  timestamp: number;
  description: string;
}

interface SiteEditorChatProps {
  userId: string;
  organizationId: string;
}

// ─── Icon helpers ─────────────────────────────────────────────────────────────

function getEditTypeIcon(type?: string) {
  switch (type) {
    case 'design':
      return <Palette className="h-3 w-3" />;
    case 'content':
      return <Code2 className="h-3 w-3" />;
    case 'layout':
      return <Layout className="h-3 w-3" />;
    case 'logic':
      return <Zap className="h-3 w-3" />;
    case 'full_control':
      return <Crown className="h-3 w-3" />;
    default:
      return null;
  }
}

// ─── Component ────────────────────────────────────────────────────────────────

export function SiteEditorChat({ userId, organizationId }: SiteEditorChatProps) {
  const { t, i18n } = useTranslation();
  const router = useRouter();

  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'system',
      content: t('aiSiteEditor.greeting'),
      timestamp: Date.now(),
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [rollingBack, setRollingBack] = useState<string | null>(null); // "filePath:timestamp"
  const [backups, setBackups] = useState<BackupMeta[]>([]);
  const [showBackups, setShowBackups] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const { features, plan } = usePlanFeatures();
  const { isActive } = useSubscription();

  const usage = useQuery(api.aiSiteEditor.getCurrentMonthUsage, {
    userId: userId as Id<'users'>,
  });

  const history = useQuery(api.aiSiteEditor.getHistory, {
    userId: userId as Id<'users'>,
    limit: 10,
  });

  // Scroll to bottom on new messages
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  // Fetch backups list
  const fetchBackups = useCallback(async () => {
    try {
      const res = await fetch('/api/ai-site-editor/apply');
      if (res.ok) {
        const data = await res.json();
        setBackups(data.backups || []);
      }
    } catch {
      // silent
    }
  }, []);

  useEffect(() => {
    fetchBackups();
  }, [fetchBackups]);

  // ─── Send message ──────────────────────────────────────────────────────────

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      role: 'user',
      content: input,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMessage]);
    const currentInput = input;
    setInput('');
    setIsLoading(true);

    // Добавляем плейсхолдер «думает...»
    setMessages((prev) => [
      ...prev,
      {
        role: 'assistant',
        content: '',
        timestamp: Date.now(),
      },
    ]);

    try {
      const response = await fetch('/api/ai-site-editor', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: currentInput,
          userId,
          organizationId,
          plan,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        setMessages((prev) => prev.slice(0, -1));

        if (error.limitReached) {
          toast.error(error.error, {
            action: {
              label: t('aiSiteEditor.upgradePlan'),
              onClick: () => router.push('/settings?tab=billing'),
            },
          });
          setMessages((prev) => [
            ...prev,
            {
              role: 'system',
              content: `⚠️ ${error.error}`,
              timestamp: Date.now(),
            },
          ]);
          return;
        }
        throw new Error(error.error || 'Server error');
      }

      // Парсим JSON ответ
      const data = await response.json();
      const { response: aiText, appliedFiles, editType } = data;

      // Обновляем сообщение с результатом
      setMessages((prev) => {
        const updated = [...prev];
        updated[updated.length - 1] = {
          role: 'assistant',
          content: aiText,
          editType,
          timestamp: Date.now(),
        };
        return updated;
      });

      // Показываем результат
      if (appliedFiles && appliedFiles.length > 0) {
        toast.success(`✅ Применено ${appliedFiles.length} изменений! Файлы обновлены.`, {
          duration: 5000,
        });
        logger.log('Applied files:', appliedFiles);
      } else {
        toast.info('AI ответил, но файлы не были изменены', { duration: 3000 });
      }

      // Обновляем список backup'ов
      fetchBackups();
    } catch (error) {
      console.error('Error:', error);
      setMessages((prev) => {
        const updated = [...prev];
        updated[updated.length - 1] = {
          role: 'system',
          content: `❌ ${t('aiSiteEditor.error')}`,
          timestamp: Date.now(),
        };
        return updated;
      });
      toast.error(t('aiSiteEditor.error'));
    } finally {
      setIsLoading(false);
    }
  };

  // ─── Rollback ──────────────────────────────────────────────────────────────

  const handleRollback = async (filePath: string, timestamp: number) => {
    const key = `${filePath}:${timestamp}`;
    setRollingBack(key);

    try {
      const res = await fetch('/api/ai-site-editor/apply', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filePath, timestamp }),
      });

      const data = await res.json();

      if (res.ok && data.success) {
        toast.success(`↩️ Откат выполнен: ${filePath}`);
        fetchBackups();
        setMessages((prev) => [
          ...prev,
          {
            role: 'system',
            content: `↩️ Откат выполнен для файла ${filePath}`,
            timestamp: Date.now(),
          },
        ]);
      } else {
        toast.error(`Ошибка отката: ${data.error || 'Неизвестная ошибка'}`);
      }
    } catch {
      toast.error('Ошибка при выполнении отката');
    } finally {
      setRollingBack(null);
    }
  };

  // ─── Render helpers ────────────────────────────────────────────────────────

  const getEditTypeLabel = (type?: string) => {
    switch (type) {
      case 'design':
        return t('aiSiteEditor.design');
      case 'content':
        return t('aiSiteEditor.content');
      case 'layout':
        return t('aiSiteEditor.layout');
      case 'logic':
        return t('aiSiteEditor.logic');
      case 'full_control':
        return t('aiSiteEditor.fullControl');
      default:
        return '';
    }
  };

  const isProfessionalOrHigher = plan === 'professional' || plan === 'enterprise';

  // ─── JSX ───────────────────────────────────────────────────────────────────

  return (
    <ErrorBoundary>
      <div className="flex flex-col h-full space-y-4">
        {/* Usage Stats — только для starter */}
        {!isProfessionalOrHigher && usage && (
          <Card className="p-4 bg-linear-to-r from-amber-100/10 to-orange-100/10 dark:from-amber-900/10 dark:to-orange-900/10 border-amber-300/20 dark:border-amber-800/20">
            <div className="flex items-start gap-3">
              <AlertCircle className="h-5 w-5 text-amber-500 dark:text-amber-600 mt-0.5" />
              <div className="flex-1">
                <h4 className="font-semibold text-amber-900 dark:text-amber-100 mb-2">
                  {t('aiSiteEditor.usageThisMonth')}
                </h4>
                <div className="grid grid-cols-3 gap-4 text-sm">
                  <div>
                    <div className="text-amber-500 dark:text-amber-600">
                      {t('aiSiteEditor.design')}
                    </div>
                    <div className="font-semibold text-amber-900 dark:text-amber-100">
                      {usage.designChanges} / {features.aiSiteEditorDesignChanges}
                    </div>
                  </div>
                  <div>
                    <div className="text-amber-600 dark:text-amber-500">
                      {t('aiSiteEditor.content')}
                    </div>
                    <div className="font-semibold text-amber-900 dark:text-amber-100">
                      {usage.contentChanges} / {features.aiSiteEditorContentChanges}
                    </div>
                  </div>
                  <div>
                    <div className="text-amber-600 dark:text-amber-500">
                      {t('aiSiteEditor.layout')}
                    </div>
                    <div className="font-semibold text-amber-900 dark:text-amber-100">
                      {usage.layoutChanges} / {features.aiSiteEditorLayoutChanges}
                    </div>
                  </div>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  className="mt-3 border-amber-300 dark:border-amber-700 md:border-amber-300/50 sm:min-w-[120px]"
                  onClick={() => router.push('/settings?tab=billing')}
                >
                  <Crown className="h-4 w-4 mr-2" />
                  {t('aiSiteEditor.upgradeForUnlimited')}
                </Button>
              </div>
            </div>
          </Card>
        )}

        {/* Professional/Enterprise badge */}
        {isProfessionalOrHigher && (
          <Card className="p-4 bg-linear-to-r from-purple-900/10 to-blue-900/10 dark:from-purple-50/20 dark:to-blue-50/20 border-purple-700/30 dark:border-purple-300/20">
            <div className="flex items-center gap-3">
              <Crown className="h-5 w-5 text-purple-600 dark:text-purple-400" />
              <div>
                <h4 className="font-semibold">
                  {plan === 'professional'
                    ? t('aiSiteEditor.professionalPlan')
                    : t('aiSiteEditor.enterprisePlan')}
                </h4>
                <p className="text-sm">
                  {t('aiSiteEditor.unlimited')} · {t('aiSiteEditor.aiAutoApplies')}
                </p>
              </div>
            </div>
          </Card>
        )}

        {/* Chat Messages */}
        <Card className="flex-1 flex flex-col min-h-0">
          <ScrollArea className="flex-1 p-4" ref={scrollRef}>
            <div className="space-y-4">
              {messages.map((msg, idx) => (
                <div
                  key={idx}
                  className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div
                    className={`max-w-[85%] rounded-lg p-4 ${
                      msg.role === 'user'
                        ? 'bg-primary text-primary-foreground'
                        : msg.role === 'system'
                          ? 'bg-muted text-muted-foreground'
                          : 'bg-secondary text-secondary-foreground'
                    }`}
                  >
                    {/* Edit type badge */}
                    {msg.editType && (
                      <Badge variant="outline" className="mb-2">
                        {getEditTypeIcon(msg.editType)}
                        <span className="ml-1">{getEditTypeLabel(msg.editType)}</span>
                      </Badge>
                    )}

                    {/* Message content */}
                    <div className="whitespace-pre-wrap text-sm leading-relaxed">
                      {msg.content || (
                        <span className="flex items-center gap-2 text-muted-foreground">
                          <ShieldLoader size="xs" variant="inline" />
                          AI читает файлы и применяет изменения…
                        </span>
                      )}
                    </div>

                    {/* Applied files list with per-file rollback */}
                    {msg.appliedFiles && msg.appliedFiles.length > 0 && (
                      <div className="mt-3 space-y-1 border-t pt-3">
                        <p className="text-xs font-medium text-muted-foreground mb-1">
                          📂 Изменённые файлы:
                        </p>
                        {msg.appliedFiles.map((af) => {
                          const key = `${af.filePath}:${af.timestamp}`;
                          const isRollingThisBack = rollingBack === key;
                          return (
                            <div
                              key={key}
                              className="flex items-center justify-between gap-2 rounded bg-background/50 px-2 py-1"
                            >
                              <div className="flex items-center gap-1.5 min-w-0">
                                <FileCode2 className="h-3 w-3 shrink-0 text-green-500" />
                                <span className="text-xs truncate font-mono">{af.filePath}</span>
                              </div>
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-6 px-2 shrink-0 text-xs"
                                disabled={isRollingThisBack}
                                onClick={() => handleRollback(af.filePath, af.timestamp)}
                              >
                                {isRollingThisBack ? (
                                  <ShieldLoader size="xs" variant="inline" />
                                ) : (
                                  <>
                                    <Undo2 className="h-3 w-3 mr-1" />
                                    Откат
                                  </>
                                )}
                              </Button>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                </div>
              ))}

              {/* Global loading indicator */}
              {isLoading && messages[messages.length - 1]?.content === '' && (
                <div className="flex justify-start">
                  <div className="bg-secondary text-secondary-foreground rounded-lg p-4">
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <Sparkles className="h-4 w-4 animate-pulse text-purple-500" />
                      AI читает код и применяет изменения…
                    </div>
                  </div>
                </div>
              )}
            </div>
          </ScrollArea>

          {/* Input area */}
          <div className="p-4 border-t">
            <div className="flex gap-2">
              <Textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
                placeholder={t('aiSiteEditor.inputPlaceholder')}
                className="min-h-[60px] resize-none"
                disabled={isLoading}
              />
              <Button
                onClick={handleSend}
                disabled={!input.trim() || isLoading}
                size="icon"
                className="h-[60px] w-[60px]"
              >
                {isLoading ? (
                  <ShieldLoader size="sm" variant="inline" />
                ) : (
                  <Send className="h-5 w-5" />
                )}
              </Button>
            </div>
          </div>
        </Card>

        {/* Backup / Rollback panel */}
        {backups.length > 0 && (
          <Card className="p-4">
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-semibold flex items-center gap-2 text-sm">
                <History className="h-4 w-4" />
                История изменений ({backups.length} backup-ов)
              </h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setShowBackups((v) => !v);
                  fetchBackups();
                }}
              >
                <RefreshCw className="h-3 w-3 mr-1" />
                {showBackups ? 'Скрыть' : 'Показать'}
              </Button>
            </div>

            {showBackups && (
              <div className="space-y-2 max-h-48 overflow-y-auto">
                {backups.slice(0, 20).map((b) => {
                  const key = `${b.originalPath}:${b.timestamp}`;
                  const isRollingThisBack = rollingBack === key;
                  return (
                    <div
                      key={key}
                      className="flex items-center justify-between gap-2 text-sm p-2 rounded hover:bg-muted/50 transition-colors"
                    >
                      <div className="min-w-0 flex-1">
