export function TypingStages() {
  const { t } = useTranslation();
  const stages = [
    t('chatWidget.thinking', { defaultValue: 'Analyzing...' }),
    t('chatWidget.stageThinking', { defaultValue: 'Thinking...' }),
    t('chatWidget.stageGenerating', { defaultValue: 'Generating...' }),
