                <Button variant="outline" onClick={() => setDeleteConfirmAsset(null)}>
                  {t('common.cancel')}
                </Button>
                <Button
                  variant="default"
                  onClick={() => {
                    const asset = deleteConfirmAsset;
                    setDeleteConfirmAsset(null);
                    setSelectedAsset(asset);
                  }}
                >
                  <ArrowUpRight className="w-4 h-4 mr-2" />
                  {t('assets.openDetails', 'Open Asset Details')}
                </Button>
              </DialogFooter>
            </>
          ) : (
            <>
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2 text-destructive">
                  <X className="w-5 h-5" />
                  {t('assets.confirmDelete', 'Delete Asset')}
                </DialogTitle>
                <DialogDescription>
                  {t(
                    'assets.deleteConfirmMessage',
                    'Are you sure you want to delete this asset? This action cannot be undone.',
                  )}
                </DialogDescription>
              </DialogHeader>
              <div className="bg-background-subtle rounded-xl p-4 my-4">
                <p className="text-sm font-medium text-foreground">
                  <strong>{deleteConfirmAsset?.name || '—'}</strong>
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  {deleteConfirmAsset?.serialNumber && `SN: ${deleteConfirmAsset.serialNumber}`}
                </p>
              </div>
              <DialogFooter>
                <Button variant="outline" onClick={() => setDeleteConfirmAsset(null)}>
                  {t('common.cancel')}
                </Button>
                <Button variant="destructive" onClick={() => handleDelete(deleteConfirmAsset._id)}>
                  <X className="w-4 h-4 mr-2" />
                  {t('common.delete')}
                </Button>
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>
    </motion.div>
  );
}

'use client';

import React from 'react';
import { useQuery } from 'convex/react';
import { useTranslation } from 'react-i18next';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Calendar, Clock, TrendingUp, AlertTriangle, Award, Target } from 'lucide-react';
import { motion } from '@/lib/cssMotion';
import { useAuthStore } from '@/store/useAuthStore';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';
import i18n from 'i18next';
import { ShieldLoader } from '@/components/ui/ShieldLoader';

export function AttendanceDashboard() {
  const { user } = useAuthStore();
  const { t } = useTranslation(['modules', 'common']);
  const currentMonth = new Date().toISOString().slice(0, 7); // "2026-02"
  const lang = i18n.language || 'en';
  const dateFnsLocale = lang === 'ru' ? ru : lang === 'hy' ? hy : enUS;

  const monthlyStats = useQuery(
    api.timeTracking.getMonthlyStats,
    user?.id ? { userId: user.id as Id<'users'>, month: currentMonth } : 'skip',
  );

  const history = useQuery(
    api.timeTracking.getUserHistory,
    user?.id ? { userId: user.id as Id<'users'>, limit: 10 } : 'skip',
  );

  if (!monthlyStats) {
    return (
      <Card>
        <CardContent className="p-6">
          <ShieldLoader size="md" className="py-8" />
        </CardContent>
      </Card>
    );
  }

  const stats = [
    {
      label: t('attendanceExtra.daysWorked'),
      value: monthlyStats.totalDays,
      icon: Calendar,
      color: 'text-blue-500',
      borderColor: 'border-blue-500/30',
      iconBg: 'bg-blue-500/10',
    },
    {
      label: t('attendanceExtra.totalHours'),
      value: `${monthlyStats.totalWorkedHours}${t('time.h')}`,
      icon: Clock,
      color: 'text-green-500',
      borderColor: 'border-green-500/30',
      iconBg: 'bg-green-500/10',
    },
    {
      label: t('attendanceExtra.punctuality'),
      value: `${monthlyStats.punctualityRate}%`,
      icon: Target,
      color: 'text-sky-400',
      borderColor: 'border-sky-400/30',
      iconBg: 'bg-sky-400/10',
    },
    {
      label: t('attendanceExtra.overtime'),
      value: `${monthlyStats.totalOvertimeHours}${t('time.h')}`,
      icon: Award,
      color: 'text-orange-500',
      borderColor: 'border-orange-500/30',
      iconBg: 'bg-orange-500/10',
    },
  ];

  return (
    <div className="space-y-6">
      {/* Monthly Stats */}
      <div>
        <h2 className="text-2xl font-bold mb-4" style={{ color: 'var(--text-primary)' }}>
          {t('attendance.monthlyAttendance')}
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {stats.map((stat, index) => (
            <motion.div
              key={stat.label}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <Card
                className={`border ${stat.borderColor}`}
                style={{ background: 'var(--background-card)' }}
              >
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-(--text-muted) mb-1">{stat.label}</p>
                      <p className={`text-3xl font-bold ${stat.color}`}>{stat.value}</p>
                    </div>
                    <div className={`p-3 rounded-xl ${stat.iconBg}`}>
                      <stat.icon className={`w-7 h-7 ${stat.color}`} />
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      </div>

      {/* Issues Alert */}
      {(Number(monthlyStats.lateDays) > 0 || Number(monthlyStats.earlyLeaveDays) > 0) && (
        <Card
          className="border border-orange-500/30"
          style={{ background: 'var(--background-card)' }}
        >
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-orange-500">
              <AlertTriangle className="w-5 h-5" />
              {t('attendanceIssues.title')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {Number(monthlyStats.lateDays) > 0 && (
                <p style={{ color: 'var(--text-primary)' }}>
                  • {monthlyStats.lateDays} {t('attendanceIssues.lateArrivals')}
                </p>
              )}
              {Number(monthlyStats.earlyLeaveDays) > 0 && (
                <p style={{ color: 'var(--text-primary)' }}>
                  • {monthlyStats.earlyLeaveDays} {t('attendanceIssues.earlyLeaves')}
                </p>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Recent History */}
      <Card>
        <CardHeader>
          <CardTitle>{t('attendance.recentAttendance')}</CardTitle>
        </CardHeader>
        <CardContent>
          {!history || history.length === 0 ? (
            <p className="text-center text-(--text-muted) py-4">
              {t('attendanceIssues.noRecordsYet')}
            </p>
          ) : (
            <div className="space-y-3">
              {history.map((record) => (
                <div
                  key={record._id}
                  className="flex flex-wrap gap-2 items-center justify-between p-4 rounded-lg border"
                  style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
                >
                  <div className="flex items-center gap-4">
                    <div>
                      <p className="font-medium" style={{ color: 'var(--text-primary)' }}>
                        {format(new Date(record.date), 'MMMM dd, yyyy', { locale: dateFnsLocale })}
                      </p>
                      <p className="text-sm text-(--text-muted)">
                        {record.checkInTime
                          ? format(new Date(record.checkInTime), 'HH:mm', { locale: dateFnsLocale })
                          : '—'}{' '}
                        →{' '}
                        {record.checkOutTime
                          ? format(new Date(record.checkOutTime), 'HH:mm', {
                              locale: dateFnsLocale,
                            })
                          : '—'}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {record.status === 'checked_in' && (
                      <Badge className="bg-green-500 text-white">
                        {t('taskStatus.inProgress')}
                      </Badge>
                    )}
                    {record.status === 'checked_out' && record.totalWorkedMinutes && (
                      <Badge variant="secondary">
                        {Math.floor(record.totalWorkedMinutes / 60)}
                        {t('attendanceExtra.hoursShort')} {record.totalWorkedMinutes % 60}
                        {t('attendanceExtra.minutesShort')}
                      </Badge>
                    )}
                    {record.isLate && <Badge variant="destructive">{t('statuses.late')}</Badge>}
                    {record.isEarlyLeave && (
                      <Badge className="bg-orange-500 text-white">
                        {t('attendanceIssues.early')}
                      </Badge>
                    )}
                    {record.overtimeMinutes && record.overtimeMinutes > 0 && (
                      <Badge className="bg-sky-400 text-white">
                        +{Math.floor(record.overtimeMinutes / 60)}
                        {t('attendanceExtra.hoursShort')} {t('attendanceExtra.overtimeShort')}
                      </Badge>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default AttendanceDashboard;

'use client';
import Image from 'next/image';

import { useTranslation } from 'react-i18next';
import { formatTime as formatTimeUtil } from '@/lib/date-format';
import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import {
  X,
  Clock,
  LogIn,
  LogOut,
  AlertTriangle,
  CheckCircle,
  Calendar,
  Timer,
  TrendingUp,
  User,
  Building2,
} from 'lucide-react';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import type { Id } from '../../../convex/_generated/dataModel';

export interface AttendanceRecord {
  _id: string;
  userId: Id<'users'>;
  date: string;
  checkInTime: number;
  checkOutTime?: number;
  totalWorkedMinutes?: number;
  status: 'checked_in' | 'checked_out' | 'absent';
  isLate?: boolean;
  lateMinutes?: number;
  isEarlyLeave?: boolean;
  earlyLeaveMinutes?: number;
  overtimeMinutes?: number;
  user?: {
    name?: string;
    email?: string;
    department?: string;
    position?: string;
    role?: string;
    avatarUrl?: string;
    supervisorName?: string;
  };
}

interface AttendanceDetailModalProps {
  record: AttendanceRecord | null;
  open: boolean;
  onClose: () => void;
}

function formatTime(timestamp: number, lang: string) {
  return formatTimeUtil(timestamp, lang, {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
}

function formatDuration(minutes: number) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${h}h ${m}m`;
}

export function AttendanceDetailModal({ record, open, onClose }: AttendanceDetailModalProps) {
  const { t, i18n } = useTranslation(['modules', 'common']);
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  const currentMonth = new Date().toISOString().slice(0, 7); // "2026-02"
  const monthlyStats = useQuery(
    api.timeTracking.getMonthlyStats,
    record?.userId ? { userId: record.userId, month: currentMonth } : 'skip',
  );

  const recentRecords = useQuery(
    api.timeTracking.getRecentAttendance,
    record?.userId ? { userId: record.userId, limit: 7 } : 'skip',
  );

  if (!record) return null;

  const workedHours = record.totalWorkedMinutes
    ? (record.totalWorkedMinutes / 60).toFixed(1)
    : null;
  const expectedHours = 9; // 9:00 to 18:00
  const workCompletion = workedHours
    ? Math.min(100, (parseFloat(workedHours) / expectedHours) * 100)
    : 0;

  if (monthlyStats === undefined)
    return (
      <div className="flex items-center justify-center p-8">
        <ShieldLoader size="md" />
      </div>
    );

  return (
    <>
      {mounted &&
        createPortal(
          <AnimatePresence>
            {open && (
              <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                {/* Backdrop */}
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="absolute inset-0 bg-black/60 backdrop-blur-sm"
                  onClick={onClose}
                />

                {/* Modal */}
                <motion.div
                  initial={{ opacity: 0, scale: 0.95, y: 20 }}
                  animate={{ opacity: 1, scale: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.95, y: 20 }}
                  transition={{ type: 'spring', stiffness: 300, damping: 25 }}
                  className="relative w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden border border-border bg-background"
                >
                  {/* Header gradient */}
                  <div className="relative h-28 bg-gradient-to-r from-primary to-primary/80 flex items-end px-6 pb-4">
                    <Button
                      onClick={onClose}
                      variant="ghost"
                      size="icon"
                      className="absolute! top-4 right-4 w-8 h-8 rounded-full bg-white/20 hover:bg-white/30 transition-colors"
                    >
                      <X className="w-4 h-4 text-white" />
                    </Button>

                    {/* Avatar */}
                    <div className="flex items-end gap-4">
                      <div className="w-16 h-16 rounded-full shrink-0 overflow-hidden shadow-lg bg-gradient-to-r from-primary to-primary/80 flex items-center justify-center text-white text-2xl font-bold">
                        {record.user?.avatarUrl ? (
                          <img
                            src={record.user.avatarUrl}
                            alt={record.user.name ?? ''}
                            className="w-full h-full object-cover scale-110"
                            referrerPolicy="no-referrer"
                          />
                        ) : (
                          (record.user?.name
                            ?.split(' ')
                            .map((n) => n[0])
                            .join('')
                            .toUpperCase()
                            .slice(0, 2) ?? '?')
                        )}
                      </div>
                      <div className="pb-1">
                        <h2 className="text-xl font-bold text-white">
                          {record.user?.name ?? t('common.unknownUser', 'Unknown')}
                        </h2>
                        <p className="text-white/70 text-sm">
                          {record.user?.position ?? record.user?.role ?? 'Employee'}
                        </p>
                      </div>
                    </div>
                  </div>

                  {/* Content */}
                  <div className="bg-background p-6 space-y-5 max-h-[70vh] overflow-y-auto">
                    {/* Date & Status */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Calendar className="w-4 h-4" />
                        {new Date(record.date).toLocaleDateString(
                          i18n?.language === 'ru'
                            ? 'ru-RU'
                            : i18n?.language === 'hy'
                              ? 'hy-AM'
                              : 'en-GB',
                          {
                            weekday: 'long',
                            day: 'numeric',
                            month: 'long',
                            year: 'numeric',
                          },
                        )}
                      </div>
                      <div className="flex gap-2">
                        {record.status === 'checked_in' && (
                          <Badge className="bg-green-500 text-white">{t('common.active')}</Badge>
                        )}
                        {record.status === 'checked_out' && (
                          <Badge className="bg-blue-500 text-white">{t('common.done')}</Badge>
                        )}
                        {record.status === 'absent' && (
                          <Badge variant="destructive">{t('statuses.absent')}</Badge>
                        )}
                      </div>
                    </div>

                    {/* Timeline */}
                    <div className="rounded-xl p-4 space-y-4 border border-border bg-muted/30 shadow-sm">
                      <h3 className="text-sm font-semibold text-foreground flex items-center gap-2">
                        <Clock className="w-4 h-4 text-blue-500" />
                        {t('attendance.timeLine')}
                      </h3>
                      <div className="flex items-center gap-3">
                        {/* Check In */}
                        <div className="flex-1 rounded-lg p-3 bg-muted/30 border border-border">
                          <div className="flex items-center gap-2 mb-1">
                            <LogIn className="w-4 h-4 text-green-500" />
                            <span className="text-xs text-muted-foreground">
                              {t('attendance.checkIn')}
                            </span>
                          </div>
                          <p className="text-lg font-bold text-green-600 dark:text-green-400">
                            {record.checkInTime
                              ? formatTime(record.checkInTime, i18n.language)
                              : '—'}
                          </p>
                          {record.isLate && (
                            <p className="text-xs text-red-500 mt-1 flex items-center gap-1">
                              <AlertTriangle className="w-3 h-3" />
                              {t('attendance.lateBy', { minutes: record.lateMinutes })}
                            </p>
                          )}
                          {!record.isLate && record.checkInTime && (
                            <p className="text-xs text-green-500 mt-1 flex items-center gap-1">
                              <CheckCircle className="w-3 h-3" />
                              {t('attendance.onTime')}
                            </p>
                          )}
                        </div>

                        {/* Arrow */}
                        <div className="text-muted-foreground text-lg">→</div>

                        {/* Check Out */}
                        <div className="flex-1 rounded-lg p-3 bg-muted/30 border border-border">
                          <div className="flex items-center gap-2 mb-1">
                            <LogOut className="w-4 h-4 text-blue-500" />
                            <span className="text-xs text-muted-foreground">
                              {t('attendance.checkOut')}
                            </span>
                          </div>
                          <p className="text-lg font-bold text-blue-600 dark:text-blue-400">
                            {record.checkOutTime
                              ? formatTime(record.checkOutTime, i18n.language)
                              : '—'}
                          </p>
                          {record.isEarlyLeave && record.earlyLeaveMinutes && (
                            <p className="text-xs text-orange-500 mt-1 flex items-center gap-1">
                              <AlertTriangle className="w-3 h-3" />
                              {t('attendance.earlyLeave', { minutes: record.earlyLeaveMinutes })}
                            </p>
                          )}
                          {record.checkOutTime && !record.isEarlyLeave && (
                            <p className="text-xs text-green-500 mt-1 flex items-center gap-1">
                              <CheckCircle className="w-3 h-3" />
                              {t('attendance.fullDay')}
                            </p>
                          )}
                          {!record.checkOutTime && record.status === 'checked_in' && (
                            <p className="text-xs text-green-500 mt-1">
                              {t('attendance.stillWorking')}
                            </p>
                          )}
                        </div>
                      </div>

                      {/* Work duration */}
                      {workedHours && (
                        <div>
                          <div className="flex justify-between text-xs text-muted-foreground mb-1">
                            <span className="flex items-center gap-1">
                              <Timer className="w-3 h-3" /> {t('attendance.worked')}
                            </span>
                            <span className="font-semibold text-foreground">
                              {workedHours}h / {expectedHours}h
                            </span>
                          </div>
                          <div className="h-2 rounded-full bg-muted overflow-hidden">
                            <motion.div
                              initial={{ width: 0 }}
                              animate={{ width: `${workCompletion}%` }}
                              transition={{ duration: 0.8, ease: 'easeOut' }}
                              className={`h-full rounded-full ${workCompletion >= 100 ? 'bg-green-500' : workCompletion >= 70 ? 'bg-blue-500' : 'bg-orange-500'}`}
                            />
                          </div>
                          {record.overtimeMinutes && record.overtimeMinutes > 0 && (
                            <p className="text-xs text-sky-500 mt-1">
                              +{formatDuration(record.overtimeMinutes)}{' '}
                              {t('attendanceExtra.overtime')}
                            </p>
                          )}
                        </div>
                      )}
                    </div>

                    {/* Department + Supervisor */}
                    <div className="flex flex-wrap gap-4">
                      {record.user?.department && (
                        <div className="flex items-center gap-2 text-sm text-muted-foreground bg-muted/30 px-3 py-2 rounded-lg">
                          <Building2 className="w-4 h-4" />
                          {record.user.department} {t('common.department')}
                        </div>
                      )}
                      {record.user?.supervisorName && (
                        <div className="flex items-center gap-2 text-sm text-blue-600 dark:text-blue-400 bg-muted/30 px-3 py-2 rounded-lg">
                          <User className="w-4 h-4" />
                          Supervisor:{' '}
                          <span className="font-semibold">{record.user.supervisorName}</span>
                        </div>
                      )}
                    </div>

                    {/* Monthly Stats */}
                    {monthlyStats && (
                      <div className="rounded-xl p-4 bg-muted/30 border border-border shadow-sm">
                        <h3 className="text-sm font-semibold text-foreground flex items-center gap-2 mb-3">
                          <TrendingUp className="w-4 h-4 text-sky-500" />
                          {t('attendance.thisMonth')}
                        </h3>
                        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                          <div className="text-center p-3 bg-background rounded-lg">
                            <p className="text-xl font-bold text-blue-600 dark:text-blue-400">
                              {monthlyStats.totalDays}
                            </p>
                            <p className="text-xs text-muted-foreground">
                              {t('attendanceExtra.daysWorked')}
                            </p>
                          </div>
                          <div className="text-center p-3 bg-background rounded-lg">
                            <p className="text-xl font-bold text-green-600 dark:text-green-400">
                              {monthlyStats.punctualityRate}%
                            </p>
                            <p className="text-xs text-muted-foreground">
                              {t('attendanceExtra.punctuality')}
                            </p>
                          </div>
                          <div className="text-center p-3 bg-background rounded-lg">
                            <p className="text-xl font-bold text-orange-600 dark:text-orange-400">
                              {monthlyStats.lateDays}
                            </p>
                            <p className="text-xs text-muted-foreground">
                              {t('attendanceExtra.lateDays')}
                            </p>
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Recent 7 days */}
                    {recentRecords && recentRecords.length > 0 && (
                      <div className="rounded-xl p-4 bg-muted/30 border border-border shadow-sm">
                        <h3 className="text-sm font-semibold text-foreground flex items-center gap-2 mb-3">
                          <Calendar className="w-4 h-4 text-blue-500" />
                          {t('attendance.last7Days')}
                        </h3>
                        <div className="space-y-2">
                          {recentRecords.map((r) => (
                            <div
                              key={r._id}
                              className="flex items-center justify-between text-sm p-2 bg-background rounded-lg"
                            >
                              <span className="text-muted-foreground">
                                {new Date(r.date).toLocaleDateString(
                                  i18n?.language === 'ru'
                                    ? 'ru-RU'
                                    : i18n?.language === 'hy'
                                      ? 'hy-AM'
                                      : 'en-GB',
                                  {
                                    weekday: 'short',
                                    day: 'numeric',
                                    month: 'short',
                                  },
                                )}
                              </span>
                              <div className="flex items-center gap-2">
                                {r.checkInTime ? (
                                  <span className="text-xs text-muted-foreground">
                                    {formatTime(r.checkInTime, i18n.language)} →{' '}
                                    {r.checkOutTime
                                      ? formatTime(r.checkOutTime, i18n.language)
                                      : '...'}
                                  </span>
                                ) : null}
                                {r.isLate && (
                                  <Badge variant="destructive" className="text-xs py-0">
                                    {t('statuses.late')}
                                  </Badge>
                                )}
                                {r.status === 'checked_out' && !r.isLate && (
                                  <Badge className="bg-green-500 text-white text-xs py-0">✓</Badge>
                                )}
                                {r.status === 'checked_in' && (
                                  <Badge className="bg-green-500 text-white text-xs py-0">
                                    {t('statuses.active')}
                                  </Badge>
                                )}
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </motion.div>
              </div>
            )}
          </AnimatePresence>,
          document.body,
        )}
    </>
  );
}

﻿'use client';

import { useTranslation } from 'react-i18next';
import React, { useState, useEffect } from 'react';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Clock, LogIn, LogOut, TrendingUp, AlertCircle } from 'lucide-react';
import { toast } from 'sonner';
import { useAuthStore } from '@/store/useAuthStore';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';

export function CheckInOutWidget() {
  const { t, i18n } = useTranslation(['modules', 'common']);
  const dfLocale = i18n.language === 'ru' ? ru : i18n.language === 'hy' ? hy : enUS;
  const { user } = useAuthStore();
  const [currentTime, setCurrentTime] = useState<Date>(new Date());

  const todayStatus = useQuery(
    api.timeTracking.getTodayStatus,
    user?.id ? { userId: user.id as Id<'users'> } : 'skip',
  );

  const checkIn = useMutation(api.timeTracking.checkIn);
  const checkOut = useMutation(api.timeTracking.checkOut);

  // Update current time every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const handleCheckIn = async () => {
    if (!user?.id) return;
    try {
      await checkIn({ userId: user.id as Id<'users'> });
      toast.success(t('toasts.checkedInSuccess'));
    } catch (error: any) {
      toast.error(error.message || t('attendance.failedCheckIn'));
    }
  };

  const handleCheckOut = async () => {
    if (!user?.id) return;
    try {
      await checkOut({ userId: user.id as Id<'users'> });
      toast.success(t('toasts.checkedOutSuccess'));
    } catch (error: any) {
      toast.error(error.message || t('attendance.failedCheckOut'));
    }
  };

  const isCheckedIn = todayStatus?.status === 'checked_in';
  const isCheckedOut = todayStatus?.status === 'checked_out';

  const formatTime = (timestamp: number) => {
    return format(new Date(timestamp), 'HH:mm:ss', { locale: dfLocale });
  };

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}${t('attendanceExtra.hoursShort')} ${mins}${t('attendanceExtra.minutesShort')}`;
  };

  if (todayStatus === undefined)
    return (
      <div className="flex items-center justify-center p-8">
        <ShieldLoader size="md" />
      </div>
    );

  return (
    <Card className="overflow-hidden">
      <CardHeader className="btn-gradient text-white font-medium shadow-md hover:shadow-lg">
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2 text-white">
            <Clock className="w-5 h-5" />
            {t('attendance.timeTracker')}
          </CardTitle>
          <div className="text-2xl font-mono">
            {currentTime ? format(currentTime, 'HH:mm:ss', { locale: dfLocale }) : '--:--:--'}
          </div>
        </div>
      </CardHeader>

      <CardContent className="p-6 space-y-4">
        {/* Current Status */}
        <div className="flex items-center justify-between p-4 rounded-lg bg-(--background-subtle)">
          <div>
            <p className="text-sm text-(--text-muted)">{t('attendance.status')}</p>
            <p className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>
              {!todayStatus && t('attendance.notCheckedIn')}
              {isCheckedIn && t('attendance.atWork')}
              {isCheckedOut && t('attendance.finishedToday')}
            </p>
          </div>
          <Badge
            variant={isCheckedIn ? 'default' : isCheckedOut ? 'secondary' : 'outline'}
            className={
              isCheckedIn ? 'bg-green-500 text-white' : isCheckedOut ? 'bg-blue-500 text-white' : ''
            }
          >
            {!todayStatus && t('attendance.offline')}
            {isCheckedIn && t('attendance.online')}
            {isCheckedOut && t('attendance.offline')}
          </Badge>
        </div>

        {/* Check In/Out Times */}
        {todayStatus && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="p-3 rounded-lg border" style={{ borderColor: 'var(--border)' }}>
              <div className="flex items-center gap-2 mb-1">
                <LogIn className="w-4 h-4 text-green-500" />
                <span className="text-xs text-(--text-muted)">{t('attendance.checkIn')}</span>
              </div>
              <p className="font-semibold" style={{ color: 'var(--text-primary)' }}>
                {formatTime(todayStatus.checkInTime)}
              </p>
              {todayStatus.isLate && todayStatus.lateMinutes && (
                <p className="text-xs text-red-500 mt-1">
                  {t('attendance.lateBy', { minutes: todayStatus.lateMinutes })}
                </p>
              )}
            </div>

            <div className="p-3 rounded-lg border" style={{ borderColor: 'var(--border)' }}>
              <div className="flex items-center gap-2 mb-1">
                <LogOut className="w-4 h-4 text-blue-500" />
                <span className="text-xs text-(--text-muted)">{t('attendance.checkOut')}</span>
              </div>
              <p className="font-semibold" style={{ color: 'var(--text-primary)' }}>
                {todayStatus.checkOutTime ? formatTime(todayStatus.checkOutTime) : '—'}
              </p>
              {todayStatus.isEarlyLeave && todayStatus.earlyLeaveMinutes && (
                <p className="text-xs text-orange-500 mt-1">
                  {t('attendance.leftEarlyBy', { minutes: todayStatus.earlyLeaveMinutes })}
                </p>
              )}
            </div>
          </div>
        )}

        {/* Work Duration */}
        {todayStatus && todayStatus.totalWorkedMinutes && (
          <div className="p-4 rounded-lg bg-linear-to-r from-green-50 to-blue-50 dark:from-green-950 dark:to-blue-950">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-green-600 dark:text-green-400" />
                <span className="font-medium" style={{ color: 'var(--text-primary)' }}>
                  {t('attendance.totalWorked')}
                </span>
              </div>
              <span className="text-2xl font-bold text-green-600 dark:text-green-400">
                {formatDuration(todayStatus.totalWorkedMinutes)}
              </span>
            </div>
            {todayStatus.overtimeMinutes && todayStatus.overtimeMinutes > 0 && (
              <p className="text-sm text-green-600 dark:text-green-400 mt-2">
                +{formatDuration(todayStatus.overtimeMinutes)} {t('attendanceExtra.overtimeShort')}{' '}
                🌟
              </p>
            )}
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex gap-3 pt-2">
          {!todayStatus && (
            <Button
              onClick={handleCheckIn}
              className="flex-1 bg-green-500 hover:bg-green-600 text-white"
              size="lg"
            >
              <LogIn className="w-5 h-5 mr-2" />
              {t('attendance.checkIn')}
            </Button>
          )}

          {isCheckedIn && (
            <Button onClick={handleCheckOut} className="flex-1 btn-gradient" size="lg">
              <LogOut className="w-5 h-5 mr-2" />
              {t('attendance.checkOut')}
            </Button>
          )}

          {isCheckedOut && (
            <div className="flex-1 p-4 rounded-lg bg-blue-50 dark:bg-blue-950 text-center">
              <p className="text-blue-600 dark:text-blue-400 font-medium">
                {t('attendance.seeYouTomorrow')}
              </p>
            </div>
          )}
        </div>

        {/* Info Message */}
        {!todayStatus && (
          <div className="flex items-start gap-2 p-3 rounded-lg bg-yellow-50 dark:bg-yellow-950">
            <AlertCircle className="w-4 h-4 text-yellow-600 dark:text-yellow-400 mt-0.5" />
            <p className="text-sm text-yellow-700 dark:text-yellow-300">
              {t('ui.notCheckedInWarning')}
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export default CheckInOutWidget;

'use client';
