      description: t('rating.teamworkDesc', 'Collaboration and support for colleagues'),
    },
    {
      key: 'initiative',
      label: t('dashboard.initiative'),
      description: t('rating.initiativeDesc', 'Proactiveness and self-motivation'),
    },
    {
      key: 'communication',
      label: t('dashboard.communication'),
      description: t('rating.communicationDesc', 'Clarity and effectiveness in communication'),
    },
    {
      key: 'reliability',
      label: t('dashboard.reliability'),
      description: t('rating.reliabilityDesc', 'Dependability and consistency'),
    },
  ];
  const { user } = useAuthStore();
  const createRating = useMutation(api.supervisorRatings.createRating);

  const [ratings, setRatings] = useState<Record<string, number>>({
    qualityOfWork: 3,
    efficiency: 3,
    teamwork: 3,
    initiative: 3,
    communication: 3,
    reliability: 3,
  });

  const [strengths, setStrengths] = useState('');
  const [areasForImprovement, setAreasForImprovement] = useState('');
  const [generalComments, setGeneralComments] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleRatingChange = (category: string, value: number) => {
    setRatings((prev) => ({ ...prev, [category]: value }));
  };

  const handleSubmit = async () => {
    if (!user?.id || user.id === '') return;

    setIsSubmitting(true);
    try {
      await createRating({
        employeeId,
        supervisorId: user.id as Id<'users'>,
        qualityOfWork: ratings.qualityOfWork ?? 3,
        efficiency: ratings.efficiency ?? 3,
        teamwork: ratings.teamwork ?? 3,
        initiative: ratings.initiative ?? 3,
        communication: ratings.communication ?? 3,
        reliability: ratings.reliability ?? 3,
        strengths: strengths || undefined,
        areasForImprovement: areasForImprovement || undefined,
        generalComments: generalComments || undefined,
      });

      toast.success(
        t('rating.submittedSuccess', 'Rating submitted for {{name}}!', { name: employeeName }),
      );
      onSuccess?.();
      onClose?.();
    } catch (error: any) {
      toast.error(error.message || t('rating.submitFailed', 'Failed to submit rating'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const averageRating = Object.values(ratings).reduce((sum, r) => sum + r, 0) / 6;

  return (
    <Card className="w-full max-w-3xl">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>{t('rating.performanceRating', 'Performance Rating')}</CardTitle>
            <CardDescription>
              {t('rating.evaluatePerformance', "Evaluate {{name}}'s performance", {
                name: employeeName,
              })}
            </CardDescription>
          </div>
          {onClose && (
            <Button
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="text-white hover:bg-white/20"
            >
              <X className="w-5 h-5" />
            </Button>
          )}
        </div>
      </CardHeader>

      <CardContent className="p-6 space-y-6">
        {/* Rating Categories */}
        <div className="space-y-4">
          <h3 className="font-semibold text-lg" style={{ color: 'var(--text-primary)' }}>
            {t('rating.ratePerformance', 'Rate Performance (1-5)')}
          </h3>

          {categories.map((category) => (
            <div key={category.key} className="space-y-2">
              <div className="flex items-center justify-between">
                <div>
                  <Label className="text-base">{category.label}</Label>
                  <p className="text-sm text-(--text-muted)">{category.description}</p>
                </div>
                <div className="flex items-center gap-1">
                  {[1, 2, 3, 4, 5].map((value) => (
                    <button
                      key={value}
                      type="button"
                      onClick={() => handleRatingChange(category.key, value)}
                      className="p-1 transition-transform hover:scale-110"
                    >
                      <Star
                        className={`w-6 h-6 ${
                          value <= (ratings[category.key] ?? 0)
                            ? 'fill-yellow-400 text-yellow-400'
                            : 'text-gray-300'
                        }`}
                      />
                    </button>
                  ))}
                  <span
                    className="ml-2 text-lg font-semibold w-8 text-center"
                    style={{ color: 'var(--text-primary)' }}
                  >
                    {ratings[category.key] ?? 0}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Average Score */}
        <div className="p-4 rounded-lg bg-(--input)">
          <div className="flex items-center justify-between">
            <span className="font-medium text-black/70 dark:text-white/70">
              {t('rating.overallAverage', 'Overall Average')}
            </span>
            <div className="flex items-center gap-2">
              <Star className="w-6 h-6 fill-yellow-400 text-yellow-400" />
              <span className="text-3xl font-bold text-sky-500 dark:text-sky-400">
                {averageRating.toFixed(1)}
              </span>
              <span className="text-sm text-(--text-muted)">/ 5.0</span>
            </div>
          </div>
        </div>

        {/* Text Feedback */}
        <div className="space-y-4">
          <h3 className="font-semibold text-lg" style={{ color: 'var(--text-primary)' }}>
            {t('rating.writtenFeedback', 'Written Feedback (Optional)')}
          </h3>

          <div className="space-y-2">
            <Label>{t('labels.strengths')}</Label>
            <Textarea
              placeholder={t('placeholders.whatDoesWell', 'What does this employee do well?')}
              value={strengths}
              onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setStrengths(e.target.value)}
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>{t('labels.areasForImprovement')}</Label>
            <Textarea
              placeholder={t('placeholders.canImprove', 'What areas can be improved?')}
              value={areasForImprovement}
              onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
                setAreasForImprovement(e.target.value)
              }
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>{t('labels.generalComments')}</Label>
            <Textarea
              placeholder={t(
                'placeholders.additionalFeedbackNotes',
                'Any additional feedback or notes...',
              )}
              value={generalComments}
              onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
                setGeneralComments(e.target.value)
              }
              rows={3}
            />
          </div>
        </div>

        {/* Submit Button */}
        <div className="flex gap-3 pt-4">
          {onClose && (
            <Button variant="outline" onClick={onClose} className="flex-1">
              {t('common.cancel', 'Cancel')}
            </Button>
          )}
          <Button onClick={handleSubmit} disabled={isSubmitting} className="flex-1" variant="info">
            {isSubmitting ? (
              t('rating.submitting', 'Submitting...')
            ) : (
              <>
                <Send className="w-4 h-4 mr-2" />
                {t('rating.submitRating', 'Submit Rating')}
              </>
            )}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

export default SupervisorRatingForm;

'use client';

import { useTranslation } from 'react-i18next';
import { useRef, useState, useEffect, useCallback } from 'react';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Camera, CheckCircle, XCircle, ScanFace } from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { CustomSelect } from '@/components/ui/CustomSelect';
import { toast } from 'sonner';
import { logger } from '@/lib/logger';
import { detectFace, loadFaceApiModels } from '@/lib/faceApi';
import { useAuthStore } from '@/store/useAuthStore';
import { useRouter } from 'next/navigation';

export function FaceLogin() {
  const { t } = useTranslation();
  const router = useRouter();

  const videoRef = useRef<HTMLVideoElement>(null);

  // ===== Refs (чтобы в setInterval всегда были актуальные значения) =====
  const streamRef = useRef<MediaStream | null>(null);
  const intervalRef = useRef<number | null>(null);
  const playStartedRef = useRef(false);
  const loopStartedRef = useRef(false);

  const processingRef = useRef(false);
  const autoTriggeredRef = useRef(false);
  const lastAttemptRef = useRef(0);

  const progressRef = useRef(0);
  const qualityRef = useRef<'poor' | 'good' | 'excellent'>('poor');
  const faceDetectedRef = useRef(false);

  const lastDescriptorRef = useRef<Float32Array | null>(null);
  const noFaceFramesRef = useRef(0);
  const detectionInProgressRef = useRef(false);

  // ===== UI State =====
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [faceDetected, setFaceDetected] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);

  const [matchStatus, setMatchStatus] = useState<'idle' | 'searching' | 'found' | 'not_found'>(
    'idle',
  );
  const [matchedUser, setMatchedUser] = useState<string | null>(null);

  const [cameras, setCameras] = useState<MediaDeviceInfo[]>([]);
  const [selectedCamera, setSelectedCamera] = useState<string>('');

  const [failedAttempts, setFailedAttempts] = useState(0);
  const [isBlocked, setIsBlocked] = useState(false);

  const [scanningProgress, setScanningProgress] = useState(0);
  const [detectionQuality, setDetectionQuality] = useState<'poor' | 'good' | 'excellent'>('poor');

  const [autoLoginTriggered, setAutoLoginTriggered] = useState(false);
  const [lastAttemptTime, setLastAttemptTime] = useState(0);

  // SECURITY: server-side face matching requires the user to identify themselves
  // by email BEFORE capturing the face. We no longer broadcast all descriptors
  // to the browser (that was a GDPR-grade biometric leak + auth bypass).
  const [emailInput, setEmailInput] = useState('');
  useEffect(() => {
    // Pre-fill from query string if provided (e.g. /login?email=x@y)
    const params = new URLSearchParams(window.location.search);
    const qEmail = params.get('email');
    if (qEmail) setEmailInput(qEmail);
  }, []);

  // sync a few refs (безопасно, но триггер используем ref’ы)
  useEffect(() => {
    processingRef.current = isProcessing;
  }, [isProcessing]);
  useEffect(() => {
    lastAttemptRef.current = lastAttemptTime;
  }, [lastAttemptTime]);
  useEffect(() => {
    autoTriggeredRef.current = autoLoginTriggered;
  }, [autoLoginTriggered]);

  // ===== Data =====
  // Face matching is now server-side; we no longer need to download descriptors.
  const recordFaceIdAttempt = useMutation(api.users.auth.recordFaceIdAttempt);
  void recordFaceIdAttempt; // kept for potential server-side fallback calls

  // ===== Init once: models + camera list =====
  useEffect(() => {
    loadFaceApiModels().catch((err) => {
      console.error('Failed to load face models:', err);
      toast.error(t('faceLogin.modelsFailed', 'Failed to load face recognition models'));
    });

    (async () => {
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoDevices = devices.filter((d) => d.kind === 'videoinput');
        setCameras(videoDevices);
        if (videoDevices.length > 0) setSelectedCamera(videoDevices[0]!.deviceId);
      } catch (err) {
        console.error('Failed to enumerate devices:', err);
      }
    })();

    return () => {
      stopDetectionLoop();
      stopStreamTracks();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    // no-op: face descriptors are never loaded client-side anymore
  }, []);

  // ===== Helpers =====
  const stopStreamTracks = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
  };

  const stopDetectionLoop = () => {
    if (intervalRef.current) {
      window.clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    loopStartedRef.current = false;
  };

  const resetRefs = () => {
    progressRef.current = 0;
    qualityRef.current = 'poor';
    faceDetectedRef.current = false;
    lastDescriptorRef.current = null;
    autoTriggeredRef.current = false;
    processingRef.current = false;
    lastAttemptRef.current = 0;
    noFaceFramesRef.current = 0;
    detectionInProgressRef.current = false;
  };

  const hardResetUiState = () => {
    setFaceDetected(false);
    setMatchStatus('idle');
    setMatchedUser(null);

    setScanningProgress(0);
    setDetectionQuality('poor');

    setAutoLoginTriggered(false);
    setIsProcessing(false);

    resetRefs();
  };

  const stopWebcam = () => {
    stopDetectionLoop();
    stopStreamTracks();

    if (videoRef.current) {
      try {
        videoRef.current.onloadedmetadata = null;
        videoRef.current.srcObject = null;
      } catch {}
    }

    setStream(null);
    setIsWebcamActive(false);
    playStartedRef.current = false;

    hardResetUiState();
  };

  const startWebcam = async () => {
    if (isBlocked) {
      toast.error(t('faceLogin.blocked', 'Face ID is blocked. Please use email/password login.'), {
        duration: 5000,
      });
      return;
    }

    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        toast.error(
          'Camera access is not supported in this browser. Please use Chrome, Edge, or Firefox.',
        );
        return;
      }

      if (isWebcamActive || streamRef.current) {
        logger.warn('⚠️ Webcam already active, ignoring startWebcam');
        return;
      }

      const constraints: MediaStreamConstraints = {
        video: selectedCamera
          ? { deviceId: { exact: selectedCamera }, width: { ideal: 640 }, height: { ideal: 480 } }
          : { width: { ideal: 640 }, height: { ideal: 480 }, facingMode: 'user' },
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);

      streamRef.current = mediaStream;
      setStream(mediaStream);
      setIsWebcamActive(true);

      // дождаться, когда React нарисует <video/>
      await new Promise((r) => setTimeout(r, 0));

      const waitForVideo = async (maxAttempts = 20) => {
        for (let i = 0; i < maxAttempts; i++) {
          if (videoRef.current) return true;
          await new Promise((r) => setTimeout(r, 50));
        }
        return false;
      };

      const ok = await waitForVideo();
      if (!ok || !videoRef.current) {
        toast.error(t('faceLogin.videoNotFound', 'Video element not found. Please try again.'));
        stopWebcam();
        return;
      }

      videoRef.current.srcObject = mediaStream;

      const playVideoOnce = async () => {
        if (!videoRef.current) return;
        if (playStartedRef.current) return;
        playStartedRef.current = true;

        try {
          await videoRef.current.play();
          startDetectionLoop();
        } catch (err) {
          console.error('❌ Failed to play video:', err);
          toast.error(t('faceLogin.videoPlaybackFailed', 'Failed to start video playback'));
          playStartedRef.current = false;
        }
      };

      videoRef.current.onloadedmetadata = () => {
        playVideoOnce();
      };

      // fallback
      setTimeout(() => {
        if (videoRef.current && streamRef.current && isWebcamActive) playVideoOnce();
      }, 1000);
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      console.error('❌ Error accessing webcam:', error);
      stopWebcam();

      if (error?.name === 'NotAllowedError' || error?.name === 'PermissionDeniedError') {
        toast.error(
          'Camera permission denied. Please allow camera access in your browser settings.',
          {
            duration: 6000,
            description: 'Click the lock icon in the address bar and allow camera access.',
          },
        );
      } else if (error?.name === 'NotFoundError' || error?.name === 'DevicesNotFoundError') {
        toast.error(t('auth.noCameraFound'));
      } else if (error?.name === 'NotReadableError' || error?.name === 'TrackStartError') {
        toast.error(
          'Camera is already in use by another application. Please close other apps using the camera.',
        );
      } else {
        toast.error(`Unable to access camera: ${error?.message || 'Unknown error'}`);
      }
    }
  };

  // ===== Detection loop =====
  const startDetectionLoop = () => {
    if (!videoRef.current) return;
    if (!streamRef.current) return;

    if (loopStartedRef.current) return;
    loopStartedRef.current = true;

    // reset for new session
    hardResetUiState();

    intervalRef.current = window.setInterval(async () => {
      const video = videoRef.current;
      if (!video || !streamRef.current) {
        stopDetectionLoop();
        return;
      }

      // пока идёт логин — не гоняем детекцию
      if (processingRef.current) return;

      // предотвращаем overlapping вызовы detectFace
      if (detectionInProgressRef.current) return;

      if (video.readyState < 2) return;

      try {
        detectionInProgressRef.current = true;

        const detection = await detectFace(video);
        const faceFound = !!detection;

        detectionInProgressRef.current = false;

        if (!faceFound) {
          noFaceFramesRef.current += 1;

          if (faceDetectedRef.current) {
            faceDetectedRef.current = false;
            setFaceDetected(false);
          }

          // мягкий сброс после нескольких кадров без лица
          if (noFaceFramesRef.current >= 3) {
            progressRef.current = 0;
            setScanningProgress(0);

            qualityRef.current = 'poor';
            setDetectionQuality('poor');

            lastDescriptorRef.current = null;

            autoTriggeredRef.current = false;
            setAutoLoginTriggered(false);
          }
          return;
        }

        // face found
        noFaceFramesRef.current = 0;

        if (!faceDetectedRef.current) {
          faceDetectedRef.current = true;
          setFaceDetected(true);
        }

        // cache descriptor
        lastDescriptorRef.current = detection!.descriptor;

        // progress via ref (не через prev => prev+..)
        const nextProgress = Math.min(progressRef.current + 34, 100);
        progressRef.current = nextProgress;
        setScanningProgress(nextProgress);

        // quality via ref
        const box = detection!.detection.box;
        const faceSize = box.width * box.height;

        let quality: 'poor' | 'good' | 'excellent' = 'poor';
        if (faceSize > 40000) quality = 'excellent';
        else if (faceSize > 20000) quality = 'good';

        qualityRef.current = quality;
        setDetectionQuality(quality);

        // auto-trigger (только ref)
        const now = Date.now();

        const shouldTrigger =
          (qualityRef.current === 'good' || qualityRef.current === 'excellent') &&
          progressRef.current >= 100 &&
          !autoTriggeredRef.current &&
          !processingRef.current &&
          now - lastAttemptRef.current >= 2000;

        if (shouldTrigger) {
          // Server-side matching: we only need the user's email to be entered.
          if (!emailInput.trim()) {
            toast.error(t('faceLogin.emailRequired', 'Enter your email before face login'), {
              id: 'no-email',
            });

            progressRef.current = 0;
            setScanningProgress(0);

            autoTriggeredRef.current = false;
            setAutoLoginTriggered(false);
            return;
          }

          autoTriggeredRef.current = true;
          lastAttemptRef.current = now;
          setAutoLoginTriggered(true);
          setLastAttemptTime(now);

          logger.log('🚀 Auto-triggering attemptFaceLogin()');
          attemptFaceLogin();
        }
      } catch (e) {
        console.error('❌ Error in face detection loop:', e);
        detectionInProgressRef.current = false;
      }
    }, 300);
  };

  // ===== Login =====
  const attemptFaceLogin = useCallback(async () => {
    if (isBlocked) return;

    const video = videoRef.current;
    if (!video) return;

    // hard-guard
    if (processingRef.current) return;

    const email = emailInput.trim().toLowerCase();
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      toast.error(t('faceLogin.emailRequired', 'Enter your email before face login'));
      autoTriggeredRef.current = false;
      setAutoLoginTriggered(false);
      return;
    }

    processingRef.current = true;
    setIsProcessing(true);
    setMatchStatus('searching');

    try {
      // Use cached descriptor if we have one, otherwise do a fresh detect
      let descriptor = lastDescriptorRef.current;
      if (!descriptor) {
        const det = await detectFace(video);
        if (!det) {
          throw new Error(
            t(
              'faceLogin.noFaceDetected',
              'No face detected. Please position your face in the frame.',
            ),
          );
        }
        descriptor = det.descriptor;
      }

      // Convert Float32Array to plain number[] for JSON
      const descriptorArray = Array.from(descriptor);

      // Send email + descriptor to the server. The server does the matching
      // against the stored descriptor for this email. Descriptors of OTHER
      // users are never exposed to the browser.
      const response = await fetch('/api/auth/face-login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, faceDescriptor: descriptorArray }),
      });

      if (!response.ok) {
        const errorData = (await response.json().catch(() => ({}))) as {
          error?: string;
          organizationId?: string;
        };

        if (errorData?.error === 'maintenance') {
          router.push(
            `/login?maintenance=true${errorData.organizationId ? `&org=${errorData.organizationId}` : ''}`,
          );
          return;
        }

        // Treat any 401/403 as face mismatch
        if (response.status === 401 || response.status === 403) {
          setMatchStatus('not_found');
          const newAttempts = failedAttempts + 1;
          setFailedAttempts(newAttempts);
          toast.error(
            t('faceLogin.notRecognized', 'Face not recognized. Attempt {{n}} of 3').replace(
              '{{n}}',
              String(newAttempts),
            ),
          );
          if (newAttempts >= 3) {
            setIsBlocked(true);
            toast.error(
              t('faceLogin.blockedTooMany', 'Too many failed attempts. Face ID is now blocked.'),
            );
            stopWebcam();
          }
          autoTriggeredRef.current = false;
          setAutoLoginTriggered(false);
          return;
        }

        throw new Error(errorData?.error || 'Login failed');
      }

      const data = await response.json();

      setFailedAttempts(0);
      setMatchedUser(data?.session?.name ?? email);
      setMatchStatus('found');

      if (data?.session) {
        const { login } = useAuthStore.getState();
        login({
          id: data.session.userId,
          name: data.session.name,
          email: data.session.email,
          role: data.session.role,
          organizationId: data.session.organizationId,
          organizationSlug: data.session.organizationSlug,
          organizationName: data.session.organizationName,
          department: data.session.department,
          position: data.session.position,
          employeeType: data.session.employeeType,
          avatar: data.session.avatar,
        });
      }

      stopWebcam();

      const params = new URLSearchParams(window.location.search);
      const nextUrl = params.get('next');
      router.push(nextUrl || '/dashboard');
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      console.error('❌ Error during face login:', error);

      const msg = error?.message?.includes('Failed to fetch')
        ? 'Network error: Cannot connect to server. Please check your connection.'
        : error?.message || 'Failed to login with Face ID. Please try again.';

      toast.error(msg, { id: 'face-login-error', duration: 5000 });

      setMatchStatus('not_found');

      // allow retry
      autoTriggeredRef.current = false;
      setAutoLoginTriggered(false);

      progressRef.current = 0;
      setScanningProgress(0);

      setTimeout(() => setMatchStatus('idle'), 2000);
    } finally {
      processingRef.current = false;
      setIsProcessing(false);
    }
  }, [isBlocked, emailInput, failedAttempts, t, router]);

  return (
    <Card className="p-6 bg-[var(--surface-base)] border-[var(--border-primary)]">
      <div className="space-y-6">
        <div className="text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-blue-500/10 mb-4">
            <ScanFace className="w-8 h-8 text-blue-500" />
          </div>
          <h3 className="text-lg font-semibold text-(--text-primary)">
            {t('faceLogin.title', 'Face ID Login')}
          </h3>
          <p className="text-sm text-[var(--text-tertiary)] mt-1">
            {t('faceLogin.subtitle', 'Position your face in the camera to login')}
          </p>
        </div>

        {/* Camera Preview */}
        <div className="relative bg-black rounded-lg overflow-hidden aspect-video">
          {!isWebcamActive && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-white/60">
              <Camera className="w-16 h-16 mb-4" />
              <p className="text-sm">{t('faceLogin.cameraNotActive', 'Camera not active')}</p>
            </div>
          )}

          {isWebcamActive && (
            <>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                className="w-full h-full object-cover"
              />

              {/* Face detection indicator */}
              <div className="absolute top-4 right-4 space-y-2">
                {faceDetected ? (
                  <div className="flex items-center gap-2 bg-green-500/90 text-white px-3 py-1.5 rounded-full text-sm animate-pulse">
                    <CheckCircle className="w-4 h-4" />
                    Face Detected
                  </div>
                ) : (
                  <div className="flex items-center gap-2 bg-red-500/90 text-white px-3 py-1.5 rounded-full text-sm">
                    <XCircle className="w-4 h-4" />
                    No Face
                  </div>
                )}

                {/* Quality indicator */}
                {faceDetected && (
                  <div
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs text-white ${
                      detectionQuality === 'excellent'
                        ? 'bg-green-600/90'
                        : detectionQuality === 'good'
                          ? 'bg-yellow-600/90'
                          : 'bg-orange-600/90'
                    }`}
                  >
                    {detectionQuality === 'excellent' && '✓ Excellent'}
                    {detectionQuality === 'good' && '◐ Good'}
                    {detectionQuality === 'poor' && '⚠ Move Closer'}
                  </div>
                )}
              </div>

              {/* Match status */}
              {matchStatus !== 'idle' && (
                <div className="absolute bottom-4 left-1/2 -translate-x-1/2">
                  {matchStatus === 'searching' && (
                    <div className="flex items-center gap-2 bg-blue-500/90 text-white px-4 py-2 rounded-full text-sm">
                      <ShieldLoader size="xs" variant="inline" />
                      Searching for match...
                    </div>
                  )}
                  {matchStatus === 'found' && matchedUser && (
                    <div className="flex items-center gap-2 bg-green-500/90 text-white px-4 py-2 rounded-full text-sm">
                      <CheckCircle className="w-4 h-4" />
                      Welcome, {matchedUser}!
                    </div>
                  )}
                  {matchStatus === 'not_found' && (
                    <div className="flex items-center gap-2 bg-red-500/90 text-white px-4 py-2 rounded-full text-sm">
                      <XCircle className="w-4 h-4" />
                      Face not recognized
                    </div>
                  )}
                </div>
              )}

              {/* Face frame guide with animated scanning */}
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="relative">
                  <div
                    className={`w-64 h-80 border-4 rounded-2xl transition-all duration-300 ${
                      faceDetected
                        ? 'border-green-500/70 shadow-[0_0_20px_rgba(34,197,94,0.5)]'
                        : 'border-white/50'
                    }`}
                  >
                    {faceDetected && scanningProgress > 0 && (
                      <>
                        <div
                          className="absolute left-0 right-0 h-1 bg-linear-to-r from-transparent via-green-400 to-transparent animate-pulse"
                          style={{ top: `${scanningProgress}%`, transition: 'top 0.35s ease-out' }}
                        />
                        <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-green-400 animate-pulse" />
                        <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-green-400 animate-pulse" />
                        <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-green-400 animate-pulse" />
                        <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-green-400 animate-pulse" />
                      </>
                    )}
                  </div>

                  {faceDetected && scanningProgress > 0 && (
                    <div className="absolute -bottom-8 left-0 right-0 text-center">
                      <div className="text-white text-xs bg-black/50 px-2 py-1 rounded">
                        {t('faceLogin.scanning', 'Scanning')}: {scanningProgress}%
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </>
          )}
        </div>

        {/* Email input — required for server-side identity claim */}
        {!isWebcamActive && !isBlocked && (
          <div className="space-y-2">
            <label
              htmlFor="face-login-email"
              className="text-sm font-medium text-(--text-secondary)"
            >
              {t('faceLogin.emailLabel', 'Your email')}
            </label>
            <input
              id="face-login-email"
              type="email"
              autoComplete="email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              placeholder="you@example.com"
              className="w-full px-3 py-2 rounded-lg border border-[var(--border-primary)] bg-[var(--surface-base)] text-(--text-primary) text-sm"
            />
            <p className="text-xs text-(--text-tertiary)">
              {t(
                'faceLogin.emailHelper',
                'Your face is verified against this account only. Descriptors of other users are never sent to your browser.',
              )}
            </p>
          </div>
        )}

        {/* Camera Selection */}
        {!isWebcamActive && cameras.length > 1 && (
          <div className="space-y-2">
            <label className="text-sm font-medium text-(--text-secondary)">
              {t('auth.selectCamera')}
            </label>
            <CustomSelect
              value={selectedCamera}
              onChange={setSelectedCamera}
              fullWidth
              options={cameras.map((camera) => ({
                value: camera.deviceId,
                label: camera.label || `Camera ${cameras.indexOf(camera) + 1}`,
              }))}
              triggerClassName="w-full px-3 py-2 rounded-lg border border-[var(--border-primary)] bg-[var(--surface-base)] text-(--text-primary)"
              dropdownClassName="bg-[var(--surface-base)] border border-[var(--border-primary)] text-[var(--text-primary)]"
            />
          </div>
        )}

        {/* Attempts counter */}
        {failedAttempts > 0 && !isBlocked && (
          <div className="bg-orange-500/10 border border-orange-500/20 rounded-lg p-3">
            <p className="text-sm text-orange-600 dark:text-orange-400 text-center">
              ⚠️ Failed attempts: {failedAttempts} of 3
            </p>
          </div>
        )}

        {/* Blocked warning */}
        {isBlocked && (
          <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-4">
            <p className="text-sm text-red-600 dark:text-red-400 text-center font-medium">
              🚫 Face ID Blocked
            </p>
            <p className="text-xs text-red-600/80 dark:text-red-400/80 text-center mt-1">
              Too many failed attempts. Please use email/password login.
            </p>
          </div>
        )}

        {/* Controls */}
        <div className="flex gap-3">
          {!isWebcamActive && !isBlocked && (
            <Button onClick={startWebcam} className="flex-1">
              <Camera className="w-4 h-4 mr-2" />
              {t('faceLogin.start', 'Start Face Login')}
            </Button>
          )}

          {isWebcamActive && !isBlocked && (
            <>
              {isProcessing ? (
                <div className="flex-1 flex items-center justify-center gap-2 bg-blue-500/10 text-blue-600 dark:text-blue-400 px-4 py-3 rounded-lg border border-blue-500/20">
                  <ShieldLoader size="xs" variant="inline" />
                  <span className="text-sm font-medium">
                    {t('faceLogin.authenticating', 'Authenticating...')}
                  </span>
                </div>
              ) : (
                <div className="flex-1 flex items-center justify-center gap-2 bg-green-500/10 text-green-600 dark:text-green-400 px-4 py-3 rounded-lg border border-green-500/20">
                  <ScanFace className="w-4 h-4" />
                  <span className="text-sm font-medium">
                    {scanningProgress >= 100
                      ? t('faceLogin.ready', 'Ready to login...')
                      : `${t('faceLogin.scanning', 'Scanning')}... ${scanningProgress}%`}
                  </span>
                </div>
              )}
              <Button onClick={stopWebcam} variant="outline">
                {t('common.cancel', 'Cancel')}
              </Button>
            </>
          )}

          {isBlocked && (
            <Button onClick={() => router.push('/login')} className="flex-1" variant="default">
              {t('faceLogin.useEmailPassword', 'Use Email/Password Login')}
            </Button>
          )}
        </div>

        {/* Info */}
        <div className="bg-blue-500/10 border border-blue-500/20 rounded-lg p-4">
          <p className="text-xs text-(--text-secondary)">
            {t(
              'faceLogin.autoLoginInfo',
              '🚀 Automatic Login: Enter your email, then position your face in the camera. The server will verify your identity when the scan completes (100%).',
            )}
          </p>
        </div>
      </div>
    </Card>
  );
}

'use client';

import { useTranslation } from 'react-i18next';
import { useRef, useState, useEffect } from 'react';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Camera, CheckCircle, XCircle } from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { CustomSelect } from '@/components/ui/CustomSelect';
import { toast } from 'sonner';
import { detectFace, loadFaceApiModels, createCanvasFromVideo, canvasToBlob } from '@/lib/faceApi';
import { uploadAvatarToCloudinary } from '@/actions/cloudinary';
import { Id } from '../../../convex/_generated/dataModel';
import { logger } from '@/lib/logger';

interface FaceRegistrationProps {
  userId: Id<'users'>;
  onSuccess?: () => void;
  onCancel?: () => void;
}

export function FaceRegistration({ userId, onSuccess, onCancel }: FaceRegistrationProps) {
  const { t } = useTranslation();
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [faceDetected, setFaceDetected] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [cameras, setCameras] = useState<MediaDeviceInfo[]>([]);
  const [selectedCamera, setSelectedCamera] = useState<string>('');

  const registerFace = useMutation(api.faceRecognition.registerFace);

  useEffect(() => {
    // Load models on mount
    loadFaceApiModels().catch((err) => {
      console.error('Failed to load face models:', err);
      toast.error(t('faceRegistration.modelLoadFailed', 'Failed to load face recognition models'));
    });

    // Get available cameras
    async function getCameras() {
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoDevices = devices.filter((d) => d.kind === 'videoinput');
        logger.log('Available cameras:', videoDevices);
        setCameras(videoDevices);
        if (videoDevices.length > 0) {
          setSelectedCamera(videoDevices[0]!.deviceId);
        }
      } catch (err) {
        console.error('Failed to enumerate devices:', err);
      }
    }
    getCameras();

    return () => {
      // Cleanup webcam on unmount
      if (stream) {
        stream.getTracks().forEach((track) => track.stop());
      }
    };
  }, [stream]);

  const startWebcam = async () => {
    try {
      // Check if mediaDevices is supported
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        toast.error(
          t(
            'faceRegistration.cameraNotSupported',
            'Camera access is not supported in this browser. Please use Chrome, Edge, or Firefox.',
          ),
        );
        return;
      }

      logger.log('🎥 Requesting camera access...');
      logger.log('Selected camera:', selectedCamera);

      const constraints: MediaStreamConstraints = {
        video: selectedCamera
          ? {
              deviceId: { exact: selectedCamera },
              width: { ideal: 640 },
              height: { ideal: 480 },
            }
          : {
              width: { ideal: 640 },
              height: { ideal: 480 },
              facingMode: 'user',
            },
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);

      logger.log('✅ Camera access granted');

      // Set state to trigger video element rendering
      setStream(mediaStream);
      setIsWebcamActive(true);

      // Wait for React to render the video element
      await new Promise((resolve) => setTimeout(resolve, 0));

      // Wait for video element to be available in DOM
      const waitForVideoElement = async (maxAttempts = 20) => {
        for (let i = 0; i < maxAttempts; i++) {
          if (videoRef.current) {
            logger.log('📹 Video element found on attempt', i + 1);
            return true;
          }
          logger.log(`⏳ Waiting for video element... attempt ${i + 1}`);
          await new Promise((resolve) => setTimeout(resolve, 50));
        }
        return false;
      };

      const videoElementAvailable = await waitForVideoElement();

      if (!videoElementAvailable || !videoRef.current) {
        console.error('❌ Video element ref is null after waiting!');
        toast.error(
          t('faceRegistration.videoNotFound', 'Video element not found. Please try again.'),
        );
        // Stop the stream and reset state
        mediaStream.getTracks().forEach((track) => track.stop());
        setStream(null);
        setIsWebcamActive(false);
        return;
      }

      logger.log('📹 Setting up video element...');
      videoRef.current.srcObject = mediaStream;

      logger.log('⏳ Waiting for metadata to load...');

      // Ensure video plays
      const playVideo = async () => {
        if (!videoRef.current) {
          console.error('❌ videoRef is null when trying to play');
          return;
        }

        try {
          logger.log('🎬 Attempting to play video...');
          logger.log('Video element state:', {
            readyState: videoRef.current.readyState,
            paused: videoRef.current.paused,
            srcObject: !!videoRef.current.srcObject,
          });
          await videoRef.current.play();
          logger.log('✅ Video playing successfully');
          detectFaceLoop(true); // Force start with true flag
        } catch (err) {
          console.error('❌ Failed to play video:', err);
          toast.error(t('faceRegistration.videoPlaybackFailed', 'Failed to start video playback'));
        }
      };

      // Wait for metadata and play
      videoRef.current.onloadedmetadata = () => {
        logger.log('✅ Video metadata loaded');
        playVideo();
      };

      // Fallback: try to play after a short delay if metadata event doesn't fire
      setTimeout(() => {
        if (videoRef.current && isWebcamActive) {
          logger.log("⚠️ Metadata event didn't fire, trying to play anyway...");
          playVideo();
        }
      }, 1000);
    } catch (error: any) {
      console.error('❌ Error accessing webcam:', error);

      // Reset state on error
      setIsWebcamActive(false);
      setStream(null);

      if (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError') {
        toast.error(
          t(
            'faceRegistration.cameraPermissionDenied',
            'Camera permission denied. Please allow camera access in your browser settings.',
          ),
        );
      } else if (error.name === 'NotFoundError' || error.name === 'DevicesNotFoundError') {
        toast.error(
          t(
            'faceRegistration.noCameraFound',
            'No camera found. Please connect a camera and try again.',
          ),
        );
      } else if (error.name === 'NotReadableError' || error.name === 'TrackStartError') {
        toast.error(
          t('faceRegistration.cameraInUse', 'Camera is already in use by another application.'),
        );
      } else {
        toast.error(
          t('faceRegistration.cameraAccessError', 'Unable to access camera: {{message}}', {
            message: error.message || 'Unknown error',
          }),
        );
      }
    }
  };

  const stopWebcam = () => {
    if (stream) {
      stream.getTracks().forEach((track) => track.stop());
      setStream(null);
    }
    setIsWebcamActive(false);
    setFaceDetected(false);
  };

  const detectFaceLoop = (forceStart = false) => {
    logger.log('🔄 Starting face detection loop...');
    logger.log(
      'forceStart:',
      forceStart,
      'videoRef.current:',
      !!videoRef.current,
      'isWebcamActive:',
      isWebcamActive,
    );

    if (!videoRef.current) {
      logger.warn('⚠️ Cannot start detection loop - videoRef is null');
      return;
    }

    if (!forceStart && !isWebcamActive) {
      logger.warn('⚠️ Cannot start detection loop - isWebcamActive is false');
      return;
    }

    const interval = setInterval(async () => {
      if (!videoRef.current) {
        logger.log('🛑 Stopping face detection loop - videoRef is null');
        clearInterval(interval);
        return;
      }

      try {
        // Check if video is actually playing and has valid dimensions
        if (videoRef.current.readyState < 2) {
          logger.log('⏳ Video not ready yet, readyState:', videoRef.current.readyState);
          return;
        }

        const detection = await detectFace(videoRef.current);
        const faceFound = !!detection;

        // Only log when face detection status changes
        if (faceFound !== faceDetected) {
          logger.log(faceFound ? '✅ Face detected!' : '❌ No face detected');
        }

        setFaceDetected(faceFound);
      } catch (error) {
        console.error('Error in face detection loop:', error);
      }
    }, 500);

    return () => clearInterval(interval);
  };

  const captureFace = async () => {
    if (!videoRef.current) return;

    setIsProcessing(true);

    try {
      // Detect face and get descriptor
      const detection = await detectFace(videoRef.current);

      if (!detection) {
        toast.error(
          t(
            'faceRegistration.noFaceDetected',
            'No face detected. Please position your face in the frame.',
          ),
        );
        setIsProcessing(false);
        return;
      }

      // Get face descriptor (128-dimensional array)
      const descriptor = Array.from(detection.descriptor);

      // Create canvas and capture image
      const canvas = createCanvasFromVideo(videoRef.current);
      const base64Image = canvas.toDataURL('image/jpeg', 0.95);

      // Upload face image to Cloudinary
      const imageUrl = await uploadAvatarToCloudinary(base64Image, `face-${userId}`);

      // Save to database
      await registerFace({
        userId,
        faceDescriptor: descriptor,
        faceImageUrl: imageUrl,
      });

      setCapturedImage(canvas.toDataURL());
      stopWebcam();

      toast.success(
        t(
          'faceRegistration.faceRegistered',
          'Face registered successfully! You can now use Face ID to login.',
        ),
      );
      onSuccess?.();
    } catch (error) {
      console.error('Error capturing face:', error);
      toast.error(
        t('faceRegistration.registrationFailed', 'Failed to register face. Please try again.'),
      );
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <Card className="p-6 bg-[var(--surface-base)] border-[var(--border-primary)]">
      <div className="space-y-6">
        <div>
          <h3 className="text-lg font-semibold text-(--text-primary)">
            {t('faceRegistration.title', 'Register Face ID')}
          </h3>
          <p className="text-sm text-[var(--text-tertiary)] mt-1">
            {t(
              'faceRegistration.subtitle',
              'Position your face in the camera frame to register Face ID login',
            )}
          </p>
        </div>

        {/* Camera Preview */}
        <div className="relative bg-black rounded-lg overflow-hidden aspect-video">
          {!isWebcamActive && !capturedImage && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-white/60">
              <Camera className="w-16 h-16 mb-4" />
              <p className="text-sm">
                {t('faceRegistration.cameraNotActive', 'Camera not active')}
              </p>
            </div>
          )}

          {isWebcamActive && (
            <>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                muted
                className="w-full h-full object-cover"
              />

              {/* Face detection indicator */}
              <div className="absolute top-4 right-4">
                {faceDetected ? (
                  <div className="flex items-center gap-2 bg-green-500/90 text-white px-3 py-1.5 rounded-full text-sm">
                    <CheckCircle className="w-4 h-4" />
                    {t('faceRegistration.faceDetected', 'Face Detected')}
                  </div>
                ) : (
                  <div className="flex items-center gap-2 bg-red-500/90 text-white px-3 py-1.5 rounded-full text-sm">
                    <XCircle className="w-4 h-4" />
                    {t('faceRegistration.noFace', 'No Face')}
                  </div>
                )}
              </div>

              {/* Face frame guide */}
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-64 h-80 border-4 border-white/50 rounded-2xl" />
              </div>
            </>
          )}

          {capturedImage && (
            <img src={capturedImage} alt="Captured face" className="w-full h-full object-cover" />
          )}
        </div>

        {/* Camera Selection */}
        {!isWebcamActive && !capturedImage && cameras.length > 1 && (
          <div className="space-y-2">
            <label className="text-sm font-medium text-(--text-secondary)">
              {t('faceRegistration.selectCamera', 'Select Camera:')}
            </label>
            <CustomSelect
              value={selectedCamera}
              onChange={setSelectedCamera}
              fullWidth
              options={cameras.map((camera) => ({
                value: camera.deviceId,
                label: camera.label || `Camera ${cameras.indexOf(camera) + 1}`,
              }))}
              triggerClassName="w-full px-3 py-2 rounded-lg border border-[var(--border-primary)] bg-[var(--surface-base)] text-(--text-primary)"
              dropdownClassName="bg-[var(--surface-base)] border border-[var(--border-primary)] text-[var(--text-primary)]"
            />
          </div>
        )}

        {/* Controls */}
        <div className="flex gap-3">
          {!isWebcamActive && !capturedImage && (
            <Button onClick={startWebcam} className="flex-1">
              <Camera className="w-4 h-4 mr-2" />
              {t('faceRegistration.startCamera', 'Start Camera')}
            </Button>
          )}

          {isWebcamActive && (
            <>
              <Button
                onClick={captureFace}
                disabled={!faceDetected || isProcessing}
                className="flex-1"
              >
                {isProcessing ? (
                  <>
                    <ShieldLoader size="xs" variant="inline" className="mr-2" />
                    {t('common.processing', 'Processing...')}
                  </>
                ) : (
                  <>
                    <CheckCircle className="w-4 h-4 mr-2" />
                    {t('faceRegistration.captureAndRegister', 'Capture & Register')}
                  </>
                )}
              </Button>
              <Button onClick={stopWebcam} variant="outline">
                {t('common.cancel', 'Cancel')}
              </Button>
            </>
          )}

          {capturedImage && onCancel && (
            <Button onClick={onCancel} variant="outline" className="flex-1">
              {t('common.close', 'Close')}
            </Button>
          )}
        </div>

        {/* Instructions */}
        <div className="bg-blue-500/10 border border-blue-500/20 rounded-lg p-4">
          <h4 className="text-sm font-medium text-blue-400 mb-2">
            {t('faceRegistration.instructions', 'Instructions:')}
          </h4>
          <ul className="text-xs text-(--text-secondary) space-y-1 list-disc list-inside">
            <li>{t('faceRegistration.positionFace', 'Position your face within the frame')}</li>
            <li>{t('faceRegistration.goodLighting', 'Ensure good lighting on your face')}</li>
            <li>{t('faceRegistration.lookAtCamera', 'Look directly at the camera')}</li>
            <li>{t('faceRegistration.removeGlasses', 'Remove glasses or hats if possible')}</li>
            <li>{t('faceRegistration.waitForDetection', 'Wait for "Face Detected" indicator')}</li>
          </ul>
        </div>
      </div>
    </Card>
  );
}

