'use client';

import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useIdleTimer } from '@/hooks/useIdleTimer';
import { useAuthStore } from '@/store/useAuthStore';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Shield, Clock, LogOut, RefreshCw } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';

export function IdleTimeoutModal() {
  const { t } = useTranslation();
  const router = useRouter();
  const { logout: authLogout, user } = useAuthStore();
  const [showModal, setShowModal] = useState(false);

  const handleIdle = useCallback(() => {
    setShowModal(true);
  }, []);

  const handleActive = useCallback(() => {
    setShowModal(false);
  }, []);

  const handleLogout = useCallback(async () => {
    try {
      await fetch('/api/auth/logout', { method: 'POST' });
      authLogout();
    } catch {
      // Ignore errors — redirect anyway
    }
    window.location.href = '/login';
  }, [authLogout]);

  const handleExtendSession = useCallback(async () => {
    try {
      const res = await fetch('/api/auth/refresh-session', { method: 'POST' });
      if (res.ok) {
        setShowModal(false);
        toast.success(t('idleModal.sessionExtended', 'Session extended successfully'));
      } else {
        handleLogout();
      }
    } catch {
      handleLogout();
    }
  }, [handleLogout, t]);

  const IDLE_TIMEOUT = parseInt(process.env.NEXT_PUBLIC_IDLE_TIMEOUT || '900', 10);
  const WARNING_DURATION = parseInt(process.env.NEXT_PUBLIC_IDLE_WARNING_DURATION || '120', 10);

  const { showWarning, countdownSeconds, extendSession, isLoggedOut } = useIdleTimer({
    onIdle: handleIdle,
    onActive: handleActive,
    onLogout: handleLogout,
  });

  useEffect(() => {
    if (showWarning) {
      setShowModal(true);
    }
  }, [showWarning]);

  if (!showModal) return null;

  const isCountingDown = countdownSeconds > 0;
  const minutes = Math.floor(countdownSeconds / 60);
  const seconds = countdownSeconds % 60;

  return (
    <Dialog open={showModal} onOpenChange={(open) => !open && !isCountingDown && extendSession()}>
      <DialogContent className="sm:max-w-md" aria-describedby={undefined}>
        <DialogHeader className="space-y-4">
          <div
            className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center border ${
              isCountingDown
                ? 'bg-amber-500/10 border-amber-500/30'
                : 'bg-blue-500/10 border-blue-500/30'
            }`}
          >
            {isCountingDown ? (
              <Clock className="w-8 h-8 text-amber-500 animate-pulse" />
            ) : (
              <Shield className="w-8 h-8 text-blue-500" />
            )}
          </div>
          <DialogTitle className="text-center text-xl font-semibold text-(--text-primary)">
            {isCountingDown
              ? t('idleModal.sessionExpiring', 'Session Expiring Soon')
              : t('idleModal.sessionExpired', 'Session Expired')}
          </DialogTitle>
          <div className="text-center text-(--text-muted) space-y-2 text-sm">
            {isCountingDown ? (
              <>
                <p>
                  {t(
                    'idleModal.expiringMessage',
                    'You have been inactive for a while. Your session will expire in:',
                  )}
                </p>
                <div className="text-3xl font-mono font-bold text-amber-500 py-2">
                  {String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}
                </div>
                <p className="text-(--text-muted)">
                  {t('idleModal.expiringHint', 'Extend your session or you will be logged out.')}
                </p>
              </>
            ) : (
              <>
                <p>
                  {t(
                    'idleModal.expiredMessage',
                    'Your session has expired due to inactivity. Please log in again to continue.',
                  )}
                </p>
                {user?.name && (
                  <p className="text-(--text-secondary)">
                    {t('idleModal.welcomeBack', 'Welcome back, {{name}}', {
                      name: user.name.split(' ')[0],
                    })}
                  </p>
                )}
              </>
            )}
          </div>
        </DialogHeader>

        <div className="space-y-3 pt-4">
          {isCountingDown ? (
            <>
              <Button
                onClick={extendSession}
                className="w-full btn-gradient text-white font-medium py-2.5 rounded-xl shadow-md hover:shadow-lg transition-all duration-200"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                {t('idleModal.extendSession', 'Extend Session')}
              </Button>
              <Button
                onClick={handleLogout}
                variant="outline"
                className="w-full border-(--border) text-(--text-secondary) hover:bg-(--background-subtle) hover:text-(--text-primary) font-medium py-2.5 rounded-xl transition-all duration-200"
              >
                <LogOut className="w-4 h-4 mr-2" />
                {t('idleModal.logoutNow', 'Logout Now')}
              </Button>
            </>
          ) : (
            <Button
              onClick={() => {
                setShowModal(false);
                window.location.href = '/login';
              }}
              className="w-full btn-gradient text-white font-medium py-2.5 rounded-xl shadow-md hover:shadow-lg transition-all duration-200"
            >
              <LogOut className="w-4 h-4 mr-2" />
              {t('idleModal.loginAgain', 'Log In Again')}
            </Button>
          )}
        </div>

        <div className="pt-2 text-center">
          <p className="text-xs text-(--text-muted)">
            {t(
              'idleModal.securityNote',
              'For your security, inactive sessions are automatically terminated.',
            )}
          </p>
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';

/**
 * "Login with imID" button for the login page.
 *
 * Checks which organizations have imID login enabled and either:
 * - Redirects immediately (single org with imID)
 * - Shows an org picker dialog (multiple orgs with imID)
 * - Hides the button (no org has imID enabled)
 */
export function ImidSignInButton() {
  const { t } = useTranslation();
  const enabledOrgs = useQuery(api.integrations.imidListEnabledOrgs);
  const [isLoading, setIsLoading] = useState(false);
  const [showPicker, setShowPicker] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Hide the button while loading and if no orgs have imID.
  if (enabledOrgs === undefined) return null;
  if (!enabledOrgs || enabledOrgs.length === 0) return null;

  const handleImidLogin = async (orgId?: string) => {
    setIsLoading(true);
    setError(null);
    setShowPicker(false);

    try {
      const convexUrl = process.env.NEXT_PUBLIC_CONVEX_URL;
      if (!convexUrl) throw new Error('Convex URL not configured');

      const resolvedOrgId = orgId ?? (enabledOrgs.length === 1 ? enabledOrgs[0]!.id : null);

      if (!resolvedOrgId) {
        // Should not happen — picker should be shown first.
        setShowPicker(true);
        setIsLoading(false);
        return;
      }

      // Call the Convex mutation to get the authorization URL and save OAuth state.
      const response = await fetch(`${convexUrl}/api/mutation`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          path: 'integrations:imidGetAuthorizationUrl',
          args: { organizationId: resolvedOrgId },
          format: 'json',
        }),
      });

      if (!response.ok) {
        const errData = await response.json().catch(() => ({}));
        throw new Error(
          (errData as { errorMessage?: string })?.errorMessage || 'Failed to initiate imID login',
        );
      }

      const data = (await response.json()) as { value?: { url: string } };
      const authUrl = data.value?.url;

      if (!authUrl) throw new Error('No authorization URL returned');

      // Redirect to imID.
      window.location.href = authUrl;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to connect to imID';
      setError(message);
      console.error('imID login error:', err);
      setIsLoading(false);
    }
  };

  const singleOrg = enabledOrgs.length === 1 ? enabledOrgs[0] : null;

  return (
    <>
      <button
        type="button"
        onClick={() => {
          if (singleOrg) {
            handleImidLogin(singleOrg.id);
          } else {
            setShowPicker(true);
          }
        }}
        disabled={isLoading}
        className="w-full flex items-center justify-center gap-3 px-4 py-2.5 rounded-xl border text-sm font-medium transition-all hover:shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
        style={{
          background: 'var(--background)',
          borderColor: 'var(--border)',
          color: 'var(--text-primary)',
        }}
      >
        {isLoading ? (
          <>
            <ShieldLoader size="sm" variant="inline" />
            <span>{t('auth.signingIn', 'Signing in...')}</span>
          </>
        ) : (
          <>
            {/* imID icon — Armenian tricolor badge */}
            <svg className="w-5 h-5" viewBox="0 0 24 24" fill="none">
              <rect x="2" y="4" width="20" height="16" rx="3" fill="#D90012" />
              <rect x="2" y="8" width="20" height="8" fill="#0033A0" />
              <rect x="2" y="12" width="20" height="4" fill="#FF6600" />
              <circle cx="12" cy="12" r="4" fill="white" opacity="0.9" />
              <text
                x="12"
                y="13.5"
                textAnchor="middle"
                fontSize="6"
                fontWeight="bold"
                fill="#0033A0"
              >
                im
              </text>
            </svg>
            <span>{t('auth.continueWithImid', 'Login with imID')}</span>
            {singleOrg && <span className="text-[10px] opacity-60 ml-auto">{singleOrg.name}</span>}
          </>
        )}
      </button>

      {/* Error toast */}
      {error && <p className="text-xs text-red-500 mt-1 text-center">{error}</p>}

      {/* Org picker dialog for multi-org */}
      <Dialog open={showPicker} onOpenChange={setShowPicker}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t('auth.selectOrganization', 'Select your organization')}</DialogTitle>
            <DialogDescription>
              {t(
                'auth.selectOrgForImid',
                'Choose the organization you want to sign in to with imID.',
              )}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2 mt-2">
            {enabledOrgs
              .filter((o): o is NonNullable<typeof o> => o !== null)
              .map((org) => (
                <Button
                  key={org.id}
                  variant="outline"
                  className="w-full justify-start gap-3 py-3"
                  onClick={() => handleImidLogin(org.id)}
                  disabled={isLoading}
                >
                  <span className="text-lg">🏢</span>
                  <span className="font-medium">{org.name}</span>
                  <span className="text-xs text-(--text-muted) ml-auto">@{org.slug}</span>
                </Button>
              ))}
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { useSession } from 'next-auth/react';
import { useAuthStore } from '@/store/useAuthStore';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { usePathname } from 'next/navigation';
import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

export function OAuthSyncLoader() {
  const { status } = useSession();
  const { isAuthenticated } = useAuthStore();
  const pathname = usePathname();
  const [isSyncing, setIsSyncing] = useState(false);
  const { t } = useTranslation();

  useEffect(() => {
    // Start showing loader when OAuth authenticated but not yet in useAuthStore
    if (status === 'authenticated' && !isAuthenticated && pathname === '/login') {
      setIsSyncing(true);

      // Hide loader after successful sync or timeout
      const timer = setTimeout(() => {
        setIsSyncing(false);
      }, 8000); // Max 8 seconds to allow smooth transition

      return () => clearTimeout(timer);
    } else if (isAuthenticated && pathname === '/login') {
      // Keep showing for a bit longer after auth to prevent flash
      setTimeout(() => {
        setIsSyncing(false);
      }, 300);
    }
    return undefined;
  }, [status, isAuthenticated, pathname]);

  // Show loader during sync

  if (!isSyncing) {
    return null;
  }

  return (
    <div
      className="fixed inset-0 z-[9999] flex items-center justify-center min-h-screen"
      style={{ background: 'var(--background)' }}
    >
      <ShieldLoader message={t('auth.signingInWithGoogle')} />
    </div>
  );
}

'use client';

import { motion, AnimatePresence } from '@/lib/cssMotion';
import { Check, X, AlertCircle, Info, Sparkles } from 'lucide-react';
import {
  validatePassword,
  getStrengthColor,
  type PasswordValidationResult,
} from '@/lib/passwordValidation';
import { useTranslation } from 'react-i18next';

interface PasswordStrengthIndicatorProps {
  password: string;
  showRequirements?: boolean;
  showSuggestions?: boolean;
}

export function PasswordStrengthIndicator({
  password,
  showRequirements = true,
  showSuggestions = true,
}: PasswordStrengthIndicatorProps) {
  const { t } = useTranslation();
  // i18next's TFunction has many overloads; wrap it in a narrow adapter
  // matching `Translator = (key, defaultValue?) => string` from passwordValidation.
  const translate = (key: string, defaultValue?: string): string =>
    String(t(key, defaultValue ?? key));
  // Pass `translate` so requirements/feedback/suggestions come back already localized.
  const validation = validatePassword(password, translate);

  if (!password) return null;

  const strengthColor = getStrengthColor(validation.strength);
  const strengthLabels: Record<PasswordValidationResult['strength'], string> = {
    weak: t('auth.passwordValidation.strength.weak', 'Слабый'),
    fair: t('auth.passwordValidation.strength.fair', 'Средний'),
    good: t('auth.passwordValidation.strength.good', 'Хороший'),
    strong: t('auth.passwordValidation.strength.strong', 'Надежный'),
    excellent: t('auth.passwordValidation.strength.excellent', 'Превосходный'),
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: -10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="space-y-3"
    >
      {/* Strength Bar */}
      <div className="space-y-2">
        <div className="flex items-center justify-between text-xs">
          <span className="text-(--text-muted)">
            {t('auth.passwordValidation.label', 'Надежность пароля')}
          </span>
          <motion.span
            key={validation.strength}
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="font-semibold"
            style={{ color: strengthColor }}
          >
            {strengthLabels[validation.strength]}
          </motion.span>
        </div>

        {/* Animated progress bar */}
        <div className="h-2 bg-(--background-subtle) rounded-full overflow-hidden">
          <motion.div
            className="h-full rounded-full transition-all duration-500"
            initial={{ width: 0 }}
            animate={{ width: `${validation.score}%` }}
            style={{ backgroundColor: strengthColor }}
          />
        </div>
      </div>

      {/* Feedback messages */}
      <AnimatePresence mode="popLayout">
        {validation.feedback.map((item, index) => (
          <motion.div
            key={`feedback-${index}`}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            transition={{ delay: index * 0.05 }}
            className={`flex items-start gap-2 text-xs p-2 rounded-lg ${
              item.type === 'success'
                ? 'bg-green-500/10 text-green-600 dark:text-green-400'
                : item.type === 'error'
                  ? 'bg-red-500/10 text-red-600 dark:text-red-400'
                  : item.type === 'warning'
                    ? 'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400'
                    : 'bg-blue-500/10 text-blue-600 dark:text-blue-400'
            }`}
          >
            <span className="text-base leading-none mt-0.5">{item.icon}</span>
            <p className="flex-1 leading-relaxed">{item.message}</p>
          </motion.div>
        ))}
      </AnimatePresence>

      {/* Requirements checklist */}
      {showRequirements && (
        <div className="space-y-1.5">
          <AnimatePresence>
            {validation.requirements.map((req, index) => (
              <motion.div
                key={req.id}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.03 }}
                className={`flex items-center gap-2 text-xs transition-all duration-200 ${
                  req.met
                    ? 'text-green-600 dark:text-green-400'
                    : req.required
                      ? 'text-(--text-muted)'
                      : 'text-(--text-muted) opacity-60'
                }`}
              >
                <motion.div
                  initial={{ scale: 0 }}
                  animate={{ scale: req.met ? 1 : 0.8 }}
                  transition={{ type: 'spring', stiffness: 500, damping: 30 }}
                >
                  {req.met ? (
                    <Check className="w-4 h-4 text-green-500" />
                  ) : (
                    <div className="w-4 h-4 rounded-full border-2 border-current opacity-30" />
                  )}
                </motion.div>
                <span
                  className={`${req.required ? 'font-medium' : ''} flex items-center gap-1 whitespace-nowrap`}
                >
                  {req.label}
                  {req.required && <span className="text-red-500">*</span>}
                </span>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* Smart suggestions */}
      {showSuggestions && validation.suggestions.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-2 pt-2 border-t border-(--border)"
        >
          <div className="flex items-center gap-1.5 text-xs text-(--text-muted)">
            <Sparkles className="w-3.5 h-3.5" />
            <span className="font-medium">
              {t('auth.passwordValidation.recommendations', 'Рекомендации:')}
            </span>
          </div>
          <ul className="space-y-1">
            {validation.suggestions.map((suggestion, index) => (
              <motion.li
                key={index}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.05 }}
                className="text-xs text-(--text-muted) flex items-start gap-2"
              >
                <span className="text-blue-500 mt-0.5">•</span>
                <span>{suggestion}</span>
              </motion.li>
            ))}
          </ul>
        </motion.div>
      )}
    </motion.div>
  );
}

