'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { Mail, Check, AlertCircle, Sparkles } from 'lucide-react';
import { validateEmail, type EmailValidationResult } from '@/lib/passwordValidation';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

interface SmartEmailInputProps {
  value: string;
  onChange: (value: string) => void;
  label?: string;
  placeholder?: string;
  required?: boolean;
  autoFocus?: boolean;
}

export function SmartEmailInput({
  value,
  onChange,
  label = 'Email',
  placeholder = 'your@email.com',
  required = true,
  autoFocus = false,
}: SmartEmailInputProps) {
  const [validation, setValidation] = useState<EmailValidationResult | null>(null);
  const [showSuggestion, setShowSuggestion] = useState(false);

  useEffect(() => {
    if (!value) {
      setValidation(null);
      setShowSuggestion(false);
      return;
    }

    // Debounce validation
    const timer = setTimeout(() => {
      const result = validateEmail(value);
      setValidation(result);
      setShowSuggestion(!!result.suggestion);
    }, 300);

    return () => clearTimeout(timer);
  }, [value]);

  const handleSuggestionClick = () => {
    if (validation?.suggestion) {
      onChange(validation.suggestion);
      setShowSuggestion(false);
    }
  };

  return (
    <div className="space-y-2">
      <Label
        htmlFor="email"
        className="flex items-center gap-1 whitespace-nowrap text-sm font-medium text-(--text-primary)"
      >
        {label}
        {required && <span className="text-red-500">*</span>}
      </Label>

      <div className="relative">
        {/* Email icon */}
        <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none">
          <Mail className="w-4 h-4 text-(--text-muted)" />
        </div>

        {/* Input field */}
        <Input
          id="email"
          type="email"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          autoFocus={autoFocus}
          className={`pl-10 pr-10 transition-all duration-200 ${
            validation?.isValid
              ? 'border-green-500 focus:border-green-500 focus:ring-green-500'
              : validation && !validation.isValid && value
                ? 'border-red-500 focus:border-red-500 focus:ring-red-500'
                : ''
          }`}
        />

        {/* Status icon */}
        <AnimatePresence mode="wait">
          {validation && value && (
            <motion.div
              initial={{ scale: 0, rotate: -180 }}
              animate={{ scale: 1, rotate: 0 }}
              exit={{ scale: 0, rotate: 180 }}
              transition={{ type: 'spring', stiffness: 500, damping: 25 }}
              className="absolute right-3 top-1/2 -translate-y-1/2"
            >
              {validation.isValid ? (
                <Check className="w-4 h-4 text-green-500" />
              ) : (
                <AlertCircle className="w-4 h-4 text-red-500" />
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Validation feedback */}
      <AnimatePresence mode="wait">
        {validation?.feedback && value && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`flex items-start gap-2 text-xs p-2 rounded-lg ${
              validation.feedback.type === 'success'
                ? 'bg-green-500/10 text-green-600 dark:text-green-400'
                : validation.feedback.type === 'error'
                  ? 'bg-red-500/10 text-red-600 dark:text-red-400'
                  : validation.feedback.type === 'warning'
                    ? 'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400'
                    : 'bg-blue-500/10 text-blue-600 dark:text-blue-400'
            }`}
          >
            <p className="flex-1 leading-relaxed">{validation.feedback.message}</p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Smart suggestion */}
      <AnimatePresence>
        {showSuggestion && validation?.suggestion && (
          <motion.button
            initial={{ opacity: 0, y: -10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -10, scale: 0.95 }}
            onClick={handleSuggestionClick}
            className="w-full flex items-center gap-2 p-3 rounded-xl border border-blue-500/20 bg-blue-500/10 hover:bg-blue-500/20 text-blue-600 dark:text-blue-400 transition-all group"
          >
            <Sparkles className="w-4 h-4 shrink-0 group-hover:rotate-12 transition-transform" />
            <div className="flex-1 text-left">
              <p className="text-xs font-medium">Использовать предложение?</p>
              <p className="text-sm font-semibold mt-0.5">{validation.suggestion}</p>
            </div>
            <Check className="w-4 h-4 opacity-0 group-hover:opacity-100 transition-opacity" />
          </motion.button>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { motion, AnimatePresence } from '@/lib/cssMotion';
import { AlertCircle, Info, CheckCircle, XCircle, Lightbulb, ArrowRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';

export type ErrorType = 'error' | 'warning' | 'info' | 'success';

export interface SmartError {
  type: ErrorType;
  message: string;
  suggestion?: string;
  action?: {
    label: string;
    onClick: () => void;
  };
}

interface SmartErrorMessageProps {
  error: SmartError | string | null;
  className?: string;
}

export function SmartErrorMessage({ error, className = '' }: SmartErrorMessageProps) {
  if (!error) return null;

  // Convert string to SmartError object
  const errorObj: SmartError =
    typeof error === 'string' ? { type: 'error', message: error } : error;

  const icons = {
    error: XCircle,
    warning: AlertCircle,
    info: Info,
    success: CheckCircle,
  };

  const Icon = icons[errorObj.type];

  const colorClasses = {
    error: 'bg-red-500/10 border-red-500/20 text-red-600 dark:text-red-400',
    warning: 'bg-yellow-500/10 border-yellow-500/20 text-yellow-600 dark:text-yellow-400',
    info: 'bg-blue-500/10 border-blue-500/20 text-blue-600 dark:text-blue-400',
    success: 'bg-green-500/10 border-green-500/20 text-green-600 dark:text-green-400',
  };

  const iconColors = {
    error: 'text-red-500',
    warning: 'text-yellow-500',
    info: 'text-blue-500',
    success: 'text-green-500',
  };

  return (
    <AnimatePresence mode="wait">
      <motion.div
        initial={{ opacity: 0, y: -10, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: -10, scale: 0.95 }}
        transition={{ type: 'spring', stiffness: 500, damping: 30 }}
        className={`relative overflow-hidden border p-4 ${colorClasses[errorObj.type]} ${className}`}
      >
        {/* Animated background gradient */}
        <motion.div
          className="absolute inset-0 opacity-30"
          animate={{
            background: [
              'radial-gradient(circle at 0% 0%, currentColor 0%, transparent 50%)',
              'radial-gradient(circle at 100% 100%, currentColor 0%, transparent 50%)',
              'radial-gradient(circle at 0% 0%, currentColor 0%, transparent 50%)',
            ],
          }}
          transition={{ duration: 3, repeat: Infinity, ease: 'linear' }}
        />

        <div className="relative flex gap-3">
          {/* Animated icon */}
          <motion.div
            initial={{ scale: 0, rotate: -180 }}
            animate={{ scale: 1, rotate: 0 }}
            transition={{ type: 'spring', stiffness: 500, damping: 25 }}
            className="shrink-0"
          >
            <Icon className={`w-5 h-5 ${iconColors[errorObj.type]}`} />
          </motion.div>

          <div className="flex-1 space-y-2">
            {/* Main message */}
            <motion.p
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.1 }}
              className="text-sm font-medium leading-relaxed"
            >
              {errorObj.message}
            </motion.p>

            {/* Suggestion */}
            {errorObj.suggestion && (
              <motion.div
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.2 }}
                className="flex items-start gap-2 text-xs opacity-90"
              >
                <Lightbulb className="w-4 h-4 shrink-0 mt-0.5" />
                <p className="leading-relaxed">{errorObj.suggestion}</p>
              </motion.div>
            )}

            {/* Action button */}
            {errorObj.action && (
              <motion.button
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.3 }}
                onClick={errorObj.action.onClick}
                className="flex items-center gap-1.5 text-xs font-medium underline underline-offset-2 hover:no-underline transition-all group"
              >
                {errorObj.action.label}
                <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
              </motion.button>
            )}
          </div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
}

/**
 * Smart error parser - converts common API errors to user-friendly messages
 */
export function parseAuthError(error: string): SmartError {
  const errorLower = error.toLowerCase();

  // Wrong password
  if (
    errorLower.includes('invalid credentials') ||
    errorLower.includes('wrong password') ||
    errorLower.includes('incorrect password')
  ) {
    return {
      type: 'error',
      message: '🔐 Неверный email или пароль',
      suggestion: 'Проверьте правильность ввода. Caps Lock включен?',
      action: {
        label: 'Забыли пароль?',
        onClick: () => window.location.assign('/forgot-password'),
      },
    };
  }

  // User not found
  if (
    errorLower.includes('user not found') ||
    errorLower.includes('no user') ||
    errorLower.includes('does not exist')
  ) {
    return {
      type: 'error',
      message: '👤 Пользователь не найден',
      suggestion: 'Возможно, вы еще не зарегистрированы в системе',
      action: {
        label: 'Создать аккаунт',
        onClick: () => window.location.assign('/register'),
      },
    };
  }

  // Email already exists
  if (
    errorLower.includes('already exists') ||
    errorLower.includes('already registered') ||
    errorLower.includes('email taken')
  ) {
    return {
      type: 'error',
      message: '📧 Этот email уже зарегистрирован',
      suggestion: 'Попробуйте войти или восстановите пароль',
      action: {
        label: 'Перейти к входу',
        onClick: () => window.location.assign('/login'),
      },
    };
  }

  // Weak password
  if (
    errorLower.includes('weak password') ||
    errorLower.includes('password too short') ||
    errorLower.includes('password must be')
  ) {
    return {
      type: 'warning',
      message: '🔒 Пароль недостаточно надежный',
      suggestion: 'Используйте минимум 8 символов, включая буквы, цифры и спецсимволы',
    };
  }

  // Network error
  if (
    errorLower.includes('network') ||
    errorLower.includes('fetch') ||
    errorLower.includes('connection')
  ) {
    return {
      type: 'warning',
      message: '🌐 Проблема с подключением',
      suggestion: 'Проверьте интернет-соединение и повторите попытку',
    };
  }

  // Server error
  if (
    errorLower.includes('500') ||
    errorLower.includes('server error') ||
    errorLower.includes('internal error')
  ) {
    return {
      type: 'error',
      message: '⚠️ Ошибка сервера',
      suggestion: 'Мы работаем над исправлением. Попробуйте через несколько минут',
    };
  }

  // Too many attempts
  if (
    errorLower.includes('too many') ||
    errorLower.includes('rate limit') ||
    errorLower.includes('blocked')
  ) {
    return {
      type: 'warning',
      message: '⏱️ Слишком много попыток',
      suggestion: 'Подождите несколько минут перед следующей попыткой',
    };
  }

  // Account blocked/suspended
  if (
    errorLower.includes('blocked') ||
    errorLower.includes('suspended') ||
    errorLower.includes('disabled')
  ) {
    return {
      type: 'error',
      message: '🚫 Аккаунт заблокирован',
      suggestion: 'Обратитесь к администратору для разблокировки',
    };
  }

  // Email not verified
  if (
    errorLower.includes('verify') ||
    errorLower.includes('not verified') ||
    errorLower.includes('confirm email')
  ) {
    return {
      type: 'warning',
      message: '📬 Email не подтвержден',
      suggestion: 'Проверьте почту и перейдите по ссылке подтверждения',
    };
  }

  // Session expired
  if (
    errorLower.includes('session') ||
    errorLower.includes('expired') ||
    errorLower.includes('timeout')
  ) {
    return {
      type: 'info',
      message: '⏰ Сессия истекла',
      suggestion: 'Войдите снова для продолжения работы',
    };
  }

  // Default error
  return {
    type: 'error',
    message: error || 'Произошла ошибка',
    suggestion: 'Попробуйте еще раз или обратитесь в поддержку',
  };
}

'use client';

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { Eye, EyeOff, Lock, Copy, RefreshCw } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { PasswordStrengthIndicator } from './PasswordStrengthIndicator';
import { generateSecurePassword } from '@/lib/passwordValidation';

interface SmartPasswordInputProps {
  value: string;
  onChange: (value: string) => void;
  label?: string;
  placeholder?: string;
  required?: boolean;
  showStrength?: boolean;
  showGenerator?: boolean;
  autoFocus?: boolean;
  forgotPasswordLink?: React.ReactNode;
}

export function SmartPasswordInput({
  value,
  onChange,
  label,
  placeholder = '••••••••',
  required = true,
  showStrength = true,
  showGenerator = false,
  autoFocus = false,
  forgotPasswordLink,
}: SmartPasswordInputProps) {
  const { t } = useTranslation();
  const [showPassword, setShowPassword] = useState(false);
  const [copied, setCopied] = useState(false);
  // Fall back to the localized "Password" label if the caller didn't supply one.
  const resolvedLabel = label ?? t('auth.password', 'Пароль');

  const handleGeneratePassword = () => {
    const newPassword = generateSecurePassword();
    onChange(newPassword);
    setShowPassword(true);

    // Auto-copy to clipboard
    navigator.clipboard.writeText(newPassword);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleCopyPassword = async () => {
    if (value) {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <Label
          htmlFor="password"
          className="flex items-center gap-1 whitespace-nowrap text-sm font-medium text-(--text-primary)"
        >
          {resolvedLabel}
          {required && <span className="text-red-500">*</span>}
        </Label>

        {forgotPasswordLink && <div className="ml-2">{forgotPasswordLink}</div>}

        {showGenerator && !forgotPasswordLink && (
          <motion.button
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            onClick={handleGeneratePassword}
            type="button"
            className="flex items-center gap-1.5 text-xs text-blue-600 dark:text-blue-400 hover:underline font-medium group ml-2"
          >
            <RefreshCw className="w-3.5 h-3.5 group-hover:rotate-180 transition-transform duration-500" />
            {t('auth.passwordInput.generate', 'Сгенерировать')}
          </motion.button>
        )}
      </div>

      <div className="relative h-9">
        {/* Lock icon */}
        <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none z-10">
          <Lock className="w-4 h-4 text-(--text-muted)" />
        </div>

        {/* Input field */}
        <Input
          id="password"
          type={showPassword ? 'text' : 'password'}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          autoFocus={autoFocus}
          className="pl-10 pr-20 w-full h-full"
        />

        {/* Action buttons */}
        <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-1 z-10">
          {/* Copy button */}
          <AnimatePresence mode="wait">
            {value && (
              <motion.button
                initial={{ scale: 0, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0, opacity: 0 }}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={handleCopyPassword}
                type="button"
                className="p-1.5 rounded-md hover:bg-(--background-subtle) transition-colors"
                title={t('auth.passwordInput.copy', 'Копировать пароль')}
              >
                {copied ? (
                  <motion.div
                    initial={{ scale: 0, rotate: -180 }}
                    animate={{ scale: 1, rotate: 0 }}
                  >
                    <svg
                      className="w-4 h-4 text-green-500"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                  </motion.div>
                ) : (
                  <Copy className="w-4 h-4 text-(--text-muted)" />
                )}
              </motion.button>
            )}
          </AnimatePresence>

          {/* Show/hide button */}
          <motion.button
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            onClick={() => setShowPassword(!showPassword)}
            type="button"
            className="p-1.5 rounded-md hover:bg-(--background-subtle) transition-colors"
            title={
              showPassword
                ? t('auth.passwordInput.hide', 'Скрыть пароль')
                : t('auth.passwordInput.show', 'Показать пароль')
            }
          >
            <AnimatePresence mode="wait">
              {showPassword ? (
                <motion.div
                  key="hide"
                  initial={{ scale: 1, rotate: -180 }}
                  animate={{ scale: 1.1, rotate: 0 }}
                  exit={{ scale: 0, rotate: 180 }}
                >
                  <EyeOff className="w-4 h-4 text-(--text-muted)" />
                </motion.div>
              ) : (
                <motion.div
                  key="show"
                  initial={{ scale: 1, rotate: -180 }}
                  animate={{ scale: 1.1, rotate: 0 }}
                  exit={{ scale: 0, rotate: 180 }}
                >
                  <Eye className="w-4 h-4 text-(--text-muted)" />
                </motion.div>
              )}
            </AnimatePresence>
          </motion.button>
        </div>
      </div>

      {/* Copied notification */}
      <AnimatePresence>
        {copied && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="text-xs text-green-600 dark:text-green-400 flex items-center gap-1.5"
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M5 13l4 4L19 7"
              />
            </svg>
            {t('auth.passwordInput.copied', 'Пароль скопирован в буфер обмена!')}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Password strength indicator */}
      {showStrength && value && <PasswordStrengthIndicator password={value} />}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { motion } from '@/lib/cssMotion';
import { Fingerprint } from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { toast } from 'sonner';
import { useTranslation } from 'react-i18next';
import { Button } from '../ui/button';

interface WebAuthnButtonProps {
  mode: 'register' | 'login';
  userId?: string;
  onSuccess?: (credentialId: string) => void;
  disabled?: boolean;
}

export function WebAuthnButton({ mode, userId, onSuccess, disabled }: WebAuthnButtonProps) {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);

  const isSupported = () => {
    return (
      typeof window !== 'undefined' &&
      window.PublicKeyCredential !== undefined &&
      typeof window.PublicKeyCredential === 'function'
    );
  };

  const handleRegister = async () => {
    if (!isSupported()) {
      toast.error(t('toasts.webAuthnNotSupported'));
      return;
    }
    if (!userId) {
      toast.error(t('toasts.completeRegistrationFirst'));
      return;
    }

    setLoading(true);
    try {
      // Generate challenge
      const challenge = new Uint8Array(32);
      crypto.getRandomValues(challenge);

      const credential = (await navigator.credentials.create({
        publicKey: {
          challenge,
          rp: {
            name: 'Strata',
            id: window.location.hostname,
          },
          user: {
            id: new TextEncoder().encode(userId),
            name: userId,
            displayName: 'Strata User',
          },
          pubKeyCredParams: [
            { alg: -7, type: 'public-key' }, // ES256
            { alg: -257, type: 'public-key' }, // RS256
          ],
          authenticatorSelection: {
            authenticatorAttachment: 'platform',
            userVerification: 'required',
            residentKey: 'preferred',
          },
          timeout: 60000,
          attestation: 'none',
        },
      })) as PublicKeyCredential;

      if (!credential) throw new Error('No credential created');

      const response = credential.response as AuthenticatorAttestationResponse;
      const credentialId = btoa(String.fromCharCode(...new Uint8Array(credential.rawId)));

      // Store credential ID for future logins
      localStorage.setItem('webauthn-credential-id', credentialId);
      localStorage.setItem('webauthn-user-id', userId);

      onSuccess?.(credentialId);
      toast.success(t('toasts.biometricRegistered'));
    } catch (err: unknown) {
      if (err instanceof Error && err.name === 'NotAllowedError') {
        toast.error(t('toasts.authCancelled'));
      } else {
        toast.error(t('toasts.biometricRegFailed'));
        console.error(err);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async () => {
    if (!isSupported()) {
      toast.error(t('toasts.webAuthnNotSupported'));
      return;
    }

    setLoading(true);
    try {
      const credentialId = localStorage.getItem('webauthn-credential-id');
      const challenge = new Uint8Array(32);
      crypto.getRandomValues(challenge);

      const allowCredentials: PublicKeyCredentialDescriptor[] = credentialId
        ? [
            {
              id: Uint8Array.from(atob(credentialId), (c) => c.charCodeAt(0)),
              type: 'public-key',
            },
          ]
        : [];

      const assertion = (await navigator.credentials.get({
        publicKey: {
          challenge,
          allowCredentials,
          userVerification: 'required',
          timeout: 60000,
        },
      })) as PublicKeyCredential;

      if (!assertion) throw new Error('No assertion');

      const assertedCredentialId = btoa(String.fromCharCode(...new Uint8Array(assertion.rawId)));

      onSuccess?.(assertedCredentialId);
    } catch (err: unknown) {
      if (err instanceof Error && err.name === 'NotAllowedError') {
        toast.error(t('toasts.authCancelled'));
      } else {
        toast.error(t('toasts.biometricLoginFailed'));
        console.error(err);
      }
    } finally {
      setLoading(false);
    }
  };

  const handle = mode === 'register' ? handleRegister : handleLogin;

  return (
    <Button
      type="button"
      variant="outline"
      onClick={handle}
      disabled={disabled || loading}
      className="w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl border-2 font-medium transition-all disabled:opacity-50"
      title={mode === 'register' ? 'Register biometric' : 'Sign in with biometric'}
    >
      {loading ? <ShieldLoader size="sm" variant="inline" /> : <Fingerprint className="w-4 h-4" />}
      {!loading && <span className="text-xs">{t('auth.touchId')}</span>}
    </Button>
  );
}

