                        >
                          <div
                            className="w-10 h-10 rounded-xl flex items-center justify-center text-white text-sm font-bold shrink-0"
                            style={{ background: LEAVE_TYPE_BG[leave.type] || '#6b7280' }}
                          >
                            {getInitials(leave.userName ?? '?')}
