                ? ''
                : conv.lastMessageSenderId
                  ? (conv.members
                      ?.find((m) => m.userId === conv.lastMessageSenderId)
                      ?.user?.name?.split(' ')[0] ?? '')
                  : '';
          const deletedMessages = [
            'This message was deleted',
            'Это сообщение было удалено',
            'Այս հաղորդագրությունը ջնջված է',
          ];
          const isDeleted = deletedMessages.includes(conv.lastMessageText || '');
          const rawLastText = isDeleted ? '' : conv.lastMessageText;

          // Remove sender prefix for System Announcements (in case it's still there)
          let displayLastText = rawLastText;
          if (isSystemAnnouncements && displayLastText) {
            const match = displayLastText.match(/^[^:]*:\s*/);
            if (match) {
              displayLastText = displayLastText.substring(match[0].length);
            }
            displayLastText = displayLastText.replace(/^\d{1,2}\s*[AP]M\s*🔔?\s*/, '');
          }

          const lastMsgPreview = isSystemAnnouncements
            ? t('maintenance.notificationLabel')
            : isDeleted
              ? t('chat.deleted')
              : displayLastText
                ? senderName && !isSystemAnnouncements && !isDeleted
                  ? `${senderName}: ${displayLastText}`
                  : displayLastText
                : isGroup
                  ? `${conv.memberCount ?? 2} ${t('chat.members')}`
                  : t('chat.startConversationHint');

          // Last message sender avatar (for groups, but NOT for System Announcements)
          const lastSenderMember =
            isGroup && !isSystemAnnouncements && conv.lastMessageSenderId
              ? conv.members?.find((m) => m.userId === conv.lastMessageSenderId)
              : null;
          const lastSenderAvatar = isSystemAnnouncements
            ? null
            : isOwnLast
              ? null
              : lastSenderMember?.user?.avatarUrl;
          const lastSenderInitial = isSystemAnnouncements
            ? null
            : isOwnLast
              ? null
              : (lastSenderMember?.user?.name?.[0]?.toUpperCase() ?? null);

          const isLoading = loadingOpId === conv._id;

          return (
            <ContextMenu key={conv._id}>
              <ContextMenuTrigger asChild>
                <div
                  onClick={() => onSelect(conv._id)}
                  className={cn(
                    'w-full rounded-xl transition-all duration-200 text-left relative cursor-pointer',
                    showCollapse && collapsed
                      ? 'flex justify-center py-1.5'
                      : 'flex items-center gap-3 px-3 py-3',
                    isSelected ? 'shadow-sm scale-[1.01]' : 'hover:opacity-90',
                  )}
                  style={{
                    background: isSelected ? 'var(--sidebar-item-active)' : 'transparent',
                    color: isSelected ? 'var(--sidebar-item-active-text)' : 'var(--text-primary)',
                    animation: `conv-in 0.25s ease-out ${idx * 0.04}s both`,
                    opacity: conv.membership.isDeleted ? 0.5 : 1,
                    userSelect: 'none',
                  }}
                  onMouseEnter={(e) => {
                    if (!isSelected) e.currentTarget.style.background = 'var(--sidebar-item-hover)';
                  }}
                  onMouseLeave={(e) => {
                    if (!isSelected) e.currentTarget.style.background = 'transparent';
                  }}
                >
                  {isLoading && (
                    <div className="absolute top-3 left-3">
                      <ShieldLoader size="xs" variant="inline" />
                    </div>
                  )}

                  {/* Conversation avatar */}
                  <div className="relative shrink-0">
                    <Avatar
                      className={cn(
                        'transition-all',
                        showCollapse && collapsed ? 'w-10 h-10' : 'w-10 h-10',
                      )}
                    >
                      {avatarUrl && <AvatarImage src={avatarUrl} />}
                      <AvatarFallback
                        className={
                          isGroup
                            ? 'text-xs font-bold text-white bg-gradient-to-br from-indigo-500 to-purple-600'
                            : 'text-xs font-bold text-white btn-gradient'
                        }
                      >
                        {isGroup ? <Users className="w-4 h-4" /> : getInitials(displayName)}
                      </AvatarFallback>
                    </Avatar>
                    {!isGroup && conv.otherUser?.presenceStatus && (
                      <PresenceDot status={conv.otherUser.presenceStatus} />
                    )}
                    {/* Unread dot for showCollapse && collapsed mode */}
                    {showCollapse && collapsed && unread > 0 && !conv.membership.isMuted && (
                      <span className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-red-500 border-2 border-white" />
                    )}
                  </div>

                  {/* Content - hidden when collapsed */}
                  {!(showCollapse && collapsed) && (
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-1">
                        <div className="flex items-center gap-1 min-w-0">
                          <span
                            className={cn(
                              'sm:text-sm text-base truncate',
                              unread > 0 ? 'font-semibold' : 'font-medium',
                            )}
                          >
                            {displayName}
                          </span>
                          {conv.isPinned && (
                            <Pin
                              className="sm:w-3 sm:h-3 w-4 h-4 shrink-0"
                              style={{ color: 'var(--primary)' }}
                            />
                          )}
                        </div>
                        {lastTime && (
                          <span
                            className="sm:text-[10px] text-xs shrink-0"
                            style={{ color: 'var(--text-disabled)' }}
                          >
                            {lastTime}
                          </span>
                        )}
                      </div>
                      <div className="flex items-center justify-between gap-1 mt-1 sm:mt-0.5">
                        <div className="flex items-center gap-1 min-w-0">
                          {/* Last message sender mini-avatar (groups only, not own, not System Announcements) */}
                          {isGroup &&
                            conv.lastMessageText &&
                            !isOwnLast &&
                            !isSystemAnnouncements && (
                              <div className="sm:w-3.5 sm:h-3.5 w-4 h-4 rounded-full shrink-0 flex items-center justify-center sm:text-[7px] text-[8px] font-bold text-white overflow-hidden btn-gradient">
                                {lastSenderAvatar ? (
                                  <Image
                                    src={lastSenderAvatar}
                                    alt=""
                                    width={16}
                                    height={16}
                                    className="w-full h-full object-cover"
                                    unoptimized
                                  />
                                ) : (
                                  lastSenderInitial
                                )}
                              </div>
                            )}
                          <p
                            className={cn(
                              'sm:text-xs text-sm truncate',
                              unread > 0 ? 'font-medium' : 'opacity-70',
                            )}
                            style={{
                              color: isSelected
                                ? 'var(--sidebar-item-active-text)'
                                : 'var(--text-muted)',
                            }}
                          >
                            {isDeleted ? t('chat.deleted') : lastMsgPreview}
                          </p>
                        </div>
                        {unread > 0 && !conv.membership.isMuted && (
                          <span className="min-w-5 sm:min-w-4.5 h-5 sm:h-4.5 px-1 rounded-full bg-linear-to-r from-red-500 to-red-600 text-white sm:text-[9px] text-[10px] font-bold flex items-center justify-center shadow-lg">
                            {unread > 99 ? '99+' : unread}
                          </span>
                        )}
                        {conv.membership.isMuted && (
                          <VolumeX className="w-3 h-3 shrink-0 opacity-50" />
                        )}
                      </div>
                    </div>
                  )}

                  {/* Action buttons for archived/deleted items (visible without right-click) */}
                  {!showCollapse && collapsed && activeFilters.includes('archived') && (
                    <div className="flex items-center gap-1 shrink-0 ml-1">
                      {conv.membership.isDeleted ? (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOperation(async () => {
                              await onRestore?.(conv._id);
                              // Force refresh by switching to chat filter after a small delay
                              setTimeout(() => setActiveFilters(['chat']), 100);
                            }, conv._id);
                          }}
                          className="p-1.5 rounded-lg transition-colors hover:bg-(--sidebar-item-hover)"
                          title={t('chat.restore')}
                        >
                          <RotateCcw className="w-3.5 h-3.5" style={{ color: 'var(--primary)' }} />
                        </button>
                      ) : conv.membership.isArchived || conv.isArchived ? (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOperation(
                              () => onToggleArchive?.(conv._id) || Promise.resolve(),
                              conv._id,
                            );
                          }}
                          className="p-1.5 rounded-lg transition-colors hover:bg-(--sidebar-item-hover)"
                          title={t('chat.unarchive')}
                        >
                          <Archive className="w-3.5 h-3.5" style={{ color: 'var(--primary)' }} />
                        </button>
                      ) : null}
                    </div>
                  )}
                </div>
              </ContextMenuTrigger>

              {/* Context Menu */}
              <ContextMenuContent className="w-48">
                {!conv.membership.isDeleted && (
                  <>
                    <ContextMenuLabel className="text-xs" style={{ color: 'var(--text-muted)' }}>
                      {displayName}
                    </ContextMenuLabel>
                    <ContextMenuSeparator />
                  </>
                )}

                {conv.membership.isDeleted ? (
                  <ContextMenuItem
                    onClick={() =>
                      handleOperation(async () => {
                        await onRestore?.(conv._id);
                        setActiveFilters(['chat']);
                      }, conv._id)
                    }
                    disabled={isLoading}
                    className="flex items-center gap-2"
                  >
                    <RotateCcw className="w-4 h-4" />
                    {t('chat.restore')}
                  </ContextMenuItem>
                ) : (
                  <>
                    <ContextMenuItem
                      onClick={() =>
                        handleOperation(
                          () => onTogglePin?.(conv._id) || Promise.resolve(),
                          conv._id,
                        )
                      }
                      disabled={isLoading}
                      className="flex items-center gap-2"
                    >
                      <Pin className="w-4 h-4" />
                      {conv.isPinned ? t('chat.unpin') : t('chat.pin')}
                    </ContextMenuItem>

                    <ContextMenuItem
                      onClick={() =>
                        handleOperation(
                          () => onToggleMute?.(conv._id) || Promise.resolve(),
                          conv._id,
                        )
                      }
                      disabled={isLoading}
                      className="flex items-center gap-2"
                    >
                      {conv.membership.isMuted ? (
                        <>
                          <Volume2 className="w-4 h-4" />
                          {t('chat.unmute')}
                        </>
                      ) : (
                        <>
                          <VolumeX className="w-4 h-4" />
                          {t('chat.mute')}
                        </>
                      )}
                    </ContextMenuItem>

                    <ContextMenuItem
                      onClick={() =>
                        handleOperation(
                          () => onToggleArchive?.(conv._id) || Promise.resolve(),
                          conv._id,
                        )
                      }
                      disabled={isLoading}
                      className="flex items-center gap-2"
                    >
                      <Archive className="w-4 h-4" />
                      {conv.membership.isArchived || conv.isArchived
                        ? t('chat.unarchive')
                        : t('chat.archive')}
                    </ContextMenuItem>

                    <ContextMenuSeparator />

                    <ContextMenuItem
                      onClick={() =>
                        handleOperation(() => onDelete?.(conv._id) || Promise.resolve(), conv._id)
                      }
                      disabled={isLoading}
                      className="flex items-center gap-2 text-red-500 focus:text-red-500"
                    >
                      <Trash2 className="w-4 h-4" />
                      {t('chat.delete')}
                    </ContextMenuItem>
                  </>
                )}
              </ContextMenuContent>
            </ContextMenu>
          );
        })}
      </div>
    </div>
  );
});

'use client';

import { useEffect, useRef } from 'react';
import { useQuery } from 'convex/react';
import { usePathname } from 'next/navigation';
import { api } from '../../../convex/_generated/api';
import { useAuthStore } from '@/store/useAuthStore';
import { playChatMessageSound, sendBrowserNotification } from '@/lib/notificationSound';
import type { Id } from '../../../convex/_generated/dataModel';
import { toast } from 'sonner';
import { MessageCircle } from 'lucide-react';
import React from 'react';

/**
 * Global chat notification listener — plays sound + shows toast
 * when new messages arrive and user is NOT on the chat page.
 */
export function GlobalChatNotifier() {
  const { user } = useAuthStore();
  const pathname = usePathname();
  const prevCountRef = useRef<number | null>(null);

  const isChatPage = pathname?.startsWith('/chat');

  const totalUnread = useQuery(
    api.chat.queries.getTotalUnread,
    user?.id && user?.organizationId
      ? {
          userId: user.id as Id<'users'>,
          organizationId: user.organizationId as Id<'organizations'>,
        }
      : 'skip',
  );

  useEffect(() => {
    if (totalUnread === undefined) return;

    if (prevCountRef.current === null) {
      prevCountRef.current = totalUnread;
      return;
    }

    // New message arrived and user is NOT on chat page
    if (totalUnread > prevCountRef.current && !isChatPage) {
      playChatMessageSound();
      toast('New message', {
        icon: React.createElement(MessageCircle, { className: 'w-4 h-4 text-blue-500' }),
        duration: 4000,
      });
    }

    prevCountRef.current = totalUnread;
  }, [totalUnread, isChatPage]);

  return null;
}

'use client';

import React, { useState, useCallback, useEffect } from 'react';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { useAuthStore } from '@/store/useAuthStore';
import { useOrgSelectorStore } from '@/store/useOrgSelectorStore';
import { CallModal } from './CallModal';
import type { ActiveCall } from './ChatClient';
import { Phone, Video, PhoneOff } from 'lucide-react';
import { playChatMessageSound } from '@/lib/notificationSound';
import { useTranslation } from 'react-i18next';

export function IncomingCallProvider() {
  const { user } = useAuthStore();
  const { selectedOrgId } = useOrgSelectorStore();
  const { t } = useTranslation();

  const uid = user?.id as Id<'users'> | undefined;
  const orgId = user?.organizationId as Id<'organizations'> | undefined;
  const effectiveOrgId = selectedOrgId ? (selectedOrgId as Id<'organizations'>) : orgId;

  const [activeCall, setActiveCall] = useState<ActiveCall | null>(null);
  const [incomingCall, setIncomingCall] = useState<ActiveCall | null>(null);

  const conversations = useQuery(
    api.chat.queries.getMyConversations,
    uid ? { userId: uid, organizationId: effectiveOrgId } : 'skip',
  );

  const incomingCallData = useQuery(
    api.chat.calls.getIncomingCalls,
    uid && effectiveOrgId ? { userId: uid, organizationId: effectiveOrgId } : 'skip',
  );

  const answerCallMutation = useMutation(api.chat.calls.answerCall);
  const declineCallMutation = useMutation(api.chat.calls.declineCall);

  // Detect incoming calls globally
  useEffect(() => {
    if (!uid) return;

    if (incomingCallData && incomingCallData.status === 'ringing') {
      let initiatorName = 'Someone';

      if (conversations) {
        const conv = conversations.find((c) => c && c._id === incomingCallData.conversationId);
        if (conv) {
          const initiatorMember = conv.members?.find(
            (m: { userId: Id<'users'> }) => m.userId === incomingCallData.initiatorId,
          );
          initiatorName = initiatorMember?.user?.name ?? conv.otherUser?.name ?? 'Someone';
        }
      }

      setIncomingCall({
        callId: incomingCallData._id,
        conversationId: incomingCallData.conversationId,
        type: incomingCallData.type,
        isInitiator: false,
        remoteUserId: incomingCallData.initiatorId,
        remoteUserName: initiatorName,
      });

      if (!activeCall) {
        playChatMessageSound();
      }
    } else {
      if (!activeCall) {
        setIncomingCall(null);
      }
    }
  }, [incomingCallData, conversations, uid, activeCall]);

  const handleEndCall = useCallback(() => {
    setActiveCall(null);
  }, []);

  if (!uid || !effectiveOrgId) return null;

  return (
    <>
      {/* Active Call Modal */}
      {activeCall && (
        <CallModal
          call={activeCall}
          currentUserId={uid}
          currentUserName={user?.name ?? ''}
          currentUserAvatar={user?.avatar}
          onEnd={handleEndCall}
        />
      )}

      {/* Incoming Call Modal — shown globally on any page */}
      {incomingCall && !activeCall && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-md animate-fade-in">
          <div
            className="relative w-80 rounded-3xl overflow-hidden shadow-2xl p-6 flex flex-col items-center gap-4"
            style={{ background: 'linear-gradient(160deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)' }}
          >
            {/* Animated ring */}
            <div className="relative">
              <div className="w-20 h-20 rounded-full flex items-center justify-center bg-linear-to-br from-purple-600 to-blue-600">
                <span className="text-white text-2xl font-bold">
                  {incomingCall.remoteUserName?.[0]?.toUpperCase() ?? '?'}
                </span>
              </div>
              <span className="absolute inset-0 rounded-full ring-4 ring-green-500/40 animate-ping" />
              <span
                className="absolute inset-0 rounded-full ring-4 ring-green-500/20 animate-ping"
                style={{ animationDelay: '0.5s' }}
              />
            </div>

            <div className="text-center">
              <p className="text-white font-semibold text-lg">{incomingCall.remoteUserName}</p>
              <p className="text-white/60 text-sm flex items-center justify-center gap-1 mt-1">
                {incomingCall.type === 'video' ? (
                  <>
                    <Video className="w-3.5 h-3.5" /> {t('chat.call.incomingVideo')}
                  </>
                ) : (
                  <>
                    <Phone className="w-3.5 h-3.5" /> {t('chat.call.incomingAudio')}
                  </>
                )}
              </p>
            </div>

            <div className="flex items-center gap-6 mt-2">
              {/* Decline */}
              <button
                onClick={async () => {
                  try {
                    await declineCallMutation({ callId: incomingCall.callId, userId: uid });
                  } catch {}
                  setIncomingCall(null);
                }}
                className="w-14 h-14 rounded-full flex items-center justify-center bg-red-500 hover:bg-red-600 transition-all hover:scale-110 shadow-lg shadow-red-500/30"
                title={t('chat.call.decline')}
              >
                <PhoneOff className="w-6 h-6 text-white" />
              </button>

              {/* Accept */}
              <button
                onClick={async () => {
                  try {
                    await answerCallMutation({ callId: incomingCall.callId, userId: uid });
                  } catch (e) {
                    console.error('[IncomingCallProvider] Error answering call:', e);
                  }
                  setActiveCall(incomingCall);
                  setIncomingCall(null);
                }}
                className="w-14 h-14 rounded-full flex items-center justify-center bg-green-500 hover:bg-green-600 transition-all hover:scale-110 shadow-lg shadow-green-500/30"
                title={t('chat.call.accept')}
              >
                <Phone className="w-6 h-6 text-white" />
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { ExternalLink } from 'lucide-react';

interface Preview {
  url: string;
  title?: string;
  description?: string;
  image?: string;
  siteName?: string;
}

interface Props {
  url: string;
  isOwn: boolean;
}

export function LinkPreview({ url, isOwn }: Props) {
  const [preview, setPreview] = useState<Preview | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetch(`/api/chat/link-preview?url=${encodeURIComponent(url)}`)
      .then((r) => r.json())
      .then((data) => {
        if (!cancelled) setPreview(data);
      })
      .catch(() => {
        if (!cancelled) setError(true);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [url]);

  if (loading || error || (!preview?.title && !preview?.image)) return null;

  return (
    <a
      href={url}
      target="_blank"
      rel="noopener noreferrer"
      className="block mt-2 rounded-xl overflow-hidden border transition-all duration-200 hover:opacity-80 hover:scale-[1.01] w-full max-w-[200px] xs:max-w-[220px] sm:max-w-[240px]"
      style={{ borderColor: isOwn ? 'rgba(255,255,255,0.2)' : 'var(--border)' }}
    >
      {preview?.image && (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={preview.image}
          alt={preview.title ?? ''}
          className="w-full h-32 object-cover"
          onError={(e) => {
            (e.target as HTMLImageElement).style.display = 'none';
          }}
        />
      )}
      <div
        className="px-3 py-2"
        style={{ background: isOwn ? 'rgba(255,255,255,0.1)' : 'var(--background-subtle)' }}
      >
        {preview?.siteName && (
          <p
            className="sm:text-[9px] text-[10px] font-medium uppercase tracking-wide mb-0.5 flex items-center gap-1"
            style={{ color: isOwn ? 'rgba(255,255,255,0.6)' : 'var(--text-disabled)' }}
          >
            <ExternalLink className="sm:w-2.5 sm:h-2.5 w-3 h-3" />
            {preview.siteName}
          </p>
        )}
        {preview?.title && (
          <p
            className="sm:text-xs text-sm font-semibold line-clamp-2"
            style={{ color: isOwn ? 'white' : 'var(--text-primary)' }}
          >
            {preview.title}
          </p>
        )}
        {preview?.description && (
          <p
            className="sm:text-[10px] text-xs mt-0.5 line-clamp-2 opacity-70"
            style={{ color: isOwn ? 'white' : 'var(--text-muted)' }}
          >
            {preview.description}
          </p>
        )}
      </div>
    </a>
  );
}

// Extract first URL from text
export function extractUrl(text: string): string | null {
  const match = text.match(/https?:\/\/[^\s]+/);
  return match ? match[0] : null;
}

