          <span style={{ color: 'var(--primary)' }}>{icon}</span>
          <span>{message.content}</span>
          <span className={statusColor}>{statusText}</span>
        </div>
      </div>
    );
  }

  const handleReaction = async (emoji: string) => {
    // Sanitize emoji to remove spaces and control characters
    const sanitizedEmoji = emoji.replace(/[\s\x00-\x1F\x7F]/g, '');
    if (!sanitizedEmoji) return; // Skip if emoji becomes empty after sanitization

    try {
      await toggleOptimisticReaction(
        sanitizedEmoji,
        (message.reactions?.[emojiToKey(sanitizedEmoji)] ?? []) as Id<'users'>[],
      );
    } catch (err) {
      console.error('Reaction failed:', err);
    }
  };

  const handleEdit = async () => {
    if (editContent.trim() === message.content) {
      setEditing(false);
      return;
    }
    await editMessage({
      messageId: message._id,
      userId: currentUserId,
      content: editContent.trim(),
    });
    setEditing(false);
  };

  const handleDeleteForEveryone = async () => {
    await deleteMessage({ messageId: message._id, userId: currentUserId, deleteForEveryone: true });
    setShowDeleteDialog(false);
    setShowMenu(false);
  };

  const handleDeleteForMe = async () => {
    await deleteMessage({ messageId: message._id, userId: currentUserId });
    setShowDeleteDialog(false);
    setShowMenu(false);
  };

  const handlePin = () => {
    pinMessage({ messageId: message._id, userId: currentUserId, pin: !message.isPinned });
    setShowMenu(false);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content);
    setShowMenu(false);
  };

  const totalReactions = Object.values(message.reactions ?? {}).reduce(
    (s, arr) => s + arr.length,
    0,
  );
  const withinFiveMin = canDeleteForEveryone(message.createdAt);

  return (
    <>
      {/* Image lightbox */}
      {lightboxSrc && (
        <div
          className="fixed inset-0 z-200 flex items-center justify-center bg-black/80 backdrop-blur-sm animate-fade-in"
          onClick={() => setLightboxSrc(null)}
        >
          <Button
            variant="ghost"
            size="icon"
            className="absolute top-4 right-4 w-9 h-9 rounded-full bg-white/10 hover:bg-white/20 text-white transition-all hover:box-shadow-lg"
            onClick={() => setLightboxSrc(null)}
          >
            <X className="w-5 h-5" />
          </Button>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={lightboxSrc}
            alt={L.preview}
            className="max-w-[90vw] max-h-[95vh] rounded-xl object-contain shadow-2xl transition-all duration-300 scale-100"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}

      {/* Delete dialog - use portal to render outside virtual list */}
      {showDeleteDialog &&
        createPortal(
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm animate-fade-in overflow-auto">
            <div
              className="rounded-2xl shadow-2xl border p-5 w-72 max-h-[95vh] overflow-auto flex flex-col gap-3 animate-slide-up my-4"
              style={{ background: 'var(--background)', borderColor: 'var(--border)' }}
            >
              <h3 className="font-semibold text-sm" style={{ color: 'var(--text-primary)' }}>
                {L.deleteMsg}
              </h3>
              <p className="text-xs" style={{ color: 'var(--text-muted)' }}>
                {L.deleteDesc}
              </p>
              <div className="flex flex-col gap-2">
                <Button onClick={handleDeleteForMe} variant="outline" className="w-full text-sm">
                  {L.deleteForMe}
                </Button>
                {isOwn && withinFiveMin && (
                  <Button
                    onClick={handleDeleteForEveryone}
                    variant="destructive"
                    className="w-full text-sm"
                  >
                    {L.deleteForEveryone}
                  </Button>
                )}
                {isOwn && !withinFiveMin && (
                  <p className="text-[11px] text-center" style={{ color: 'var(--text-disabled)' }}>
                    {L.canOnlyDelete}
                  </p>
                )}
              </div>
              <Button
                onClick={() => setShowDeleteDialog(false)}
                variant="ghost"
                className="text-xs hover:opacity-70 transition-opacity"
              >
                {L.cancel}
              </Button>
            </div>
          </div>,
          document.body,
        )}

      {/* Message row */}
      <div
        ref={msgRowRef}
        data-msg-row
        className={cn(
          'relative flex items-end gap-2.5 my-1 group animate-msg-in',
          isOwn ? 'flex-row-reverse' : 'flex-row',
          showActions ? 'z-10' : 'z-0',
        )}
        onMouseEnter={() => {
          const rowEl = msgRowRef.current;
          if (rowEl) {
            const rect = rowEl.getBoundingClientRect();
            const below = rect.top < 120;
            setActionBarBelow(below);
            setActionBarPos({
              top: below ? rect.bottom + 4 : rect.top - 40,
              left: isOwn ? rect.right - 320 : rect.left + 40,
            });
          }
          setShowActions(true);
          if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
        }}
        onMouseLeave={() => {
          // Don't hide if menu is open — let the menu's own handlers control visibility
          if (showMenu) return;
          hoverTimeoutRef.current = setTimeout(() => {
            setShowActions(false);
          }, 100);
        }}
        onTouchStart={() => {
          setShowActions((prev) => !prev);
        }}
      >
        {/* Avatar */}
        <div className="w-8 shrink-0 mb-1">
          {showAvatar && !isOwn && message.sender?._id ? (
            // Other person's avatar → clickable profile link
            <Link
              href={`/employees/${message.sender._id}`}
              className="block rounded-full transition-transform duration-200 hover:scale-105 focus:outline-none"
              title={`View ${message.sender?.name}'s profile`}
              onClick={(e) => e.stopPropagation()}
            >
              <Avatar className="w-7 h-7 ring-2 ring-transparent hover:ring-(--primary) transition-all duration-200">
                {message.sender?.avatarUrl && <AvatarImage src={message.sender.avatarUrl} />}
                <AvatarFallback className="btn-gradient text-[11px] font-bold text-white">
                  {getInitials(message.sender?.name ?? '?')}
                </AvatarFallback>
              </Avatar>
            </Link>
          ) : showAvatar && isOwn ? (
            // Own avatar on the right
            <Avatar className="w-7 h-7">
              {currentUserAvatar && <AvatarImage src={currentUserAvatar} />}
              <AvatarFallback className="btn-gradient text-[11px] font-bold text-white">
                {getInitials(currentUserName ?? L.me)}
              </AvatarFallback>
            </Avatar>
          ) : (
            <div className="w-8" />
          )}
        </div>

        <div className="flex flex-col max-w-[75%] sm:max-w-[65%] md:max-w-[55%]">
          {showName && (
            <span
              className="text-[11px] font-medium mb-0.5 px-1"
              style={{ color: 'var(--text-muted)' }}
            >
              {message.sender?.name ?? L.unknown}
            </span>
          )}

          {/* Reply preview */}
          {message.replyToContent && (
            <div
              className="mb-1 px-2 py-1 rounded-lg border-l-2 text-xs max-w-full transition-all duration-200"
              style={{
                borderColor: 'var(--primary)',
                background: 'var(--background-subtle)',
                color: 'var(--text-muted)',
              }}
            >
              <span className="font-medium" style={{ color: 'var(--primary)' }}>
                {message.replyToSenderName}
              </span>
              <p className="truncate">{message.replyToContent}</p>
            </div>
          )}

          {/* Bubble */}
          <div
            className="relative rounded-2xl px-3.5 py-2.5 text-[14px] leading-[1.45] wrap-break-words transition-all duration-200"
            style={{
              background: isOwn ? 'var(--primary)' : 'var(--secondary)',
              color: isOwn ? 'white' : 'var(--text-primary)',
              borderBottomRightRadius: isOwn ? '6px' : undefined,
              borderBottomLeftRadius: !isOwn ? '6px' : undefined,
            }}
          >
            {editing ? (
              <div className="space-y-2">
                {/* Edit header */}
                <div className="flex items-center gap-1.5 text-[10px] font-medium opacity-60">
                  <Edit2 className="w-3 h-3" />
                  {L.edit}
                </div>
                {/* Edit textarea */}
                <textarea
                  autoFocus
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  onFocus={() => setEditFocused(true)}
                  onBlur={() => setEditFocused(false)}
                  className="w-full bg-transparent outline-none resize-none text-sm leading-relaxed min-h-[60px] max-h-[200px]"
                  style={{
                    color: isOwn ? 'white' : 'var(--text-primary)',
                    borderColor: editFocused ? 'var(--primary)' : 'transparent',
                    borderBottom: `1px solid ${editFocused ? 'var(--primary)' : 'var(--border)'}`,
                    paddingBottom: '4px',
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleEdit();
                    }
                    if (e.key === 'Escape') setEditing(false);
                  }}
                />
                {/* Action buttons */}
                <div className="flex items-center justify-end gap-2">
                  <button
                    onClick={() => setEditing(false)}
                    className="px-3 py-1 rounded-lg text-xs font-medium transition-all duration-150 hover:opacity-80"
                    style={{
                      background: 'transparent',
                      color: isOwn ? 'rgba(255,255,255,0.7)' : 'var(--text-muted)',
                    }}
                  >
                    {L.cancel}
                  </button>
                  <button
                    onClick={handleEdit}
                    disabled={!editContent.trim()}
                    className="px-3 py-1 rounded-lg text-xs font-medium transition-all duration-150 hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed"
                    style={{
                      background: isOwn ? 'rgba(255,255,255,0.2)' : 'var(--primary)',
                      color: isOwn ? 'white' : 'white',
                    }}
                  >
                    {L.edit}
                  </button>
                </div>
              </div>
            ) : (
              message.content && (
                <p className="whitespace-pre-wrap leading-relaxed">{message.content}</p>
              )
            )}

            {/* Attachments */}
            {message.attachments && message.attachments.length > 0 && (
              <div className={cn('space-y-2', message.content ? 'mt-2' : '')}>
                {message.attachments.map((att, i) => {
                  // Voice/Audio message
                  if (att.type.startsWith('audio/') || message.type === 'audio') {
                    const duration = message.callDuration || 0;
                    const formatDuration = (secs: number) => {
                      const m = Math.floor(secs / 60);
                      const s = Math.floor(secs % 60);
                      return `${m}:${s.toString().padStart(2, '0')}`;
                    };
                    return (
                      <div
                        key={i}
                        className="flex items-center gap-2 p-2 rounded-xl min-w-50 max-w-70"
                        style={{
                          background: isOwn ? 'rgba(255,255,255,0.15)' : 'var(--background-subtle)',
                        }}
                      >
                        {/* Play icon */}
                        <button
                          className="w-7 h-7 rounded-full flex items-center justify-center shrink-0 hover:scale-105 transition-transform"
                          style={{
                            background: isOwn ? 'rgba(255,255,255,0.2)' : 'var(--primary)',
                            color: 'white',
                          }}
                        >
                          <svg className="w-4 h-4 ml-0.5" fill="currentColor" viewBox="0 0 24 24">
                            <path d="M8 5v14l11-7z" />
                          </svg>
                        </button>

                        {/* Waveform visualization placeholder */}
                        <div className="flex-1 flex items-center gap-0.5 h-8">
                          {Array.from({ length: 20 }).map((_, j) => (
                            <div
                              key={j}
                              className="w-1 rounded-full"
                              style={{
                                height: `${Math.random() * 20 + 8}px`,
                                background: isOwn ? 'rgba(255,255,255,0.6)' : 'var(--primary)',
                              }}
                            />
                          ))}
                        </div>

                        {/* Duration */}
                        <span
                          className="text-xs font-mono"
                          style={{ color: isOwn ? 'rgba(255,255,255,0.8)' : 'var(--text-muted)' }}
                        >
                          {formatDuration(duration)}
                        </span>

                        {/* Download */}
                        <a
                          href={att.url}
                          download={att.name}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="p-1.5 rounded-lg hover:opacity-80 transition-opacity"
                          style={{ color: isOwn ? 'rgba(255,255,255,0.8)' : 'var(--text-muted)' }}
                        >
                          <Download className="w-3.5 h-3.5" />
                        </a>
                      </div>
                    );
                  }

                  // Image
                  if (isImage(att.type)) {
                    return (
                      <div key={i} className="relative group/img">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                          src={att.url}
                          alt={att.name}
                          className="rounded-xl max-w-[28vw] xs:max-w-[180px] sm:max-w-50 max-h-50 object-cover cursor-pointer transition-all duration-200 hover:opacity-90 hover:scale-[1.02]"
                          onClick={() => setLightboxSrc(att.url)}
                        />
                        <Link
                          href={att.url}
                          download={att.name}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="absolute top-1.5 right-1.5 w-7 h-7 rounded-full bg-black/50 flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-all duration-200 hover:box-shadow-lg"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <Download className="w-3.5 h-3.5 text-white" />
                        </Link>
                        <p className="text-[9px] xs:text-[10px] mt-0.5 opacity-70 truncate max-w-[28vw] xs:max-w-[180px] sm:max-w-50">
                          {att.name}
                        </p>
                      </div>
                    );
                  }
                  if (isPDF(att.type)) {
                    return (
                      <div
                        key={i}
                        className="rounded-xl overflow-hidden w-full max-w-50 xs:max-w-55 sm:max-w-60"
                      >
                        <div
                          className="flex items-center gap-2 px-2 py-1.5 text-xs"
                          style={{ background: isOwn ? 'rgba(255,255,255,0.15)' : 'var(--border)' }}
                        >
                          <FileText className="w-4 h-4 shrink-0 text-red-400" />
                          <span className="truncate flex-1 text-[10px] xs:text-xs">{att.name}</span>
                          <span className="shrink-0 opacity-70 text-[9px] xs:text-[10px]">
                            {formatFileSize(att.size)}
                          </span>
                        </div>
                        <iframe
                          src={att.url + '#toolbar=0&navpanes=0&scrollbar=0'}
                          className="w-full"
                          style={{ height: 140 }}
                          title={att.name}
                        />
                        <Link
                          href={att.url}
                          download={att.name}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center justify-center gap-1 py-1.5 text-[9px] xs:text-xs hover:opacity-80 transition-opacity"
                          style={{
                            background: isOwn
                              ? 'rgba(255,255,255,0.1)'
                              : 'var(--background-subtle)',
                            color: isOwn ? 'white' : 'var(--text-muted)',
                          }}
                        >
                          <Download className="w-3 h-3" /> {L.download}
                        </Link>
                      </div>
                    );
                  }
                  return (
                    <Link
                      key={i}
                      href={att.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs hover:opacity-80 transition-all duration-200 hover:scale-[1.01]"
                      style={{ background: isOwn ? 'rgba(255,255,255,0.15)' : 'var(--border)' }}
                    >
                      <span>📎</span>
                      <span className="truncate flex-1 text-[9px] xs:text-xs">{att.name}</span>
                      <span className="shrink-0 opacity-70 text-[9px] xs:text-[10px]">
                        {formatFileSize(att.size)}
                      </span>
                    </Link>
                  );
                })}
              </div>
            )}

            {/* Link Preview */}
            {urlInContent && !message.poll && <LinkPreview url={urlInContent} isOwn={isOwn} />}

            {message.isEdited && (
              <span className="sm:text-[9px] text-xs opacity-60 ml-1">(edited)</span>
            )}
            {message.isPinned && (
              <span className="absolute -top-2 -right-1 sm:text-[10px] text-xs">📌</span>
            )}
          </div>

          {/* Poll UI */}
          {message.poll && (
            <div
              className="mt-1 rounded-xl overflow-hidden border w-full min-w-45 xs:min-w-[200px] sm:min-w-55 max-w-65 xs:max-w-[280px] sm:max-w-[320px] animate-fade-in"
              style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
            >
              <div
                className="px-2.5 xs:px-3 py-2 border-b"
                style={{ borderColor: 'var(--border)' }}
              >
                <p
                  className="text-xs xs:text-sm font-semibold wrap-break-words"
                  style={{ color: 'var(--text-primary)' }}
                >
                  📊 {message.poll.question}
                </p>
                {message.poll.closedAt && (
                  <p
                    className="text-[9px] xs:text-[10px] mt-1"
                    style={{ color: 'var(--text-disabled)' }}
                  >
                    {L.pollClosed}
                  </p>
                )}
              </div>
              <div className="px-2.5 xs:px-3 py-2 space-y-1">
                {(() => {
                  const totalVotes = message.poll.options.reduce((s, o) => s + o.votes.length, 0);
                  const userVote = message.poll.options.find((o) =>
                    o.votes.includes(currentUserId),
                  )?.id;
                  return message.poll.options.map((opt) => {
                    const pct =
                      totalVotes > 0 ? Math.round((opt.votes.length / totalVotes) * 100) : 0;
                    const isVoted = opt.id === userVote;
                    const isClosed = !!message.poll!.closedAt;
                    return (
                      <button
                        key={opt.id}
                        disabled={isClosed}
                        onClick={() =>
                          votePoll({
                            messageId: message._id,
                            userId: currentUserId,
                            optionId: opt.id,
                          })
                        }
                        className="w-full text-left relative rounded-lg overflow-hidden transition-all duration-200 hover:opacity-80 disabled:cursor-default"
                        style={{ background: 'var(--background)' }}
                      >
                        {/* Progress bar */}
                        <div
                          className="absolute inset-0 rounded-lg transition-all duration-500"
                          style={{
                            width: `${pct}%`,
                            background: isVoted ? 'var(--primary)' : 'var(--border)',
                            opacity: 0.25,
                          }}
                        />
                        <div className="relative flex items-center justify-between px-2.5 xs:px-3 py-2 min-h-9 xs:min-h-[32px]">
                          <span
                            className="text-[11px] xs:text-[12px] font-medium flex items-center gap-1 truncate max-w-[75%]"
                            style={{ color: isVoted ? 'var(--primary)' : 'var(--text-primary)' }}
                          >
                            {isVoted && (
                              <span
                                className="w-1.5 h-1.5 rounded-full shrink-0"
                                style={{ background: 'var(--primary)' }}
                              />
                            )}
                            {opt.text}
                          </span>
                          <span
                            className="text-[9px] xs:text-[10px] font-bold shrink-0 ml-1"
                            style={{ color: 'var(--text-muted)' }}
                          >
                            {pct}%
                          </span>
                        </div>
                      </button>
                    );
                  });
                })()}
              </div>
              <div
                className="px-2.5 xs:px-3 py-1.5 border-t flex items-center justify-between"
                style={{ borderColor: 'var(--border)' }}
              >
                <span
                  className="text-[9px] xs:text-[10px]"
                  style={{ color: 'var(--text-disabled)' }}
                >
                  {message.poll.options.reduce((s, o) => s + o.votes.length, 0)} {L.votes}
                </span>
                {isOwn && !message.poll.closedAt && (
                  <button
                    onClick={() => closePoll({ messageId: message._id, userId: currentUserId })}
                    className="text-[9px] xs:text-[10px] hover:opacity-70 transition-opacity py-0.5 px-1.5 hover:bg-opacity-50 rounded"
                    style={{ color: 'var(--primary)' }}
                  >
                    {L.closePoll}
                  </button>
                )}
              </div>
            </div>
          )}

          {/* Thread count */}
          {(message.threadCount ?? 0) > 0 && (
            <button
              onClick={() => onOpenThread(message._id, message.content)}
              className="flex items-center gap-1 mt-1 px-2 py-0.5 rounded-full sm:text-[10px] text-xs font-medium border transition-all duration-200 hover:scale-105"
              style={{
                borderColor: 'var(--primary)',
                color: 'var(--primary)',
                background: 'transparent',
              }}
            >
              <MessageSquare className="w-2.5 h-2.5" />
              {message.threadCount} repl{message.threadCount === 1 ? 'y' : 'ies'}
            </button>
          )}

          {/* Smart Reply — only for incoming messages */}
          {!isOwn &&
            !message.isDeleted &&
            message.type !== 'system' &&
            message.type !== 'call' &&
            message.content && (
              <SmartReply
                message={message.content}
                lang={lang}
                onSelect={(reply) =>
                  onSendMessage
                    ? onSendMessage(reply)
                    : onReply(
                        message._id,
                        message.content,
                        message.sender?.name ?? t('common.someone'),
                      )
                }
              />
            )}

          {/* Timestamp + read receipt */}
          <div
            className={cn(
              'flex items-center gap-1 mt-1 px-1',
              isOwn ? 'flex-row-reverse' : 'flex-row',
            )}
          >
            <span
              className="sm:text-[10px] text-xs opacity-60"
              style={{ color: 'var(--text-muted)' }}
            >
              {format(new Date(message.createdAt), 'HH:mm', { locale: dateFnsLocale })}
            </span>
            {isOwn && (
              <ReadReceipt readBy={message.readBy} isOwn={isOwn} isDirect={isDirect} lang={lang} />
            )}
          </div>

          {/* Reactions */}
          {totalReactions > 0 && (
            <div className="flex flex-wrap gap-1.5 mt-2 px-1">
              {Object.entries(message.reactions ?? {}).map(([emojiKey, users]) => {
                // Convert ASCII-safe key back to emoji for display
                const displayEmoji = keyToEmoji(emojiKey);
                return users.length > 0 ? (
                  <button
                    key={emojiKey}
                    onClick={() => handleReaction(displayEmoji)}
                    className="flex items-center gap-0.5 sm:px-1.5 px-2 sm:py-0.5 py-1 rounded-full sm:text-xs text-sm border transition-all duration-200 hover:box-shadow-lg min-h-7 sm:min-h-auto"
                    style={{
                      background: users.includes(currentUserId)
                        ? 'var(--primary)'
                        : 'var(--background-subtle)',
                      borderColor: users.includes(currentUserId)
                        ? 'var(--primary)'
                        : 'var(--border)',
                      color: users.includes(currentUserId) ? 'white' : 'var(--text-primary)',
                    }}
                    title={users.join(', ')}
                  >
                    {displayEmoji} {users.length}
                  </button>
                ) : null;
              })}
            </div>
          )}
        </div>

        {/* Action bar — disabled for service broadcasts unless sender is superadmin */}
        {(!message.isServiceBroadcast || (message.isServiceBroadcast && isOwn)) &&
          showActions &&
          actionBarPos &&
          createPortal(
            <div
              ref={actionBarRef}
              className="fixed flex items-center gap-0.5 z-40 rounded-full px-1.5 py-1 shadow-2xl border transition-all duration-150"
              style={{
                top: actionBarPos.top,
                left: actionBarPos.left,
                background: 'var(--background)',
                borderColor: 'var(--border)',
              }}
              onTouchStart={(e) => e.stopPropagation()}
              onMouseEnter={() => {
                if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
                setShowActions(true);
              }}
              onMouseLeave={() => {
                if (showMenu) return;
                hoverTimeoutRef.current = setTimeout(() => {
                  setShowActions(false);
                }, 100);
              }}
            >
              {QUICK_EMOJIS.map((emoji) => (
                <button
                  key={emoji}
                  onClick={() => handleReaction(emoji)}
                  className="w-7 h-7 flex items-center justify-center rounded-full text-sm sm:text-xs hover:scale-110 hover:bg-white/10 transition-all duration-150"
                >
                  {emoji}
                </button>
              ))}
              <button
                onClick={() =>
                  onReply(message._id, message.content, message.sender?.name ?? t('common.someone'))
                }
                className="w-7 h-7 flex items-center justify-center rounded-full hover:scale-110 hover:bg-white/10 transition-all duration-150"
                style={{ color: 'var(--text-muted)' }}
                title={L.reply}
              >
                <Reply className="w-4 h-4" />
              </button>
              <div className="relative">
                <button
                  ref={menuBtnRef}
                  onClick={() => {
                    if (menuBtnRef.current) {
                      const rect = menuBtnRef.current.getBoundingClientRect();
                      const spaceBelow = window.innerHeight - rect.bottom;
                      const openDown = spaceBelow > 220;
                      setMenuOpenDown(openDown);
                      setMenuPosition({
                        top: openDown ? rect.bottom + 8 : rect.top - 8,
                        left: isOwn ? undefined : rect.left,
                        right: isOwn ? window.innerWidth - rect.right - 8 : undefined,
                      });
                    }
                    setShowMenu((prev) => !prev);
                  }}
                  className="w-7 h-7 flex items-center justify-center rounded-full hover:scale-110 hover:bg-white/10 transition-all duration-150"
                  style={{ color: 'var(--text-muted)' }}
                >
                  <MoreHorizontal className="w-4 h-4" />
                </button>
              </div>
            </div>,
            document.body,
          )}
      </div>

      {/* Context menu rendered via portal so it isn't clipped by scroll containers */}
      <MessageMenuPortal
        open={showMenu}
        position={menuPosition}
        openDown={menuOpenDown}
        onMouseEnter={() => {
          if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
          setShowActions(true);
        }}
      >
        <div ref={menuRef}>
          <MenuItem icon={<Copy className="w-3.5 h-3.5" />} label={L.copy} onClick={handleCopy} />
          <MenuItem
            icon={<Pin className="w-3.5 h-3.5" />}
            label={message.isPinned ? L.unpin : L.pin}
            onClick={handlePin}
          />
          {isOwn && (
            <MenuItem
              icon={<Edit2 className="w-3.5 h-3.5" />}
              label={L.edit}
              onClick={() => {
                setEditing(true);
                setShowMenu(false);
              }}
            />
          )}
          <MenuItem
            icon={<Trash className="w-3.5 h-3.5" />}
            label={L.deleteForMe}
            onClick={() => {
              setShowDeleteDialog(true);
              setShowMenu(false);
            }}
            danger
          />
          {isOwn && withinFiveMin && (
            <MenuItem
              icon={<Trash2 className="w-3.5 h-3.5" />}
              label={L.deleteForEveryone}
              onClick={() => {
                setShowDeleteDialog(true);
                setShowMenu(false);
              }}
              danger
            />
          )}
        </div>
      </MessageMenuPortal>
    </>
  );
});

// Portal-mounted menu so it isn't clipped by scroll containers / input area
function MessageMenuPortal({
  open,
  position,
  openDown,
  children,
  onMouseEnter,
  onMouseLeave,
}: {
  open: boolean;
  position: { top: number; left?: number; right?: number } | null;
  openDown: boolean;
  children: React.ReactNode;
  onMouseEnter: () => void;
  onMouseLeave?: () => void;
}) {
  if (!open || !position || typeof document === 'undefined') return null;
  return createPortal(
    <div
      className="fixed z-120 rounded-xl shadow-2xl border py-1 min-w-40 animate-slide-up"
      style={{
        top: position.top,
        left: position.left,
        right: position.right,
        background: 'var(--background)',
        borderColor: 'var(--border)',
        transform: openDown ? 'translateY(0)' : 'translateY(-100%)',
      }}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      {children}
    </div>,
    document.body,
  );
}

function MenuItem({
  icon,
  label,
  onClick,
  danger,
}: {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  danger?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className="w-full flex items-center gap-2 px-3 py-1.5 text-xs transition-all duration-150 hover:opacity-80"
      style={{ color: danger ? '#ef4444' : 'var(--text-primary)' }}
      onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--sidebar-item-hover)')}
      onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
    >
      {icon}
      {label}
    </button>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Sparkles } from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';

interface Props {
  message: string;
  context?: string;
  onSelect: (reply: string) => void;
  lang?: string;
}

export function SmartReply({ message, context, onSelect, lang = 'en' }: Props) {
  const [replies, setReplies] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [fetched, setFetched] = useState(false);

  useEffect(() => {
    setReplies([]);
    setFetched(false);
  }, [message]);

  const fetchReplies = async () => {
    if (fetched || loading) return;
    setLoading(true);
    try {
      const res = await fetch('/api/chat/smart-reply', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message, context, lang }),
      });
      const data = await res.json();
      setReplies(data.replies ?? []);
      setFetched(true);
    } catch {
      const fallbacks: Record<string, string[]> = {
        ru: ['👍 Понял!', 'Можете уточнить?', 'Сделаю позже'],
        hy: ['👍 Հասկացա!', 'Կարող եք պարզաբանել:', 'Կանեմ ավելի ուշ'],
        en: ['👍 Got it!', 'Can you clarify?', "I'll do it later"],
      };
      const key = lang.startsWith('ru') ? 'ru' : lang.startsWith('hy') ? 'hy' : 'en';
      setReplies(fallbacks[key]!);
      setFetched(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-30 flex items-center gap-2 mt-2 flex-wrap">
      {!fetched && !loading && (
        <button
          onClick={fetchReplies}
          className="flex items-center gap-1.5 sm:px-2 px-3 sm:py-0.5 py-1.5 rounded-full sm:text-[10px] text-xs font-medium border transition-all duration-200 hover:scale-105 hover:opacity-80 min-h-[36px] sm:min-h-auto"
          style={{
            borderColor: 'var(--primary)',
            color: 'var(--primary)',
            background: 'transparent',
          }}
        >
          <Sparkles className="sm:w-2.5 w-3.5 sm:h-2.5 h-3.5" />
          Smart Reply
        </button>
      )}
      {loading && (
        <div
          className="flex items-center gap-1.5 sm:px-2 px-3 sm:py-0.5 py-1.5 rounded-full sm:text-[10px] text-xs min-h-[36px] sm:min-h-auto"
          style={{ color: 'var(--text-muted)' }}
        >
          <ShieldLoader size="xs" variant="inline" />
          Thinking…
        </div>
      )}
      {replies.map((r, i) => (
        <button
          key={i}
          onClick={() => onSelect(r)}
          className="sm:px-2.5 px-3 sm:py-0.5 py-1.5 rounded-full sm:text-[11px] text-xs font-medium border transition-all duration-200 hover:scale-105 animate-fade-in min-h-[36px] sm:min-h-auto"
          style={{
            borderColor: 'var(--border)',
            color: 'var(--text-primary)',
            background: 'var(--background-subtle)',
            animationDelay: `${i * 0.06}s`,
          }}
        >
          {r}
        </button>
      ))}
    </div>
  );
}

﻿'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { X, Send } from 'lucide-react';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';
import i18n from 'i18next';
import { useTranslation } from 'react-i18next';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { useOptimisticThreadReply } from '@/hooks/useOptimisticActions';

interface Props {
  parentMessageId: Id<'chatMessages'>;
  parentContent: string;
  currentUserId: Id<'users'>;
  conversationId: Id<'chatConversations'>;
  organizationId?: Id<'organizations'>;
  currentUserName?: string;
  onClose: () => void;
}

function getInitials(name: string) {
  return name
    .split(' ')
    .map((n: string) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);
}

export function ThreadPanel({
  parentMessageId,
  parentContent,
  currentUserId,
  conversationId,
  organizationId,
  currentUserName,
  onClose,
}: Props) {
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const endRef = useRef<HTMLDivElement>(null);
  const { t } = useTranslation();
  const lang = i18n.language || 'en';
  const dateFnsLocale = lang === 'ru' ? ru : lang === 'hy' ? hy : enUS;

  const replies = useQuery(api.chat.queries.getThreadReplies, { parentMessageId });

  const {
    replyOptimistic,
    optimisticReplies: optReplies,
    setUserName,
  } = useOptimisticThreadReply(parentMessageId, conversationId, currentUserId, organizationId);

  useEffect(() => {
    if (currentUserName) setUserName(currentUserName);
  }, [currentUserName, setUserName]);

  // Merge real replies with optimistic replies for instant UI feedback
  const allReplies = React.useMemo(() => {
    const real = replies ?? [];
    const optimistic = optReplies ?? [];
    const realIds = new Set<string>(real.map((r) => r._id));
    const pendingOptimistic = optimistic.filter((r) => !realIds.has(r._id));
    return [...real, ...pendingOptimistic];
  }, [replies, optReplies]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [allReplies?.length]);

  const handleSend = async () => {
    if (!input.trim() || sending) return;
    setSending(true);
    try {
      await replyOptimistic(input.trim());
      setInput('');
    } catch (err) {
      console.error('Thread reply failed:', err);
    } finally {
      setSending(false);
    }
  };

  return (
    <div
      className="flex flex-col h-full border-l animate-slide-in-right"
      style={{
        borderColor: 'var(--border)',
        background: 'var(--background)',
        width: 320,
        minWidth: 280,
      }}
    >
      {/* Header */}
      <div
        className="flex items-center justify-between px-4 py-3 border-b shrink-0"
        style={{ borderColor: 'var(--border)' }}
      >
        <div>
          <h3 className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
            {t('chat.thread.title')}
          </h3>
          <p className="text-[10px]" style={{ color: 'var(--text-muted)' }}>
            {t('chat.thread.repliesCount', { count: allReplies?.length ?? 0 })}
          </p>
        </div>
        <button
          onClick={onClose}
          className="w-7 h-7 flex items-center justify-center rounded-lg hover:opacity-70 transition-opacity"
          style={{ color: 'var(--text-muted)' }}
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      {/* Parent message */}
      <div
        className="px-4 py-3 border-b"
        style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
      >
        <p className="text-xs italic line-clamp-3" style={{ color: 'var(--text-muted)' }}>
          "{parentContent}"
        </p>
      </div>

      {/* Replies */}
      <div className="flex-1 overflow-y-auto px-3 py-3 space-y-3">
        {allReplies === undefined && (
          <div className="flex items-center justify-center py-8">
            <ShieldLoader size="xs" variant="inline" />
          </div>
        )}
        {allReplies?.map((r) => {
          const isOwn = r.senderId === currentUserId;
          return (
            <div
              key={r._id}
              className={`flex gap-2 animate-fade-in ${isOwn ? 'flex-row-reverse' : ''}`}
            >
              <Avatar className="sm:w-6 w-8 sm:h-6 h-8 shrink-0 mt-0.5">
                {r.sender?.avatarUrl && <AvatarImage src={r.sender.avatarUrl} />}
                <AvatarFallback className="sm:text-[8px] text-[10px] font-bold text-white btn-gradient">
                  {getInitials(r.sender?.name ?? '?')}
                </AvatarFallback>
              </Avatar>
              <div className={`flex flex-col ${isOwn ? 'items-end' : 'items-start'} max-w-[80%]`}>
                <span
                  className="sm:text-[10px] text-xs font-medium sm:mb-0.5 mb-1"
                  style={{ color: 'var(--text-muted)' }}
                >
                  {isOwn ? t('chat.thread.you') : r.sender?.name}
                </span>
                <div
                  className={`sm:px-3 px-3.5 sm:py-1.5 py-2 rounded-xl sm:text-xs text-sm break-words ${isOwn ? 'btn-gradient' : ''}`}
                  style={{
                    background: isOwn ? undefined : 'var(--background-subtle)',
                    color: isOwn ? 'white' : 'var(--text-primary)',
                  }}
                >
                  {r.content}
                </div>
                <span
                  className="sm:text-[9px] text-xs mt-1 opacity-50"
                  style={{ color: 'var(--text-muted)' }}
                >
                  {format(new Date(r.createdAt), 'HH:mm', { locale: dateFnsLocale })}
                </span>
              </div>
            </div>
          );
        })}
        <div ref={endRef} />
      </div>

      {/* Input */}
      <div className="px-3 py-2 border-t shrink-0" style={{ borderColor: 'var(--border)' }}>
        <div
          className="flex items-center gap-2 px-3 py-1.5 rounded-xl border"
          style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
        >
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSend();
              }
            }}
            placeholder={t('chat.thread.replyPlaceholder')}
            className="flex-1 bg-transparent outline-none text-xs"
            style={{ color: 'var(--text-primary)' }}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || sending}
            className={`w-6 h-6 flex items-center justify-center rounded-lg transition-all hover:scale-110 disabled:opacity-30 ${input.trim() ? 'btn-gradient' : ''}`}
            style={{
              background: input.trim() ? undefined : 'var(--border)',
            }}
          >
            <Send className="w-3 h-3 text-white" />
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { useMutation } from 'convex/react';
import { api } from '@/convex/_generated/api';
import { Id } from '@/convex/_generated/dataModel';
import { useTranslation } from 'react-i18next';
import { useAuthStore } from '@/store/useAuthStore';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import { toast } from 'sonner';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Award,
  ChevronLeft,
  ChevronRight,
  CheckCircle,
  X,
  DollarSign,
  Users,
  FileText,
} from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';

type BonusType = 'performance' | 'retention' | 'signing' | 'referral' | 'holiday' | 'custom';

interface BonusProgramWizardProps {
  onClose: () => void;
  onSuccess: () => void;
}

export default function BonusProgramWizard({ onClose, onSuccess }: BonusProgramWizardProps) {
  const { t } = useTranslation();
  const { user } = useAuthStore();
  const selectedOrgId = useSelectedOrganization();
  const effectiveOrgId = selectedOrgId ?? user?.organizationId;

  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Step 1: Basic Info
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [bonusType, setBonusType] = useState<BonusType>('performance');

  // Step 2: Eligibility & Amount
  const [eligibleRolesInput, setEligibleRolesInput] = useState('');
  const [eligibleDeptsInput, setEligibleDeptsInput] = useState('');
  const [currency, setCurrency] = useState('AMD');
  const [bonusAmount, setBonusAmount] = useState('');
  const [bonusPercentage, setBonusPercentage] = useState('');

  // Step 3: Period
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');

  // Step 4: Review
  const steps = [
    {
      id: 'basic',
      title: t('compensation.wizard.basicInfo', 'Basic Info'),
      icon: <FileText className="w-4 h-4" />,
    },
    {
      id: 'eligibility',
      title: t('compensation.wizard.eligibility', 'Eligibility'),
      icon: <Users className="w-4 h-4" />,
    },
    {
      id: 'period',
      title: t('compensation.wizard.period', 'Period'),
      icon: <Award className="w-4 h-4" />,
    },
    {
      id: 'review',
      title: t('compensation.wizard.review', 'Review'),
      icon: <CheckCircle className="w-4 h-4" />,
    },
  ];

  const createProgramMutation = useMutation(api.compensation.createBonusProgram);

  const bonusTypeLabels: Record<BonusType, string> = {
    performance: t('compensation.performance', 'Performance'),
    retention: t('compensation.retention', 'Retention'),
    signing: t('compensation.signing', 'Signing'),
    referral: t('compensation.referral', 'Referral'),
    holiday: t('compensation.holiday', 'Holiday'),
    custom: t('compensation.custom', 'Custom'),
  };

  const canProceed = () => {
    switch (currentStep) {
      case 0:
        return name.trim().length > 0;
      case 1:
        return parseFloat(bonusAmount) > 0 || parseFloat(bonusPercentage) > 0;
      case 2:
        return periodStart.trim().length > 0 && periodEnd.trim().length > 0;
      case 3:
        return true;
      default:
        return true;
    }
  };

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep((prev) => prev + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  const handleSubmit = async () => {
    if (!effectiveOrgId || !user?.id) return;

    setIsSubmitting(true);
    try {
      const eligibleRoles = eligibleRolesInput
        .split(',')
        .map((r) => r.trim())
        .filter(Boolean);
      const eligibleDepartments = eligibleDeptsInput
        .split(',')
        .map((d) => d.trim())
        .filter(Boolean);

      await createProgramMutation({
        organizationId: effectiveOrgId as Id<'organizations'>,
        name: name.trim(),
        description: description.trim() || undefined,
        type: bonusType,
        eligibleRoles: eligibleRoles.length > 0 ? eligibleRoles : undefined,
        eligibleDepartments: eligibleDepartments.length > 0 ? eligibleDepartments : undefined,
        currency,
        bonusAmount: bonusAmount ? parseFloat(bonusAmount) : undefined,
        bonusPercentage: bonusPercentage ? parseFloat(bonusPercentage) : undefined,
        periodStart: new Date(periodStart).getTime(),
        periodEnd: new Date(periodEnd).getTime(),
        createdBy: user.id as Id<'users'>,
      });

      toast.success(t('compensation.bonusProgramCreated', 'Bonus program created successfully'));
      onSuccess();
    } catch (error) {
      console.error('Create bonus program error:', error);
      toast.error(t('compensation.createBonusProgramFailed', 'Failed to create bonus program'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="programName">{t('compensation.programName', 'Program Name')} *</Label>
              <Input
                id="programName"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder={t('compensation.programNamePlaceholder', 'e.g., Q4 Performance Bonus')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label>{t('compensation.bonusType', 'Bonus Type')}</Label>
              <Select value={bonusType} onValueChange={(v) => setBonusType(v as BonusType)}>
                <SelectTrigger className="bg-(--input) border-(--input-border) text-(--text-primary)">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="performance">
                    {t('compensation.performance', 'Performance')}
                  </SelectItem>
                  <SelectItem value="retention">
                    {t('compensation.retention', 'Retention')}
                  </SelectItem>
                  <SelectItem value="signing">{t('compensation.signing', 'Signing')}</SelectItem>
                  <SelectItem value="referral">{t('compensation.referral', 'Referral')}</SelectItem>
                  <SelectItem value="holiday">{t('compensation.holiday', 'Holiday')}</SelectItem>
                  <SelectItem value="custom">{t('compensation.custom', 'Custom')}</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="programDescription">
                {t('compensation.description', 'Description')}
              </Label>
              <Textarea
                id="programDescription"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder={t(
                  'compensation.programDescriptionPlaceholder',
                  'Describe the bonus program...',
                )}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground) resize-none"
                rows={3}
              />
            </div>
          </div>
        );

      case 1:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="eligibleRoles">
                {t('compensation.eligibleRoles', 'Eligible Roles')}
              </Label>
              <Input
                id="eligibleRoles"
                value={eligibleRolesInput}
                onChange={(e) => setEligibleRolesInput(e.target.value)}
                placeholder={t(
                  'compensation.eligibleRolesPlaceholder',
                  'Comma-separated, e.g., Engineer, Manager',
                )}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="eligibleDepts">
                {t('compensation.eligibleDepartments', 'Eligible Departments')}
              </Label>
              <Input
                id="eligibleDepts"
                value={eligibleDeptsInput}
                onChange={(e) => setEligibleDeptsInput(e.target.value)}
                placeholder={t(
                  'compensation.eligibleDeptsPlaceholder',
                  'Comma-separated, e.g., Engineering, Sales',
                )}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label>{t('compensation.currency', 'Currency')}</Label>
              <Select value={currency} onValueChange={setCurrency}>
                <SelectTrigger className="bg-(--input) border-(--input-border) text-(--text-primary)">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="AMD">AMD</SelectItem>
                  <SelectItem value="USD">USD</SelectItem>
                  <SelectItem value="EUR">EUR</SelectItem>
                  <SelectItem value="RUB">RUB</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="bonusAmount">{t('compensation.bonusAmount', 'Bonus Amount')}</Label>
              <Input
                id="bonusAmount"
                type="number"
                value={bonusAmount}
                onChange={(e) => setBonusAmount(e.target.value)}
                placeholder={t('compensation.enterBonusAmount', 'Enter fixed bonus amount')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="bonusPercentage">
                {t('compensation.bonusPercentage', 'Bonus Percentage')}
              </Label>
              <Input
                id="bonusPercentage"
                type="number"
                value={bonusPercentage}
                onChange={(e) => setBonusPercentage(e.target.value)}
                placeholder={t(
                  'compensation.enterBonusPercentage',
                  'Enter percentage of base salary',
                )}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="periodStart">{t('compensation.periodStart', 'Period Start')} *</Label>
              <Input
                id="periodStart"
                type="date"
                value={periodStart}
                onChange={(e) => setPeriodStart(e.target.value)}
                className="bg-(--input) border-(--input-border) text-(--text-primary)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="periodEnd">{t('compensation.periodEnd', 'Period End')} *</Label>
              <Input
                id="periodEnd"
                type="date"
                value={periodEnd}
                onChange={(e) => setPeriodEnd(e.target.value)}
                className="bg-(--input) border-(--input-border) text-(--text-primary)"
              />
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4">
            <div className="p-4 rounded-lg border border-(--border) bg-(--background-subtle) space-y-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-(--primary)/10 flex items-center justify-center">
                  <Award className="w-5 h-5 text-(--primary)" />
                </div>
                <div className="min-w-0">
                  <p className="font-medium text-(--text-primary) truncate">{name || '—'}</p>
                  <p className="text-xs text-(--muted-foreground)">{bonusTypeLabels[bonusType]}</p>
                </div>
              </div>

              <div className="space-y-2 text-sm">
                {description && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('compensation.description', 'Description')}:
                    </span>
                    <span className="font-medium text-(--text-primary) text-right max-w-[200px] truncate">
                      {description}
                    </span>
                  </div>
                )}
                {eligibleRolesInput && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('compensation.eligibleRoles', 'Roles')}:
                    </span>
                    <span className="font-medium text-(--text-primary)">{eligibleRolesInput}</span>
                  </div>
                )}
                {eligibleDeptsInput && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('compensation.eligibleDepartments', 'Departments')}:
                    </span>
                    <span className="font-medium text-(--text-primary)">{eligibleDeptsInput}</span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('compensation.bonusAmount', 'Amount')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">
                    {bonusAmount
                      ? `${bonusAmount} ${currency}`
                      : bonusPercentage
                        ? `${bonusPercentage}%`
                        : '—'}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('compensation.period', 'Period')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">
                    {periodStart ? new Date(periodStart).toLocaleDateString() : '—'} —{' '}
                    {periodEnd ? new Date(periodEnd).toLocaleDateString() : '—'}
                  </span>
                </div>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepDescription = () => {
    switch (currentStep) {
      case 0:
        return t(
          'compensation.wizard.basicInfoDesc',
          'Define the program name, type and description',
        );
      case 1:
        return t(
          'compensation.wizard.eligibilityDesc',
          'Set eligibility criteria and bonus amount',
        );
      case 2:
        return t('compensation.wizard.periodDesc', 'Define the bonus program period');
      case 3:
        return t('compensation.wizard.reviewDesc', 'Review and confirm the bonus program');
      default:
        return '';
    }
  };

  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) return null;

  return ReactDOM.createPortal(
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-(--card) rounded-xl shadow-xl w-full max-w-lg mx-4 overflow-y-auto"
      >
        <div className="flex items-center justify-between p-6 pb-4 border-b border-(--border)">
          <h2 className="text-xl font-bold text-(--text-primary)">
            {t('compensation.newBonusProgram', 'New Bonus Program')}
          </h2>
          <Button variant="ghost" size="sm" onClick={onClose}>
            <X className="w-4 h-4" />
          </Button>
        </div>

        <div className="px-6 pt-4">
          <div className="flex items-center justify-between">
            {steps.map((step, index) => {
              const isCompleted = index < currentStep;
              const isCurrent = index === currentStep;
              return (
                <React.Fragment key={step.id}>
                  <div className="flex flex-col items-center flex-1">
                    <div
                      className={cn(
                        'w-8 h-8 rounded-full flex items-center justify-center border-2 transition-colors',
                        isCompleted
                          ? 'bg-blue-500 border-blue-500 text-white'
                          : isCurrent
                            ? 'border-(--primary) bg-(--card) text-(--primary)'
                            : 'border-(--border) bg-(--card) text-(--muted-foreground)',
                      )}
                    >
                      {isCompleted ? (
                        <CheckCircle className="w-4 h-4" />
                      ) : (
                        <span className="text-xs font-semibold">{index + 1}</span>
                      )}
                    </div>
                    <p
                      className={cn(
                        'text-xs mt-1 font-medium',
                        isCurrent ? 'text-(--primary)' : 'text-(--muted-foreground)',
                      )}
                    >
                      {step.title}
                    </p>
                  </div>
                  {index < steps.length - 1 && (
                    <div className="flex-1 h-0.5 bg-(--border) mx-2 mb-6">
                      <div
                        className={cn(
                          'h-full transition-colors',
                          isCompleted ? 'bg-(--primary)' : 'bg-(--border)',
                        )}
                      />
                    </div>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>

        <div className="px-6 py-4 max-h-[60vh] overflow-y-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={currentStep}
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.2 }}
            >
              <div className="mb-4">
                <h3 className="text-lg font-semibold text-(--text-primary)">
                  {steps[currentStep]!.title}
                </h3>
                <p className="text-sm text-(--muted-foreground)">{getStepDescription()}</p>
              </div>
              {renderStepContent()}
            </motion.div>
          </AnimatePresence>
        </div>

        <div className="flex items-center justify-between gap-3 p-6 pt-4 border-t border-(--border)">
          <Button
            variant="outline"
            onClick={handleBack}
            disabled={currentStep === 0 || isSubmitting}
            className="border-(--border) bg-(--card) hover:bg-(--background-subtle) text-(--text-primary)"
          >
            <ChevronLeft className="w-4 h-4 mr-1" />
            {t('wizard.back', 'Back')}
          </Button>

          {currentStep < steps.length - 1 ? (
            <Button
              onClick={handleNext}
              disabled={!canProceed() || isSubmitting}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2"
            >
              {t('wizard.next', 'Next')}
              <ChevronRight className="w-4 h-4" />
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || !canProceed()}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2"
            >
              {isSubmitting ? (
                <ShieldLoader size="xs" variant="inline" />
              ) : (
                <>
                  <CheckCircle className="w-4 h-4" />
                  {t('wizard.submit', 'Submit')}
                </>
              )}
            </Button>
          )}
        </div>
      </motion.div>
    </div>,
    document.body,
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { useMutation } from 'convex/react';
import { api } from '@/convex/_generated/api';
import { Id } from '@/convex/_generated/dataModel';
import { useTranslation } from 'react-i18next';
import { useAuthStore } from '@/store/useAuthStore';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import { toast } from 'sonner';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  BarChart3,
  ChevronLeft,
  ChevronRight,
  CheckCircle,
  X,
  DollarSign,
  Users,
  FileText,
} from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';

type Frequency = 'monthly' | 'yearly';

interface CompensationBandWizardProps {
  onClose: () => void;
  onSuccess: () => void;
}

export default function CompensationBandWizard({
  onClose,
  onSuccess,
}: CompensationBandWizardProps) {
  const { t } = useTranslation();
  const { user } = useAuthStore();
  const selectedOrgId = useSelectedOrganization();
  const effectiveOrgId = selectedOrgId ?? user?.organizationId;

  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Step 1: Basic Info
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [level, setLevel] = useState('');
  const [department, setDepartment] = useState('');

  // Step 2: Salary Range
  const [currency, setCurrency] = useState('AMD');
  const [minSalary, setMinSalary] = useState('');
  const [maxSalary, setMaxSalary] = useState('');
  const [medianSalary, setMedianSalary] = useState('');
  const [frequency, setFrequency] = useState<Frequency>('monthly');

  // Step 3: Review
  const steps = [
    {
      id: 'basic',
      title: t('compensation.wizard.basicInfo', 'Basic Info'),
      icon: <FileText className="w-4 h-4" />,
    },
    {
      id: 'salary',
      title: t('compensation.wizard.salaryRange', 'Salary Range'),
      icon: <DollarSign className="w-4 h-4" />,
    },
    {
      id: 'review',
      title: t('compensation.wizard.review', 'Review'),
      icon: <BarChart3 className="w-4 h-4" />,
    },
  ];

  const createBandMutation = useMutation(api.compensation.createCompensationBand);

  const canProceed = () => {
    switch (currentStep) {
      case 0:
        return name.trim().length > 0 && level.trim().length > 0;
      case 1:
        return (
          parseFloat(minSalary) > 0 &&
          parseFloat(maxSalary) > 0 &&
          parseFloat(maxSalary) >= parseFloat(minSalary)
        );
      case 2:
        return true;
      default:
        return true;
    }
  };

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep((prev) => prev + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  const handleSubmit = async () => {
    if (!effectiveOrgId || !user?.id) return;

    setIsSubmitting(true);
    try {
      await createBandMutation({
        organizationId: effectiveOrgId as Id<'organizations'>,
        name: name.trim(),
        description: description.trim() || undefined,
        level: level.trim(),
        department: department.trim() || undefined,
        currency,
        minSalary: parseFloat(minSalary),
        maxSalary: parseFloat(maxSalary),
        medianSalary: medianSalary ? parseFloat(medianSalary) : undefined,
        frequency,
        createdBy: user.id as Id<'users'>,
      });

      toast.success(t('compensation.bandCreated', 'Compensation band created successfully'));
      onSuccess();
    } catch (error) {
      console.error('Create compensation band error:', error);
      toast.error(t('compensation.createBandFailed', 'Failed to create compensation band'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const getFrequencyLabel = (freq: Frequency) => {
    return freq === 'monthly'
      ? t('compensation.monthly', 'Monthly')
      : t('compensation.yearly', 'Yearly');
  };

  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="bandName">{t('compensation.bandName', 'Band Name')} *</Label>
              <Input
                id="bandName"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder={t('compensation.bandNamePlaceholder', 'e.g., Senior Engineer')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="level">{t('compensation.level', 'Level')} *</Label>
              <Input
                id="level"
                value={level}
                onChange={(e) => setLevel(e.target.value)}
                placeholder={t('compensation.levelPlaceholder', 'e.g., Senior, Lead, Manager')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="department">{t('compensation.department', 'Department')}</Label>
              <Input
                id="department"
                value={department}
                onChange={(e) => setDepartment(e.target.value)}
                placeholder={t('compensation.departmentPlaceholder', 'e.g., Engineering')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="bandDescription">
                {t('compensation.description', 'Description')}
              </Label>
              <Textarea
                id="bandDescription"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder={t(
                  'compensation.bandDescriptionPlaceholder',
                  'Describe this compensation band...',
                )}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground) resize-none"
                rows={3}
              />
            </div>
          </div>
        );

      case 1:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label>{t('compensation.currency', 'Currency')}</Label>
              <Select value={currency} onValueChange={setCurrency}>
                <SelectTrigger className="bg-(--input) border-(--input-border) text-(--text-primary)">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="AMD">AMD</SelectItem>
                  <SelectItem value="USD">USD</SelectItem>
                  <SelectItem value="EUR">EUR</SelectItem>
                  <SelectItem value="RUB">RUB</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="minSalary">{t('compensation.minSalary', 'Min Salary')} *</Label>
              <Input
                id="minSalary"
                type="number"
                value={minSalary}
                onChange={(e) => setMinSalary(e.target.value)}
                placeholder={t('compensation.enterMinSalary', 'Enter minimum salary')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="maxSalary">{t('compensation.maxSalary', 'Max Salary')} *</Label>
              <Input
                id="maxSalary"
                type="number"
                value={maxSalary}
                onChange={(e) => setMaxSalary(e.target.value)}
                placeholder={t('compensation.enterMaxSalary', 'Enter maximum salary')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="medianSalary">
                {t('compensation.medianSalary', 'Median Salary')}
              </Label>
              <Input
                id="medianSalary"
                type="number"
                value={medianSalary}
                onChange={(e) => setMedianSalary(e.target.value)}
                placeholder={t('compensation.enterMedianSalary', 'Enter median salary (optional)')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label>{t('compensation.frequency', 'Frequency')}</Label>
              <Select value={frequency} onValueChange={(v) => setFrequency(v as Frequency)}>
                <SelectTrigger className="bg-(--input) border-(--input-border) text-(--text-primary)">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="monthly">{t('compensation.monthly', 'Monthly')}</SelectItem>
                  <SelectItem value="yearly">{t('compensation.yearly', 'Yearly')}</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            <div className="p-4 rounded-lg border border-(--border) bg-(--background-subtle) space-y-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-(--primary)/10 flex items-center justify-center">
                  <BarChart3 className="w-5 h-5 text-(--primary)" />
                </div>
                <div className="min-w-0">
                  <p className="font-medium text-(--text-primary) truncate">{name || '—'}</p>
                  <p className="text-xs text-(--muted-foreground)">
                    {level}
                    {department ? ` · ${department}` : ''}
                  </p>
                </div>
              </div>

              <div className="space-y-2 text-sm">
                {description && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('compensation.description', 'Description')}:
                    </span>
                    <span className="font-medium text-(--text-primary) text-right max-w-[200px] truncate">
                      {description}
                    </span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('compensation.salaryRange', 'Salary Range')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">
                    {minSalary} - {maxSalary} {currency}
                  </span>
                </div>
                {medianSalary && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('compensation.medianSalary', 'Median')}:
                    </span>
                    <span className="font-medium text-(--text-primary)">
                      {medianSalary} {currency}
                    </span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('compensation.frequency', 'Frequency')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">
                    {getFrequencyLabel(frequency)}
                  </span>
                </div>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepDescription = () => {
    switch (currentStep) {
      case 0:
        return t('compensation.wizard.basicInfoDesc', 'Define the band name, level and department');
      case 1:
        return t('compensation.wizard.salaryRangeDesc', 'Set the salary range and currency');
      case 2:
        return t('compensation.wizard.reviewDesc', 'Review and confirm the compensation band');
      default:
        return '';
    }
  };

  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) return null;

  return ReactDOM.createPortal(
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-(--card) rounded-xl shadow-xl w-full max-w-lg mx-4 overflow-y-auto"
      >
        <div className="flex items-center justify-between p-6 pb-4 border-b border-(--border)">
          <h2 className="text-xl font-bold text-(--text-primary)">
            {t('compensation.newBand', 'New Compensation Band')}
          </h2>
          <Button variant="ghost" size="sm" onClick={onClose}>
            <X className="w-4 h-4" />
          </Button>
        </div>

        <div className="px-6 pt-4">
          <div className="flex items-center justify-between">
            {steps.map((step, index) => {
              const isCompleted = index < currentStep;
              const isCurrent = index === currentStep;
              return (
                <React.Fragment key={step.id}>
                  <div className="flex flex-col items-center flex-1">
                    <div
                      className={cn(
                        'w-8 h-8 rounded-full flex items-center justify-center border-2 transition-colors',
                        isCompleted
                          ? 'bg-blue-500 border-blue-500 text-white'
                          : isCurrent
                            ? 'border-(--primary) bg-(--card) text-(--primary)'
                            : 'border-(--border) bg-(--card) text-(--muted-foreground)',
                      )}
                    >
                      {isCompleted ? (
                        <CheckCircle className="w-4 h-4" />
                      ) : (
                        <span className="text-xs font-semibold">{index + 1}</span>
                      )}
                    </div>
                    <p
                      className={cn(
                        'text-xs mt-1 font-medium',
                        isCurrent ? 'text-(--primary)' : 'text-(--muted-foreground)',
                      )}
                    >
                      {step.title}
                    </p>
                  </div>
                  {index < steps.length - 1 && (
                    <div className="flex-1 h-0.5 bg-(--border) mx-2 mb-6">
                      <div
                        className={cn(
                          'h-full transition-colors',
                          isCompleted ? 'bg-(--primary)' : 'bg-(--border)',
                        )}
                      />
                    </div>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>

        <div className="px-6 py-4 max-h-[60vh] overflow-y-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={currentStep}
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.2 }}
            >
              <div className="mb-4">
                <h3 className="text-lg font-semibold text-(--text-primary)">
                  {steps[currentStep]!.title}
                </h3>
                <p className="text-sm text-(--muted-foreground)">{getStepDescription()}</p>
              </div>
              {renderStepContent()}
            </motion.div>
          </AnimatePresence>
        </div>

        <div className="flex items-center justify-between gap-3 p-6 pt-4 border-t border-(--border)">
          <Button
            variant="outline"
            onClick={handleBack}
            disabled={currentStep === 0 || isSubmitting}
            className="border-(--border) bg-(--card) hover:bg-(--background-subtle) text-(--text-primary)"
          >
            <ChevronLeft className="w-4 h-4 mr-1" />
            {t('wizard.back', 'Back')}
          </Button>

          {currentStep < steps.length - 1 ? (
            <Button
              onClick={handleNext}
              disabled={!canProceed() || isSubmitting}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2"
            >
              {t('wizard.next', 'Next')}
              <ChevronRight className="w-4 h-4" />
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || !canProceed()}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2"
            >
              {isSubmitting ? (
                <ShieldLoader size="xs" variant="inline" />
              ) : (
                <>
                  <CheckCircle className="w-4 h-4" />
                  {t('wizard.submit', 'Submit')}
                </>
              )}
            </Button>
          )}
        </div>
      </motion.div>
    </div>,
    document.body,
  );
}

