];

const SEVERITY_COLORS: Record<string, string> = {
  info: 'text-blue-500 bg-blue-500/10',
  warning: 'text-amber-500 bg-amber-500/10',
  critical: 'text-red-500 bg-red-500/10',
};

const CATEGORY_ICONS: Record<string, typeof Shield> = {
  auth: LogIn,
