'use client';

import React, { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from 'convex/react';
import { useAuthStore } from '@/store/useAuthStore';
import { api } from '@/convex/_generated/api';
import { Id } from '@/convex/_generated/dataModel';
import { motion } from '@/lib/cssMotion';
import {
  Clock,
  UserPlus,
  CheckCircle2,
  XCircle,
  AlertCircle,
  FileText,
  DollarSign,
  Target,
  Truck,
  Plane,
  ListChecks,
  Bell,
  ArrowRight,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import Link from 'next/link';

// ── Types ──
type ActivityAction =
  | 'task_created'
  | 'task_completed'
  | 'task_status_updated'
  | 'leave_created'
  | 'leave_approved'
  | 'leave_rejected'
  | 'employee_added'
  | 'employee_updated'
  | 'payroll_approved'
  | 'payroll_paid'
  | 'goal_created'
  | 'goal_completed'
  | 'driver_requested'
  | 'driver_approved'
  | 'attendance_checkin'
  | 'recruitment_stage_changed'
  | 'unknown';

interface Activity {
  id: string;
  action: ActivityAction;
  title: string;
  description: string;
  timestamp: number;
  user: { name: string; avatarUrl?: string | null } | null;
  route?: string;
  severity?: 'info' | 'success' | 'warning' | 'error';
}

// ── Config ──
const ACTION_CONFIG: Record<
  ActivityAction,
  { icon: typeof Clock; color: string; bg: string; defaultSeverity: Activity['severity'] }
> = {
  task_created: {
    icon: ListChecks,
    color: 'text-blue-500',
    bg: 'bg-blue-500/10',
    defaultSeverity: 'info',
  },
  task_completed: {
    icon: CheckCircle2,
    color: 'text-emerald-500',
    bg: 'bg-emerald-500/10',
    defaultSeverity: 'success',
  },
  task_status_updated: {
    icon: ArrowRight,
    color: 'text-amber-500',
    bg: 'bg-amber-500/10',
    defaultSeverity: 'info',
  },
  leave_created: {
    icon: Plane,
    color: 'text-sky-500',
    bg: 'bg-sky-500/10',
    defaultSeverity: 'info',
  },
  leave_approved: {
    icon: CheckCircle2,
    color: 'text-emerald-500',
    bg: 'bg-emerald-500/10',
    defaultSeverity: 'success',
  },
  leave_rejected: {
    icon: XCircle,
    color: 'text-rose-500',
    bg: 'bg-rose-500/10',
    defaultSeverity: 'error',
  },
  employee_added: {
    icon: UserPlus,
    color: 'text-violet-500',
    bg: 'bg-violet-500/10',
    defaultSeverity: 'success',
  },
  employee_updated: {
    icon: UserPlus,
    color: 'text-indigo-500',
    bg: 'bg-indigo-500/10',
    defaultSeverity: 'info',
  },
  payroll_approved: {
    icon: DollarSign,
    color: 'text-green-500',
    bg: 'bg-green-500/10',
    defaultSeverity: 'success',
  },
  payroll_paid: {
    icon: DollarSign,
    color: 'text-emerald-500',
    bg: 'bg-emerald-500/10',
    defaultSeverity: 'success',
  },
  goal_created: {
    icon: Target,
    color: 'text-purple-500',
    bg: 'bg-purple-500/10',
    defaultSeverity: 'info',
  },
  goal_completed: {
    icon: Target,
    color: 'text-emerald-500',
    bg: 'bg-emerald-500/10',
    defaultSeverity: 'success',
  },
  driver_requested: {
    icon: Truck,
    color: 'text-orange-500',
    bg: 'bg-orange-500/10',
    defaultSeverity: 'info',
  },
