'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useRouter } from 'next/navigation';
import { Shield, Timer } from 'lucide-react';
import { SmartBanner } from '@/components/ui/SmartBanner';
import { useAuthStore } from '@/store/useAuthStore';

interface DashboardBannersProps {
  /** Leave balances from Convex user data */
  paidLeaveBalance?: number;
  sickLeaveBalance?: number;
  familyLeaveBalance?: number;
  /** User's createdAt timestamp — to detect first-time login */
  userCreatedAt?: number;
  /** Last login timestamp */
  lastLoginAt?: number;
}

export function DashboardBanners({
  paidLeaveBalance,
  sickLeaveBalance,
  familyLeaveBalance,
  userCreatedAt,
  lastLoginAt,
}: DashboardBannersProps) {
  const { t } = useTranslation();
  const router = useRouter();
  const { user } = useAuthStore();

  // ── 1. Success banner after login ─────────────────────────────────────────
  const [showLoginSuccess, setShowLoginSuccess] = useState(false);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const justLoggedIn = sessionStorage.getItem('just_logged_in');
      if (justLoggedIn === 'true') {
        setShowLoginSuccess(true);
        sessionStorage.removeItem('just_logged_in');
      }
    }
  }, []);

  // ── 2. Suspicious login warning ───────────────────────────────────────────
  const [showSuspiciousLogin, setShowSuspiciousLogin] = useState(false);
  const [suspiciousDetails, setSuspiciousDetails] = useState('');

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const suspicious = sessionStorage.getItem('suspicious_login');
      if (suspicious) {
        setShowSuspiciousLogin(true);
        setSuspiciousDetails(suspicious);
        sessionStorage.removeItem('suspicious_login');
      }
    }
  }, []);

  // ── 3. Session expiry countdown ───────────────────────────────────────────
  const [showSessionExpiry, setShowSessionExpiry] = useState(false);
  const [sessionMinutes, setSessionMinutes] = useState(5);

  useEffect(() => {
    // Check session expiry every 60 seconds
    const checkSession = () => {
      if (typeof window === 'undefined') return;
      const cookieStr = document.cookie;
      const sessionCookie = cookieStr.split('; ').find((c) => c.startsWith('session_expiry='));

      if (sessionCookie) {
        const expiryStr = sessionCookie.split('=')[1];
        if (!expiryStr) return;
        const expiry = parseInt(expiryStr, 10);
        const remaining = expiry - Date.now();
        const minutesLeft = Math.ceil(remaining / 60000);

        if (minutesLeft <= 5 && minutesLeft > 0) {
          setSessionMinutes(minutesLeft);
          setShowSessionExpiry(true);
        } else {
          setShowSessionExpiry(false);
        }
      }
    };

    checkSession();
    const interval = setInterval(checkSession, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleExtendSession = useCallback(async () => {
    try {
      const res = await fetch('/api/auth/refresh-session', { method: 'POST' });
      if (res.ok) {
        setShowSessionExpiry(false);
      }
    } catch {
      // If refresh fails, session will expire naturally
    }
  }, []);

  // ── 4. Welcome banner for new employees ───────────────────────────────────
  const [showWelcome, setShowWelcome] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined' || !userCreatedAt) return;

    // Show welcome if account created within last 24 hours
    // AND user hasn't dismissed it before
    const ageMs = Date.now() - userCreatedAt;
    const isNewUser = ageMs < 24 * 60 * 60 * 1000;
    const dismissed = localStorage.getItem('welcome_banner_dismissed');

    if (isNewUser && !dismissed) {
      setShowWelcome(true);
    }
  }, [userCreatedAt]);

  const handleDismissWelcome = useCallback(() => {
    setShowWelcome(false);
    localStorage.setItem('welcome_banner_dismissed', 'true');
  }, []);

  // ── 5. Leave balance warning ──────────────────────────────────────────────
  const lowBalances: string[] = [];
  if (paidLeaveBalance !== undefined && paidLeaveBalance <= 2) {
    lowBalances.push(t('dashboard.paidLeaveBalance', { count: paidLeaveBalance }));
  }
  if (sickLeaveBalance !== undefined && sickLeaveBalance <= 2) {
    lowBalances.push(t('dashboard.sickLeaveBalance', { count: sickLeaveBalance }));
  }
  if (familyLeaveBalance !== undefined && familyLeaveBalance <= 1) {
    lowBalances.push(t('dashboard.familyLeaveBalance', { count: familyLeaveBalance }));
  }
  const showLeaveWarning = lowBalances.length > 0;

  // Don't render anything if no banners are active
  if (
    !showLoginSuccess &&
    !showSuspiciousLogin &&
    !showSessionExpiry &&
    !showWelcome &&
    !showLeaveWarning
  ) {
    return null;
  }

  return (
    <div className="space-y-3">
      {/* 1. Login success — green */}
      {showLoginSuccess && (
        <SmartBanner
          type="success"
          message={t('banners.welcomeBack', { name: user?.name?.split(' ')[0] || '' })}
          suggestion={t('banners.productiveDay', 'Have a productive day ahead!')}
          autoDismiss={5000}
          onDismiss={() => setShowLoginSuccess(false)}
        />
      )}

      {/* 2. Suspicious login — warning/orange */}
      {showSuspiciousLogin && (
        <SmartBanner
          type="warning"
          message={t('banners.unusualLogin', 'Unusual login activity detected')}
          suggestion={
            suspiciousDetails ||
            t(
              'banners.loginWarning',
              'This login was from a new device or location. If this was not you, change your password immediately.',
            )
          }
          icon={<Shield className="w-5 h-5 text-amber-500" />}
          action={{
            label: t('banners.reviewSecurity', 'Review security settings'),
            onClick: () => router.push('/settings'),
          }}
          onDismiss={() => setShowSuspiciousLogin(false)}
        />
      )}

      {/* 3. Session expiry countdown — orange */}
      {showSessionExpiry && (
        <SmartBanner
          type="warning"
          message={t('banners.sessionExpires', {
            minutes: sessionMinutes,
            plural: sessionMinutes > 1 ? 's' : '',
          })}
          suggestion={t(
            'banners.saveWork',
            'Save your work and extend your session to avoid losing changes.',
          )}
          icon={<Timer className="w-5 h-5 text-amber-500" />}
          dismissable={false}
          action={{
            label: t('banners.extendSession', 'Extend session'),
            onClick: handleExtendSession,
          }}
        />
      )}

      {/* 4. Welcome banner for new employees — purple */}
      {showWelcome && (
        <SmartBanner
          type="purple"
          message={t(
            'banners.welcomeTeam',
            'Welcome to the team! We are excited to have you here.',
          )}
          suggestion={t(
            'banners.exploreDashboard',
            'Start by exploring the dashboard, setting up your profile, and checking your leave balances.',
          )}
          action={{
            label: t('banners.setUpProfile', 'Set up your profile'),
            onClick: () => router.push('/settings'),
          }}
          onDismiss={handleDismissWelcome}
        />
      )}

      {/* 5. Leave balance warning — orange */}
      {showLeaveWarning && (
        <SmartBanner
          type="warning"
          message={t('banners.leaveBalanceLow', 'Your leave balance is running low')}
          suggestion={lowBalances.join(' / ')}
          action={{
            label: t('banners.viewLeaveHistory', 'View leave history'),
            onClick: () => router.push('/leaves'),
          }}
          autoDismiss={15000}
        />
      )}
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { motion } from '@/lib/cssMotion';
import { useTranslation } from 'react-i18next';
import { Users, Clock, CheckCircle, UserCheck, TrendingUp } from 'lucide-react';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Id } from '../../../convex/_generated/dataModel';
import { useAuthUser } from '@/store/useAuthStore';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import { StatsCard } from '@/components/dashboard/StatsCard';
import { LEAVE_TYPE_LABELS, LEAVE_TYPE_COLORS, type LeaveType } from '@/lib/types';
import { type LeaveEnriched, type Organization } from '@/lib/convex-types';
import { DashboardBanners } from '@/components/dashboard/DashboardBanners';
import { DashboardHeader } from '@/components/dashboard/DashboardHeader';
import { SecurityWidget } from '@/components/dashboard/SecurityWidget';
import { LeaveCharts } from '@/components/dashboard/LeaveCharts';
import { RecentLeavesCard } from '@/components/dashboard/RecentLeavesCard';
import { EnterpriseWidgets } from '@/components/dashboard/EnterpriseWidgets';
import StrategyDashboardWidget from '@/components/dashboard/StrategyDashboardWidget';
import LeaveStats from '@/components/dashboard/LeaveStats';
import { QuickActions } from '@/components/dashboard/QuickActions';

const containerVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.08, delayChildren: 0.1 } },
};
const itemVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0 },
};

export default function DashboardClient() {
  const { t, i18n } = useTranslation();
  const user = useAuthUser();

  const [mounted, setMounted] = React.useState(false);

  const selectedOrgId = useSelectedOrganization();

  const userId = user?.id && user.id !== '' ? (user.id as Id<'users'>) : null;

  const organizationsList = useQuery(
    api.organizations.getOrganizationsForPicker,
    userId ? { userId } : 'skip',
  );

  const selectedOrganization = organizationsList?.find((o) => o._id === selectedOrgId);

  // Lightweight aggregated queries instead of loading all leaves/users
  const dashboardStats = useQuery(
    api.analytics.getDashboardStats,
    userId
      ? {
          organizationId: (selectedOrgId || undefined) as Id<'organizations'> | undefined,
        }
      : 'skip',
  );

  const recentLeavesData = useQuery(
    api.analytics.getRecentLeaves,
    userId
      ? {
          organizationId: (selectedOrgId || undefined) as Id<'organizations'> | undefined,
        }
      : 'skip',
  );

  const organization = useQuery(
    api.organizations.getMyOrganization,
    userId ? { userId } : 'skip',
  ) as Organization | null;

  const isSuperadmin = user?.role === 'superadmin';
  const securityStats = useQuery(
    api.security.getLoginStats,
    mounted && isSuperadmin ? { hours: 24 } : 'skip',
  );

  React.useEffect(() => {
    setMounted(true);
  }, []);

  const stats = dashboardStats ?? {
    totalEmployees: 0,
    pendingRequests: 0,
    onLeaveNow: 0,
    approvedThisMonth: 0,
    pieData: [],
    monthlyTrend: [],
  };

  const recentLeaves = recentLeavesData ?? [];

  const pieData = useMemo(() => {
    const data = (Object.keys(LEAVE_TYPE_COLORS) as LeaveType[]).map((key) => ({
      name: t(`leaveTypes.${key}`) || LEAVE_TYPE_LABELS[key],
      value: stats.pieData.find((p) => p.type === key)?.value ?? 0,
      color: LEAVE_TYPE_COLORS[key],
    }));
    return data.filter((d) => d.value > 0);
  }, [stats.pieData, t]);

  const monthlyTrend = useMemo(() => {
    const now = new Date();
    return stats.monthlyTrend.map((entry) => {
      const [year, month] = entry.key.split('-');
      const monthIdx = parseInt(month!, 10) - 1;
      const monthKey =
        ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'][
          monthIdx
        ] ?? 'jan';
      return {
        month: t(`months.${monthKey}`),
        approved: entry.approved,
        pending: entry.pending,
        rejected: entry.rejected,
      };
    });
  }, [stats.monthlyTrend, t, i18n?.language]);

  if (!mounted) return null;

  const isLoading = dashboardStats === undefined || recentLeavesData === undefined;
  const isError = dashboardStats === null || recentLeavesData === null;

  if (isError)
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4 text-center">
        <div className="w-16 h-16 rounded-2xl bg-amber-500/10 flex items-center justify-center">
          <TrendingUp className="w-8 h-8 text-amber-500" />
        </div>
        <h2 className="text-xl font-semibold text-(--text-primary)">
          {t('dashboard.convexNotDeployed')}
        </h2>
        <p className="text-(--text-muted) text-sm max-w-sm">{t('dashboard.convexNotDeployed')}</p>
      </div>
    );

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className="space-y-4 sm:space-y-6"
    >
      <h1 className="sr-only">{t('nav.dashboard', { defaultValue: 'Dashboard' })}</h1>

      <DashboardHeader
        selectedOrganization={selectedOrganization as Organization | undefined}
        userRole={user?.role}
      />

      <DashboardBanners />

      <motion.div variants={itemVariants}>
        <div
          data-tour="quick-stats"
          className="grid grid-cols-2 sm:grid-cols-2 xl:grid-cols-4 gap-2 sm:gap-4"
        >
          <StatsCard
            title={t('titles.totalEmployees')}
            value={isLoading ? '—' : stats.totalEmployees}
            icon={<Users className="w-4 h-4 sm:w-5 sm:h-5" />}
            color="blue"
            index={0}
          />
          <StatsCard
            title={t('titles.pendingRequests')}
            value={isLoading ? '—' : stats.pendingRequests}
            icon={<Clock className="w-4 h-4 sm:w-5 sm:h-5" />}
            color="yellow"
            index={1}
          />
          <StatsCard
            title={t('titles.approvedThisMonth')}
            value={isLoading ? '—' : stats.approvedThisMonth}
            icon={<CheckCircle className="w-4 h-4 sm:w-5 sm:h-5" />}
            color="green"
            index={2}
          />
          <StatsCard
            title={t('titles.onLeaveNow')}
            value={isLoading ? '—' : stats.onLeaveNow}
            icon={<UserCheck className="w-4 h-4 sm:w-5 sm:h-5" />}
            color="purple"
            index={3}
          />
        </div>
      </motion.div>

      {user?.role === 'superadmin' && <SecurityWidget securityStats={securityStats} />}

      <LeaveCharts monthlyTrend={monthlyTrend} pieData={pieData} />

      <div className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-4">
        <RecentLeavesCard
          recentLeaves={
            recentLeaves.map((l) => ({
              ...l,
              organizationId: l.organizationId ?? ('' as Id<'organizations'>),
            })) as LeaveEnriched[]
          }
        />
        {user?.id && (
          <motion.div variants={itemVariants} data-tour="leave-balance">
            <LeaveStats userId={user.id as Id<'users'>} />
          </motion.div>
        )}
      </div>

      {/* Strategy OKR Widget */}
      <motion.div variants={itemVariants}>
        <StrategyDashboardWidget />
      </motion.div>

      <motion.div variants={itemVariants} data-tour="quick-actions" className="lg:col-span-2">
        <QuickActions />
      </motion.div>

      <motion.div variants={itemVariants} data-tour="recent-activity" className="lg:col-span-1">
        {organization?.plan === 'enterprise' && <EnterpriseWidgets />}
      </motion.div>
    </motion.div>
  );
}

'use client';

import React from 'react';
import { motion } from '@/lib/cssMotion';
import { useTranslation } from 'react-i18next';
