type DocumentCategory =
  | 'policy'
  | 'contract'
  | 'report'
  | 'template'
  | 'form'
  | 'certificate'
  | 'other';

interface UploadedFile {
  url: string;
  name: string;
  size: number;
  type: string;
}

interface LocalFile {
  id: string;
  file: File;
  preview?: string;
  base64?: string;
}

const FILE_ICONS: Record<string, React.ReactNode> = {
  'application/pdf': <FileText className="w-10 h-10 text-red-400" />,
  'image/': <ImageIcon className="w-10 h-10 text-blue-400" />,
  'video/': <Video className="w-10 h-10 text-purple-400" />,
  'audio/': <Music className="w-10 h-10 text-green-400" />,
};

function getFileIcon(type: string): React.ReactNode {
  for (const [key, icon] of Object.entries(FILE_ICONS)) {
    if (type.startsWith(key)) return icon;
  }
  return <File className="w-10 h-10 text-gray-400" />;
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

function getCategories(t: (key: string, fallback: string) => string) {
  return [
    {
      value: 'policy' as DocumentCategory,
      label: t('documents.categoryPolicy', 'Policy'),
      icon: <FileText className="w-4 h-4 text-blue-500" />,
    },
    {
      value: 'contract' as DocumentCategory,
      label: t('documents.categoryContract', 'Contract'),
      icon: <FileText className="w-4 h-4 text-green-500" />,
    },
    {
      value: 'report' as DocumentCategory,
      label: t('documents.categoryReport', 'Report'),
      icon: <FileText className="w-4 h-4 text-purple-500" />,
    },
    {
      value: 'template' as DocumentCategory,
      label: t('documents.categoryTemplate', 'Template'),
      icon: <FileText className="w-4 h-4 text-orange-500" />,
    },
    {
      value: 'form' as DocumentCategory,
      label: t('documents.categoryForm', 'Form'),
      icon: <FileText className="w-4 h-4 text-cyan-500" />,
    },
    {
      value: 'certificate' as DocumentCategory,
      label: t('documents.categoryCertificate', 'Certificate'),
      icon: <FileText className="w-4 h-4 text-yellow-500" />,
    },
    {
      value: 'other' as DocumentCategory,
      label: t('documents.categoryOther', 'Other'),
      icon: <FileText className="w-4 h-4 text-gray-500" />,
    },
  ];
}

function getSteps(t: (key: string, fallback: string) => string) {
  return [
    { id: 'file', title: t('documents.file', 'File'), icon: <Upload className="w-4 h-4" /> },
    { id: 'details', title: t('documents.details', 'Details'), icon: <Info className="w-4 h-4" /> },
    {
      id: 'settings',
      title: t('documents.settings', 'Settings'),
      icon: <Settings className="w-4 h-4" />,
    },
    { id: 'review', title: t('documents.review', 'Review'), icon: <Eye className="w-4 h-4" /> },
  ];
}

interface DocumentUploadWizardProps {
  onClose: () => void;
  onSuccess: () => void;
  templateId?: Id<'documentTemplates'>;
}

export default function DocumentUploadWizard({
  onClose,
  onSuccess,
  templateId,
}: DocumentUploadWizardProps) {
  const { t } = useTranslation();
  const { user } = useAuthStore();
  const selectedOrgId = useSelectedOrganization();
  const effectiveOrgId = selectedOrgId ?? user?.organizationId;
  const mainRef = useMainRef();

  useLayoutEffect(() => {
    const mainEl = mainRef.current;
    if (mainEl) {
      const original = mainEl.style.overflow;
      mainEl.style.overflow = 'hidden';
      return () => {
        mainEl.style.overflow = original;
      };
    }
  }, []);

  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Step 1: File
  const [localFiles, setLocalFiles] = useState<LocalFile[]>([]);
  const [uploadedFile, setUploadedFile] = useState<UploadedFile | null>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [dragActive, setDragActive] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Step 2: Details
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState<DocumentCategory>('other');
  const [tagsInput, setTagsInput] = useState('');

  // Fetch template if provided
  const templateData = useQuery(api.signatures.getTemplate, templateId ? { templateId } : 'skip');

  // Prefill from template
  React.useEffect(() => {
    if (templateData && !title) {
      setTitle(templateData.title);
      setDescription(templateData.description || '');
      setCategory('template');
    }
  }, [templateData, title]);

  // Step 3: Settings
  const [isMandatory, setIsMandatory] = useState(false);
  const [publishImmediately, setPublishImmediately] = useState(false);
  const [enableExpiration, setEnableExpiration] = useState(false);
  const [expiresAt, setExpiresAt] = useState('');

  const createDocumentMutation = useMutation(api.documents.createDocument);
  const updateDocumentMutation = useMutation(api.documents.updateDocument);

  const categories = getCategories(t);
  const steps = getSteps(t);

  const handleFileSelect = useCallback(
    async (files: FileList | File[]) => {
      const fileArray = Array.from(files);
      if (fileArray.length === 0) return;

      const file = fileArray[0] as File;
      const sizeMB = file.size / (1024 * 1024);
      if (sizeMB > MAX_FILE_SIZE / (1024 * 1024)) {
        toast.error(
          `File size (${formatSize(file.size)}) ${t('documents.exceedsLimit', 'exceeds 10MB limit')}`,
        );
        return;
      }

      const id = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      let preview: string | undefined;
      if (file.type.startsWith('image/')) {
        preview = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      }

      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.readAsDataURL(file);
      });

      setLocalFiles([{ id, file, preview, base64 }]);
    },
    [t],
  );

  const uploadFile = async (): Promise<boolean> => {
    if (localFiles.length === 0) return false;

    setUploading(true);
    setUploadProgress(0);
    try {
      const localFile = localFiles[0] as LocalFile;
      if (!localFile.base64) {
        toast.error(t('documents.fileDataMissing', 'File data is missing'));
        return false;
      }
      setUploadProgress(25);

      const result = await uploadDocument(
        localFile.base64,
        localFile.file.name,
        localFile.file.type,
      );
      setUploadProgress(100);

      setUploadedFile({
        url: result.url,
        name: result.name,
        size: result.size,
        type: result.type,
      });

      if (!title.trim()) {
        setTitle(result.name.replace(/\.[^/.]+$/, '').replace(/_/g, ' '));
      }

      toast.success(t('documents.fileUploaded', 'File uploaded successfully'));
      return true;
    } catch (error) {
      console.error('Upload error:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : t('documents.uploadFailed', 'Failed to upload file'),
      );
      setLocalFiles([]);
      return false;
    } finally {
      setUploading(false);
      setUploadProgress(0);
    }
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files);
    }
  };

  const removeFile = () => {
    setLocalFiles([]);
    setUploadedFile(null);
  };

  const canProceed = () => {
    switch (currentStep) {
      case 0:
        return localFiles.length > 0;
      case 1:
        return title.trim().length > 0;
      case 2:
        return true;
      case 3:
        return true;
      default:
        return true;
    }
  };

  const handleNext = async () => {
    if (currentStep === 0 && localFiles.length > 0 && !uploadedFile) {
      const success = await uploadFile();
      if (success) {
        setCurrentStep(1);
      }
      return;
    }
    if (currentStep < steps.length - 1) {
      setCurrentStep((prev) => prev + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  const handleSubmit = async () => {
    if (!effectiveOrgId || !user?.id || !uploadedFile) return;

    setIsSubmitting(true);
    try {
      const tags = tagsInput
        .split(',')
        .map((tag) => tag.trim())
        .filter(Boolean);

      const expirationDate =
        enableExpiration && expiresAt ? new Date(expiresAt).getTime() : undefined;

      const docId = await createDocumentMutation({
        organizationId: effectiveOrgId as Id<'organizations'>,
        title: title.trim(),
        description: description.trim() || undefined,
        category,
        fileUrl: uploadedFile.url,
        fileName: uploadedFile.name,
        fileSize: uploadedFile.size,
        mimeType: uploadedFile.type,
        isMandatory,
        expiresAt: expirationDate,
        tags: tags.length > 0 ? tags : undefined,
      });

      if (publishImmediately && docId) {
        await updateDocumentMutation({
          documentId: docId,
          isPublished: true,
        });
      }

      toast.success(t('documents.documentCreated', 'Document created successfully'));
      onSuccess();
    } catch (error) {
      console.error('Create document error:', error);
      toast.error(t('documents.createFailed', 'Failed to create document'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-4">
            {!uploadedFile && localFiles.length === 0 && (
              <div
                className={cn(
                  'border-2 border-dashed rounded-xl p-8 text-center transition-colors cursor-pointer',
                  dragActive
                    ? 'border-(--primary) bg-(--primary)/5'
                    : 'border-(--border) hover:border-(--primary)/50 hover:bg-(--background-subtle)',
                )}
                onDragEnter={handleDrag}
                onDragLeave={handleDrag}
                onDragOver={handleDrag}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
              >
                <Input
                  ref={fileInputRef}
                  type="file"
                  accept="*/*"
                  className="hidden"
                  onChange={(e) => e.target.files && handleFileSelect(e.target.files)}
                />
                <Upload className="w-12 h-12 mx-auto mb-4 text-(--muted-foreground)" />
                <p className="text-lg font-medium text-(--text-primary) mb-1">
                  {t('documents.dragDrop', 'Drag & drop your file here')}
                </p>
                <p className="text-sm text-(--muted-foreground) mb-4">
                  {t('documents.orClick', 'or click to browse')}
                </p>
                <p className="text-xs text-(--muted-foreground)">
                  {t('documents.maxSize', 'Max file size: 10MB')}
                </p>
              </div>
            )}

            {localFiles.length > 0 && !uploadedFile && (
              <div className="space-y-3">
                {localFiles.map((file) => (
                  <div
                    key={file.id}
                    className="flex items-center gap-4 p-4 rounded-lg border border-(--border) bg-(--background-subtle)"
                  >
                    {file.preview ? (
                      <Image
                        src={file.preview}
                        alt={file.file.name}
                        width={48}
                        height={48}
                        className="rounded object-cover"
                      />
                    ) : (
                      getFileIcon(file.file.type)
                    )}
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-(--text-primary) truncate">{file.file.name}</p>
                      <p className="text-xs text-(--muted-foreground)">
                        {formatSize(file.file.size)}
                      </p>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        removeFile();
                      }}
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
                {uploading && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-sm text-(--muted-foreground)">
                      <ShieldLoader size="xs" variant="inline" />
                      <span>{t('documents.uploading', 'Uploading to Cloudinary...')}</span>
                    </div>
                    <div className="h-2 bg-(--background-subtle) rounded-full overflow-hidden">
                      <motion.div
                        className="h-full bg-(--primary)"
                        initial={{ width: '0%' }}
                        animate={{ width: `${uploadProgress}%` }}
                        transition={{ duration: 0.3 }}
                      />
                    </div>
                  </div>
                )}
              </div>
            )}

            {uploadedFile && (
              <div className="flex items-center gap-4 p-4 rounded-lg border border-green-500/30 bg-green-500/5">
                {uploadedFile.type.startsWith('image/') ? (
                  <Image
                    src={uploadedFile.url}
                    alt={uploadedFile.name}
                    width={48}
                    height={48}
                    className="rounded object-cover"
                  />
                ) : (
                  getFileIcon(uploadedFile.type)
                )}
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-(--text-primary) truncate">{uploadedFile.name}</p>
                  <p className="text-xs text-(--muted-foreground)">
                    {formatSize(uploadedFile.size)}
                  </p>
                </div>
                <CheckCircle className="w-5 h-5 text-green-500" />
              </div>
            )}
          </div>
        );

      case 1:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="title">
                {t('documents.title', 'Title')} <span className="text-red-500">*</span>
              </Label>
              <Input
                id="title"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder={t('documents.titlePlaceholder', 'Enter document title')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">{t('documents.description', 'Description')}</Label>
              <Textarea
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder={t('documents.descriptionPlaceholder', 'Enter document description')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground) resize-none"
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>{t('documents.category', 'Category')}</Label>
              <Select value={category} onValueChange={(v) => setCategory(v as DocumentCategory)}>
                <SelectTrigger className="bg-(--input) border-(--input-border) text-(--text-primary)">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((cat) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      <div className="flex items-center gap-2">
                        {cat.icon}
                        {cat.label}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="tags">{t('documents.tags', 'Tags')}</Label>
              <Input
                id="tags"
                value={tagsInput}
                onChange={(e) => setTagsInput(e.target.value)}
                placeholder={t('documents.tagsPlaceholder', 'Comma-separated tags')}
                className="bg-(--input) border-(--input-border) text-(--text-primary) placeholder-(--muted-foreground)"
              />
              {tagsInput.trim() && (
                <div className="flex flex-wrap gap-1 mt-2">
                  {tagsInput
                    .split(',')
                    .map((tag) => tag.trim())
                    .filter(Boolean)
                    .map((tag, i) => (
                      <Badge key={i} variant="secondary" className="text-xs">
                        {tag}
                      </Badge>
                    ))}
                </div>
              )}
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            <div className="flex items-center space-x-2">
              <Checkbox
                id="mandatory"
                checked={isMandatory}
                onCheckedChange={(checked) => setIsMandatory(checked as boolean)}
              />
              <Label htmlFor="mandatory" className="cursor-pointer">
                {t('documents.mandatory', 'Mandatory')}
              </Label>
            </div>
            <p className="text-xs text-(--muted-foreground) -mt-2 ml-6">
              {t('documents.mandatoryDesc', 'Users must acknowledge this document')}
            </p>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="publish"
                checked={publishImmediately}
                onCheckedChange={(checked) => setPublishImmediately(checked as boolean)}
              />
              <Label htmlFor="publish" className="cursor-pointer">
                {t('documents.publishImmediately', 'Publish immediately')}
              </Label>
            </div>
            <p className="text-xs text-(--muted-foreground) -mt-2 ml-6">
              {t('documents.publishDesc', 'Make this document visible to all users')}
            </p>

            <div className="space-y-3 pt-2">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="expiration"
                  checked={enableExpiration}
                  onCheckedChange={(checked) => setEnableExpiration(checked as boolean)}
                />
                <Label htmlFor="expiration" className="cursor-pointer">
                  {t('documents.setExpiration', 'Set expiration date')}
                </Label>
              </div>

              {enableExpiration && (
                <div className="ml-6">
                  <Input
                    type="date"
                    value={expiresAt}
                    onChange={(e) => setExpiresAt(e.target.value)}
                    min={new Date().toISOString().split('T')[0]}
                    className="bg-(--input) border-(--input-border) text-(--text-primary)"
                  />
                </div>
              )}
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4">
            <div className="p-4 rounded-lg border border-(--border) bg-(--background-subtle) space-y-3">
              <div className="flex items-center gap-3">
                {uploadedFile?.type.startsWith('image/') ? (
                  <Image
                    src={uploadedFile.url}
                    alt={uploadedFile.name}
                    width={40}
                    height={40}
                    className="rounded object-cover"
                  />
                ) : (
                  getFileIcon(uploadedFile?.type || 'application/octet-stream')
                )}
                <div className="min-w-0">
                  <p className="font-medium text-(--text-primary) truncate">{uploadedFile?.name}</p>
                  <p className="text-xs text-(--muted-foreground)">
                    {formatSize(uploadedFile?.size || 0)}
                  </p>
                </div>
              </div>

              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('documents.title', 'Title')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">{title}</span>
                </div>
                {description && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('documents.description', 'Description')}:
                    </span>
                    <span className="font-medium text-(--text-primary) text-right max-w-[200px] truncate">
                      {description}
                    </span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('documents.category', 'Category')}:
                  </span>
                  <span className="font-medium text-(--text-primary) capitalize">{category}</span>
                </div>
                {tagsInput.trim() && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('documents.tags', 'Tags')}:
                    </span>
                    <div className="flex flex-wrap gap-1 justify-end">
                      {tagsInput
                        .split(',')
                        .map((tag) => tag.trim())
                        .filter(Boolean)
                        .map((tag, i) => (
                          <Badge key={i} variant="secondary" className="text-xs">
                            {tag}
                          </Badge>
                        ))}
                    </div>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('documents.mandatory', 'Mandatory')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">
                    {isMandatory ? t('common.yes', 'Yes') : t('common.no', 'No')}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-(--muted-foreground)">
                    {t('documents.publish', 'Publish')}:
                  </span>
                  <span className="font-medium text-(--text-primary)">
                    {publishImmediately
                      ? t('documents.publishImmediately', 'Immediately')
                      : t('documents.draft', 'Draft')}
                  </span>
                </div>
                {enableExpiration && expiresAt && (
                  <div className="flex justify-between">
                    <span className="text-(--muted-foreground)">
                      {t('documents.expires', 'Expires')}:
                    </span>
                    <span className="font-medium text-(--text-primary)">
                      {new Date(expiresAt).toLocaleDateString()}
                    </span>
                  </div>
                )}
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/70 backdrop-blur-sm">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-(--card) rounded-xl shadow-xl w-full max-w-lg mx-4 overflow-y-auto"
      >
        {/* Header */}
        <div className="flex items-center justify-between p-6 pb-4 border-b border-(--border)">
          <h2 className="text-xl font-bold text-(--text-primary)">
            {t('documents.uploadDocument', 'Upload Document')}
          </h2>
          <Button variant="ghost" size="sm" onClick={onClose}>
            <X className="w-4 h-4" />
          </Button>
        </div>

        {/* Stepper */}
        <div className="px-6 pt-4">
          <div className="flex items-center justify-between">
            {steps.map((step, index) => {
              const isCompleted = index < currentStep;
              const isCurrent = index === currentStep;

              return (
                <React.Fragment key={step.id}>
                  <div className="flex flex-col items-center flex-1">
                    <div
                      className={cn(
                        'w-8 h-8 rounded-full flex items-center justify-center border-2 transition-colors',
                        isCompleted
                          ? 'bg-blue-500 border-blue-500 text-white'
                          : isCurrent
                            ? 'border-(--primary) bg-(--card) text-(--primary)'
                            : 'border-(--border) bg-(--card) text-(--muted-foreground)',
                      )}
                    >
                      {isCompleted ? (
                        <CheckCircle className="w-4 h-4" />
                      ) : (
                        <span className="text-xs font-semibold">{index + 1}</span>
                      )}
                    </div>
                    <p
                      className={cn(
                        'text-xs mt-1 font-medium',
                        isCurrent ? 'text-(--primary)' : 'text-(--muted-foreground)',
                      )}
                    >
                      {step.title}
                    </p>
                  </div>
                  {index < steps.length - 1 && (
                    <div className="flex-1 h-0.5 bg-(--border) mx-2 mb-6">
                      <div
                        className={cn(
                          'h-full transition-colors',
                          isCompleted ? 'bg-(--primary)' : 'bg-(--border)',
                        )}
                      />
                    </div>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>

        {/* Content */}
        <div className="px-6 py-4 max-h-[60vh] overflow-y-clip">
          <AnimatePresence mode="wait">
            <motion.div
              key={currentStep}
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.2 }}
            >
              <div className="mb-4">
                <h3 className="text-lg font-semibold text-(--text-primary)">
                  {steps[currentStep]!.title}
                </h3>
                <p className="text-sm text-(--muted-foreground)">
                  {currentStep === 0 &&
                    t('documents.fileUploadStep', 'Select the file you want to upload')}
                  {currentStep === 1 &&
                    t('documents.detailsStep', 'Add title, description and category')}
                  {currentStep === 2 && t('documents.settingsStep', 'Configure document settings')}
                  {currentStep === 3 &&
                    t('documents.reviewStep', 'Review and confirm your document')}
                </p>
              </div>
              {renderStepContent()}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Navigation */}
        <div className="flex items-center justify-between gap-3 p-6 pt-4 border-t border-(--border)">
          <Button
            variant="outline"
            onClick={handleBack}
            disabled={currentStep === 0 || isSubmitting}
            className="border-(--border) bg-(--card) hover:bg-(--background-subtle) text-(--text-primary)"
          >
            <ChevronLeft className="w-4 h-4 mr-1" />
            {t('wizard.back', 'Back')}
          </Button>

          {currentStep < steps.length - 1 ? (
            <Button
              onClick={handleNext}
              disabled={!canProceed() || uploading || isSubmitting}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2"
            >
              {uploading ? (
                <>
                  <ShieldLoader size="xs" variant="inline" />
                </>
              ) : (
                <>
                  {t('wizard.next', 'Next')}
                  <ChevronRight className="w-4 h-4" />
                </>
              )}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || !canProceed()}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2"
            >
              {isSubmitting ? (
                <>
                  <ShieldLoader size="xs" variant="inline" />
                </>
              ) : (
                <>
                  <CheckCircle className="w-4 h-4" />
                  {t('wizard.submit', 'Submit')}
                </>
              )}
            </Button>
          )}
        </div>
      </motion.div>
    </div>,
    document.body,
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Id } from '../../../convex/_generated/dataModel';
import { useTranslation } from 'react-i18next';
import { useAuthStore } from '@/store/useAuthStore';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  FileText,
  Upload,
  Eye,
  BarChart3,
  FolderOpen,
  CheckCircle,
  Clock,
  Plus,
  Trash2,
  PenTool,
} from 'lucide-react';
import { toast } from 'sonner';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import DocumentUploadWizard from '@/components/documents/DocumentUploadWizard';
import DocumentTemplateWizard from '@/components/documents/DocumentTemplateWizard';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

type DocumentWithUploader = {
  _id: Id<'documents'>;
  _creationTime: number;
  organizationId: Id<'organizations'>;
  title: string;
  description?: string;
  category: 'policy' | 'contract' | 'report' | 'template' | 'form' | 'certificate' | 'other';
  fileUrl: string;
  fileName: string;
  fileSize?: number;
  mimeType?: string;
  uploadedBy: Id<'users'>;
  isPublished?: boolean;
  isMandatory?: boolean;
  expiresAt?: number;
  tags?: string[];
  createdAt: number;
  updatedAt: number;
  uploaderName: string;
};

type DocumentView = {
  _id: Id<'documentViews'>;
  _creationTime: number;
  organizationId: Id<'organizations'>;
  documentId: Id<'documents'>;
  userId: Id<'users'>;
  viewedAt: number;
  acknowledged?: boolean;
};

export default function DocumentsClient() {
  const { t } = useTranslation();
  const router = useRouter();
  const { user } = useAuthStore();
  const selectedOrgId = useSelectedOrganization();
  const isAdmin = user?.role === 'admin' || user?.role === 'superadmin';
  const effectiveOrgId = selectedOrgId ?? user?.organizationId;

  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [showUploadWizard, setShowUploadWizard] = useState(false);
  const [showTemplateWizard, setShowTemplateWizard] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState<DocumentWithUploader | null>(null);
  const [createDocFromTemplate, setCreateDocFromTemplate] =
    useState<Id<'documentTemplates'> | null>(null);

  // Fetch data
  const documents = useQuery(
    api.documents.listDocuments,
    effectiveOrgId && user?.id
      ? {
          organizationId: effectiveOrgId as Id<'organizations'>,
          category: categoryFilter !== 'all' ? categoryFilter : undefined,
          search: searchQuery || undefined,
          includeUnpublished: isAdmin,
        }
      : 'skip',
  );

  const templates = useQuery(
    api.signatures.listTemplates,
    effectiveOrgId ? { organizationId: effectiveOrgId as Id<'organizations'> } : 'skip',
  );

  const deleteTemplateMutation = useMutation(api.signatures.deleteTemplate);

  const myViews = useQuery(
    api.documents.getMyDocumentViews,
    effectiveOrgId && user?.id
      ? {
          organizationId: effectiveOrgId as Id<'organizations'>,
        }
      : 'skip',
  );

  const teamOverview = useQuery(
    api.documents.getTeamDocumentOverview,
    effectiveOrgId && user?.id && isAdmin
      ? {
          organizationId: effectiveOrgId as Id<'organizations'>,
        }
      : 'skip',
  );

  const categories = useQuery(
    api.documents.getDocumentCategories,
    effectiveOrgId && user?.id
      ? {
          organizationId: effectiveOrgId as Id<'organizations'>,
        }
      : 'skip',
  );

  // Mutations
  const updateDocumentMutation = useMutation(api.documents.updateDocument);
  const deleteDocumentMutation = useMutation(api.documents.deleteDocument);
  const recordViewMutation = useMutation(api.documents.recordDocumentView);

  const handleWizardSuccess = () => {
    setShowUploadWizard(false);
  };

  const handleViewDocument = async (doc: DocumentWithUploader) => {
    if (!effectiveOrgId || !user?.id) return;

    try {
      await recordViewMutation({
        organizationId: effectiveOrgId as Id<'organizations'>,
        documentId: doc._id,
      });
      setSelectedDocument(doc);
      window.open(doc.fileUrl, '_blank', 'noopener,noreferrer');
    } catch {
      toast.error(t('documents.viewError', 'Failed to record document view'));
    }
  };

  const handleDeleteDocument = async (documentId: Id<'documents'>) => {
    if (!user?.id) return;

    try {
      await deleteDocumentMutation({
        documentId,
      });

      toast.success(t('documents.documentDeleted', 'Document deleted successfully'));
    } catch {
      toast.error(t('documents.deleteError', 'Failed to delete document'));
    }
  };

  const handlePublishDocument = async (documentId: Id<'documents'>) => {
    if (!user?.id) return;

    try {
      await updateDocumentMutation({
        documentId,
        isPublished: true,
      });

      toast.success(t('documents.documentPublished', 'Document published successfully'));
    } catch {
      toast.error(t('documents.publishError', 'Failed to publish document'));
    }
  };

  const isViewed = (documentId: Id<'documents'>) => {
    return myViews?.some((v) => v.documentId === documentId);
  };

  const isAcknowledged = (documentId: Id<'documents'>) => {
    return myViews?.some((v) => v.documentId === documentId && v.acknowledged);
  };

  const formatFileSize = (bytes?: number) => {
    if (!bytes) return '';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  };

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString();
  };

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'policy':
        return <FileText className="h-5 w-5 text-blue-500" />;
      case 'contract':
        return <FileText className="h-5 w-5 text-green-500" />;
      case 'report':
        return <BarChart3 className="h-5 w-5 text-purple-500" />;
      case 'template':
        return <FolderOpen className="h-5 w-5 text-orange-500" />;
      case 'form':
        return <FileText className="h-5 w-5 text-cyan-500" />;
      case 'certificate':
        return <CheckCircle className="h-5 w-5 text-yellow-500" />;
      default:
        return <FileText className="h-5 w-5 text-gray-500" />;
    }
  };

  // Loading state
  if (documents === undefined) {
    return (
      <div className="flex items-center justify-center h-96">
        <ShieldLoader message={t('documents.loading', 'Loading documents...')} />
      </div>
    );
  }

  const handleTemplateSuccess = () => {
    setShowTemplateWizard(false);
  };

  const handleDeleteTemplate = async (templateId: Id<'documentTemplates'>) => {
    try {
      await deleteTemplateMutation({ templateId });
      toast.success(t('documents.templateDeleted', 'Template deleted successfully'));
    } catch {
      toast.error(t('documents.templateDeleteError', 'Failed to delete template'));
    }
  };

  const handleCreateDocFromTemplate = (templateId: Id<'documentTemplates'>) => {
    setCreateDocFromTemplate(templateId);
    setShowUploadWizard(true);
  };

  // Filter documents by tab
  const filteredDocuments = documents.filter((doc) => {
    if (activeTab === 'mandatory') return doc.isMandatory;
    if (activeTab === 'unpublished') return !doc.isPublished;
    return true;
  });

  return (
    <div className="mx-auto">
      {/* Header */}
      <div className="sticky top-0 z-10 -mx-4 sm:-mx-6 lg:-mx-8 px-4 sm:px-6 lg:px-8 py-4 mb-4 bg-(--background)/95 backdrop-blur supports-[backdrop-filter]:bg-(--background)/60 border-b border-(--border)">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-(--text-primary)">
              {t('documents.title', 'Document Management')}
            </h2>
            <p className="text-(--text-muted) text-sm mt-1">
              {t('documents.subtitle', 'Manage and organize your organization documents')}
            </p>
          </div>
          {isAdmin && (
            <Button onClick={() => setShowUploadWizard(true)}>
              <Upload className="h-4 w-4 mr-2" />
              {t('documents.uploadDocument', 'Upload Document')}
            </Button>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      {isAdmin && teamOverview && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-3">
                <FileText className="h-5 w-5 text-muted-foreground" />
                <div>
                  <p className="text-2xl font-bold">{teamOverview.totalDocuments}</p>
                  <p className="text-sm text-muted-foreground">
                    {t('documents.totalDocuments', 'Total Documents')}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-3">
                <CheckCircle className="h-5 w-5 text-muted-foreground" />
                <div>
                  <p className="text-2xl font-bold">{teamOverview.publishedDocuments}</p>
                  <p className="text-sm text-muted-foreground">
                    {t('documents.publishedDocuments', 'Published Documents')}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-3">
                <Eye className="h-5 w-5 text-muted-foreground" />
                <div>
                  <p className="text-2xl font-bold">{teamOverview.totalViews}</p>
                  <p className="text-sm text-muted-foreground">
                    {t('documents.totalViews', 'Total Views')}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-3">
                <Clock className="h-5 w-5 text-muted-foreground" />
                <div>
                  <p className="text-2xl font-bold">{teamOverview.acknowledgmentRate}%</p>
                  <p className="text-sm text-muted-foreground">
                    {t('documents.acknowledgmentRate', 'Acknowledgment Rate')}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Search and Filter Bar */}
      <div className="flex flex-col sm:flex-row gap-4 mb-6">
        <div className="flex-1">
          <input
            type="text"
            placeholder={t('documents.searchDocuments', 'Search documents...')}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full px-4 py-2 rounded-lg border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-primary"
          />
        </div>
        <div className="w-full sm:w-48">
          <select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="w-full grid grid-cols-2 md:grid-cols-3 px-4 py-2 rounded-lg border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-primary"
          >
            <option value="all">{t('documents.allCategories', 'All Categories')}</option>
            <option value="policy">{t('documents.categoryPolicy', 'Policy')}</option>
            <option value="contract">{t('documents.categoryContract', 'Contract')}</option>
            <option value="report">{t('documents.categoryReport', 'Report')}</option>
            <option value="template">{t('documents.categoryTemplate', 'Template')}</option>
            <option value="form">{t('documents.categoryForm', 'Form')}</option>
            <option value="certificate">{t('documents.categoryCertificate', 'Certificate')}</option>
            <option value="other">{t('documents.categoryOther', 'Other')}</option>
          </select>
        </div>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-6">
        <TabsList
          className={`w-full mb-4 gap-2 bg-transparent p-0 h-auto ${isAdmin ? 'grid grid-cols-2 md:grid-cols-4' : 'grid grid-cols-2 md:grid-cols-3'}`}
        >
          <TabsTrigger
            value="all"
            className="w-full px-4 py-2.5 rounded-xl data-[state=active]:bg-[#3b82f6] data-[state=active]:text-white data-[state=inactive]:bg-[var(--background-subtle)] shadow-sm font-medium flex items-center justify-center gap-2"
          >
            <FileText className="h-4 w-4" />
            {t('documents.allDocuments', 'All Documents')}
          </TabsTrigger>
          <TabsTrigger
            value="mandatory"
            className="w-full px-4 py-2.5 rounded-xl data-[state=active]:bg-[#3b82f6] data-[state=active]:text-white data-[state=inactive]:bg-[var(--background-subtle)] shadow-sm font-medium flex items-center justify-center gap-2"
          >
            <CheckCircle className="h-4 w-4" />
            {t('documents.mandatoryDocuments', 'Mandatory')}
          </TabsTrigger>
          {isAdmin && (
            <TabsTrigger
              value="unpublished"
              className="w-full px-4 py-2.5 rounded-xl data-[state=active]:bg-[#3b82f6] data-[state=active]:text-white data-[state=inactive]:bg-[var(--background-subtle)] shadow-sm font-medium flex items-center justify-center gap-2"
            >
              <Clock className="h-4 w-4" />
              {t('documents.unpublishedDocuments', 'Unpublished')}
            </TabsTrigger>
          )}
          <TabsTrigger
            value="templates"
            className="w-full px-4 py-2.5 rounded-xl data-[state=active]:bg-[#3b82f6] data-[state=active]:text-white data-[state=inactive]:bg-[var(--background-subtle)] shadow-sm font-medium flex items-center justify-center gap-2"
          >
            <FolderOpen className="h-4 w-4" />
            {t('documents.templates', 'Templates')}
          </TabsTrigger>
        </TabsList>

        {/* Documents List */}
        <TabsContent
          value={activeTab === 'templates' ? 'templates' : activeTab}
          className="space-y-4"
        >
          {activeTab === 'templates' ? (
            <div>
              {/* Templates header */}
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h2 className="text-xl font-semibold">
                    {t('documents.documentTemplates', 'Document Templates')}
                  </h2>
                  <p className="text-sm text-muted-foreground mt-1">
                    {t('documents.templatesDesc', 'Reusable templates for document signing')}
                  </p>
                </div>
                {isAdmin && (
                  <Button onClick={() => setShowTemplateWizard(true)}>
                    <Plus className="h-4 w-4 mr-2" />
                    {t('documents.createTemplate', 'Create Template')}
                  </Button>
                )}
              </div>

              {/* Templates list */}
              {templates === undefined ? (
                <div className="flex items-center justify-center py-12">
                  <ShieldLoader message={t('documents.loadingTemplates', 'Loading templates...')} />
                </div>
              ) : templates.length === 0 ? (
                <Card>
                  <CardContent className="flex flex-col items-center justify-center py-12">
                    <FolderOpen className="h-12 w-12 text-muted-foreground/40 mb-3" />
                    <p className="text-muted-foreground">
                      {t('documents.noTemplates', 'No templates available')}
                    </p>
                    {isAdmin && (
                      <Button
                        variant="outline"
                        className="mt-3"
                        onClick={() => setShowTemplateWizard(true)}
                      >
                        <Plus className="h-4 w-4 mr-1" />
                        {t('documents.createFirstTemplate', 'Create your first template')}
                      </Button>
                    )}
                  </CardContent>
                </Card>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {templates.map((template) => (
                    <Card key={template._id} className="hover:shadow-md transition-shadow">
                      <CardContent className="pt-6">
                        <div className="flex items-start gap-3">
                          <PenTool className="h-5 w-5 text-purple-500 shrink-0" />
                          <div className="flex-1 min-w-0">
                            <h3 className="font-semibold truncate">{template.title}</h3>
                            {template.description && (
                              <p className="text-sm text-muted-foreground mt-1 line-clamp-2">
                                {template.description}
                              </p>
                            )}
                            <div className="flex items-center gap-2 mt-2">
                              <Badge variant="secondary" className="text-xs">
                                {t(
                                  `documents.template${template.category.charAt(0).toUpperCase() + template.category.slice(1)}`,
                                  template.category,
                                )}
                              </Badge>
                              <Badge variant="outline" className="text-xs">
                                {template.fields.length} {t('documents.fields', 'fields')}
                              </Badge>
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center gap-2 mt-4">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleCreateDocFromTemplate(template._id)}
                            className="flex-1"
                          >
                            <FileText className="h-4 w-4 mr-1" />
                            {t('documents.useTemplate', 'Use Template')}
                          </Button>
                          {isAdmin && (
                            <Button
                              variant="destructive"
                              size="sm"
                              onClick={() => handleDeleteTemplate(template._id)}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </div>
          ) : filteredDocuments.length === 0 ? (
            <Card>
              <CardContent className="pt-6 text-center">
                <FileText className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <h3 className="text-lg font-semibold">
                  {t('documents.noDocuments', 'No documents available')}
                </h3>
                <p className="text-sm text-muted-foreground mt-1">
                  {t('documents.noDocumentsDesc', 'Check back later or contact your admin')}
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredDocuments.map((doc) => (
                <Card
                  key={doc._id}
                  className="hover:shadow-md transition-shadow cursor-pointer"
                  onClick={() => router.push(`/documents/${doc._id}`)}
                >
                  <CardContent className="pt-6">
                    <div className="flex items-start gap-3">
                      {getCategoryIcon(doc.category)}
                      <div className="flex-1 min-w-0">
                        <h3 className="font-semibold truncate">{doc.title}</h3>
                        <p className="text-sm text-muted-foreground mt-1 line-clamp-2">
                          {doc.description ||
                            t('documents.noDescription', 'No description available')}
                        </p>
                        <div className="flex items-center gap-4 mt-3 text-xs text-muted-foreground">
                          <span>{doc.uploaderName}</span>
                          <span>{formatDate(doc.createdAt)}</span>
                          {doc.fileSize && <span>{formatFileSize(doc.fileSize)}</span>}
                        </div>
                        <div className="flex items-center gap-2 mt-3">
                          {doc.isMandatory && (
                            <span className="px-2 py-0.5 rounded-full bg-red-100 text-red-700 text-xs font-medium">
                              {t('documents.mandatory', 'Mandatory')}
                            </span>
                          )}
                          {!doc.isPublished && (
                            <span className="px-2 py-0.5 rounded-full bg-yellow-100 text-yellow-700 text-xs font-medium">
                              {t('documents.unpublished', 'Unpublished')}
                            </span>
                          )}
                          {isAcknowledged(doc._id) && (
                            <span className="px-2 py-0.5 rounded-full bg-green-100 text-green-700 text-xs font-medium">
                              {t('documents.acknowledged', 'Acknowledged')}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 mt-4">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleViewDocument(doc);
                        }}
                        className="flex-1"
                      >
                        <Eye className="h-4 w-4 mr-1" />
                        {t('documents.view', 'View')}
                      </Button>
                      {isAdmin && !doc.isPublished && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={(e) => {
                            e.stopPropagation();
                            handlePublishDocument(doc._id);
                          }}
                        >
                          {t('documents.publish', 'Publish')}
                        </Button>
                      )}
                      {isAdmin && (
                        <Button
                          variant="destructive"
                          size="sm"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDeleteDocument(doc._id);
                          }}
                        >
                          {t('common.delete', 'Delete')}
                        </Button>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Upload Wizard */}
      {showUploadWizard && (
        <DocumentUploadWizard
          onClose={() => {
            setShowUploadWizard(false);
            setCreateDocFromTemplate(null);
          }}
          onSuccess={handleWizardSuccess}
          templateId={createDocFromTemplate || undefined}
        />
      )}

      {/* Template Wizard */}
      {showTemplateWizard && (
        <DocumentTemplateWizard
          open={showTemplateWizard}
          onClose={() => setShowTemplateWizard(false)}
          onSuccess={handleTemplateSuccess}
        />
      )}
    </div>
  );
}

/**
 * Block Time Wizard - Пошаговая форма блокировки времени водителя
 * Использует универсальный Wizard компонент
 */

'use client';

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Wizard, WizardStep } from '@/components/ui/wizard';
import { CardSelectionStep, TextInputStep } from '@/components/ui/wizard-step-components';
import { Calendar, Clock, FileText } from 'lucide-react';
import { useMutation } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { toast } from 'sonner';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';

interface BlockTimeWizardProps {
  driverId: Id<'drivers'>;
  organizationId: Id<'organizations'>;
  onComplete?: () => void;
  onCancel?: () => void;
}

export function BlockTimeWizard({
  driverId,
  organizationId,
  onComplete,
  onCancel,
}: BlockTimeWizardProps) {
  const { t } = useTranslation();
  const blockTimeOff = useMutation(api.drivers.driver_operations.blockTimeOff);

  const [wizardData, setWizardData] = useState<Record<string, any>>({});

  const updateStepData = (key: string, value: string | number | boolean | null) => {
    setWizardData((prev) => ({ ...prev, [key]: value }));
  };

  const steps: WizardStep[] = [
    {
      id: 'type',
      title: t('driverCalendar.wizardSteps.type.title'),
      description: t('driverCalendar.wizardSteps.type.description'),
      icon: <Calendar className="w-5 h-5" />,
      content: (
        <CardSelectionStep
          stepData={wizardData}
          updateStepData={updateStepData}
          field="type"
          label={t('driverCalendar.type')}
          options={[
            {
              value: 'vacation',
              title: t('driverCalendar.vacation'),
              description: '',
              icon: <Calendar className="w-6 h-6" />,
              color: 'bg-blue-500/10 text-blue-600',
            },
            {
              value: 'sick',
              title: t('driverCalendar.sickLeave'),
              description: '',
              icon: <Clock className="w-6 h-6" />,
              color: 'bg-red-500/10 text-red-600',
            },
            {
              value: 'personal',
              title: t('driverCalendar.personal'),
              description: '',
              icon: <FileText className="w-6 h-6" />,
              color: 'bg-green-500/10 text-green-600',
            },
          ]}
          columns={3}
          required
        />
      ),
    },
    {
      id: 'datetime',
      title: t('driverCalendar.wizardSteps.datetime.title'),
      description: t('driverCalendar.wizardSteps.datetime.description'),
      icon: <Clock className="w-5 h-5" />,
      content: (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="startTime">{t('driverCalendar.startTime')}</Label>
            <Input
              id="startTime"
              type="datetime-local"
              value={String(wizardData.startTime || '')}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                updateStepData('startTime', e.target.value)
              }
              className="bg-(--background) border-(--border) text-(--text-primary)"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="endTime">{t('driverCalendar.endTime')}</Label>
            <Input
              id="endTime"
              type="datetime-local"
              value={String(wizardData.endTime || '')}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                updateStepData('endTime', e.target.value)
              }
              className="bg-(--background) border-(--border) text-(--text-primary)"
            />
          </div>
          <TextInputStep
            stepData={wizardData}
            updateStepData={updateStepData}
            field="reason"
            label={t('driverCalendar.reason')}
            placeholder={t('driverCalendar.enterReason')}
            required
          />
        </div>
      ),
    },
  ];

  const handleSubmit = async (
    data: Record<string, string | number | boolean | string[] | null>,
  ) => {
    try {
      const mergedData = { ...wizardData, ...data };

      const type = mergedData.type as string;
      const startTimeStr = mergedData.startTime as string;
      const endTimeStr = mergedData.endTime as string;
      const reason = mergedData.reason as string;

      if (!type || !startTimeStr || !endTimeStr || !reason) {
        toast.error(t('toasts.pleaseFillAllFields'));
        return;
      }

      const startTime = new Date(startTimeStr).getTime();
      const endTime = new Date(endTimeStr).getTime();

      if (isNaN(startTime) || isNaN(endTime)) {
        toast.error(t('driverCalendar.failedToBlockTime'));
        return;
      }

      if (endTime <= startTime) {
        toast.error('End time must be after start time');
        return;
      }

      await blockTimeOff({
        driverId,
        organizationId,
        startTime,
        endTime,
        type: type as 'vacation' | 'sick' | 'personal',
        reason,
      });

      toast.success(t('toasts.timeBlockedSuccess'));
      onComplete?.();
    } catch (error) {
      toast.error(t('driverCalendar.failedToBlockTime'));
      console.error(error);
    }
  };

  return (
    <Wizard
      steps={steps}
      onComplete={handleSubmit}
      onCancel={onCancel}
      submitLabel={t('driverCalendar.blockTimeBtn')}
      cancelLabel={t('actions.cancel')}
    />
  );
}

