              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2"
            >
              <span>{nav.icon}</span>
              <span className="flex-1">{nav.name}</span>
              <ExternalLink className="w-3 h-3 opacity-50" />
            </a>
