function NavigatorButtons({
  pickupCoords,
  dropoffCoords,
  pickupLabel,
  dropoffLabel,
}: {
  pickupCoords?: Location;
  dropoffCoords?: Location;
  pickupLabel?: string;
  dropoffLabel?: string;
