/**
 * Driver Statistics Component
 * Shows weekly/monthly stats, popular routes, and trip history
 */

'use client';

import React, { useMemo } from 'react';
import { useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { useTranslation } from 'react-i18next';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { TrendingUp, MapPin, Clock, Calendar, Download, FileText, BarChart3 } from 'lucide-react';
import { exportTripsToExcel } from '@/lib/exportDriversToExcel';
import { exportTripsToPDF } from '@/lib/exportDriversToPDF';

interface DriverStatsCardProps {
  driverId: Id<'drivers'>;
  organizationId: Id<'organizations'>;
}

export function DriverStatsCard({ driverId, organizationId }: DriverStatsCardProps) {
  const { t, i18n } = useTranslation(['drivers', 'common']);
  const [period, setPeriod] = React.useState<'week' | 'month' | 'year'>('month');

  const stats = useQuery(api.drivers.requests_queries.getDriverStats, { driverId, period });

  // Calculate time range with useMemo to prevent infinite re-renders
  const timeRange = useMemo(() => {
    const now = Date.now();
    const days = period === 'week' ? 7 : period === 'month' ? 30 : 365;
    return {
      startTime: now - days * 24 * 60 * 60 * 1000,
      endTime: now,
    };
  }, [period]);

  const schedules = useQuery(
    api.drivers.queries.getDriverSchedule,
    driverId
      ? {
          driverId,
          startTime: timeRange.startTime,
          endTime: timeRange.endTime,
        }
      : 'skip',
  );

  const handleExportExcel = () => {
    if (!schedules) return;
    const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';

    const trips = schedules
      .filter((s) => s.type === 'trip' && s.status === 'completed')
      .map((s) => ({
        date: new Date(s.startTime).toLocaleDateString(locale),
        driver: s.userName || t('common.unknownUser', 'Unknown'),
        passenger: s.userName || t('common.unknownUser', 'Unknown'),
        from: s.tripInfo?.from || 'N/A',
        to: s.tripInfo?.to || 'N/A',
        purpose: s.tripInfo?.purpose || 'N/A',
        distanceKm: s.tripInfo?.distanceKm || 0,
        durationMin: s.tripInfo?.durationMinutes || 0,
        status: s.status,
      }));

    exportTripsToExcel(trips, `driver-trips-${period}.xlsx`);
  };

  const handleExportPDF = () => {
    if (!schedules || !stats) return;
    const locale = i18n.language === 'ru' ? 'ru-RU' : i18n.language === 'hy' ? 'hy-AM' : 'en-US';

    const trips = schedules
      .filter((s) => s.type === 'trip' && s.status === 'completed')
      .map((s) => ({
        date: new Date(s.startTime).toLocaleDateString(locale),
        driver: s.userName || t('common.unknownUser', 'Unknown'),
        passenger: s.userName || t('common.unknownUser', 'Unknown'),
        from: s.tripInfo?.from || 'N/A',
        to: s.tripInfo?.to || 'N/A',
        purpose: s.tripInfo?.purpose || 'N/A',
        distanceKm: s.tripInfo?.distanceKm || 0,
        durationMin: s.tripInfo?.durationMinutes || 0,
        status: s.status,
      }));

    exportTripsToPDF(
      trips,
      {
        totalTrips: stats.totalTrips,
        totalDistance: 0, // TODO: Add distance tracking to schema
        totalDuration: stats.totalWorkedHours * 60,
        period:
          period === 'week'
            ? t('driver.lastWeek', 'Last Week')
            : period === 'month'
              ? t('driver.lastMonth', 'Last Month')
              : t('driver.lastYear', 'Last Year'),
      },
      `driver-report-${period}.pdf`,
    );
  };

  if (!stats) {
    return null;
  }

  return (
    <div className="space-y-3 sm:space-y-4">
      {/* Period Selector & Export */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 py-4">
        <div className="flex gap-2 w-full sm:w-auto">
          <Button
            variant={period === 'week' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setPeriod('week')}
            className="flex-1 sm:flex-none text-xs"
          >
            {t('driver.week', 'Week')}
          </Button>
          <Button
            variant={period === 'month' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setPeriod('month')}
            className="flex-1 sm:flex-none text-xs"
          >
            {t('driver.month', 'Month')}
          </Button>
          <Button
            variant={period === 'year' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setPeriod('year')}
            className="flex-1 sm:flex-none text-xs"
          >
            {t('driver.year', 'Year')}
          </Button>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <Button
            variant="secondary"
            size="sm"
            onClick={handleExportExcel}
            className="flex-1 sm:flex-none text-xs"
          >
            <Download className="w-3.5 h-3.5 sm:w-4 sm:h-4 mr-1.5 sm:mr-2" />
            Excel
          </Button>
          <Button
            variant="secondary"
            size="sm"
            onClick={handleExportPDF}
            className="flex-1 sm:flex-none text-xs"
          >
            <FileText className="w-3.5 h-3.5 sm:w-4 sm:h-4 mr-1.5 sm:mr-2" />
            PDF
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 gap-2 sm:gap-3">
        <Card variant="elevated">
          <CardHeader className="flex flex-row items-center justify-between pb-2 px-3 py-2">
            <h3 className="text-xs sm:text-sm font-medium text-(--text-muted)">
              {t('driver.totalTrips', 'Total Trips')}
            </h3>
            <TrendingUp className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-(--primary)" />
          </CardHeader>
          <CardContent className="px-3 py-2 pb-3">
            <div className="text-xl sm:text-2xl font-bold text-(--text-primary)">
              {stats.totalTrips}
            </div>
          </CardContent>
        </Card>
        <Card variant="elevated">
          <CardHeader className="flex flex-row items-center justify-between pb-2 px-3 py-2">
            <h3 className="text-xs sm:text-sm font-medium text-(--text-muted)">
              {t('driver.totalDistance', 'Total Distance')}
            </h3>
            <MapPin className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-(--warning)" />
          </CardHeader>
          <CardContent className="px-3 py-2 pb-3">
            <div className="text-xl sm:text-2xl font-bold text-(--text-primary)">N/A</div>
            <p className="text-[10px] sm:text-xs text-(--text-muted) mt-1">
              {t('driver.distanceTrackingSoon')}
            </p>
          </CardContent>
        </Card>
        <Card variant="elevated">
          <CardHeader className="flex flex-row items-center justify-between pb-2 px-3 py-2">
            <h3 className="text-xs sm:text-sm font-medium text-(--text-muted)">
              {t('driver.totalDuration', 'Total Duration')}
            </h3>
            <Clock className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-(--success)" />
          </CardHeader>
          <CardContent className="px-3 py-2 pb-3">
            <div className="text-xl sm:text-2xl font-bold text-(--text-primary)">
              {Math.round(stats.totalWorkedHours * 60)} {t('driver.min', 'min')}
            </div>
          </CardContent>
        </Card>
        <Card variant="elevated">
          <CardHeader className="flex flex-row items-center justify-between pb-2 px-3 py-2">
            <h3 className="text-xs sm:text-sm font-medium text-(--text-muted)">
              {t('driver.avgPerTrip', 'Avg per Trip')}
            </h3>
            <BarChart3 className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-(--info)" />
          </CardHeader>
          <CardContent className="px-3 py-2 pb-3">
            <div className="text-xl sm:text-2xl font-bold text-(--text-primary)">
              {stats.totalTrips > 0
                ? ((stats.totalWorkedHours * 60) / stats.totalTrips).toFixed(0)
                : 0}{' '}
              {t('driver.min', 'min')}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Popular Routes — coming soon */}
    </div>
  );
}

'use client';

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { MapPin, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import { ShieldLoader } from '@/components/ui/ShieldLoader';

interface PlaceSuggestion {
  display_name: string;
  lat: string;
  lon: string;
  type: string;
  address?: Record<string, string>;
}

interface PlaceAutocompleteProps {
  value: string;
  onChange: (value: string) => void;
  onSelect: (place: { address: string; lat: number; lng: number }) => void;
  placeholder?: string;
  className?: string;
  label?: string;
}

export function PlaceAutocomplete({
  value,
  onChange,
  onSelect,
  placeholder = 'Search for a place...',
  className,
}: PlaceAutocompleteProps) {
  const [suggestions, setSuggestions] = useState<PlaceSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const abortRef = useRef<AbortController | undefined>(undefined);

  // Fetch suggestions from Nominatim
  const fetchSuggestions = useCallback(async (query: string) => {
    if (query.length < 2) {
      setSuggestions([]);
      setIsOpen(false);
      return;
    }

    // Abort previous request
    if (abortRef.current) {
      abortRef.current.abort();
    }
    abortRef.current = new AbortController();

    setIsLoading(true);
    try {
      const res = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=5&addressdetails=1&accept-language=en,ru`,
        {
          signal: abortRef.current.signal,
          headers: { 'User-Agent': 'OfficeApp/1.0' },
        },
      );
      const data: PlaceSuggestion[] = await res.json();
      setSuggestions(data);
      setIsOpen(data.length > 0);
      setHighlightedIndex(-1);
    } catch (e: any) {
      if (e.name !== 'AbortError') {
        setSuggestions([]);
        setIsOpen(false);
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Debounced search
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    onChange(val);

    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => fetchSuggestions(val), 350);
  };

  // Select a suggestion
  const handleSelect = (suggestion: PlaceSuggestion) => {
    const shortName = formatAddress(suggestion);
    onChange(shortName);
    onSelect({
      address: shortName,
      lat: parseFloat(suggestion.lat),
      lng: parseFloat(suggestion.lon),
    });
    setSuggestions([]);
    setIsOpen(false);
    inputRef.current?.blur();
  };

  // Format address to shorter form
  const formatAddress = (s: PlaceSuggestion): string => {
    const addr = s.address;
    if (!addr) return s.display_name;

    const parts: string[] = [];
    // Try to build a concise address
    if (addr.road || addr.pedestrian || addr.street) {
      parts.push(addr.road || addr.pedestrian || addr.street || '');
      if (addr.house_number) parts[0] = `${parts[0]} ${addr.house_number}`;
    }
    if (addr.city || addr.town || addr.village) {
      parts.push(addr.city || addr.town || addr.village || '');
    }
    if (addr.country) {
      parts.push(addr.country);
    }

    if (parts.length === 0) return s.display_name;
    // If the place has a specific name (like a business/airport), prepend it
    const name = addr.aeroway || addr.amenity || addr.tourism || addr.building || addr.shop;
    if (name) {
      return `${name}, ${parts.join(', ')}`;
    }
    return parts.join(', ');
  };

  // Keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen || suggestions.length === 0) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlightedIndex((prev) => (prev < suggestions.length - 1 ? prev + 1 : 0));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : suggestions.length - 1));
    } else if (e.key === 'Enter' && highlightedIndex >= 0) {
      e.preventDefault();
      handleSelect(suggestions[highlightedIndex]!);
    } else if (e.key === 'Escape') {
      setIsOpen(false);
    }
  };

  // Close on outside click
  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  // Cleanup
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  const clearInput = () => {
    onChange('');
    setSuggestions([]);
    setIsOpen(false);
    inputRef.current?.focus();
  };

  return (
    <div ref={containerRef} className={cn('relative', className)}>
      <div className="relative flex items-center">
        <MapPin className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-(--text-muted) pointer-events-none" />
        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (suggestions.length > 0) setIsOpen(true);
          }}
          placeholder={placeholder}
          className={cn(
            'flex h-9 w-full rounded-lg border border-(--input-border) bg-(--input) pl-8 py-1 text-sm text-(--text-primary) shadow-sm transition-colors',
            value || isLoading ? 'pr-9' : 'pr-3',
            'placeholder:text-(--text-muted)',
            'focus:outline-none focus:ring-2 focus:ring-(--ring) focus:border-(--primary)',
          )}
        />
        {isLoading ? (
          <div className="absolute right-0 top-0 bottom-0 flex items-center pr-2.5 pl-3 bg-linear-to-l from-(--input) via-(--input) to-transparent pointer-events-none">
            <ShieldLoader size="xs" variant="inline" />
          </div>
        ) : value ? (
          <div className="absolute right-0 top-0 bottom-0 flex items-center pr-1.5 pl-4 bg-linear-to-l from-(--input) from-60% to-transparent">
            <button
              type="button"
              onClick={clearInput}
              className="p-1 rounded-full text-(--text-muted) hover:text-(--text-primary) hover:bg-(--muted) transition-colors"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          </div>
        ) : null}
      </div>

      {/* Dropdown */}
      {isOpen && suggestions.length > 0 && (
        <div className="absolute z-50 mt-1 w-full rounded-lg border border-(--input-border) bg-(--card) shadow-lg overflow-hidden">
          {suggestions.map((s, i) => (
            <button
              key={`${s.lat}-${s.lon}`}
              type="button"
              onClick={() => handleSelect(s)}
              className={cn(
                'w-full text-left px-3 py-2.5 text-sm flex items-start gap-2.5 transition-colors border-b border-(--input-border) last:border-b-0',
                i === highlightedIndex
                  ? 'bg-(--primary)/10 text-(--primary)'
                  : 'text-(--text-primary) hover:bg-(--muted)',
              )}
            >
              <MapPin className="h-4 w-4 mt-0.5 shrink-0 text-(--text-muted)" />
              <div className="min-w-0">
                <div className="font-medium truncate">{formatAddress(s)}</div>
                {s.display_name !== formatAddress(s) && (
                  <div className="text-xs text-(--text-muted) truncate mt-0.5">
                    {s.display_name}
                  </div>
                )}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

﻿/**
 * Request Driver Wizard - Пошаговая форма заказа водителя
 * Использует универсальный Wizard компонент
 */

'use client';

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Wizard, WizardStep } from '@/components/ui/wizard';
import {
  TextInputStep,
  TextareaStep,
  CardSelectionStep,
} from '@/components/ui/wizard-step-components';
import { Car, MapPin, Clock, Calendar, Users } from 'lucide-react';
import { useMutation, useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { toast } from 'sonner';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useAuthStore } from '@/store/useAuthStore';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import { useOptimisticDriverRequest } from '@/hooks/useOptimisticActions';

interface RequestDriverWizardProps {
  userId: Id<'users'>;
  onComplete?: () => void;
  onCancel?: () => void;
  preselectedDriverId?: string;
}

export function RequestDriverWizard({
  userId,
  onComplete,
  onCancel,
  preselectedDriverId,
}: RequestDriverWizardProps) {
  const { t } = useTranslation();
  const { requestOptimistic } = useOptimisticDriverRequest();
  const { user } = useAuthStore();
  const selectedOrgId = useSelectedOrganization();
  const organizationId = (selectedOrgId ?? user?.organizationId) as Id<'organizations'> | undefined;
  const drivers = useQuery(
    api.drivers.queries.getAvailableDrivers,
    organizationId ? { organizationId } : 'skip',
  );

  const [wizardData, setWizardData] = useState<Record<string, string | number | boolean | null>>(
    {},
  );

  const updateStepData = (key: string, value: string | number | boolean | null) => {
    setWizardData((prev) => ({ ...prev, [key]: value }));
  };

  const steps: WizardStep[] = [
    {
      id: 'type',
      title: t('driverWizard.steps.type.title'),
      description: t('driverWizard.steps.type.description'),
      icon: <Car className="w-5 h-5" />,
      content: (
        <CardSelectionStep
          stepData={wizardData}
          updateStepData={updateStepData}
          field="tripCategory"
          label={t('driverWizard.steps.type.typeLabel')}
          options={[
            {
              value: 'airport',
              title: t('driverWizard.types.airport'),
              description: t('driverWizard.types.airportDesc'),
              icon: <Calendar className="w-6 h-6" />,
              color: 'bg-blue-500/10 text-blue-600',
            },
            {
              value: 'office_transfer',
              title: t('driverWizard.types.officeTransfer'),
              description: t('driverWizard.types.officeTransferDesc'),
              icon: <MapPin className="w-6 h-6" />,
              color: 'bg-green-500/10 text-green-600',
            },
            {
              value: 'client_meeting',
              title: t('driverWizard.types.clientMeeting'),
              description: t('driverWizard.types.clientMeetingDesc'),
              icon: <Users className="w-6 h-6" />,
              color: 'bg-purple-500/10 text-purple-600',
            },
          ]}
          columns={3}
          required
        />
      ),
    },
    {
      id: 'route',
      title: t('driverWizard.steps.route.title'),
      description: t('driverWizard.steps.route.description'),
      icon: <MapPin className="w-5 h-5" />,
      content: (
        <div className="space-y-4">
          <TextInputStep
            stepData={wizardData}
            updateStepData={updateStepData}
            field="from"
            label={t('driverWizard.steps.route.fromLabel')}
            placeholder={t('driverWizard.steps.route.fromPlaceholder')}
            required
          />
          <TextInputStep
            stepData={wizardData}
            updateStepData={updateStepData}
            field="to"
            label={t('driverWizard.steps.route.toLabel')}
            placeholder={t('driverWizard.steps.route.toPlaceholder')}
            required
          />
          <TextInputStep
            stepData={wizardData}
            updateStepData={updateStepData}
            field="purpose"
            label={t('driverWizard.steps.route.purposeLabel')}
            placeholder={t('driverWizard.steps.route.purposePlaceholder')}
            required
          />
          <div className="space-y-2">
            <Label htmlFor="passengerCount">
              {t('driverWizard.steps.route.passengerCountLabel')}
            </Label>
            <Input
              id="passengerCount"
              type="number"
              min="1"
              max="10"
              value={String(wizardData.passengerCount || '1')}
              onChange={(e) => updateStepData('passengerCount', parseInt(e.target.value) || 1)}
              className="bg-(--background) border-(--border) text-(--text-primary)"
            />
          </div>
        </div>
      ),
    },
    {
      id: 'driver',
      title: t('driverWizard.steps.driver.title'),
      description: t('driverWizard.steps.driver.description'),
      icon: <Car className="w-5 h-5" />,
      content:
        drivers && drivers.length > 0 ? (
          <CardSelectionStep
            stepData={wizardData}
            updateStepData={updateStepData}
            field="driverId"
            label={t('driverWizard.steps.driver.selectLabel')}
            options={drivers
              .filter((driver) => driver !== null)
              .map((driver) => ({
                value: driver._id,
                title: driver.userName,
                description: driver.userPosition || '',
                icon: <Car className="w-6 h-6" />,
                color: 'bg-blue-500/10 text-blue-600',
              }))}
            columns={2}
            required
          />
        ) : (
          <div className="text-center py-8 text-(--text-muted)">
            {t('driverWizard.steps.driver.noDrivers')}
          </div>
        ),
    },
    {
      id: 'datetime',
      title: t('driverWizard.steps.datetime.title'),
      description: t('driverWizard.steps.datetime.description'),
      icon: <Clock className="w-5 h-5" />,
      content: (
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <TextInputStep
              stepData={wizardData}
              updateStepData={updateStepData}
              field="date"
              label={t('driverWizard.steps.datetime.dateLabel')}
              type="text"
              placeholder="YYYY-MM-DD"
              required
            />
            <TextInputStep
              stepData={wizardData}
              updateStepData={updateStepData}
              field="time"
              label={t('driverWizard.steps.datetime.timeLabel')}
              type="text"
              placeholder="HH:MM"
              required
            />
          </div>
          <TextareaStep
            stepData={wizardData}
            updateStepData={updateStepData}
            field="notes"
            label={t('driverWizard.steps.datetime.notesLabel')}
            placeholder={t('driverWizard.steps.datetime.notesPlaceholder')}
            rows={3}
          />
        </div>
      ),
    },
  ];

  const handleSubmit = async (
    data: Record<string, string | number | boolean | string[] | null>,
  ) => {
    try {
      const mergedData = { ...wizardData, ...data };

      if (!organizationId) {
        toast.error(t('driverWizard.toast.noOrg'));
        return;
      }

      const dateStr = String(mergedData.date || '').trim();
      const timeStr = String(mergedData.time || '').trim();

      if (!dateStr || !timeStr) {
        toast.error(
          t('driverWizard.toast.fillDateAndTime', 'Please fill in both date and time fields.'),
        );
        return;
      }

      const parsedDate = new Date(`${dateStr}T${timeStr}:00`);
      const startTime = parsedDate.getTime();

      if (isNaN(startTime)) {
        toast.error(
          t(
            'driverWizard.toast.invalidDateTime',
            'Invalid date or time. Please use YYYY-MM-DD and HH:MM formats.',
          ),
        );
        return;
      }

      const endTime = startTime + 3600000;

      const result = await requestOptimistic(
        organizationId,
        userId,
        mergedData.driverId as Id<'drivers'>,
        startTime,
        endTime,
        {
          from: String(mergedData.from),
          to: String(mergedData.to),
          purpose: String(mergedData.purpose),
          passengerCount: Number(mergedData.passengerCount) || 1,
          notes: mergedData.notes ? String(mergedData.notes) : undefined,
        },
        mergedData.tripCategory as
          | 'client_meeting'
          | 'airport'
          | 'office_transfer'
          | 'emergency'
          | 'team_event'
          | 'personal',
      );

      if (result?.error) {
        toast.error(result.error.message);
        return;
      }

      toast.success(t('driverWizard.toast.success'));
      onComplete?.();
    } catch (error) {
      toast.error(t('driverWizard.toast.error'));
      console.error(error);
    }
  };

  if (drivers === undefined)
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin h-6 w-6 border-2 border-primary border-t-transparent rounded-full" />
      </div>
    );

  return (
    <Wizard
      steps={steps}
      onComplete={handleSubmit}
      onCancel={onCancel}
      submitLabel={t('driverWizard.submit')}
      cancelLabel={t('actions.cancel')}
    />
  );
}

'use client';

import React from 'react';
import { useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { useTranslation } from 'react-i18next';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { History, Clock, TrendingUp, CheckCircle, Coffee } from 'lucide-react';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';

interface ShiftHistoryProps {
  driverId: Id<'drivers'>;
}

export function ShiftHistory({ driverId }: ShiftHistoryProps) {
  const { t, i18n } = useTranslation(['drivers', 'common']);
  const dfLocale = i18n.language === 'ru' ? ru : i18n.language === 'hy' ? hy : enUS;
  const shifts = useQuery(api.drivers.shifts_mutations.getShiftHistory, { driverId, limit: 10 });

  if (!shifts) return null;

  const formatDuration = (hours: number | null) => {
    if (!hours) return '-';
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    return `${h}${t('driver.shift.h', 'h')} ${m}${t('driver.shift.m', 'm')}`;
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'success' | 'primary' | 'warning' | 'outline'> = {
      completed: 'success',
      active: 'primary',
      paused: 'warning',
      overtime: 'outline',
    };

    const labels: Record<string, string> = {
      completed: t('driver.shift.completed', 'Completed'),
      active: t('driver.shift.active', 'Active'),
      paused: t('driver.shift.paused', 'Paused'),
      overtime: t('driver.shift.overtime', 'Overtime'),
    };

    return (
      <Badge variant={variants[status] || 'outline'}>
        {status === 'completed' && <CheckCircle className="w-3 h-3 mr-1" />}
        {status === 'active' && (
          <span className="w-2 h-2 rounded-full bg-(--success) mr-1 animate-pulse" />
        )}
        {status === 'paused' && <Coffee className="w-3 h-3 mr-1" />}
        {labels[status] || status}
      </Badge>
    );
  };

  return (
    <Card>
      <CardHeader className="px-4 py-3 sm:px-6 sm:py-4">
        <CardTitle className="text-base sm:text-lg flex items-center gap-2">
          <History className="w-4 h-4 sm:w-5 sm:h-5" />
          {t('driver.shift.history', 'Shift History')}
        </CardTitle>
      </CardHeader>
      <CardContent className="px-4 py-3 sm:px-6 sm:py-4">
        {shifts.length === 0 ? (
          <div className="text-center py-6 sm:py-8 text-muted-foreground">
            <History className="w-10 h-10 sm:w-12 sm:h-12 mx-auto mb-3 sm:mb-4 opacity-50" />
            <p className="text-sm">{t('driver.shift.noHistory', 'No shift history yet')}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {shifts.map((shift) => (
              <div
                key={shift._id}
                className="p-3 sm:p-4 border rounded-lg hover:bg-muted/50 transition-colors"
              >
                <div className="flex flex-col sm:flex-row items-start justify-between gap-2 mb-3">
                  <div className="flex items-center gap-2 sm:gap-3 w-full sm:w-auto">
                    <div className="p-2 bg-primary/10 rounded-lg">
                      <Clock className="w-4 h-4 sm:w-5 sm:h-5 text-primary" />
                    </div>
                    <div>
                      <p className="font-semibold text-sm sm:text-base">
                        {format(shift.startTime, 'MMM dd, yyyy', { locale: dfLocale })}
                      </p>
                      <p className="text-xs sm:text-sm text-muted-foreground">
                        {format(shift.startTime, 'HH:mm', { locale: dfLocale })} -{' '}
                        {shift.endTime
                          ? format(shift.endTime, 'HH:mm', { locale: dfLocale })
                          : t('driver.shift.now', 'Now')}
                      </p>
                    </div>
                  </div>
                  {getStatusBadge(shift.status)}
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs sm:text-sm">
                  <div>
                    <p className="text-[10px] sm:text-xs text-muted-foreground">
                      {t('driver.shift.duration', 'Duration')}
                    </p>
                    <p className="font-medium text-xs sm:text-sm">
                      {formatDuration(shift.duration)}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] sm:text-xs text-muted-foreground">
                      {t('driver.shift.trips', 'Trips')}
                    </p>
                    <p className="font-medium text-xs sm:text-sm">{shift.tripsCompleted}</p>
                  </div>
                  <div>
                    <p className="text-[10px] sm:text-xs text-muted-foreground">
                      {t('driver.shift.distance', 'Distance')}
                    </p>
                    <p className="font-medium text-xs sm:text-sm">
                      {(shift.totalDistance || 0).toFixed(1)} {t('driver.shift.km', 'km')}
                    </p>
                  </div>
                  {shift.overtimeHours && shift.overtimeHours > 0 && (
                    <div>
                      <p className="text-[10px] sm:text-xs text-muted-foreground">
                        {t('driver.shift.overtime', 'Overtime')}
                      </p>
                      <p className="font-medium text-orange-600 text-xs sm:text-sm">
                        {shift.overtimeHours.toFixed(1)}
                        {t('driver.shift.h', 'h')}
                      </p>
                    </div>
                  )}
                </div>

                {shift.driverNotes && (
                  <div className="mt-3 p-2 bg-muted/50 rounded text-xs sm:text-sm">
                    <p className="text-[10px] sm:text-xs text-muted-foreground mb-1">
                      📝 {t('driver.shift.notes', 'Notes')}
                    </p>
                    <p>{shift.driverNotes}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { useState } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import {
  Car,
  User,
  Settings,
  Calendar,
  CheckCircle2,
  X,
  ArrowRight,
  Shield,
  Clock,
  Phone,
  Mail,
  type LucideIcon,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import type { TFunction } from 'i18next';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';

interface RegisterDriverModalProps {
  userName: string;
  userEmail: string;
  userPhone?: string;
  onSubmit: (data: {
    vehicleMake: string;
    vehicleModel: string;
    vehicleYear: string;
    vehicleColor: string;
    licensePlate: string;
    maxPassengers: number;
    vehicleType: string;
    notes?: string;
    availability: {
      monday: boolean;
      tuesday: boolean;
      wednesday: boolean;
      thursday: boolean;
      friday: boolean;
      saturday: boolean;
      sunday: boolean;
    };
  }) => Promise<void>;
  onClose: () => void;
}

const steps = ['personal', 'vehicle', 'schedule', 'confirm'];

const stepIcons: LucideIcon[] = [User, Car, Calendar, CheckCircle2];

const getVehicleTypes = (t: TFunction) => [
  { id: 'sedan', label: t('driverWizard.sedan', 'Sedan'), icon: '🚗' },
  { id: 'suv', label: t('driverWizard.suv', 'SUV'), icon: '🚙' },
  { id: 'van', label: t('driverWizard.van', 'Van'), icon: '🚐' },
  { id: 'luxury', label: t('driverWizard.luxury', 'Luxury'), icon: '✨' },
];

export function RegisterDriverModal({
  userName,
  userEmail,
  userPhone,
  onSubmit,
  onClose,
}: RegisterDriverModalProps) {
  const { t } = useTranslation();
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState({
    vehicleMake: '',
    vehicleModel: '',
    vehicleYear: '',
    vehicleColor: '',
    licensePlate: '',
    maxPassengers: 4,
    vehicleType: 'sedan',
    notes: '',
    availability: {
      monday: true,
      tuesday: true,
      wednesday: true,
      thursday: true,
      friday: true,
      saturday: false,
      sunday: false,
    },
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const days = [
    'monday',
    'tuesday',
    'wednesday',
    'thursday',
    'friday',
    'saturday',
    'sunday',
  ] as const;
  const dayLabels = {
    monday: t('driver.monday', 'Mon'),
    tuesday: t('driver.tuesday', 'Tue'),
    wednesday: t('driver.wednesday', 'Wed'),
    thursday: t('driver.thursday', 'Thu'),
    friday: t('driver.friday', 'Fri'),
    saturday: t('driver.saturday', 'Sat'),
    sunday: t('driver.sunday', 'Sun'),
  };

  const canProceed = () => {
    switch (currentStep) {
      case 0:
        return true; // Personal info is pre-filled
      case 1:
        return (
          formData.vehicleMake.trim() &&
          formData.vehicleModel.trim() &&
          formData.licensePlate.trim()
        );
      case 2:
        return Object.values(formData.availability).some((v) => v);
      default:
        return true;
    }
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      await onSubmit(formData);
      onClose();
    } catch (error) {
      console.error('Failed to register:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const nextStep = () => {
    if (canProceed() && currentStep < steps.length - 1) {
      setCurrentStep((s) => s + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep((s) => s - 1);
    }
  };

  return createPortal(
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ opacity: 0, scale: 0.9, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.9, y: 20 }}
        transition={{ duration: 0.3, ease: 'easeOut' }}
        className="w-full max-w-2xl bg-(--card) rounded-2xl border border-(--border) shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="relative p-6 btn-gradient rounded-t-2xl">
          <button
            onClick={onClose}
            className="absolute top-4 right-4 p-2 rounded-lg bg-white/20 hover:bg-white/30 transition-colors"
          >
            <X className="w-4 h-4 text-white" />
          </button>
          <div className="flex items-center gap-3">
            <div className="p-3 bg-white/20 rounded-xl">
              <Shield className="w-6 h-6 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-white">
                {t('driver.registerAsDriver', 'Register as Driver')}
              </h2>
              <p className="text-white/80 text-sm mt-0.5">
                {t('driver.registerDesc', 'Join our driver team')}
              </p>
            </div>
          </div>
        </div>

        {/* Steps */}
        <div className="px-6 pt-6">
          <div className="flex items-center justify-between">
            {steps.map((step, idx) => {
              const Icon: LucideIcon | undefined = stepIcons[idx];
              const isCompleted = idx < currentStep;
              const isCurrent = idx === currentStep;

              return (
                <div key={step} className="flex items-center">
                  <motion.div
                    animate={{ scale: isCurrent ? 1.1 : 1 }}
                    className={`flex items-center justify-center w-10 h-10 rounded-xl transition-all duration-300 ${
                      isCompleted
                        ? 'bg-emerald-500 text-white'
                        : isCurrent
                          ? 'bg-emerald-500/20 text-emerald-500 ring-2 ring-emerald-500'
                          : 'bg-(--background-subtle) text-(--text-muted)'
                    }`}
                  >
                    {isCompleted ? (
                      <CheckCircle2 className="w-5 h-5" />
                    ) : (
                      Icon && <Icon className="w-5 h-5" />
                    )}
                  </motion.div>
                  {idx < steps.length - 1 && (
                    <div
                      className={`w-12 sm:w-20 h-0.5 mx-2 transition-colors duration-300 ${
                        idx < currentStep ? 'bg-emerald-500' : 'bg-(--border)'
                      }`}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Content */}
        <div className="p-6 max-h-[60vh] overflow-y-auto">
          <AnimatePresence mode="wait">
            {/* Step 0: Personal Info */}
            {currentStep === 0 && (
              <motion.div
                key="step-0"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-4"
              >
                <h3 className="text-lg font-semibold">
                  {t('driver.personalInfo', 'Personal Information')}
                </h3>
                <div className="space-y-3">
                  <div className="p-4 rounded-xl bg-(--background-subtle) space-y-3">
                    <div className="flex items-center gap-3">
                      <User className="w-4 h-4 text-(--primary)" />
                      <div>
                        <p className="text-xs text-(--text-muted)">
                          {t('driver.fullName', 'Full Name')}
                        </p>
                        <p className="font-medium">{userName}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <Mail className="w-4 h-4 text-(--primary)" />
                      <div>
                        <p className="text-xs text-(--text-muted)">{t('driver.email', 'Email')}</p>
                        <p className="font-medium">{userEmail}</p>
                      </div>
                    </div>
                    {userPhone && (
                      <div className="flex items-center gap-3">
                        <Phone className="w-4 h-4 text-(--primary)" />
                        <div>
                          <p className="text-xs text-(--text-muted)">
                            {t('driver.phone', 'Phone')}
                          </p>
                          <p className="font-medium">{userPhone}</p>
                        </div>
                      </div>
                    )}
                  </div>
                  <p className="text-sm text-(--text-muted)">
                    {t(
                      'driver.personalInfoDesc',
                      'Your personal information will be used for driver registration. Vehicle details are required in the next step.',
                    )}
                  </p>
                </div>
              </motion.div>
            )}

            {/* Step 1: Vehicle Info */}
            {currentStep === 1 && (
              <motion.div
                key="step-1"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-4"
              >
                <h3 className="text-lg font-semibold">
                  {t('driver.vehicleInfo', 'Vehicle Information')}
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-sm">{t('driver.make', 'Make')}</Label>
                    <Input
                      value={formData.vehicleMake}
                      onChange={(e) => setFormData((p) => ({ ...p, vehicleMake: e.target.value }))}
                      placeholder={t('driverWizard.makePlaceholder', 'Toyota')}
                      className="border-(--border) bg-(--input)"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label className="text-sm">{t('driver.model', 'Model')}</Label>
                    <Input
                      value={formData.vehicleModel}
                      onChange={(e) => setFormData((p) => ({ ...p, vehicleModel: e.target.value }))}
                      placeholder={t('driverWizard.modelPlaceholder', 'Camry')}
                      className="border-(--border) bg-(--input)"
                    />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-sm">{t('driver.year', 'Year')}</Label>
                    <Input
                      type="number"
                      value={formData.vehicleYear}
                      onChange={(e) => setFormData((p) => ({ ...p, vehicleYear: e.target.value }))}
                      placeholder={t('driverWizard.yearPlaceholder', '2024')}
                      className="border-(--border) bg-(--input)"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label className="text-sm">{t('driver.color', 'Color')}</Label>
                    <Input
                      value={formData.vehicleColor}
                      onChange={(e) => setFormData((p) => ({ ...p, vehicleColor: e.target.value }))}
                      placeholder={t('driverWizard.colorPlaceholder', 'Black')}
                      className="border-(--border) bg-(--input)"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label className="text-sm">{t('driver.licensePlate', 'License Plate')}</Label>
                  <Input
                    value={formData.licensePlate}
                    onChange={(e) =>
                      setFormData((p) => ({ ...p, licensePlate: e.target.value.toUpperCase() }))
                    }
                    placeholder={t('driverWizard.platePlaceholder', 'ABC-1234')}
                    className="border-(--border) bg-(--input) font-mono"
                  />
                </div>
                <div className="space-y-2">
                  <Label className="text-sm">{t('driver.vehicleType', 'Vehicle Type')}</Label>
                  <div className="grid grid-cols-4 gap-2">
                    {getVehicleTypes(t).map((type) => (
                      <button
                        key={type.id}
                        onClick={() => setFormData((p) => ({ ...p, vehicleType: type.id }))}
                        className={`p-3 rounded-xl border text-center transition-all duration-200 ${
                          formData.vehicleType === type.id
                            ? 'border-emerald-500 bg-emerald-500/10'
                            : 'border-(--border) bg-(--background-subtle) hover:border-(--primary)/50'
                        }`}
                      >
                        <span className="text-2xl">{type.icon}</span>
                        <p className="text-xs font-medium mt-1">{type.label}</p>
                      </button>
                    ))}
                  </div>
                </div>
                <div className="space-y-2">
                  <Label className="text-sm">{t('driver.maxPassengers', 'Max Passengers')}</Label>
                  <div className="flex items-center gap-3">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() =>
                        setFormData((p) => ({
                          ...p,
                          maxPassengers: Math.max(1, p.maxPassengers - 1),
                        }))
                      }
                    >
                      -
                    </Button>
                    <span className="text-lg font-bold w-8 text-center">
                      {formData.maxPassengers}
                    </span>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() =>
                        setFormData((p) => ({
                          ...p,
                          maxPassengers: Math.min(8, p.maxPassengers + 1),
                        }))
                      }
                    >
                      +
                    </Button>
                  </div>
                </div>
              </motion.div>
            )}

            {/* Step 2: Schedule */}
            {currentStep === 2 && (
              <motion.div
                key="step-2"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-4"
              >
                <h3 className="text-lg font-semibold">
                  {t('driver.availability', 'Availability')}
                </h3>
                <p className="text-sm text-(--text-muted)">
                  {t('driver.availabilityDesc', 'Select your available days')}
                </p>
                <div className="grid grid-cols-4 sm:grid-cols-7 gap-2">
                  {days.map((day) => (
                    <motion.button
                      key={day}
                      whileTap={{ scale: 0.95 }}
                      onClick={() =>
                        setFormData((p) => ({
                          ...p,
                          availability: { ...p.availability, [day]: !p.availability[day] },
                        }))
                      }
                      className={`p-3 rounded-xl border text-center transition-all duration-200 ${
                        formData.availability[day]
                          ? 'border-emerald-500 bg-emerald-500/10'
                          : 'border-(--border) bg-(--background-subtle)'
                      }`}
                    >
                      <Clock
                        className={`w-4 h-4 mx-auto mb-1 ${formData.availability[day] ? 'text-emerald-500' : 'text-(--text-muted)'}`}
                      />
                      <p className="text-xs font-medium">{dayLabels[day]}</p>
                    </motion.button>
                  ))}
                </div>
                <div className="space-y-2">
                  <Label className="text-sm">
                    {t('driver.notes', 'Notes')} ({t('driver.optional', 'Optional')})
                  </Label>
                  <Textarea
                    value={formData.notes}
                    onChange={(e) => setFormData((p) => ({ ...p, notes: e.target.value }))}
                    placeholder={t('driver.notesPlaceholder', 'Any additional information...')}
                    className="resize-none border-(--border) bg-(--input)"
                    rows={2}
                  />
                </div>
              </motion.div>
            )}

            {/* Step 3: Confirm */}
            {currentStep === 3 && (
              <motion.div
                key="step-3"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-4"
              >
                <h3 className="text-lg font-semibold">
                  {t('driver.confirmRegistration', 'Confirm Registration')}
                </h3>
                <div className="space-y-3">
                  <div className="p-4 rounded-xl bg-(--background-subtle) space-y-3">
                    <div className="flex items-center gap-3">
                      <User className="w-4 h-4 text-(--primary)" />
                      <div>
                        <p className="text-xs text-(--text-muted)">
                          {t('driver.driver', 'Driver')}
                        </p>
                        <p className="font-medium">{userName}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <Car className="w-4 h-4 text-(--primary)" />
                      <div>
                        <p className="text-xs text-(--text-muted)">
                          {t('driver.vehicle', 'Vehicle')}
                        </p>
                        <p className="font-medium">
                          {formData.vehicleYear} {formData.vehicleMake} {formData.vehicleModel} (
                          {formData.licensePlate})
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <Settings className="w-4 h-4 text-(--primary)" />
                      <div>
                        <p className="text-xs text-(--text-muted)">
                          {t('driver.vehicleType', 'Type')}
                        </p>
                        <Badge variant="secondary">
                          {getVehicleTypes(t).find((vt) => vt.id === formData.vehicleType)?.icon}{' '}
                          {getVehicleTypes(t).find((vt) => vt.id === formData.vehicleType)?.label}
                        </Badge>
                      </div>
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-(--background-subtle)">
                    <p className="text-xs text-(--text-muted) mb-2">
                      {t('driver.availableDays', 'Available Days')}
                    </p>
                    <div className="flex flex-wrap gap-1">
                      {days
                        .filter((d) => formData.availability[d])
                        .map((d) => (
                          <Badge key={d} variant="outline" className="text-xs">
                            {dayLabels[d]}
                          </Badge>
                        ))}
                    </div>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-(--border) bg-(--background-subtle)">
          {currentStep > 0 ? (
            <Button variant="outline" onClick={prevStep} disabled={isSubmitting}>
              {t('driver.back', 'Back')}
            </Button>
          ) : (
            <div />
          )}
          {currentStep < steps.length - 1 ? (
            <Button onClick={nextStep} disabled={!canProceed()} className="gap-2">
              {t('driver.next', 'Next')}
              <ArrowRight className="w-4 h-4" />
            </Button>
          ) : (
            <Button onClick={handleSubmit} disabled={isSubmitting} className="gap-2">
              {isSubmitting ? (
                <>{t('driver.registering', 'Registering...')}</>
              ) : (
                <>
                  <CheckCircle2 className="w-4 h-4" />
                  {t('driver.completeRegistration', 'Complete Registration')}
                </>
              )}
            </Button>
          )}
        </div>
      </motion.div>
    </motion.div>,
    document.body,
  );
}

'use client';

import { useState } from 'react';
import { createPortal } from 'react-dom';
import { motion } from '@/lib/cssMotion';
import { useTranslation } from 'react-i18next';
import { UserPlus, Search, X, User } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import type { Id } from '@/convex/_generated/dataModel';

interface DriverCandidate {
  _id: Id<'users'>;
  name: string;
  email: string;
  phone?: string;
  department?: string;
  position?: string;
}

interface SelectDriverModalProps {
  candidates: DriverCandidate[];
  onSelect: (driver: DriverCandidate) => void;
  onClose: () => void;
}

export function SelectDriverModal({ candidates, onSelect, onClose }: SelectDriverModalProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useState('');

  const filtered = candidates.filter(
    (c) =>
      c.name.toLowerCase().includes(search.toLowerCase()) ||
      c.email.toLowerCase().includes(search.toLowerCase()) ||
      (c.department && c.department.toLowerCase().includes(search.toLowerCase())),
  );

  return createPortal(
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[999999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 20 }}
        transition={{ duration: 0.2 }}
        className="w-full max-w-lg bg-(--card) rounded-2xl border border-(--border) shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="p-6 border-b border-(--border)">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-(--primary)/10 rounded-xl">
                <UserPlus className="w-5 h-5 text-(--primary)" />
              </div>
              <div>
                <h2 className="text-lg font-semibold text-(--text-primary)">
                  {t('driver.selectDriver', 'Select Driver')}
                </h2>
                <p className="text-sm text-(--text-muted)">
                  {t('driver.selectDriverDesc', 'Choose an employee with driver role')}
                </p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="p-2 rounded-lg hover:bg-(--background-subtle) transition-colors"
            >
              <X className="w-4 h-4 text-(--text-muted)" />
            </button>
          </div>

          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-(--text-muted)" />
            <Input
              placeholder={t('common.search', 'Search by name, email, or department...')}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-10"
            />
          </div>
        </div>

        {/* List */}
        <div className="max-h-[400px] overflow-y-auto p-4 space-y-2">
          {filtered.length === 0 ? (
            <div className="text-center py-8 text-(--text-muted)">
              <User className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p className="text-sm">
                {t('driver.noDriverCandidates', 'No employees with driver role found')}
              </p>
              <p className="text-xs mt-1">
                {t('driver.createDriverFirst', 'Create an employee with driver role first')}
              </p>
            </div>
          ) : (
            filtered.map((candidate) => (
              <button
                key={candidate._id}
                onClick={() => onSelect(candidate)}
                className="w-full p-4 rounded-xl border border-(--border) bg-(--background-subtle) hover:border-(--primary) hover:bg-(--primary)/5 transition-all text-left"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-(--primary)/10 flex items-center justify-center flex-shrink-0">
                    <span className="text-sm font-semibold text-(--primary)">
                      {candidate.name
                        .split(' ')
                        .map((n) => n[0])
                        .join('')
                        .toUpperCase()
                        .slice(0, 2)}
                    </span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-(--text-primary) truncate">{candidate.name}</p>
                    <p className="text-xs text-(--text-muted) truncate">{candidate.email}</p>
                    {candidate.department && (
                      <div className="flex items-center gap-2 mt-1">
                        <Badge variant="outline" className="text-xs">
                          {candidate.department}
                        </Badge>
                        {candidate.position && (
                          <span className="text-xs text-(--text-muted)">{candidate.position}</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </button>
            ))
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-(--border) bg-(--background-subtle)">
          <p className="text-xs text-(--text-muted) text-center">
            {t('driver.driverCount', '{{count}} employees with driver role', {
              count: candidates.length,
            })}
          </p>
        </div>
      </motion.div>
    </motion.div>,
    document.body,
  );
}

'use client';

import { motion } from '@/lib/cssMotion';
import {
  Car,
  Clock,
  MapPin,
  Users,
  Star,
  Navigation2,
  MessageSquare,
  PhoneCall,
  AlertCircle,
  X,
  ExternalLink,
  ChevronDown,
} from 'lucide-react';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';
import { useTranslation } from 'react-i18next';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { useState, useRef, useEffect } from 'react';

interface TripDetailsModalProps {
  schedule: TripSchedule | null;
  currentTime: number;
  onClose: () => void;
  onRate?: (rating: number) => void;
  onReassign?: () => void;
  onMessage?: () => void;
  onCall?: () => void;
  userId: string;
  isAdmin?: boolean;
}

export interface TripSchedule {
  type: string;
  status: string;
  startTime: number;
  endTime: number;
  userName?: string;
  userAvatar?: string;
  tripInfo?: {
    from?: string;
    to?: string;
    purpose?: string;
    passengerPhone?: string;
    passengerCount?: number;
    distanceKm?: number;
    notes?: string;
  };
}

export function TripDetailsModal({
  schedule,
  currentTime,
  onClose,
  onRate,
  onReassign,
  onMessage,
  onCall,
  userId,
  isAdmin = false,
}: TripDetailsModalProps & { isAdmin?: boolean }) {
  const { t, i18n } = useTranslation();
  const [showMapMenu, setShowMapMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMapMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const dateFnsLocale = i18n.language === 'ru' ? ru : i18n.language === 'hy' ? hy : enUS;

  if (!schedule) return null;

  const isTrip = schedule.type === 'trip';
  const statusColors: Record<string, string> = {
    scheduled: 'bg-blue-500/10 text-blue-600 dark:text-blue-400',
    pending: 'bg-amber-500/10 text-amber-600 dark:text-amber-400',
    approved: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400',
    rejected: 'bg-red-500/10 text-red-600 dark:text-red-400',
    in_progress: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400',
    completed: 'bg-green-500/10 text-green-600 dark:text-green-400',
    cancelled: 'bg-slate-500/10 text-slate-600 dark:text-slate-400',
  };

  const statusTranslations: Record<string, string> = {
    scheduled: t('driver.status.scheduled', 'Scheduled'),
    pending: t('driver.status.pending', 'Pending'),
    approved: t('driver.status.approved', 'Approved'),
    rejected: t('driver.status.rejected', 'Rejected'),
    in_progress: t('driver.status.in_progress', 'In Progress'),
    completed: t('driver.status.completed', 'Completed'),
    cancelled: t('driver.status.cancelled', 'Cancelled'),
  };

  const openInMap = (provider: string) => {
    if (!schedule.tripInfo?.from || !schedule.tripInfo?.to) return;
    const from = encodeURIComponent(schedule.tripInfo.from);
    const to = encodeURIComponent(schedule.tripInfo.to);
    let url = '';
    switch (provider) {
      case 'google':
        url = `https://www.google.com/maps/dir/?api=1&origin=${from}&destination=${to}`;
        break;
      case 'yandex':
        // Use /route/ endpoint for explicit addresses, not rtext which uses geolocation
        url = `https://yandex.ru/maps/?pt=${from}&l=map&z=12&text=${to}`;
        break;
      case 'apple':
        url = `https://maps.apple.com/?saddr=${from}&daddr=${to}&dirflg=d`;
        break;
      case 'waze':
        url = `https://waze.com/ul?from=${from}&to=${to}&navigate=yes`;
        break;
      case '2gis':
        url = `https://2gis.ru/directions/points/${from}|${to}`;
        break;
    }
    if (url) {
      window.open(url, '_blank', 'noopener,noreferrer');
      setShowMapMenu(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95, y: 20 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.95, y: 20 }}
      transition={{ duration: 0.3, ease: 'easeOut' }}
      className="w-full h-[85vh] flex flex-col"
    >
      <div className="rounded-2xl shadow-2xl overflow-clip w-full h-full flex flex-col">
        {/* Header with gradient */}
        <div
          className={`relative p-6 shrink-0 ${
            isTrip ? 'btn-gradient' : 'bg-linear-to-r from-amber-500 to-orange-500'
          }`}
        >
          {/* Close button */}
          <button
            onClick={onClose}
            className="absolute top-4 right-4 p-2 rounded-lg bg-white/10 hover:bg-white/20 text-white/80 hover:text-white transition-all"
