/**
 * AvailableDriversSection - Section with driver search, filters, and cards
 */

'use client';

import React, { memo, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useRouter } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  CarFront,
  Search,
  Filter,
  SortAsc,
  Car,
  Users,
  MapPin,
  Star,
  Calendar,
  Heart,
  Plus,
} from 'lucide-react';
import { DriverCard } from '../cards/DriverCard';
import { NoDriversEmptyState } from '../empty-states/NoDriversEmptyState';

interface Driver {
  _id: string;
  userName: string;
  userAvatar?: string;
  userPosition?: string;
  rating: number;
  totalTrips: number;
  isOnShift?: boolean;
  vehicleInfo: {
    model: string;
    capacity: number;
    plateNumber: string;
  };
}

interface AvailableDriversSectionProps {
  drivers: Driver[];
  favoriteIds: Set<string>;
  searchQuery: string;
  capacityFilter: number | null;
  sortBy: 'rating' | 'name' | 'availability';
  onSearchChange: (value: string) => void;
  onCapacityChange: (value: number | null) => void;
  onSortChange: (value: 'rating' | 'name' | 'availability') => void;
  onBook: (driverId: string) => void;
  onCalendar: (driverId: string) => void;
  onToggleFavorite: (driverId: string) => void;
  onRequestDriver: () => void;
}

export const AvailableDriversSection = memo(function AvailableDriversSection({
  drivers,
  favoriteIds,
  searchQuery,
  capacityFilter,
  sortBy,
  onSearchChange,
  onCapacityChange,
  onSortChange,
  onBook,
  onCalendar,
  onToggleFavorite,
  onRequestDriver,
}: AvailableDriversSectionProps) {
  const { t } = useTranslation();
  const router = useRouter();

  const filteredDrivers = useMemo(() => {
    let filtered = [...drivers];

    if (searchQuery) {
      filtered = filtered.filter((d) =>
        d.userName?.toLowerCase().includes(searchQuery.toLowerCase()),
      );
    }

    if (capacityFilter) {
      filtered = filtered.filter((d) => d.vehicleInfo.capacity >= capacityFilter);
    }

    filtered.sort((a, b) => {
      if (sortBy === 'rating') return b.rating - a.rating;
      if (sortBy === 'name') return (a.userName ?? '').localeCompare(b.userName ?? '');
      if (sortBy === 'availability') return (b.isOnShift ? 1 : 0) - (a.isOnShift ? 1 : 0);
      return 0;
    });

    return filtered;
  }, [drivers, searchQuery, capacityFilter, sortBy]);

  return (
    <Card className="mb-6 sm:mb-8 border-(--border)">
      <CardHeader>
        <div className="flex flex-col gap-3">
          <div className="flex flex-col sm:flex-row sm:items-center gap-3 sm:justify-between">
            <div className="flex items-center gap-2 sm:gap-3">
              <div>
                <CardTitle className="text-base sm:text-lg flex items-center gap-2">
                  <CarFront className="w-4 h-4 sm:w-5 sm:h-5 text-(--primary)" />
                  <span className="hidden sm:inline">
                    {t('driver.availableDrivers', 'Available Drivers')}
                  </span>
                  <span className="sm:hidden">{t('driver.availableDrivers', 'Drivers')}</span>
                </CardTitle>
                <CardDescription className="hidden sm:block">
                  {t('driver.availableDriversDesc', 'Browse and book drivers')}
                </CardDescription>
              </div>
              {favoriteIds.size > 0 && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => router.push('/drivers/favorites')}
                  className="gap-1.5 h-8 text-xs rounded-xl hover:bg-red-500/10 hover:text-red-500 transition-all p-1.5 sm:p-0"
                >
                  <Heart className="w-3.5 h-3.5 fill-red-500 text-red-500" />
                  <span className="hidden sm:inline">
                    {t('driver.favorites.title', 'Favorites')}
                  </span>
                  <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-red-500/20 text-red-500 text-[10px] font-bold">
                    {favoriteIds.size}
                  </span>
                </Button>
              )}
            </div>
            <div className="relative w-full sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-(--text-muted)" />
              <Input
                placeholder={t('driver.searchDriver', 'Search driver...')}
                value={searchQuery}
                onChange={(e) => onSearchChange(e.target.value)}
                className="pl-10 w-full"
                style={{ borderRadius: '1rem', background: 'var(--background-subtle)' }}
              />
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Filter className="w-4 h-4 text-(--text-muted)" />
            <Select
              value={String(capacityFilter ?? 0)}
              onValueChange={(v) => onCapacityChange(v === '0' ? null : Number(v))}
            >
              <SelectTrigger
                className="w-full sm:w-[140px] h-8 text-xs"
                style={{ borderRadius: '0.75rem' }}
              >
                <SelectValue placeholder={t('driver.minSeats', 'Min seats')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="0">{t('driver.anyCapacity', 'Any capacity')}</SelectItem>
                <SelectItem value="2">{t('driver.seats2Plus', '2+ seats')}</SelectItem>
                <SelectItem value="4">{t('driver.seats4Plus', '4+ seats')}</SelectItem>
                <SelectItem value="6">{t('driver.seats6Plus', '6+ seats')}</SelectItem>
                <SelectItem value="8">{t('driver.seats8Plus', '8+ seats')}</SelectItem>
              </SelectContent>
            </Select>
            <Select value={sortBy} onValueChange={onSortChange}>
              <SelectTrigger
                className="w-full sm:w-[130px] h-8 text-xs"
                style={{ borderRadius: '0.75rem' }}
              >
                <SortAsc className="w-3 h-3 mr-1 hidden sm:inline" />
                <SelectValue placeholder={t('driver.sortBy', 'Sort by')} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="rating">{t('driver.byRating', 'By Rating')}</SelectItem>
                <SelectItem value="name">{t('driver.byName', 'By Name')}</SelectItem>
                <SelectItem value="availability">
                  {t('driver.byAvailability', 'By Availability')}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {filteredDrivers.length > 0 ? (
          <div className="grid gap-3 sm:gap-4 sm:grid-cols-2 lg:grid-cols-3 drivers-stagger">
            {filteredDrivers.map((driver) => (
              <DriverCard
                key={driver._id}
                driver={driver}
                isFavorite={favoriteIds.has(driver._id)}
                onBook={onBook}
                onCalendar={onCalendar}
                onToggleFavorite={onToggleFavorite}
              />
            ))}
          </div>
        ) : (
          <NoDriversEmptyState
            onAction={onRequestDriver}
            actionLabel={t('driver.requestDriver', 'Request Driver')}
          />
        )}
      </CardContent>
    </Card>
  );
});

'use client';

import React, { memo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Clock,
  History,
  Repeat,
  Plus,
  Eye,
  Star,
  Car,
  Pencil,
  Trash2,
  CheckCircle,
  XCircle,
} from 'lucide-react';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';
import i18n from 'i18next';
import { motion } from '@/lib/cssMotion';

interface Request {
  _id: string;
  status: string;
  startTime?: number;
  tripInfo?: {
    from: string;
    to: string;
  };
  assignedDriver?: {
    userName: string;
  };
}

interface RecurringTrip {
  _id: string;
  isActive: boolean;
  days: number[];
  startTime: string;
  endTime: string;
  tripInfo: {
    from: string;
    to: string;
  };
}

interface MyRequestsSectionProps {
  activeRequests: Request[];
  historyRequests: Request[];
  recurringTrips: RecurringTrip[];
  onViewDetails: (request: Request) => void;
  onRate: (request: Request) => void;
  onEdit: (request: Request) => void;
  onDelete: (request: Request) => void;
  onCancel: (request: Request) => void;
  onToggleRecurring: (trip: RecurringTrip) => void;
  onDeleteRecurring: (trip: RecurringTrip) => void;
  onRequestDriver: () => void;
}

const statusLabel = (status: string, t: (key: string, fallback: string) => string) => {
  const labels: Record<string, string> = {
    pending: t('driver.status.pending', 'Pending'),
    approved: t('driver.status.approved', 'Approved'),
    completed: t('driver.status.completed', 'Completed'),
    cancelled: t('driver.status.cancelled', 'Cancelled'),
  };
  return labels[status] || status;
};

const RequestItem = memo(function RequestItem({
  request,
  onViewDetails,
  onRate,
  onEdit,
  onDelete,
  onCancel,
}: {
  request: Request;
  onViewDetails: () => void;
  onRate?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  onCancel?: () => void;
}) {
  const { t } = useTranslation();
  const lang = i18n.language || 'en';
  const dateFnsLocale = lang === 'ru' ? ru : lang === 'hy' ? hy : enUS;
  const statusColors: Record<string, string> = {
    completed: 'bg-green-500',
    pending: 'bg-amber-500',
    approved: 'bg-blue-500',
    cancelled: 'bg-gray-400',
  };

  return (
    <motion.div
      initial={{ opacity: 0, x: -10 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.3 }}
      className="p-4 rounded-xl border border-(--border) bg-(--card) hover:border-(--primary)/30 transition-all duration-300 hover:shadow-lg"
    >
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-start gap-3 flex-1 min-w-0">
          <div
            className={`w-2 h-2 rounded-full mt-2 shrink-0 ${statusColors[request.status] || 'bg-gray-400'}`}
          />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap mb-1">
              <p className="font-medium text-sm truncate">
                {request.tripInfo?.from} → {request.tripInfo?.to}
              </p>
              <Badge
                variant={
                  request.status === 'completed'
                    ? 'default'
                    : request.status === 'pending'
                      ? 'secondary'
                      : 'outline'
                }
                className="text-xs"
              >
                {statusLabel(request.status, t)}
              </Badge>
            </div>
            {request.startTime && (
              <p className="text-xs text-(--text-muted)">
                {format(new Date(request.startTime), 'MMM dd, HH:mm', { locale: dateFnsLocale })}
              </p>
            )}
            {request.assignedDriver && (
              <p className="text-xs text-(--text-muted) mt-1 flex items-center gap-1">
                <Car className="w-3 h-3" />
                {request.assignedDriver.userName}
              </p>
            )}
          </div>
        </div>
        <div className="flex gap-1.5 shrink-0">
          <Button
            size="sm"
            variant="ghost"
            onClick={onViewDetails}
            className="gap-1.5 rounded-lg hover:bg-blue-500/10 hover:text-blue-500 transition-all duration-200 group"
          >
            <Eye className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
          </Button>
          {request.status === 'completed' && onRate && (
            <Button
              size="sm"
              variant="ghost"
              onClick={onRate}
              className="rounded-lg hover:bg-yellow-500/10 hover:text-yellow-500 transition-all duration-200 group"
            >
              <Star className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
            </Button>
          )}
          {request.status === 'pending' && onEdit && (
            <Button
              size="sm"
              variant="ghost"
              onClick={onEdit}
              className="rounded-lg hover:bg-purple-500/10 hover:text-purple-500 transition-all duration-200 group"
            >
              <Pencil className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
            </Button>
          )}
          {request.status === 'pending' && onCancel && (
            <Button
              size="sm"
              variant="ghost"
              onClick={onCancel}
              className="rounded-lg hover:bg-red-500/10 hover:text-red-500 transition-all duration-200 group"
            >
              <XCircle className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
            </Button>
          )}
          {onDelete && (
            <Button
              size="sm"
              variant="ghost"
              onClick={onDelete}
              className="rounded-lg hover:bg-red-500/10 hover:text-red-500 transition-all duration-200 group"
            >
              <Trash2 className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
            </Button>
          )}
        </div>
      </div>
    </motion.div>
  );
});

const RecurringTripItem = memo(function RecurringTripItem({
  trip,
  onToggle,
  onDelete,
}: {
  trip: RecurringTrip;
  onToggle: () => void;
  onDelete: () => void;
}) {
  const { t } = useTranslation();
  const dayNames = [
    t('weekdays.mon', 'Mon'),
    t('weekdays.tue', 'Tue'),
    t('weekdays.wed', 'Wed'),
    t('weekdays.thu', 'Thu'),
    t('weekdays.fri', 'Fri'),
    t('weekdays.sat', 'Sat'),
    t('weekdays.sun', 'Sun'),
  ];
  const activeDays = trip.days.map((d) => dayNames[d - 1]).join(', ');

  return (
    <div className="p-4 rounded-xl border border-(--border) bg-(--card)">
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <Repeat className="w-4 h-4 text-(--primary)" />
            <p className="font-medium text-sm">
              {trip.tripInfo.from} → {trip.tripInfo.to}
            </p>
            <Badge variant={trip.isActive ? 'default' : 'secondary'} className="text-xs">
              {trip.isActive
                ? t('driver.status.active', 'Active')
                : t('driver.status.inactive', 'Inactive')}
            </Badge>
          </div>
          <p className="text-xs text-(--text-muted)">
            {activeDays} · {trip.startTime} - {trip.endTime}
          </p>
        </div>
        <div className="flex gap-1.5 shrink-0">
          <Button
            size="sm"
            variant="outline"
            onClick={onToggle}
            className="rounded-lg hover:bg-emerald-500/10 hover:text-emerald-500 hover:border-emerald-500/30 transition-all duration-200 group"
          >
            <CheckCircle className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={onDelete}
            className="rounded-lg hover:bg-red-500/10 hover:text-red-500 transition-all duration-200 group"
          >
            <Trash2 className="w-3.5 h-3.5 group-hover:scale-110 transition-transform duration-200" />
          </Button>
        </div>
      </div>
    </div>
  );
});

