'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { useMutation } from 'convex/react';
import { useTranslation } from 'react-i18next';
import { api } from '../../../convex/_generated/api';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { DEPARTMENTS, getTravelAllowance } from '@/lib/types';
import { useAuthStore } from '@/store/useAuthStore';
import { useQuery } from 'convex/react';
import type { Id } from '../../../convex/_generated/dataModel';
import type { FunctionReference } from 'convex/server';
import { toCountryCode, TAX_RULES, type CountryCode } from '../../../convex/lib/taxRules';
import { computeGrossFromNet } from '../../../convex/lib/payrollCalculator';
import { SalaryCalculatorStep, type SalaryState } from './SalaryCalculatorStep';
import {
  PassportFields,
  EMPTY_PASSPORT,
  type PassportData,
  type PassportScanFile,
} from './PassportFields';
import {
  UserPlus,
  User,
  Mail,
  Briefcase,
  Phone,
  CheckCircle,
  ChevronRight,
  ChevronLeft,
  Building2,
  Shield,
  DollarSign,
  IdCard,
} from 'lucide-react';

const ADMIN_EMAIL = (process.env.NEXT_PUBLIC_BOOTSTRAP_SUPERADMIN_EMAIL ?? '').toLowerCase();

interface AddEmployeeModalProps {
  open: boolean;
  onClose: () => void;
}

function formatCurrency(amount: number, lang: string = 'en'): string {
  const locale = lang === 'ru' ? 'ru-RU' : lang === 'hy' ? 'hy-AM' : 'en-US';
  return amount.toLocaleString(locale) + ' ֏';
}

// Bizier easing for smooth animations
const bizierEasing = [0.34, 1.56, 0.64, 1];

const TOTAL_STEPS = 6;

export function AddEmployeeModal({ open, onClose }: AddEmployeeModalProps) {
  const { t, i18n } = useTranslation();
  const createUser = useMutation(api.users.mutations.createUser as FunctionReference<'mutation'>);
  const uploadEmployeeDocument = useMutation(api.employeeProfiles.uploadDocument);
  const currentUser = useAuthStore((s) => s.user);
  const isActualAdmin = currentUser?.email?.toLowerCase() === ADMIN_EMAIL;
  const isSuperadmin = currentUser?.role === 'superadmin';

  const organizations = useQuery(api.organizations.getAllOrganizations, isSuperadmin ? {} : 'skip');
  const myOrg = useQuery(
    api.organizations.getMyOrganization,
    !isSuperadmin && currentUser?.id ? { userId: currentUser.id as Id<'users'> } : 'skip',
  );

  const [step, setStep] = useState(0);
  const [direction, setDirection] = useState(1);
  const [submitting, setSubmitting] = useState(false);

  // Form state
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [department, setDepartment] = useState('');
  const [position, setPosition] = useState('');
  const [phone, setPhone] = useState('');
  const [role, setRole] = useState<'admin' | 'supervisor' | 'employee'>('employee');
  const [type, setType] = useState<'staff' | 'contractor'>('staff');
  const [selectedOrgId, setSelectedOrgId] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Resolve the tax country for salary calc from the target organization.
  const targetOrg = isSuperadmin ? organizations?.find((o) => o._id === selectedOrgId) : myOrg;
  const orgCountry: CountryCode =
    toCountryCode(targetOrg?.taxCountry) ?? toCountryCode(targetOrg?.country) ?? 'armenia';

  const [salary, setSalary] = useState<SalaryState>({
    mode: 'gross',
    amount: 0,
    currency: TAX_RULES.armenia.currency,
    country: 'armenia',
  });
  const [passport, setPassport] = useState<PassportData>(EMPTY_PASSPORT);
  const [passportScan, setPassportScan] = useState<PassportScanFile | null>(null);

  const allowance = getTravelAllowance(email);

  // Superadmin: org selection is step 0, so adjust total
  const effectiveTotalSteps = isSuperadmin ? TOTAL_STEPS + 1 : TOTAL_STEPS;

  useEffect(() => {
    if (open) {
      setStep(0);
      setDirection(1);
      setName('');
      setEmail('');
      setDepartment('');
      setPosition('');
      setPhone('');
      setType('staff');
      setRole('employee');
      setSelectedOrgId('');
      setSalary({
        mode: 'gross',
        amount: 0,
        currency: TAX_RULES.armenia.currency,
        country: 'armenia',
      });
      setPassport(EMPTY_PASSPORT);
      setPassportScan(null);
      setErrors({});
    }
  }, [open, isSuperadmin]);

  // Keep salary calc country/currency in sync with the resolved organization.
  useEffect(() => {
    setSalary((p) => ({ ...p, country: orgCountry, currency: TAX_RULES[orgCountry].currency }));
  }, [orgCountry]);

  useEffect(() => {
    if (email.toLowerCase().includes('contractor')) setType('contractor');
    else if (email && !email.toLowerCase().includes('contractor')) setType('staff');
  }, [email]);

  const validateStep = (currentStep: number): boolean => {
    const errs: Record<string, string> = {};

    if (isSuperadmin && currentStep === 0) {
      if (!selectedOrgId)
        errs.organization = t('employees.organization') + ' ' + t('errors.required').toLowerCase();
    }

    if (currentStep === (isSuperadmin ? 1 : 0)) {
      if (!name.trim()) errs.name = t('common.name') + ' ' + t('errors.required').toLowerCase();
      if (!email.trim()) errs.email = t('common.email') + ' ' + t('errors.required').toLowerCase();
      else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errs.email = t('errors.invalidEmail');
    }

    if (currentStep === (isSuperadmin ? 2 : 1)) {
      if (!department)
        errs.department = t('employees.department') + ' ' + t('errors.required').toLowerCase();
      if (!position.trim())
        errs.position = t('employees.position') + ' ' + t('errors.required').toLowerCase();
    }

    if (currentStep === (isSuperadmin ? 3 : 2)) {
      // Role & Type — optional validation
    }

    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const nextStep = () => {
    if (validateStep(step)) {
      setDirection(1);
      setStep((s) => Math.min(s + 1, effectiveTotalSteps - 1));
    }
  };

  const prevStep = () => {
    setDirection(-1);
    setStep((s) => Math.max(s - 1, 0));
  };

  const handleSubmit = async () => {
    if (!validateStep(step)) return;
    if (!currentUser?.id) {
      toast.error(t('toasts.userIdNotFound'));
      return;
    }

    setSubmitting(true);
    try {
      // Persist the resolved GROSS salary (net is always derivable from it).
      const salaryGross =
        salary.amount > 0
          ? salary.mode === 'gross'
            ? salary.amount
            : computeGrossFromNet({ country: salary.country, net: salary.amount }).grossSalary
          : undefined;

      const passportProvided = Object.values(passport).some((v) => v.trim() !== '');

      const newUserId = (await createUser({
        adminId: currentUser.id as Id<'users'>,
        name,
        email,
        passwordHash: 'temp-password-will-be-changed',
        role,
        department,
        position,
        employeeType: type,
        phone: phone || undefined,
        ...(isSuperadmin && selectedOrgId
          ? { organizationId: selectedOrgId as Id<'organizations'> }
          : {}),
        ...(salaryGross !== undefined
          ? { baseSalary: salaryGross, salaryCurrency: salary.currency }
          : {}),
        ...(passportProvided
          ? {
              passportNumber: passport.passportNumber || undefined,
              passportIssuedBy: passport.passportIssuedBy || undefined,
              passportIssueDate: passport.passportIssueDate || undefined,
              passportExpiryDate: passport.passportExpiryDate || undefined,
              socialCardNumber: passport.socialCardNumber || undefined,
              nationality: passport.nationality || undefined,
            }
          : {}),
      })) as Id<'users'>;

      // Persist the uploaded passport scan now that we have the user id.
      if (passportScan && newUserId) {
        await uploadEmployeeDocument({
          userId: newUserId,
          uploaderId: currentUser.id as Id<'users'>,
          category: 'id_document',
          fileName: passportScan.name,
          fileUrl: passportScan.url,
          fileSize: passportScan.size,
        }).catch(() => {});
      }

      toast.success(t('success.created'));
      fetch('/api/telegram/notify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'new_employee',
          data: { name, email, department, position, role },
        }),
      }).catch(() => {});
      onClose();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : t('errors.somethingWentWrong'));
    } finally {
      setSubmitting(false);
    }
  };

  const isLastStep = step === effectiveTotalSteps - 1;

  // Steps config
  const steps = [
    ...(isSuperadmin ? [{ icon: Building2, label: t('employees.organization') }] : []),
    { icon: User, label: t('common.name') },
    { icon: Briefcase, label: t('employees.position') },
    { icon: Shield, label: t('employees.role') },
    { icon: DollarSign, label: t('payroll.salary') || 'Salary' },
    { icon: IdCard, label: t('employees.identity') || 'Identity' },
    { icon: CheckCircle, label: t('common.review') || 'Review' },
  ];

  const slideVariants = {
    hidden: { x: 300, opacity: 0 },
    visible: { x: 0, opacity: 1 },
    exit: { x: -300, opacity: 0 },
  } as const;

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()} modal={false}>
      <DialogContent className="max-w-lg max-h-[95vh] p-0">
        {/* Header with progress */}
        <div className="relative overflow-hidden">
          <div className="absolute inset-0 btn-gradient" />
          <div className="relative z-10 px-6 pt-6 pb-4">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center backdrop-blur-sm">
                <UserPlus className="w-5 h-5 text-white" />
              </div>
              <div>
                <DialogTitle className="text-lg text-white">
                  {t('employees.addEmployee')}
                </DialogTitle>
                <DialogDescription className="text-white/70 text-sm">
                  {t('employees.enterDetails')}
                </DialogDescription>
              </div>
            </div>

            {/* Step indicators */}
            <div className="flex items-center gap-1.5 mt-2">
              {steps.map((s, i) => (
                <div key={i} className="flex items-center gap-1.5 flex-1">
                  <div
                    className={`flex-1 h-1 rounded-full transition-all duration-300 ${
                      i <= step ? 'bg-white' : 'bg-white/30'
                    }`}
                    style={{ transformOrigin: 'left' }}
                  />
                </div>
              ))}
            </div>

            {/* Step labels */}
            <div className="flex items-center justify-between mt-2">
              <span className="text-xs text-white/60">
                {t('common.step') || 'Step'} {step + 1} / {effectiveTotalSteps}
              </span>
              <span className="text-xs text-white/80 font-medium">{steps[step]?.label}</span>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="px-6 py-5 max-h-[50vh] overflow-y-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={step}
              variants={slideVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ duration: 0.35, ease: bizierEasing }}
            >
              {/* Step 0: Organization (superadmin only) */}
              {isSuperadmin && step === 0 && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-4"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-(--primary)/10 flex items-center justify-center">
                      <Building2 className="w-5 h-5 text-(--primary)" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('employees.selectOrganization')}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('employees.selectOrgDescription') ||
                          'Choose which organization to add this employee to'}
                      </p>
                    </div>
                  </div>

                  <div className="space-y-1.5">
                    <Label>{t('employees.organization')} *</Label>
                    <Select value={selectedOrgId} onValueChange={setSelectedOrgId}>
                      <SelectTrigger
                        className={errors.organization ? 'border-(--destructive)' : ''}
                      >
                        <SelectValue placeholder={t('employees.selectOrganization')} />
                      </SelectTrigger>
                      <SelectContent>
                        {organizations?.map((org) => (
                          <SelectItem key={org._id} value={org._id}>
                            {org.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {errors.organization && (
                      <p className="text-xs text-(--destructive)">{errors.organization}</p>
                    )}
                  </div>
                </motion.div>
              )}

              {/* Step 1: Personal Info */}
              {step === (isSuperadmin ? 1 : 0) && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-5"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-blue-500/10 flex items-center justify-center">
                      <User className="w-5 h-5 text-blue-500" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('wizard.personalInfo') || 'Personal Information'}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('wizard.personalInfoDesc') || 'Basic details about the employee'}
                      </p>
                    </div>
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="emp-name">{t('common.name')} *</Label>
                    <div className="relative">
                      <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-(--text-muted)" />
                      <Input
                        id="emp-name"
                        placeholder={t('placeholders.johnSmith')}
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        className={`pl-10 ${errors.name ? 'border-(--destructive)' : ''}`}
                      />
                    </div>
                    {errors.name && <p className="text-xs text-(--destructive)">{errors.name}</p>}
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="emp-email">{t('common.email')} *</Label>
                    <div className="relative">
                      <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-(--text-muted)" />
                      <Input
                        id="emp-email"
                        type="email"
                        placeholder="john.smith@company.com"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className={`pl-10 ${errors.email ? 'border-(--destructive)' : ''}`}
                      />
                    </div>
                    {errors.email && <p className="text-xs text-(--destructive)">{errors.email}</p>}
                    <p className="text-xs text-(--text-muted)">{t('employees.contractorHint')}</p>
                  </div>
                </motion.div>
              )}

              {/* Step 2: Work Details */}
              {step === (isSuperadmin ? 2 : 1) && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-5"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center">
                      <Briefcase className="w-5 h-5 text-amber-500" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('wizard.workDetails') || 'Work Details'}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('wizard.workDetailsDesc') || 'Department and position information'}
                      </p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <div className="space-y-1.5">
                      <Label>{t('employees.department')} *</Label>
                      <Select value={department} onValueChange={setDepartment}>
                        <SelectTrigger
                          className={errors.department ? 'border-(--destructive)' : ''}
                        >
                          <SelectValue placeholder={t('placeholders.selectEmployee')} />
                        </SelectTrigger>
                        <SelectContent>
                          {DEPARTMENTS.map((d) => (
                            <SelectItem key={d} value={d}>
                              {d}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      {errors.department && (
                        <p className="text-xs text-(--destructive)">{errors.department}</p>
                      )}
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="emp-position">{t('employees.position')} *</Label>
                      <Input
                        id="emp-position"
                        placeholder="e.g. Developer"
                        value={position}
                        onChange={(e) => setPosition(e.target.value)}
                        className={errors.position ? 'border-(--destructive)' : ''}
                      />
                      {errors.position && (
                        <p className="text-xs text-(--destructive)">{errors.position}</p>
                      )}
                    </div>
                  </div>
                </motion.div>
              )}

              {/* Step 3: Role & Type */}
              {step === (isSuperadmin ? 3 : 2) && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-5"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-purple-500/10 flex items-center justify-center">
                      <Shield className="w-5 h-5 text-purple-500" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('wizard.roleType') || 'Role & Type'}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('wizard.roleTypeDesc') || 'Set role and employment type'}
                      </p>
                    </div>
                  </div>

                  {/* Role */}
                  <div className="space-y-1.5">
                    <Label>{t('employees.role')}</Label>
                    <Select
                      value={role}
                      onValueChange={(v) => setRole(v as 'admin' | 'supervisor' | 'employee')}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="employee">{t('roles.employee')}</SelectItem>
                        <SelectItem value="supervisor">{t('roles.supervisor')}</SelectItem>
                        <SelectItem value="driver">{t('roles.driver')}</SelectItem>
                        {isActualAdmin && <SelectItem value="admin">{t('roles.admin')}</SelectItem>}
                      </SelectContent>
                    </Select>
                  </div>

                  {/* Employee type */}
                  <div className="space-y-1.5">
                    <Label>{t('employees.employeeType')}</Label>
                    <div className="grid grid-cols-2 gap-2">
                      {(['staff', 'contractor'] as const).map((empType) => {
                        const selected = type === empType;
                        return (
                          <button
                            key={empType}
                            type="button"
                            onClick={() => setType(empType)}
                            className={`relative flex items-center justify-center gap-2 px-4 py-3 rounded-xl border-2 text-sm font-medium transition-all ${
                              selected
                                ? 'btn-gradient border-transparent text-white shadow-md ring-[3px] ring-blue-500/30'
                                : 'border-(--border) bg-(--background-subtle) text-(--text-muted) hover:border-(--border-subtle)'
                            }`}
                          >
                            {selected && <CheckCircle className="w-4 h-4" />}
                            {t(`employees.${empType}`)}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  {/* Phone */}
                  <div className="space-y-1.5">
                    <Label htmlFor="emp-phone">{t('common.phone')}</Label>
                    <div className="relative">
                      <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-(--text-muted)" />
                      <Input
                        id="emp-phone"
                        placeholder="+374 91 123456"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        className="pl-10"
                      />
                    </div>
                  </div>
                </motion.div>
              )}

              {/* Step: Salary */}
              {step === (isSuperadmin ? 4 : 3) && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-5"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center">
                      <DollarSign className="w-5 h-5 text-emerald-500" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('wizard.salaryInfo') || 'Salary'}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('wizard.salaryInfoDesc') ||
                          'Set salary — taxes are calculated automatically'}
                      </p>
                    </div>
                  </div>
                  <SalaryCalculatorStep
                    value={salary}
                    onChange={(patch) => setSalary((p) => ({ ...p, ...patch }))}
                  />
                </motion.div>
              )}

              {/* Step: Identity / Passport */}
              {step === (isSuperadmin ? 5 : 4) && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-5"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-sky-500/10 flex items-center justify-center">
                      <IdCard className="w-5 h-5 text-sky-500" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('wizard.identityInfo') || 'Identity Documents'}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('wizard.identityInfoDesc') ||
                          'Passport / ID details — upload a scan to auto-fill'}
                      </p>
                    </div>
                  </div>
                  <PassportFields
                    value={passport}
                    onChange={(patch) => setPassport((p) => ({ ...p, ...patch }))}
                    onScanUploaded={setPassportScan}
                  />
                </motion.div>
              )}

              {/* Step 4: Review */}
              {step === effectiveTotalSteps - 1 && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-5"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-green-500/10 flex items-center justify-center">
                      <CheckCircle className="w-5 h-5 text-green-500" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-(--text-primary)">
                        {t('common.review') || 'Review'}
                      </h3>
                      <p className="text-sm text-(--text-muted)">
                        {t('wizard.reviewDesc') || 'Confirm the details before adding'}
                      </p>
                    </div>
                  </div>

                  {/* Summary card */}
                  <div className="rounded-xl border border-(--border) bg-(--background-subtle) overflow-hidden">
                    {/* Avatar preview */}
                    <div className="flex items-center gap-4 p-4 border-b border-(--border)">
                      <div className="w-14 h-14 rounded-full bg-primary text-primary-foreground hover:bg-primary/90 flex items-center justify-center text-xl font-bold shadow-lg">
                        {name.charAt(0).toUpperCase() || 'E'}
                      </div>
                      <div>
                        <p className="font-semibold text-(--text-primary)">{name || '—'}</p>
                        <p className="text-sm text-(--text-muted)">{email || '—'}</p>
                      </div>
                    </div>

                    {/* Details */}
                    <div className="p-4 space-y-2.5">
                      {[
                        { label: t('employees.department'), value: department },
                        { label: t('employees.position'), value: position },
                        { label: t('employees.role'), value: t(`roles.${role}`) },
                        { label: t('employees.employeeType'), value: t(`employees.${type}`) },
                        ...(phone ? [{ label: t('common.phone'), value: phone }] : []),
                        ...(salary.amount > 0
                          ? [
                              {
                                label: `${t('payroll.baseSalary')} (${salary.mode === 'gross' ? t('payroll.grossMode') || 'Gross' : t('payroll.netMode') || 'Net'})`,
                                value: `${salary.amount.toLocaleString()} ${salary.currency}`,
                              },
                            ]
                          : []),
                        ...(passport.passportNumber
                          ? [
                              {
                                label: t('employees.passportNumber'),
                                value: passport.passportNumber,
                              },
                            ]
                          : []),
                        ...(passportScan
                          ? [{ label: t('employees.identity'), value: passportScan.name }]
                          : []),
                      ].map((item, i) => (
                        <div key={i} className="flex items-center justify-between text-sm">
                          <span className="text-(--text-muted)">{item.label}</span>
                          <span className="font-medium text-(--text-primary)">
                            {item.value || '—'}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Travel allowance preview */}
                  <motion.div
                    key={allowance}
                    initial={{ scale: 0.95, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    className="rounded-lg bg-(--background-subtle) border border-(--border) p-4 flex items-center justify-between"
                  >
                    <div>
                      <p className="text-sm font-medium text-(--text-primary)">
                        {t('employees.travelAllowance')}
                      </p>
                      <p className="text-xs text-(--text-muted) mt-0.5">
                        {type === 'contractor'
                          ? t('employeeTypes.contractor')
                          : t('employeeTypes.staff')}{' '}
                        type
                      </p>
                    </div>
                    <p className="text-xl font-bold text-(--text-primary)">
                      {formatCurrency(allowance, i18n.language)}
                    </p>
                  </motion.div>
                </motion.div>
              )}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Footer */}
        <DialogFooter className="px-6 py-4 border-t border-(--border) bg-(--background-subtle)">
          <div className="flex items-center justify-between w-full">
            {step > 0 ? (
              <Button
                type="button"
                variant="outline"
                onClick={prevStep}
                disabled={submitting}
                className="flex items-center gap-1"
              >
                <ChevronLeft className="w-4 h-4" />
                {t('wizard.previous') || 'Previous'}
              </Button>
            ) : (
              <div />
            )}

            {!isLastStep ? (
              <Button type="button" onClick={nextStep} className="flex items-center gap-1">
                {t('wizard.next') || 'Next'}
                <ChevronRight className="w-4 h-4" />
              </Button>
            ) : (
              <Button
                type="button"
                onClick={handleSubmit}
                disabled={submitting}
                className="flex items-center gap-2"
              >
                {submitting ? (
                  <>
                    <ShieldLoader size="xs" variant="inline" />
                    {t('employees.adding') || 'Adding...'}
                  </>
                ) : (
                  <>
                    <UserPlus className="w-4 h-4" />
                    {t('employees.addEmployee')}
                  </>
                )}
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useMemo, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import { useAuthStore } from '@/store/useAuthStore';
import { useShallow } from 'zustand/shallow';
import type { User as UserType } from '@/store/useAuthStore';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { createPortal } from 'react-dom';
import {
  X,
  Search,
  UserCheck,
  UserCog,
  Shield,
  Crown,
  User,
  Car,
  ChevronRight,
  Building2,
  Briefcase,
  CheckCircle2,
  AlertCircle,
  Loader2,
  Star,
  Users,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { AvatarUpload } from '@/components/ui/avatar-upload';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { toast } from 'sonner';

// ── Role config ─────────────────────────────────────────────────────────────
const ROLE_CONFIG = {
  admin: { icon: Crown, color: '#2563eb', bg: 'rgba(37,99,235,0.1)', label: 'Admin' },
  supervisor: {
    icon: UserCheck,
    color: '#f59e0b',
    bg: 'rgba(245,158,11,0.1)',
    label: 'Supervisor',
  },
  employee: { icon: User, color: '#10b981', bg: 'rgba(16,185,129,0.1)', label: 'Employee' },
  driver: { icon: Car, color: '#06b6d4', bg: 'rgba(6,182,212,0.1)', label: 'Driver' },
};
type RoleKey = keyof typeof ROLE_CONFIG;

function roleConfig(role: string) {
  return ROLE_CONFIG[role as RoleKey] ?? ROLE_CONFIG.employee;
}

interface PotentialManager {
  _id: Id<'users'>;
  name: string;
  email: string;
  role: string;
  department?: string;
  position?: string;
  avatarUrl?: string;
}

interface AssignManagerModalProps {
  employeeId: Id<'users'>;
  employeeName: string;
  currentSupervisorId?: Id<'users'> | null;
  organizationId: Id<'organizations'>;
  open: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export function AssignManagerModal({
  employeeId,
  employeeName,
  currentSupervisorId,
  organizationId,
  open,
  onClose,
  onSuccess,
}: AssignManagerModalProps) {
  const { t, i18n } = useTranslation();
  const currentUser = useAuthStore(useShallow((state: { user: UserType | null }) => state.user));
  const [mounted, setMounted] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedSupervisorId, setSelectedSupervisorId] = useState<Id<'users'> | null>(
    currentSupervisorId ?? null,
  );
  const [isSubmitting, setIsSubmitting] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [avatarErrors, setAvatarErrors] = useState<Set<string>>(new Set());

  useEffect(() => setMounted(true), []);

  // Focus search input when modal opens
  useEffect(() => {
    if (open) {
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [open]);

  // Fetch potential managers
  const potentialManagers = useQuery(
    api.reporting.getPotentialManagers,
    open
      ? {
          organizationId,
          searchQuery: searchQuery || undefined,
          excludeUserId: employeeId,
        }
      : 'skip',
  );

  // Fetch current reporting line for the employee (to show hierarchy)
  const reportingLine = useQuery(
    api.reporting.getReportingLine,
    open ? { userId: employeeId, organizationId } : 'skip',
  );

  // Mutation
  const assignManager = useMutation(api.reporting.assignManager);

  // Build list of candidates: if no search, show current supervisor + managers by role hierarchy
  const candidates = useMemo(() => {
    if (!potentialManagers) return [];

    // Sort: selected supervisor first, then by role hierarchy
    return [...potentialManagers].sort((a, b) => {
      if (selectedSupervisorId) {
        if (a._id === selectedSupervisorId) return -1;
        if (b._id === selectedSupervisorId) return 1;
      }
      const roleOrder = { admin: 0, supervisor: 1, employee: 2, driver: 3 } as const;
      return (
        (roleOrder[a.role as keyof typeof roleOrder] ?? 99) -
        (roleOrder[b.role as keyof typeof roleOrder] ?? 99)
      );
    });
  }, [potentialManagers, selectedSupervisorId]);

  const handleAssign = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      if (!currentUser?.id) {
        toast.error(t('common.error', 'Authentication error'));
        return;
      }
      await assignManager({
        employeeId,
        supervisorId: selectedSupervisorId ?? undefined,
      });
      toast.success(
        selectedSupervisorId
          ? `${t('employees.managerAssigned', 'Manager assigned successfully')}`
          : `${t('employees.managerRemoved', 'Manager removed successfully')}`,
      );
      onSuccess?.();
      onClose();
    } catch (error: any) {
      toast.error(error.message || t('employees.managerAssignFailed', 'Failed to assign manager'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const getInitials = (name: string) =>
    name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);

  // ── Render ─────────────────────────────────────────────────────────────
  const content = (
    <AnimatePresence>
      {open && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-black/50 backdrop-blur-sm"
            onClick={onClose}
          />

          {/* Modal */}
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            transition={{ type: 'spring', stiffness: 300, damping: 28 }}
            className="relative w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden border"
            style={{ background: 'var(--card)', borderColor: 'var(--border)' }}
          >
            {/* ── Header ─────────────────────────────────────────────── */}
            <div
              className="relative px-6 pt-6 pb-4 border-b"
              style={{ borderColor: 'var(--border)' }}
            >
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div
                    className="w-10 h-10 rounded-xl flex items-center justify-center"
                    style={{ background: 'rgba(37,99,235,0.1)' }}
                  >
                    <UserCog className="w-5 h-5 text-blue-500" />
                  </div>
                  <div>
                    <h2 className="text-lg font-bold" style={{ color: 'var(--text-primary)' }}>
                      {t('employees.assignManager', 'Assign Manager')}
                    </h2>
                    <p className="text-sm" style={{ color: 'var(--text-muted)' }}>
                      {t('employees.assignManagerFor', 'Set manager for {{name}}', {
                        name: employeeName,
                      })}
                    </p>
                  </div>
                </div>
                <button
                  onClick={onClose}
                  className="w-8 h-8 rounded-lg flex items-center justify-center hover:opacity-70 transition-opacity"
                  style={{ color: 'var(--text-muted)' }}
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* ── Current Reporting Line ─────────────────────────────── */}
            {reportingLine && reportingLine.ancestors.length > 0 && (
              <div
                className="px-6 py-3 border-b"
                style={{ background: 'rgba(37,99,235,0.03)', borderColor: 'var(--border)' }}
              >
                <p
                  className="text-xs font-medium mb-2 flex items-center gap-1"
                  style={{ color: 'var(--text-muted)' }}
                >
                  <Users className="w-3 h-3" />
                  {t('employees.currentReportingLine', 'Current reporting line')}
                </p>
                <div className="flex items-center gap-1.5 flex-wrap">
                  {reportingLine.ancestors.map((anc, idx) => (
                    <span key={anc._id} className="flex items-center gap-1">
                      <span
                        className="text-xs px-2 py-0.5 rounded-full font-medium"
                        style={{
                          background: roleConfig(anc.role).bg,
                          color: roleConfig(anc.role).color,
                        }}
                      >
                        {anc.name}
                      </span>
                      {idx < reportingLine.ancestors.length - 1 && (
                        <ChevronRight className="w-3 h-3" style={{ color: 'var(--text-muted)' }} />
                      )}
                    </span>
                  ))}
                  <ChevronRight className="w-3 h-3" style={{ color: 'var(--text-muted)' }} />
                  <span className="text-xs px-2 py-0.5 rounded-full font-medium bg-blue-500/10 text-blue-500">
                    {employeeName}
                  </span>
                </div>
              </div>
            )}

            {/* ── Search ──────────────────────────────────────────────── */}
            <div className="px-6 pt-4 pb-2">
              <div className="relative">
                <Search
                  className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4"
                  style={{ color: 'var(--text-muted)' }}
                />
                <input
                  ref={searchInputRef}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t(
                    'employees.searchManager',
                    'Search by name, email, or department...',
                  )}
                  className="w-full pl-10 pr-4 py-2.5 rounded-xl border text-sm outline-none transition-all focus:ring-2"
                  style={{
                    background: 'var(--background)',
                    borderColor: 'var(--border)',
                    color: 'var(--text-primary)',
                  }}
                />
                {searchQuery && (
                  <button
                    onClick={() => setSearchQuery('')}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-xs opacity-50 hover:opacity-100"
                    style={{ color: 'var(--text-muted)' }}
                  >
                    ✕
                  </button>
                )}
              </div>
            </div>

            {/* ── Manager List ────────────────────────────────────────── */}
            <div className="px-6 py-2 max-h-[320px] overflow-y-auto">
              {/* Clear selection (remove manager) */}
              {currentSupervisorId && (
                <motion.button
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  onClick={() => setSelectedSupervisorId(null)}
                  className="w-full flex items-center gap-3 p-3 rounded-xl border-2 border-dashed mb-2 transition-all hover:opacity-80"
                  style={{
                    borderColor: selectedSupervisorId === null ? '#ef4444' : 'var(--border)',
                    background:
                      selectedSupervisorId === null ? 'rgba(239,68,68,0.05)' : 'transparent',
                  }}
                >
                  <div
                    className="w-9 h-9 rounded-lg flex items-center justify-center"
                    style={{
                      background:
                        selectedSupervisorId === null
                          ? 'rgba(239,68,68,0.1)'
                          : 'rgba(100,100,100,0.1)',
                    }}
                  >
                    <X
                      className="w-4 h-4"
                      style={{
                        color: selectedSupervisorId === null ? '#ef4444' : 'var(--text-muted)',
                      }}
                    />
                  </div>
                  <div className="text-left">
                    <p
                      className="text-sm font-medium"
                      style={{
                        color: selectedSupervisorId === null ? '#ef4444' : 'var(--text-primary)',
                      }}
                    >
                      {selectedSupervisorId === null
                        ? t('employees.removeManager', 'Remove manager')
                        : t('employees.clickToRemove', 'Click to remove current manager')}
                    </p>
                    <p className="text-xs" style={{ color: 'var(--text-muted)' }}>
                      {t(
                        'employees.employeeWillHaveNoManager',
                        'Employee will have no manager assigned',
                      )}
                    </p>
                  </div>
                </motion.button>
              )}

              {/* Loading state */}
              {potentialManagers === undefined && (
                <div className="flex items-center justify-center py-12">
                  <ShieldLoader size="sm" variant="inline" />
                </div>
              )}

              {/* Empty state */}
              {potentialManagers && candidates.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 gap-3">
                  <div
                    className="w-12 h-12 rounded-xl flex items-center justify-center"
                    style={{ background: 'rgba(100,100,100,0.1)' }}
                  >
                    <Search className="w-6 h-6" style={{ color: 'var(--text-muted)' }} />
                  </div>
                  <p className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>
                    {t('employees.noManagersFound', 'No managers found')}
                  </p>
                  <p className="text-xs" style={{ color: 'var(--text-muted)' }}>
                    {t('employees.tryDifferentSearch', 'Try a different search query')}
                  </p>
                </div>
              )}

              {/* Candidates list */}
              {potentialManagers && (
                <div className="space-y-1.5">
                  <AnimatePresence mode="popLayout">
                    {candidates.map((manager, idx) => {
                      const roleConf = roleConfig(manager.role);
                      const RoleIcon = roleConf.icon;
                      const isSelected = selectedSupervisorId === manager._id;
                      const isCurrent = manager._id === currentSupervisorId;

                      return (
                        <motion.button
                          key={manager._id}
                          layout
                          initial={{ opacity: 0, x: -20 }}
                          animate={{ opacity: 1, x: 0 }}
                          exit={{ opacity: 0, x: 20 }}
                          transition={{ delay: idx * 0.02 }}
                          onClick={() => setSelectedSupervisorId(manager._id)}
                          className="w-full flex items-center gap-3 p-3 rounded-xl border text-left transition-all"
                          style={{
                            borderColor: isSelected ? '#2563eb' : 'var(--border)',
                            background: isSelected ? 'rgba(37,99,235,0.05)' : 'transparent',
                            boxShadow: isSelected ? '0 0 0 1px rgba(37,99,235,0.3)' : 'none',
                          }}
                          onMouseEnter={(e) => {
                            if (!isSelected)
                              e.currentTarget.style.background = 'var(--background-subtle)';
                          }}
                          onMouseLeave={(e) => {
                            if (!isSelected) e.currentTarget.style.background = 'transparent';
                          }}
                        >
                          {/* Avatar */}
                          <div className="relative shrink-0">
                            <div
                              className="w-10 h-10 rounded-full overflow-hidden flex items-center justify-center text-white text-sm font-bold"
                              style={{
                                background: `linear-gradient(135deg, ${roleConf.color}, ${roleConf.color}88)`,
                              }}
                            >
                              {manager.avatarUrl && !avatarErrors.has(manager._id) ? (
                                <img
                                  src={manager.avatarUrl}
                                  alt={manager.name}
                                  className="w-full h-full object-cover"
                                  onError={() =>
                                    setAvatarErrors((prev) => new Set(prev).add(manager._id))
