                                {t(`roles.${manager.role}`, roleConf.label)}
                              </span>
                              {manager.position && (
                                <span className="text-xs" style={{ color: 'var(--text-muted)' }}>
                                  {manager.position}
                                </span>
                              )}
                            </div>
                            <div className="flex items-center gap-3 mt-0.5">
                              {manager.department && (
                                <span
                                  className="text-xs flex items-center gap-1"
                                  style={{ color: 'var(--text-muted)' }}
                                >
                                  <Building2 className="w-3 h-3" />
                                  {manager.department}
                                </span>
                              )}
                              <span
                                className="text-xs truncate"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                {manager.email}
                              </span>
                            </div>
                          </div>

                          {/* Radio indicator */}
                          <div
                            className="w-5 h-5 rounded-full border-2 shrink-0 flex items-center justify-center transition-all"
                            style={{
                              borderColor: isSelected ? '#2563eb' : 'var(--border)',
                            }}
                          >
                            {isSelected && (
                              <motion.div
                                initial={{ scale: 0 }}
                                animate={{ scale: 1 }}
                                className="w-2.5 h-2.5 rounded-full bg-blue-500"
                              />
                            )}
                          </div>
                        </motion.button>
                      );
                    })}
                  </AnimatePresence>
                </div>
              )}
            </div>

            {/* ── Footer ──────────────────────────────────────────────── */}
            <div
              className="px-6 py-4 border-t flex items-center justify-between gap-3"
              style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
            >
              <p className="text-xs" style={{ color: 'var(--text-muted)' }}>
                {selectedSupervisorId
                  ? t(
                      'employees.managerWillBeAssigned',
                      'Manager will be assigned to this employee',
                    )
                  : currentSupervisorId
                    ? t('employees.managerWillBeRemoved', 'Current manager will be removed')
                    : t('employees.selectManagerHint', 'Select a manager from the list above')}
              </p>
              <div className="flex gap-2 shrink-0">
                <Button variant="outline" size="sm" onClick={onClose}>
                  {t('common.cancel', 'Cancel')}
                </Button>
                <Button
                  size="sm"
                  onClick={handleAssign}
                  disabled={isSubmitting || selectedSupervisorId === currentSupervisorId}
                  className="btn-gradient text-white"
                >
                  {isSubmitting ? (
                    <span className="flex items-center gap-1">
                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      {t('common.saving', 'Saving...')}
                    </span>
                  ) : (
                    <span className="flex items-center gap-1">
                      <UserCheck className="w-3.5 h-3.5" />
                      {selectedSupervisorId
                        ? t('employees.assignManager', 'Assign Manager')
                        : t('employees.removeManager', 'Remove')}
                    </span>
                  )}
                </Button>
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );

  return mounted ? createPortal(content, document.body) : null;
}

