            </div>
            <div className="space-y-3">
              <Input
                label="LinkedIn"
                value={form.socialLinks.linkedin}
                onChange={(v) =>
                  setForm((p) => ({ ...p, socialLinks: { ...p.socialLinks, linkedin: v } }))
