                        <Input
                          label={t('extendedProfile.endDate', 'End')}
                          value={entry.endDate ?? ''}
                          onChange={(v) => updateWorkEntry(idx, { endDate: v || undefined })}
                          type="month"
                          placeholder="Present"
                        />
                      </div>
                      <Input
                        label={t('extendedProfile.description', 'Description')}
                        value={entry.description ?? ''}
                        onChange={(v) => updateWorkEntry(idx, { description: v || undefined })}
                        type="textarea"
                        placeholder="Describe your role and achievements..."
                      />
                    </motion.div>
                  ))}
                </div>
              )}
            </AnimatePresence>
          </motion.div>
        );

      case 'education':
        return (
          <motion.div
            key="education"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="space-y-4"
          >
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-sm font-semibold text-(--text-primary) flex items-center gap-2">
                  <GraduationCap className="w-4 h-4 text-sky-500" />
                  {t('extendedProfile.education', 'Education')}
                </h3>
                <p className="text-xs text-(--text-muted) mt-1">
                  {t('extendedProfile.educationDesc', 'Academic background and qualifications')}
                </p>
              </div>
              <Button size="sm" variant="outline" onClick={addEduEntry} className="gap-1">
                <Plus className="w-3.5 h-3.5" />
                {t('common.add', 'Add')}
              </Button>
            </div>

            <AnimatePresence mode="popLayout">
              {form.structuredEducation.length === 0 ? (
                <div className="text-center py-8 text-(--text-muted) text-sm border border-dashed border-(--border) rounded-xl">
                  <GraduationCap className="w-8 h-8 mx-auto mb-2 opacity-30" />
                  {t('extendedProfile.noEducation', 'No education entries')}
                </div>
              ) : (
                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-1">
                  {form.structuredEducation.map((entry, idx) => (
                    <motion.div
                      key={idx}
                      layout
                      initial={{ opacity: 0, y: -8, scale: 0.97 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: -8, scale: 0.97 }}
                      className="p-3 rounded-xl border border-(--border) bg-(--background-subtle)/50 space-y-2 relative group/entry"
                    >
                      {' '}
                      <button
                        onClick={() => removeEduEntry(idx)}
                        className="absolute top-2 right-2 p-1 rounded-lg text-red-400 opacity-0 group-hover/entry:opacity-100 hover:bg-red-500/10 transition-all"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                        <Input
                          label={t('extendedProfile.institution', 'Institution')}
                          value={entry.institution}
                          onChange={(v) => updateEduEntry(idx, { institution: v })}
                          placeholder="University / School"
                        />
                        <Input
                          label={t('extendedProfile.degree', 'Degree')}
                          value={entry.degree}
                          onChange={(v) => updateEduEntry(idx, { degree: v })}
                          placeholder="e.g. Bachelor's"
                        />
                      </div>
                      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                        <Input
                          label={t('extendedProfile.field', 'Field')}
                          value={entry.field}
                          onChange={(v) => updateEduEntry(idx, { field: v })}
                          placeholder="e.g. Computer Science"
                        />
                        <Input
                          label={t('extendedProfile.startDate', 'Start')}
                          value={entry.startDate}
                          onChange={(v) => updateEduEntry(idx, { startDate: v })}
                          type="month"
                        />
                        <Input
                          label={t('extendedProfile.endDate', 'End')}
                          value={entry.endDate ?? ''}
                          onChange={(v) => updateEduEntry(idx, { endDate: v || undefined })}
                          type="month"
                          placeholder="Present"
                        />
                      </div>
                      <Input
                        label="GPA"
                        value={entry.gpa ?? ''}
                        onChange={(v) => updateEduEntry(idx, { gpa: v || undefined })}
                        placeholder="e.g. 3.8"
                      />
                    </motion.div>
                  ))}
                </div>
              )}
            </AnimatePresence>
          </motion.div>
        );

      default:
        return null;
    }
  };

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-2xl max-h-[95vh] p-0 flex flex-col">
        {/* Header */}
        <div className="relative overflow-hidden rounded-t-2xl">
          <div className="absolute inset-0 bg-linear-to-br from-blue-600/20 to-purple-600/20" />
          <div className="relative z-10 px-6 pt-6 pb-4">
            <DialogTitle className="text-lg font-bold text-(--text-primary) flex items-center gap-2">
              <User className="w-5 h-5 text-(--primary)" />
              {t('extendedProfile.editTitle', 'Edit Extended Profile')}
            </DialogTitle>
            <DialogDescription className="text-sm text-(--text-muted) mt-1">
              {t(
                'extendedProfile.editDesc',
                'Manage personal details, work preferences, history and more',
              )}
            </DialogDescription>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex overflow-x-auto gap-1 px-6 py-3 border-b border-(--border) bg-(--background-subtle)/30">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.key;
            return (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all ${
                  isActive
                    ? 'bg-(--primary)/10 text-(--primary) shadow-xs'
                    : 'text-(--text-muted) hover:text-(--text-primary) hover:bg-(--background-subtle)'
                }`}
              >
                <Icon className="w-3.5 h-3.5" />
                {t(tab.labelKey)}
              </button>
            );
          })}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto px-6 py-4 min-h-[300px]">
          <AnimatePresence mode="wait">{renderTabContent()}</AnimatePresence>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-(--border) flex items-center justify-between bg-(--background-subtle)/30">
          <Button variant="ghost" size="sm" onClick={onClose} className="gap-1">
            <X className="w-4 h-4" />
            {t('common.cancel', 'Cancel')}
          </Button>
          <Button
            onClick={handleSave}
            disabled={saving}
            size="sm"
            className="gap-2 bg-linear-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white shadow-md"
          >
            {saving ? <ShieldLoader size="xs" variant="inline" /> : <Save className="w-4 h-4" />}
            {saving ? t('common.saving', 'Saving...') : t('common.save', 'Save Changes')}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

﻿'use client';
import Image from 'next/image';

import React, { useState } from 'react';
import { useQuery, useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  User,
  Mail,
  Phone,
  Building2,
  Calendar,
  Briefcase,
  Star,
  Clock,
  Target,
  Award,
  AlertTriangle,
  Plus,
  Edit2,
  Trash2,
  IdCard,
} from 'lucide-react';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import type { Id } from '../../../convex/_generated/dataModel';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';
import i18n from 'i18next';
import { useAuthStore } from '@/store/useAuthStore';
import { SupervisorRatingForm } from '@/components/attendance/SupervisorRatingForm';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { EditEmployeeModal } from './EditEmployeeModal';
import { ReportingLineWidget } from './ReportingLineWidget';
import { AssignManagerModal } from './AssignManagerModal';
import ExtendedProfileSection from './ExtendedProfileSection';
import EditExtendedProfileModal from './EditExtendedProfileModal';
import EmployeeProfileHero from './EmployeeProfileHero';

interface EmployeeProfileDetailProps {
  employeeId: Id<'users'>;
}

export default function EmployeeProfileDetail({ employeeId }: EmployeeProfileDetailProps) {
  const { user: currentUser } = useAuthStore();
  const [showRatingForm, setShowRatingForm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [showAssignManager, setShowAssignManager] = useState(false);
  const [showExtendedEdit, setShowExtendedEdit] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const { t } = useTranslation(['modules', 'common']);
  const lang = i18n.language || 'en';
  const dateFnsLocale = lang === 'ru' ? ru : lang === 'hy' ? hy : enUS;

  const employee = useQuery(api.users.queries.getUserById, { userId: employeeId });
  const profile = useQuery(api.employeeProfiles.getEmployeeProfile, { userId: employeeId });
  const score = useQuery(api.aiEvaluator.calculateEmployeeScore, { userId: employeeId });
  const latestRating = useQuery(api.supervisorRatings.getLatestRating, { employeeId });
  const monthlyStats = useQuery(api.timeTracking.getMonthlyStats, {
    userId: employeeId,
    month: new Date().toISOString().slice(0, 7),
  });
  const ratingHistory = useQuery(api.supervisorRatings.getEmployeeRatings, {
    employeeId,
    limit: 3,
  });

  const deleteUser = useMutation(api.users.mutations.deleteUser);

  const isAdminOrSupervisor = currentUser?.role === 'admin' || currentUser?.role === 'supervisor';
  const isSuperadmin = currentUser?.role === 'superadmin';
  const isTargetSuperadmin = employee?.role === 'superadmin';
  const canEdit = isAdminOrSupervisor || isSuperadmin;
  const canDelete = canEdit && !isTargetSuperadmin && employeeId !== currentUser?.id;

  const handleDelete = async () => {
    setDeleting(true);
    try {
      if (!currentUser?.id) {
        toast.error('User ID not found');
        return;
      }
      await deleteUser({
        userId: employeeId as Id<'users'>,
        adminId: currentUser.id as Id<'users'>,
      });
      toast.success(t('employees.employeeDeleted', 'Employee deleted successfully'));
      window.history.back();
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      toast.error(error.message || t('employees.deleteFailed', 'Failed to delete employee'));
    } finally {
      setDeleting(false);
    }
  };

  const renderStars = (rating: number) =>
    [1, 2, 3, 4, 5].map((i) => (
      <Star
        key={i}
        className={`w-3.5 h-3.5 ${i <= Math.round(rating) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
      />
    ));

  if (!employee) {
    return (
      <Card>
        <CardContent className="p-8 text-center">
          <p className="text-(--text-muted)">{t('employees.loadingProfile')}</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Professional Hero Header */}
      <EmployeeProfileHero
        employee={{
          _id: employee._id,
          name: employee.name,
          email: employee.email,
          phone: employee.phone,
          role: employee.role,
          position: employee.position,
          department: employee.department,
          location: employee.location,
          employeeType: employee.employeeType,
          isActive: employee.isActive,
          avatarUrl: employee.avatarUrl,
          createdAt: employee.createdAt,
        }}
        score={score as any}
        monthlyStats={monthlyStats as any}
        canEdit={canEdit}
        canDelete={canDelete}
        isAdminOrSupervisor={isAdminOrSupervisor}
        showRatingForm={showRatingForm}
        onEdit={() => setShowEditModal(true)}
        onDelete={() => setShowDeleteDialog(true)}
        onRate={() => setShowRatingForm(!showRatingForm)}
      />

      {/* Reporting Line Widget */}
      {employee.organizationId && (
        <ReportingLineWidget
          userId={employeeId}
          organizationId={employee.organizationId as Id<'organizations'>}
          onAssignManager={() => setShowAssignManager(true)}
          canEdit={canEdit}
        />
      )}

      {/* Extended Profile Section */}
      <ExtendedProfileSection
        data={profile?.profile as any}
        canEdit={canEdit}
        onEdit={() => setShowExtendedEdit(true)}
      />

      {/* Supervisor Rating Form (inline) */}
      {isAdminOrSupervisor && showRatingForm && (
        <SupervisorRatingForm
          employeeId={employeeId}
          employeeName={employee.name}
          onClose={() => setShowRatingForm(false)}
          onSuccess={() => setShowRatingForm(false)}
        />
      )}

      {/* This Month's Attendance Stats */}
      {monthlyStats && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <Clock className="w-5 h-5 text-blue-500" />
              {t('attendance.thisMonthsAttendance')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="text-center p-3 rounded-lg bg-(--background-subtle)">
                <p className="text-2xl font-bold text-blue-500">{monthlyStats.totalDays}</p>
                <p className="text-xs text-(--text-muted) mt-1">{t('attendance.daysWorked')}</p>
              </div>
              <div className="text-center p-3 rounded-lg bg-(--background-subtle)">
                <p className="text-2xl font-bold text-green-500">
                  {monthlyStats.totalWorkedHours}h
                </p>
                <p className="text-xs text-(--text-muted) mt-1">{t('attendance.totalHours')}</p>
              </div>
              <div className="text-center p-3 rounded-lg bg-(--background-subtle)">
                <p className="text-2xl font-bold text-sky-400">{monthlyStats.punctualityRate}%</p>
                <p className="text-xs text-(--text-muted) mt-1">{t('attendance.punctuality')}</p>
              </div>
              <div className="text-center p-3 rounded-lg bg-(--background-subtle)">
                <p
                  className={`text-2xl font-bold ${Number(monthlyStats.lateDays) > 0 ? 'text-red-500' : 'text-green-500'}`}
                >
                  {monthlyStats.lateDays}
                </p>
                <p className="text-xs text-(--text-muted) mt-1">{t('attendance.lateDays')}</p>
              </div>
            </div>
            {(Number(monthlyStats.lateDays) > 0 || Number(monthlyStats.earlyLeaveDays) > 0) && (
              <div className="mt-3 flex items-center gap-2 p-3 rounded-lg bg-orange-50 dark:bg-orange-950">
                <AlertTriangle className="w-4 h-4 text-orange-500 shrink-0" />
                <p className="text-sm text-orange-700 dark:text-orange-200">
                  {Number(monthlyStats.lateDays) > 0 &&
                    `${monthlyStats.lateDays} ${t('attendance.lateArrivals')}`}
                  {Number(monthlyStats.lateDays) > 0 &&
                    Number(monthlyStats.earlyLeaveDays) > 0 &&
                    ' · '}
                  {Number(monthlyStats.earlyLeaveDays) > 0 &&
                    `${monthlyStats.earlyLeaveDays} ${t('attendance.earlyLeaves')}`}
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Latest Performance Rating */}
      {latestRating && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg flex items-center gap-2">
                <Star className="w-5 h-5 text-yellow-400 fill-yellow-400" />
                {t('employeeProfile.latestPerformanceRating')}
              </CardTitle>
              <div className="text-right">
                <p className="text-2xl font-bold text-(--primary)">
                  {latestRating.overallRating.toFixed(1)}
                  <span className="text-sm font-normal text-(--text-muted)">/5</span>
                </p>
                <p className="text-xs text-(--text-muted)">
                  {t('performance.by')} {latestRating.supervisor?.name ?? t('roles.supervisor')} ·{' '}
                  {latestRating.ratingPeriod}
                </p>
              </div>
            </div>
          </CardHeader>
          <CardContent className="space-y-3">
            {[
              { label: t('dashboard.qualityOfWork'), value: latestRating.qualityOfWork },
              { label: t('dashboard.efficiency'), value: latestRating.efficiency },
              { label: t('dashboard.teamwork'), value: latestRating.teamwork },
              { label: t('dashboard.initiative'), value: latestRating.initiative },
              { label: t('dashboard.communication'), value: latestRating.communication },
              { label: t('dashboard.reliability'), value: latestRating.reliability },
            ].map(({ label, value }: any) => (
              <div key={label} className="flex items-center justify-between">
                <span className="text-sm text-(--text-muted) w-36">{label}</span>
                <div className="flex items-center gap-2">
                  <div className="flex">{renderStars(value)}</div>
                  <span
                    className="text-sm font-semibold w-5 text-right"
                    style={{ color: 'var(--text-primary)' }}
                  >
                    {value}
                  </span>
                </div>
              </div>
            ))}
            {latestRating.strengths && (
              <div className="mt-3 p-3 rounded-lg bg-green-50 dark:bg-green-950">
                <p className="text-xs font-semibold text-green-700 dark:text-green-300 mb-1">
                  💪 {t('performance.strengths')}
                </p>
                <p className="text-sm text-green-700 dark:text-green-300">
                  {latestRating.strengths}
                </p>
              </div>
            )}
            {latestRating.areasForImprovement && (
              <div className="mt-2 p-3 rounded-lg bg-orange-50 dark:bg-orange-950">
                <p className="text-xs font-semibold text-orange-700 dark:text-orange-300 mb-1">
                  📈 {t('performance.areasForImprovement')}
                </p>
                <p className="text-sm text-orange-700 dark:text-orange-300">
                  {latestRating.areasForImprovement}
                </p>
              </div>
            )}
            {latestRating.generalComments && (
              <div className="mt-2 p-3 rounded-lg bg-(--background-subtle)">
                <p className="text-xs font-semibold text-(--text-muted) mb-1">
                  💬 {t('performance.comments')}
                </p>
                <p className="text-sm text-(--text-primary)">{latestRating.generalComments}</p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Rating History */}
      {ratingHistory && ratingHistory.length > 1 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">{t('employeeProfile.ratingHistory')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {ratingHistory.map((rating) => (
                <div
                  key={rating._id}
                  className="flex items-center justify-between p-3 rounded-lg border"
                  style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
                >
                  <div>
                    <p className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>
                      {rating.ratingPeriod}
                    </p>
                    <p className="text-xs text-(--text-muted)">
                      by {rating.supervisor?.name ?? 'Supervisor'}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="flex">{renderStars(rating.overallRating)}</div>
                    <span className="text-sm font-bold text-(--primary)">
                      {rating.overallRating.toFixed(1)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* No rating yet */}
      {latestRating === null && isAdminOrSupervisor && (
        <Card className="border-dashed">
          <CardContent className="p-6 text-center">
            <Star className="w-10 h-10 text-(--text-muted) mx-auto mb-2 opacity-30" />
            <p className="text-sm text-(--text-muted)">{t('employeeProfile.noRatingYet')}</p>
            <Button
              size="sm"
              className="mt-3 bg-linear-to-r from-blue-600 to-sky-700 text-white"
              onClick={() => setShowRatingForm(true)}
            >
              <Plus className="w-4 h-4 mr-1" />
              {t('employeeProfile.addFirstRating')}
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Leave Balances */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">{t('employeeProfile.leaveBalances')}</CardTitle>
        </CardHeader>
        <CardContent className="grid grid-cols-3 gap-4">
          <div className="text-center">
            <p className="text-2xl font-bold text-[#2563eb]">{employee.paidLeaveBalance}</p>
            <p className="text-xs text-(--text-muted) mt-1">{t('employeeProfile.paidLeave')}</p>
          </div>
          <div className="text-center">
            <p className="text-2xl font-bold text-[#ef4444]">{employee.sickLeaveBalance}</p>
            <p className="text-xs text-(--text-muted) mt-1">{t('employeeProfile.sickLeave')}</p>
          </div>
          <div className="text-center">
            <p className="text-2xl font-bold text-[#10b981]">{employee.familyLeaveBalance}</p>
            <p className="text-xs text-(--text-muted) mt-1">{t('employeeProfile.familyLeave')}</p>
          </div>
        </CardContent>
      </Card>

      {/* Identity / Passport */}
      {profile?.profile &&
        (profile.profile.passportNumber ||
          profile.profile.passportIssuedBy ||
          profile.profile.passportIssueDate ||
          profile.profile.passportExpiryDate ||
          profile.profile.socialCardNumber ||
          profile.profile.nationality) && (
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <IdCard className="w-5 h-5 text-sky-500" />
                {t('employees.identity') || 'Identity'}
              </CardTitle>
            </CardHeader>
            <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {[
                { label: t('employees.passportNumber'), value: profile.profile.passportNumber },
                { label: t('employees.nationality'), value: profile.profile.nationality },
                { label: t('employees.passportIssuedBy'), value: profile.profile.passportIssuedBy },
                {
                  label: t('employees.socialCardNumber'),
                  value: profile.profile.socialCardNumber,
                },
                {
                  label: t('employees.passportIssueDate'),
                  value: profile.profile.passportIssueDate,
                },
                {
                  label: t('employees.passportExpiryDate'),
                  value: profile.profile.passportExpiryDate,
                },
              ]
                .filter((f) => f.value)
                .map((f, i) => (
                  <div key={i}>
                    <p className="text-sm text-(--text-muted)">{f.label}</p>
                    <p className="font-medium text-(--text-primary)">{f.value}</p>
                  </div>
                ))}
            </CardContent>
          </Card>
        )}

      {/* AI Performance Breakdown */}
      {score && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <Target className="w-5 h-5 text-(--primary)" />
              {t('employeeProfile.performance')} {t('common.breakdown', 'Breakdown')}
            </CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <p className="text-sm text-(--text-muted)">{t('employeeProfile.performance')}</p>
              <p className="text-2xl font-bold text-(--primary)">{score.breakdown.performance}%</p>
            </div>
            <div>
              <p className="text-sm text-(--text-muted)">{t('employeeProfile.attendance')}</p>
              <p className="text-2xl font-bold text-(--primary)">{score.breakdown.attendance}%</p>
            </div>
            <div>
              <p className="text-sm text-(--text-muted)">{t('employeeProfile.behavior')}</p>
              <p className="text-2xl font-bold text-(--primary)">{score.breakdown.behavior}%</p>
            </div>
            <div>
              <p className="text-sm text-(--text-muted)">{t('employeeProfile.leaveHistory')}</p>
              <p className="text-2xl font-bold text-(--primary)">{score.breakdown.leaveHistory}%</p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Biography */}
      {profile?.profile?.biography && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">{t('employeeProfile.biography')}</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {profile.profile.biography.skills && profile.profile.biography.skills.length > 0 && (
              <div>
                <p className="text-sm font-medium mb-2">{t('employeeProfile.skills')}</p>
                <div className="flex flex-wrap gap-2">
                  {profile.profile.biography.skills.map((skill, i) => (
                    <Badge key={i} variant="secondary">
                      {skill}
                    </Badge>
                  ))}
                </div>
              </div>
            )}
            {profile.profile.biography.languages &&
              profile.profile.biography.languages.length > 0 && (
                <div>
                  <p className="text-sm font-medium mb-2">{t('employeeProfile.languages')}</p>
                  <div className="flex flex-wrap gap-2">
                    {profile.profile.biography.languages.map((lang, i) => (
                      <Badge key={i} variant="outline">
                        {lang}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
          </CardContent>
        </Card>
      )}

      {/* Documents */}
      {profile?.documents && profile.documents.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">{t('employeeProfile.documents')}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {profile.documents.map((doc) => (
                <div
                  key={doc._id}
                  className="flex items-center justify-between p-3 bg-[var(--card-hover)] rounded-lg"
                >
                  <div className="flex items-center gap-3">
                    <Briefcase className="w-5 h-5 text-(--text-muted)" />
                    <div>
                      <p className="text-sm font-medium">{doc.fileName}</p>
                      <p className="text-xs text-(--text-muted)">{doc.category}</p>
                    </div>
                  </div>
                  <p className="text-xs text-(--text-muted)">
                    {format(new Date(doc.uploadedAt), 'MMM d, yyyy', { locale: dateFnsLocale })}
                  </p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Delete Confirmation Dialog */}
      <AnimatePresence>
        {showDeleteDialog && (
          <Dialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
            <DialogContent>
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2 text-red-500">
                  <Trash2 className="w-5 h-5" />
                  {t('employees.confirmDelete', 'Confirm Deletion')}
                </DialogTitle>
                <DialogDescription>
                  {t(
                    'employees.deleteWarning',
                    'Are you sure you want to delete this employee? This action cannot be undone.',
                  )}
                </DialogDescription>
              </DialogHeader>
              <DialogFooter>
                <Button
                  variant="outline"
                  onClick={() => setShowDeleteDialog(false)}
                  disabled={deleting}
                >
                  {t('common.cancel', 'Cancel')}
                </Button>
                <Button variant="destructive" onClick={handleDelete} disabled={deleting}>
                  {deleting ? (
                    <>
                      <ShieldLoader size="xs" variant="inline" />
                      {t('common.deleting', 'Deleting...')}
                    </>
                  ) : (
                    <>
                      <Trash2 className="w-4 h-4 mr-2" />
                      {t('common.delete', 'Delete')}
                    </>
                  )}
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        )}
      </AnimatePresence>

      {/* Edit Employee Modal */}
      <EditEmployeeModal
        employee={employee as any}
        open={showEditModal}
        onClose={() => setShowEditModal(false)}
      />

      {/* Assign Manager Modal */}
      {employee.organizationId && (
        <AssignManagerModal
          employeeId={employeeId}
          employeeName={employee.name}
          currentSupervisorId={employee.supervisorId as Id<'users'> | null | undefined}
          organizationId={employee.organizationId as Id<'organizations'>}
          open={showAssignManager}
          onClose={() => setShowAssignManager(false)}
          onSuccess={() => setShowAssignManager(false)}
        />
      )}

      {/* Edit Extended Profile Modal */}
      <EditExtendedProfileModal
        open={showExtendedEdit}
        onClose={() => setShowExtendedEdit(false)}
        onSuccess={() => setShowExtendedEdit(false)}
        employeeId={employeeId}
        {...(employee.organizationId
          ? { organizationId: employee.organizationId as Id<'organizations'> }
          : {})}
        initialData={profile?.profile as any}
      />
    </div>
  );
}

'use client';

import React from 'react';
import { useTranslation } from 'react-i18next';
import { Mail, Phone, Building2, Calendar, Edit2, Trash2, Star, MapPin } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { motion } from '@/lib/cssMotion';
import { format } from 'date-fns';
import { enUS, ru, hy } from 'date-fns/locale';

// ── Types ──
interface EmployeeData {
  _id: string;
  name: string;
  email: string;
  phone?: string;
  role: string;
  position?: string;
  department?: string;
  location?: string;
  employeeType?: string;
  isActive?: boolean;
  avatarUrl?: string;
  createdAt: number;
}

interface ScoreData {
  overallScore: number;
  breakdown: {
    performance: number;
    attendance: number;
    behavior: number;
    leaveHistory: number;
  };
}

interface EmployeeProfileHeroProps {
  employee: EmployeeData;
  score?: ScoreData | null;
  monthlyStats?: {
    totalDays: number;
    totalWorkedHours: number;
    punctualityRate: number;
    lateDays: number;
  } | null;
  canEdit: boolean;
  canDelete: boolean;
  isAdminOrSupervisor: boolean;
  showRatingForm: boolean;
  onEdit: () => void;
  onDelete: () => void;
  onRate: () => void;
}

// ── Helpers ──
function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);
}

// Theme-aware gradient using CSS variables
function getRoleGradientStyle(): React.CSSProperties {
  return {
    background:
      'linear-gradient(135deg, rgba(var(--primary-rgb), 0.8), rgba(var(--primary-rgb), 0.35))',
  };
}

// ── Circular Stat ──
function CircularStat({
  value,
  label,
  idx,
}: {
  value: number | string;
  label: string;
  idx: number;
}) {
  // Alternate opacities for visual variety without hardcoded hues
  const opacities = ['70', '55', '40', '25'];
  const opacity = opacities[idx % opacities.length] ?? '50';
  return (
    <div className="text-center">
      <div className="relative w-14 h-14 sm:w-16 sm:h-16 mx-auto mb-1">
        <svg className="w-full h-full -rotate-90" viewBox="0 0 64 64">
          <circle
            cx="32"
            cy="32"
            r="28"
            fill="none"
            stroke="currentColor"
            strokeWidth="3"
            className="text-white/10"
          />
          <circle
            cx="32"
            cy="32"
            r="28"
            fill="none"
            stroke="currentColor"
            strokeWidth="3"
            strokeDasharray={`${2 * Math.PI * 28}`}
            strokeDashoffset={`${
              2 * Math.PI * 28 * (1 - (typeof value === 'number' ? Math.min(value, 100) : 0) / 100)
            }`}
            className={`text-white/${opacity}`}
            strokeLinecap="round"
          />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-sm sm:text-base font-bold text-white">{value}</span>
        </div>
      </div>
      <p className="text-[10px] text-white/60 truncate max-w-[80px]">{label}</p>
    </div>
  );
}

// ── EmployeeProfileHero ──
export default function EmployeeProfileHero({
  employee,
  score,
  monthlyStats,
  canEdit,
  canDelete,
  isAdminOrSupervisor,
  showRatingForm,
  onEdit,
  onDelete,
  onRate,
}: EmployeeProfileHeroProps) {
  const { t, i18n } = useTranslation();
  const lang = i18n.language || 'en';
  const dateFnsLocale = lang === 'ru' ? ru : lang === 'hy' ? hy : enUS;

  return (
    <div className="relative overflow-hidden rounded-2xl border border-(--border) shadow-sm">
      {/* Cover gradient */}
      <div className="absolute inset-0 bg-primary opacity-90" />

      {/* Decorative circles */}
      <div className="absolute -top-20 -right-20 w-64 h-64 bg-white/[0.06] rounded-full" />
      <div className="absolute -bottom-16 -left-16 w-48 h-48 bg-white/[0.04] rounded-full" />
      <div className="absolute top-1/2 left-1/3 w-32 h-32 bg-white/[0.02] rounded-full" />

      {/* Content */}
      <div className="relative z-10 p-6 sm:p-8">
        {/* Top row: Avatar + Name + Actions */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-6">
          <div className="flex items-center gap-4 sm:gap-5">
            {/* Avatar */}
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.4, ease: 'easeOut' }}
              className="relative shrink-0"
            >
              <div className="w-20 h-20 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-2 border-white/30 shadow-xl bg-white/10 backdrop-blur-sm">
                {employee.avatarUrl ? (
                  <img
                    src={employee.avatarUrl}
                    alt={employee.name}
                    className="w-full h-full object-cover"
                    referrerPolicy="no-referrer"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-white font-bold text-2xl sm:text-3xl">
                    {getInitials(employee.name)}
                  </div>
                )}
              </div>
              {/* Online indicator */}
              <div className="absolute -bottom-0.5 -right-0.5 w-5 h-5 rounded-full border-2 border-white bg-white/60" />
            </motion.div>

            {/* Name + Role */}
            <div className="text-white">
              <motion.h1
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.4, delay: 0.1 }}
                className="text-2xl sm:text-3xl font-bold tracking-tight"
              >
                {employee.name}
              </motion.h1>
              <motion.p
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.4, delay: 0.15 }}
                className="text-white/70 text-sm mt-1"
              >
                {employee.position || employee.role}
              </motion.p>
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.4, delay: 0.2 }}
                className="flex flex-wrap items-center gap-2 mt-2"
              >
                <Badge className="bg-white/15 text-white border-0 hover:bg-white/25 text-[10px] sm:text-xs">
                  {t(`roles.${employee.role}`, employee.role)}
                </Badge>
                <Badge className="bg-white/10 text-white/80 border-0 text-[10px] sm:text-xs">
                  {t(
                    `employeeTypes.${employee.employeeType ?? 'staff'}`,
                    employee.employeeType ?? 'Staff',
                  )}
                </Badge>
                <Badge
                  className={`border-0 text-[10px] sm:text-xs ${
                    employee.isActive !== false
                      ? 'bg-white/15 text-white/90'
                      : 'bg-white/5 text-white/60'
                  }`}
                >
                  {employee.isActive !== false ? t('statuses.active') : t('statuses.inactive')}
                </Badge>
              </motion.div>
            </div>
          </div>

          {/* Action buttons — glassmorphism, theme-neutral */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.4, delay: 0.25 }}
            className="flex items-center gap-2 w-full sm:w-auto"
          >
            {canEdit && (
              <Button
                size="sm"
                onClick={onEdit}
                className="bg-white/15 hover:bg-white/25 text-white border-0 backdrop-blur-sm gap-1.5"
              >
                <Edit2 className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">{t('common.edit')}</span>
              </Button>
            )}
            {canDelete && (
              <Button
                size="sm"
                onClick={onDelete}
                className="bg-white/10 hover:bg-white/20 text-white/70 hover:text-white border-0 backdrop-blur-sm"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </Button>
            )}
            {isAdminOrSupervisor && (
              <Button
                size="sm"
                onClick={onRate}
                className={`gap-1.5 border-0 backdrop-blur-sm ${
                  showRatingForm
                    ? 'bg-white/25 text-white'
                    : 'bg-white/10 hover:bg-white/20 text-white/80'
                }`}
              >
                <Star className={`w-3.5 h-3.5 ${showRatingForm ? 'text-white' : ''}`} />
                <span className="hidden sm:inline">
                  {showRatingForm
                    ? t('employeeProfile.cancelRating')
                    : t('employeeProfile.ratePerformance')}
                </span>
              </Button>
            )}
          </motion.div>
        </div>

        {/* Stats row */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: 0.3 }}
          className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6"
        >
          {score && (
            <CircularStat
              value={score.overallScore}
              label={t('employeeProfile.aiScore', 'AI Score')}
              idx={0}
            />
          )}
          {score && (
            <CircularStat
              value={`${score.breakdown.attendance}%`}
              label={t('employeeProfile.attendance', 'Attendance')}
              idx={1}
            />
          )}
          {monthlyStats && (
            <CircularStat
              value={`${monthlyStats.punctualityRate}%`}
              label={t('employeeProfile.punctuality', 'Punctuality')}
              idx={2}
            />
          )}
          {monthlyStats && (
            <CircularStat
              value={`${monthlyStats.totalWorkedHours}h`}
              label={t('employeeProfile.hoursWorked', 'Hours')}
              idx={3}
            />
          )}
        </motion.div>

        {/* Contact info row */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: 0.35 }}
          className="flex flex-wrap items-center gap-x-4 gap-y-2 text-white/70 text-xs sm:text-sm"
        >
          {[
            { icon: Mail, value: employee.email, href: `mailto:${employee.email}` },
            ...(employee.phone
              ? [{ icon: Phone, value: employee.phone, href: `tel:${employee.phone}` }]
              : []),
            ...(employee.department ? [{ icon: Building2, value: employee.department }] : []),
            ...(employee.location ? [{ icon: MapPin, value: employee.location }] : []),
            {
              icon: Calendar,
              value: format(new Date(employee.createdAt), 'MMM d, yyyy', {
                locale: dateFnsLocale,
              }),
            },
          ].map((item, idx) => {
            const Icon = item.icon;
            const children = (
              <>
                <Icon className="w-3.5 h-3.5 text-white/40" />
                <span className="truncate max-w-[150px]">{item.value}</span>
              </>
            );
            if ('href' in item && item.href) {
              return (
                <a
                  key={idx}
                  href={item.href}
                  className="flex items-center gap-1.5 hover:text-white transition-colors"
                >
                  {children}
                </a>
              );
            }
            return (
              <div key={idx} className="flex items-center gap-1.5">
                {children}
              </div>
            );
          })}
        </motion.div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { useMainRef } from '@/hooks/useMainRef';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation, usePaginatedQuery } from '@/lib/convex-typed';
import { useDebouncedCallback } from 'use-debounce';
import { api } from '../../../convex/_generated/api';
import { Doc, Id } from '../../../convex/_generated/dataModel';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { cn } from '@/lib/utils';
import { CustomSelect } from '@/components/ui/CustomSelect';
import {
  Plus,
  Search,
  Shield,
  Users,
  User,
  AlertTriangle,
  LayoutGrid,
  List,
  Car,
  Crown,
  UserCheck,
  UserCog,
  Mail,
  Phone,
  Building2,
  Eye,
  ChevronRight,
  Edit2,
  Trash2,
  MoreVertical,
} from 'lucide-react';
import { useShallow } from 'zustand/shallow';
import { useAuthStore } from '@/store/useAuthStore';
import type { User as UserType } from '@/store/useAuthStore';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';
import { AddEmployeeModal } from './AddEmployeeModal';
import { EditEmployeeModal } from './EditEmployeeModal';
import { AvatarUpload } from '@/components/ui/avatar-upload';
import { TeamSidebar } from './TeamSidebar';
import { toast } from 'sonner';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { useRouter } from 'next/navigation';

import { useMediaQuery } from '@/hooks/useMediaQuery';
import { MobileCard } from '@/components/ui/mobile-card';
import { Button } from '../ui/button';
import Image from 'next/image';

const ROLE_CONFIG = {
  superadmin: {
    labelKey: 'roles.superAdmin',
    icon: Shield,
    color: '#9333ea',
    bg: 'rgba(147,51,234,0.1)',
  },
  admin: { labelKey: 'roles.admin', icon: Crown, color: '#2563eb', bg: 'rgba(99,102,241,0.1)' },
  supervisor: {
    labelKey: 'roles.supervisor',
    icon: UserCheck,
    color: '#f59e0b',
    bg: 'rgba(245,158,11,0.1)',
  },
  employee: {
    labelKey: 'roles.employee',
    icon: User,
    color: '#10b981',
    bg: 'rgba(16,185,129,0.1)',
  },
  driver: { labelKey: 'roles.driver', icon: Car, color: '#06b6d4', bg: 'rgba(6,182,212,0.1)' },
};

const TYPE_CONFIG = {
  staff: { labelKey: 'employeeTypes.staff', color: '#2563eb', bg: 'rgba(99,102,241,0.1)' },
  contractor: {
    labelKey: 'employeeTypes.contractor',
    color: '#f59e0b',
    bg: 'rgba(245,158,11,0.1)',
  },
};

export function EmployeesClient() {
  const { t } = useTranslation();
  const mainRef = useMainRef();
  const user = useAuthStore(useShallow((state: { user: UserType | null }) => state.user));
  const selectedOrgId = useSelectedOrganization();
  const router = useRouter();
  const isMobile = useMediaQuery('(max-width: 640px)');
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => setMounted(true), []);

  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [filterRole, setFilterRole] = useState<string>('all');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>(
    user?.role === 'employee' ? 'active' : 'active',
  );
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editEmployee, setEditEmployee] = useState<Doc<'users'> | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [isPanelOpen, setIsPanelOpen] = useState(false); // Закрыт по умолчанию

  // Server-side pagination state
  const paginatedArgs =
    mounted && user?.id
      ? {
          ...(selectedOrgId ? { organizationId: selectedOrgId as Id<'organizations'> } : {}),
        }
      : 'skip';

  const {
    results: accumulatedUsers,
    status: usersStatus,
    loadMore,
  } = usePaginatedQuery(api.users.listUsersPaginated, paginatedArgs, {
    initialNumItems: 50,
  });

  const hasMore = usersStatus === 'CanLoadMore';
  const isLoadingMore = usersStatus === 'LoadingMore';

  // Debounced search - prevents excessive re-renders while typing
  const handleSearchChange = useDebouncedCallback((value: string) => {
    setDebouncedSearch(value);
  }, 300);

  // For superadmin with selected org, ALWAYS use getOrgMembers
  // For others, use getAllUsers which returns their org's members
  const isSuperadmin = user?.role === 'superadmin';

  // Build supervisor lookup map from accumulatedUsers
  const supervisorMap = useMemo(() => {
    const map = new Map<string, string>();
    (accumulatedUsers || [])
      .filter((u) => u.role === 'supervisor' || u.role === 'admin')
      .forEach((u) => map.set(u._id, u.name));
    return map;
  }, [accumulatedUsers]);
  const deleteUser = useMutation(api.users.deleteUser);

  const isAdmin = user?.role === 'admin';
  const isSupervisor = user?.role === 'supervisor';
  const canManage = isAdmin || isSupervisor || isSuperadmin;

  const filtered = useMemo(() => {
    const usersToFilter = accumulatedUsers || [];
    if (usersToFilter.length === 0) return [];

    return usersToFilter.filter((u) => {
      // Filter out superadmins
      if (u.role === 'superadmin') {
        return false;
      }
      const matchSearch =
        !debouncedSearch ||
        u.name.toLowerCase().includes(debouncedSearch.toLowerCase()) ||
        u.email.toLowerCase().includes(debouncedSearch.toLowerCase()) ||
        (u.department ?? '').toLowerCase().includes(debouncedSearch.toLowerCase()) ||
        (u.position ?? '').toLowerCase().includes(debouncedSearch.toLowerCase());
      const matchRole = filterRole === 'all' || u.role === filterRole;
      const matchType = filterType === 'all' || u.employeeType === filterType;
      const matchStatus =
        filterStatus === 'all' ||
        (filterStatus === 'active' && u.isActive) ||
        (filterStatus === 'inactive' && !u.isActive);
      return matchSearch && matchRole && matchType && matchStatus;
    });
  }, [accumulatedUsers, debouncedSearch, filterRole, filterType, filterStatus]);

  const stats = useMemo(() => {
    if (!accumulatedUsers || accumulatedUsers.length === 0)
      return { total: 0, staff: 0, contractors: 0, admins: 0, supervisors: 0 };
    const active = accumulatedUsers.filter((u) => u.isActive);
    return {
      total: active.length,
      staff: active.filter((u) => u.employeeType === 'staff').length,
      contractors: active.filter((u) => u.employeeType === 'contractor').length,
      admins: active.filter((u) => u.role === 'admin').length,
      supervisors: active.filter((u) => u.role === 'supervisor').length,
    };
  }, [accumulatedUsers]);

  const handleDelete = async (userId: string) => {
    if (!user?.id) {
      toast.error(t('toasts.userIdNotFound'));
      return;
    }
    try {
      await deleteUser({ adminId: user.id as Id<'users'>, userId: userId as Id<'users'> });
      toast.success(t('employees.deactivated'));
      setDeleteConfirm(null);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : t('employees.deactivateFailed'));
    }
  };

  if (!mounted) return null;
  if (accumulatedUsers === undefined)
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <ShieldLoader size="lg" />
      </div>
    );

  return (
    <div className="relative min-h-screen">
      {/* Sticky Header */}
      <div className="sticky top-0 z-10 -mx-4 sm:-mx-6 lg:-mx-8 px-4 sm:px-6 lg:px-8 py-4 mb-4 bg-(--background)/95 backdrop-blur supports-[backdrop-filter]:bg-(--background)/60 border-b border-(--border)">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="min-w-0">
            <h1
              className="text-2xl sm:text-3xl font-bold tracking-tight"
              style={{ color: 'var(--text-primary)' }}
            >
              {t('nav.employees')}
            </h1>
            <p className="text-sm mt-1" style={{ color: 'var(--text-muted)' }}>
              {stats.total} {t('employees.total')} · {stats.staff} {t('employeeTypes.staff')} ·{' '}
              {stats.contractors} {t('employeeTypes.contractors')}
            </p>
          </div>
          {canManage && (
            <Button
              onClick={() => {
                const mainEl = mainRef.current;
                if (mainEl) {
                  mainEl.scrollTo({ top: 0, behavior: 'smooth' });
                }
                window.scrollTo({ top: 0, behavior: 'smooth' });
                setShowAddModal(true);
              }}
              className="flex items-center gap-2 w-full sm:w-auto justify-center btn-gradient text-white font-medium shadow-md hover:shadow-lg"
              variant="default"
            >
              <Plus className="w-5 h-5" /> {t('employees.addEmployee')}
            </Button>
          )}
        </div>
      </div>

      <div
        className="space-y-6"
        style={{
          transition: isMobile ? 'none' : 'padding-right 600ms cubic-bezier(0.4, 0, 0.2, 1)',
          willChange: isMobile ? 'auto' : 'padding-right',
          paddingRight: isMobile ? '0' : isPanelOpen ? '19rem' : '5rem',
        }}
      >
        {/* Info Banner for Admins */}
        {canManage && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.08 }}
            className="p-4 rounded-xl border flex items-start gap-3"
            style={{ background: 'rgba(37,99,235,0.08)', borderColor: 'rgba(37,99,235,0.2)' }}
          >
            <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0 text-blue-500 bg-blue-500/10">
              <Plus className="w-5 h-5" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-sm" style={{ color: '#2563eb' }}>
                {t('employees.infoBannerTitle')}
              </h3>
              <p
                className="text-xs mt-1"
                style={{ color: 'var(--text-muted)' }}
                dangerouslySetInnerHTML={{ __html: t('employees.infoBannerDesc') }}
              />
            </div>
          </motion.div>
        )}

        {/* Stats */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="grid gap-3"
        >
          <div className="flex gap-2 items-center">
            <div className="relative flex-1">
              <Search
                className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4"
                style={{ color: 'var(--text-muted)' }}
              />
              <input
                value={search}
                onChange={(e) => {
                  const value = e.target.value;
                  setSearch(value); // Мгновенное обновление для input
                  handleSearchChange(value); // Debounced для фильтрации
                }}
                placeholder={t('placeholders.searchByName')}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border text-sm outline-none"
                style={{
                  background: 'var(--card)',
                  borderColor: 'var(--border)',
                  color: 'var(--text-primary)',
                }}
              />
              {search && (
                <button
                  onClick={() => {
                    setSearch('');
                    setDebouncedSearch('');
                  }}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-gray-400 hover:text-gray-600"
                >
                  ✕
                </button>
              )}
            </div>
            {/* View toggle */}
            <div className="flex rounded-xl shrink-0">
              <button
                onClick={() => setViewMode('grid')}
                className={cn(
                  'p-2.5 transition-colors rounded-lg',
                  viewMode === 'grid'
                    ? 'btn-gradient text-white'
                    : 'bg-(--card) text-(--text-muted)',
                )}
                title={t('ariaLabels.gridView')}
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button
                onClick={() => setViewMode('list')}
                className={cn(
                  'p-2.5 transition-colors rounded-lg',
                  viewMode === 'list'
                    ? 'btn-gradient text-white'
                    : 'bg-(--card) text-(--text-muted)',
                )}
                title={t('ariaLabels.listView')}
              >
                <List className="w-4 h-4" />
              </button>
            </div>
          </div>
          <div className="flex gap-2 items-center overflow-x-auto pb-2 scrollbar-hide">
            {[
              {
                value: filterRole,
                setter: setFilterRole,
                options: ['all', 'admin', 'supervisor', 'employee'],
                label: 'Role',
              },
              {
                value: filterType,
                setter: setFilterType,
                options: ['all', 'staff', 'contractor'],
                label: 'Type',
              },
              ...(canManage
                ? [
                    {
                      value: filterStatus,
                      setter: setFilterStatus,
                      options: ['all', 'active', 'inactive'],
                      label: 'Status',
                    },
                  ]
                : []),
            ].map(({ value, setter, options, label }) => {
              const getTranslation = (o: string) => {
                if (o === 'all') {
                  if (label === 'Role')
                    return t('employees.allRoles', { defaultValue: 'All Roles' });
                  if (label === 'Type')
                    return t('employees.allTypes', { defaultValue: 'All Types' });
                  if (label === 'Status')
                    return t('employees.allStatuses', { defaultValue: 'All Statuses' });
                }
                return t(`employees.filter_${o}`, { defaultValue: o });
              };
              return (
                <CustomSelect
                  key={label}
                  value={value}
                  onChange={setter}
                  options={options.map((o) => ({
                    value: o,
                    label: (() => {
                      if (label === 'Type')
                        return t('employees.allTypes', { defaultValue: 'All Types' });
                      if (label === 'Status')
                        return t('employees.allStatuses', { defaultValue: 'All Statuses' });
                      return t(`employees.filter_${o}`, { defaultValue: o });
                    })(),
                  }))}
                  triggerClassName="bg-(--card) border-(--border) text-(--text-primary) px-3 py-2 rounded-xl border text-sm outline-none capitalize flex-1 min-w-[100px]"
                  dropdownClassName="bg-(--card) border-(--border) text-(--text-primary)"
                />
              );
            })}
          </div>
        </motion.div>

        {/* Empty State - No Employees */}
        {accumulatedUsers.length === 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="flex flex-col items-center justify-center py-20 gap-4 text-center border-2 border-dashed rounded-2xl"
            style={{ borderColor: 'var(--border)', background: 'var(--background-subtle)' }}
          >
            <Users className="w-16 h-16 opacity-30" style={{ color: 'var(--text-muted)' }} />
            <div>
              <h3 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>
                {t('employees.noEmployees', 'No employees yet')}
              </h3>
              <p className="text-sm mt-1" style={{ color: 'var(--text-muted)' }}>
                {t('employees.noEmployeesDesc', 'Get started by adding your first team member')}
              </p>
            </div>
            {canManage && (
              <Button
                onClick={() => {
                  const mainEl = mainRef.current;
                  if (mainEl) {
                    mainEl.scrollTo({ top: 0, behavior: 'smooth' });
                  }
                  window.scrollTo({ top: 0, behavior: 'smooth' });
                  setShowAddModal(true);
                }}
                className="flex items-center gap-2 btn-gradient text-white font-medium shadow-md"
                variant="default"
              >
                <Plus className="w-4 h-4" /> {t('employees.addFirstEmployee', 'Add First Employee')}
              </Button>
            )}
          </motion.div>
        )}

        {/* Presence badge helper */}
        {(() => {
          const getPresenceBadge = (status: string | undefined) => {
            const cfg: Record<string, { labelKey: string; cls: string }> = {
              available: { labelKey: 'presence.available', cls: 'bg-emerald-100 text-emerald-700' },
              in_meeting: { labelKey: 'presence.inMeeting', cls: 'bg-amber-100 text-amber-700' },
              in_call: { labelKey: 'presence.inCall', cls: 'bg-blue-100 text-blue-700' },
              out_of_office: { labelKey: 'presence.outOfOffice', cls: 'bg-rose-100 text-rose-700' },
              busy: { labelKey: 'presence.busy', cls: 'bg-orange-100 text-orange-700' },
            };
            return cfg[status ?? 'available'] ?? cfg['available'];
          };

          const renderMenu = (emp: Doc<'users'>) =>
            canManage ? (
              <div className="relative shrink-0">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setOpenMenuId(openMenuId === emp._id ? null : emp._id);
                  }}
                  className="p-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                  style={{ color: 'var(--text-muted)', background: 'var(--background-subtle)' }}
                >
                  <MoreVertical className="w-4 h-4" />
                </button>
                <AnimatePresence>
                  {openMenuId === emp._id && (
                    <motion.div
                      initial={{ opacity: 0, scale: 0.95, y: -8 }}
                      animate={{ opacity: 1, scale: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      className="absolute right-0 top-8 w-40 rounded-xl border shadow-xl z-20 overflow-hidden"
                      style={{ background: 'var(--card)', borderColor: 'var(--border)' }}
                    >
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          router.push(`/employees/${emp._id}`);
                          setOpenMenuId(null);
                        }}
                        className="w-full flex items-center gap-2 px-4 py-2.5 text-sm hover:opacity-80"
                        style={{ color: 'var(--text-primary)' }}
                      >
                        <Eye className="w-3.5 h-3.5" /> {t('common.viewProfile')}
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setEditEmployee(emp);
                          setOpenMenuId(null);
                        }}
                        className="w-full flex items-center gap-2 px-4 py-2.5 text-sm hover:opacity-80"
                        style={{ color: 'var(--text-primary)' }}
                      >
                        <Edit2 className="w-3.5 h-3.5" /> {t('common.edit')}
                      </button>
                      {isAdmin && emp.role !== 'admin' && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            setDeleteConfirm(emp._id);
                            setOpenMenuId(null);
                          }}
                          className="w-full flex items-center gap-2 px-4 py-2.5 text-sm hover:opacity-80"
                          style={{ color: '#ef4444' }}
                        >
                          <Trash2 className="w-3.5 h-3.5" /> {t('employees.deactivate')}
                        </button>
                      )}
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            ) : null;

          return (
            <>
              {/* GRID VIEW */}
              {viewMode === 'grid' && (
                <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
                  <AnimatePresence>
                    {filtered.map((emp, i) => {
                      const roleConf = ROLE_CONFIG[emp.role as keyof typeof ROLE_CONFIG];
                      const typeConf =
                        TYPE_CONFIG[emp.employeeType as keyof typeof TYPE_CONFIG] ||
                        TYPE_CONFIG.staff;
                      const RoleIcon = roleConf.icon;
                      const presenceStatus = emp.presenceStatus;
                      const presence = presenceStatus ? getPresenceBadge(presenceStatus) : null;
                      return (
                        <motion.div
                          key={emp._id}
                          initial={{ opacity: 0, scale: 0.95 }}
                          animate={{ opacity: 1, scale: 1 }}
                          exit={{ opacity: 0, scale: 0.95 }}
                          transition={{ delay: i * 0.03 }}
                          onClick={() => router.push(`/employees/${emp._id}`)}
                          className="flex flex-col justify-between relative p-5 rounded-2xl border group cursor-pointer hover:shadow-lg transition-shadow"
                          style={{
                            background: 'var(--card)',
                            borderColor: emp.isActive ? 'var(--border)' : 'rgba(239,68,68,0.2)',
                            opacity: emp.isActive ? 1 : 0.6,
                          }}
                        >
                          <div className="flex items-start gap-3 mb-4">
                            <AvatarUpload
                              userId={emp._id}
                              currentUrl={emp.avatarUrl}
                              name={emp.name}
                              size="md"
                              readonly={!canManage && emp._id !== user?.id}
                            />
                            <div className="min-w-0 flex-1">
                              <h3
                                className="font-semibold truncate cursor-pointer hover:text-blue-500 transition-colors"
                                style={{ color: 'var(--text-primary)' }}
                              >
                                {emp.name}
                              </h3>
                              <p
                                className="text-xs truncate"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                {emp.position ?? t('employees.noPosition')}
                              </p>
                              <span
                                className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium mt-1"
                                style={{ background: roleConf.bg, color: roleConf.color }}
                              >
                                <RoleIcon className="w-2.5 h-2.5" />
                                {t(roleConf.labelKey)}
                              </span>
                            </div>
                          </div>
                          <div className="space-y-1.5 text-xs">
                            <div
                              className="flex items-center gap-2"
                              style={{ color: 'var(--text-muted)' }}
                            >
                              <Mail className="w-3 h-3 shrink-0" />
                              <span className="truncate">{emp.email}</span>
                            </div>
                            {emp.phone && (
                              <div
                                className="flex items-center gap-2"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                <Phone className="w-3 h-3" />
                                {emp.phone}
                              </div>
                            )}
                            {emp.department && (
                              <div
                                className="flex items-center gap-2"
                                style={{ color: 'var(--text-muted)' }}
                              >
                                <Building2 className="w-3 h-3" />
                                {emp.department}
                              </div>
                            )}
                            {emp.supervisorId && (
                              <div className="flex items-center gap-2">
                                <UserCog className="w-3 h-3 shrink-0 text-blue-400" />
                                <span className="truncate text-blue-500 font-medium">
                                  {supervisorMap.get(emp.supervisorId) ??
                                    t('employees.noSupervisor')}
                                </span>
                              </div>
                            )}
                          </div>
                          <div
                            className="flex flex-wrap gap-2 items-center justify-between mt-4 pt-3 border-t"
                            style={{ borderColor: 'var(--border)' }}
                          >
                            <div className="flex gap-2">
                              <span
                                className="text-xs px-2 py-0.5 rounded-full font-medium"
                                style={{ background: typeConf.bg, color: typeConf.color }}
                              >
                                {t(typeConf.labelKey)}
                              </span>
                              {emp.supervisorId && (
                                <span className="text-xs px-2 py-0.5 rounded-full font-medium bg-blue-500/10 text-blue-500">
                                  {supervisorMap.get(emp.supervisorId) ??
                                    t('employees.noSupervisor')}
                                </span>
                              )}
                            </div>
                            <div className="flex items-center gap-1">
                              {isAdmin ? (
                                <span
                                  className="text-xs font-semibold"
                                  style={{ color: 'var(--text-muted)' }}
                                >
                                  {emp.travelAllowance?.toLocaleString() ?? '0'} {t('currency.amd')}
                                </span>
                              ) : (
                                <span
                                  className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                                    emp.isActive
                                      ? 'bg-emerald-100 text-emerald-700'
                                      : 'bg-red-100 text-red-700'
                                  }`}
                                >
                                  {emp.isActive
                                    ? t('common.active', { defaultValue: 'Активен' })
                                    : t('common.inactive', { defaultValue: 'Неактивен' })}
                                </span>
                              )}
                            </div>
                          </div>
                          {!emp.isActive && (
                            <div
                              className="absolute inset-0 rounded-2xl flex items-center justify-center"
                              style={{ background: 'rgba(0,0,0,0.05)' }}
                            >
                              <span
                                className="text-xs font-bold px-3 py-1 rounded-full"
