                              {expense.status === 'draft' && canManage && (
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => deleteExpense({ expenseId: expense._id })}
                                >
                                  <X className="w-3 h-3" />
                                </Button>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="text-center py-8 text-(--text-muted)">
                        <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p>{t('expenses.noExpenses')}</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            </TabsContent>

            {/* Reports Tab */}
            <TabsContent value="reports">
              <motion.div variants={itemVariants}>
                <Card>
                  <CardHeader>
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                      <CardTitle className="text-lg">{t('expenses.reports')}</CardTitle>
                      {canManage && (
                        <Button size="sm" onClick={() => setReportWizardOpen(true)}>
                          <Plus className="w-4 h-4 mr-2" />
                          {t('expenses.newReport')}
                        </Button>
                      )}
                    </div>
                  </CardHeader>
                  <CardContent>
                    {expenseReports && expenseReports.length > 0 ? (
                      <div className="space-y-3">
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        {expenseReports.map((report: any) => (
                          <div
                            key={report._id}
                            className="flex flex-wrap gap-3 items-center justify-between p-3 rounded-lg bg-(--card) border border-(--border)"
                          >
                            <div>
                              <p className="font-medium text-(--text-primary)">{report.name}</p>
                              <p className="text-sm text-(--text-muted)">
                                {report.userName} - {report.expenseCount}{' '}
                                {t('expenses.expenses').toLowerCase()}
                              </p>
                            </div>
                            <div className="flex flex-wrap items-center gap-4">
                              <div className="text-right">
                                <p className="font-medium text-(--text-primary)">
                                  {formatCurrency(report.totalAmount, report.currency)}
                                </p>
                                <p className="text-sm text-(--text-muted)">
                                  {formatDate(report.periodStart)} - {formatDate(report.periodEnd)}
                                </p>
                              </div>
                              {getStatusBadge(report.status, t)}
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="text-center py-8 text-(--text-muted)">
                        <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p>{t('expenses.noReports')}</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            </TabsContent>

            {/* Categories Tab */}
            <TabsContent value="categories">
              <motion.div variants={itemVariants}>
                <Card>
                  <CardHeader>
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                      <CardTitle className="text-lg">{t('expenses.categories')}</CardTitle>
                      {canManage && (
                        <Button size="sm" onClick={() => setCategoryWizardOpen(true)}>
                          <Plus className="w-4 h-4 mr-2" />
                          {t('expenses.newCategory')}
                        </Button>
                      )}
                    </div>
                  </CardHeader>
                  <CardContent>
                    {expenseCategories && expenseCategories.length > 0 ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        {expenseCategories.map((category: any) => (
                          <Card key={category._id}>
                            <CardHeader>
                              <div className="flex items-start justify-between">
                                <div>
                                  <CardTitle className="text-base">
                                    {getCategoryLabel(category.key, t)}
                                  </CardTitle>
                                  <p className="text-sm text-(--text-muted) mt-1">
                                    {category.description}
                                  </p>
                                </div>
                                <Badge variant={category.isActive ? 'success' : 'secondary'}>
                                  {category.isActive ? t('common.active') : t('common.inactive')}
                                </Badge>
                              </div>
                            </CardHeader>
                            <CardContent>
                              <div className="space-y-2 text-sm">
                                {category.dailyLimit && (
                                  <div className="flex justify-between">
                                    <span className="text-(--text-muted)">
                                      {t('expenses.dailyLimit')}
                                    </span>
                                    <span>{formatCurrency(category.dailyLimit, 'AMD')}</span>
                                  </div>
                                )}
                                {category.monthlyLimit && (
                                  <div className="flex justify-between">
                                    <span className="text-(--text-muted)">
                                      {t('expenses.monthlyLimit')}
                                    </span>
                                    <span>{formatCurrency(category.monthlyLimit, 'AMD')}</span>
                                  </div>
                                )}
                                <div className="flex justify-between">
                                  <span className="text-(--text-muted)">
                                    {t('expenses.requiresReceipt')}
                                  </span>
                                  <span>
                                    {category.requiresReceipt ? t('common.yes') : t('common.no')}
                                  </span>
                                </div>
                                <div className="flex justify-between">
                                  <span className="text-(--text-muted)">
                                    {t('expenses.requiresApproval')}
                                  </span>
                                  <span>
                                    {category.requiresApproval ? t('common.yes') : t('common.no')}
                                  </span>
                                </div>
                              </div>
                            </CardContent>
                          </Card>
                        ))}
                      </div>
                    ) : (
                      <div className="text-center py-8 text-(--text-muted)">
                        <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p>{t('expenses.noCategories')}</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            </TabsContent>

            {/* Policies Tab */}
            <TabsContent value="policies">
              <motion.div variants={itemVariants}>
                <Card>
                  <CardHeader>
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                      <CardTitle className="text-lg">{t('expenses.policies')}</CardTitle>
                      {canManage && (
                        <Button size="sm" onClick={() => setPolicyWizardOpen(true)}>
                          <Plus className="w-4 h-4 mr-2" />
                          {t('expenses.newPolicy')}
                        </Button>
                      )}
                    </div>
                  </CardHeader>
                  <CardContent>
                    {expensePolicy ? (
                      <div className="space-y-4">
                        <div className="flex items-center justify-between">
                          <h3 className="font-medium text-(--text-primary)">
                            {expensePolicy.name}
                          </h3>
                          <Badge variant={expensePolicy.isActive ? 'success' : 'secondary'}>
                            {expensePolicy.isActive ? t('common.active') : t('common.inactive')}
                          </Badge>
                        </div>
                        {expensePolicy.description && (
                          <p className="text-sm text-(--text-muted)">{expensePolicy.description}</p>
                        )}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-2">
                            <h4 className="font-medium text-(--text-primary)">
                              {t('expenses.approvalLimits')}
                            </h4>
                            {expensePolicy.autoApprovalLimit && (
                              <div className="flex justify-between text-sm">
                                <span className="text-(--text-muted)">
                                  {t('expenses.autoApprovalLimit')}
                                </span>
                                <span>
                                  {formatCurrency(expensePolicy.autoApprovalLimit, 'AMD')}
                                </span>
                              </div>
                            )}
                            {expensePolicy.managerApprovalLimit && (
                              <div className="flex justify-between text-sm">
                                <span className="text-(--text-muted)">
                                  {t('expenses.managerApprovalLimit')}
                                </span>
                                <span>
                                  {formatCurrency(expensePolicy.managerApprovalLimit, 'AMD')}
                                </span>
                              </div>
                            )}
                            {expensePolicy.directorApprovalLimit && (
                              <div className="flex justify-between text-sm">
                                <span className="text-(--text-muted)">
                                  {t('expenses.directorApprovalLimit')}
                                </span>
                                <span>
                                  {formatCurrency(expensePolicy.directorApprovalLimit, 'AMD')}
                                </span>
                              </div>
                            )}
                          </div>
                          <div className="space-y-2">
                            <h4 className="font-medium text-(--text-primary)">
                              {t('expenses.receiptPolicy')}
                            </h4>
                            {expensePolicy.receiptRequiredAbove && (
                              <div className="flex justify-between text-sm">
                                <span className="text-(--text-muted)">
                                  {t('expenses.receiptRequiredAbove')}
                                </span>
                                <span>
                                  {formatCurrency(expensePolicy.receiptRequiredAbove, 'AMD')}
                                </span>
                              </div>
                            )}
                            {expensePolicy.submissionDeadlineDays && (
                              <div className="flex justify-between text-sm">
                                <span className="text-(--text-muted)">
                                  {t('expenses.submissionDeadline')}
                                </span>
                                <span>
                                  {expensePolicy.submissionDeadlineDays} {t('common.days')}
                                </span>
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    ) : (
                      <div className="text-center py-8 text-(--text-muted)">
                        <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p>{t('expenses.noPolicies')}</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            </TabsContent>
          </Tabs>

          {/* Charts */}
          {expenseSummary && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 my-4">
              <motion.div variants={itemVariants}>
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">{t('expenses.byCategory')}</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <ResponsiveContainer width="100%" height={300}>
                      <BarChart data={categoryChartData}>
                        <CartesianGrid
                          strokeDasharray="3 3"
                          stroke={isDark ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.1)'}
                        />
                        <XAxis dataKey="name" tick={{ fill: textColor, fontSize: 13 }} />
                        <YAxis tick={{ fill: textColor, fontSize: 13 }} />
                        <RechartsTooltip
                          contentStyle={{
                            backgroundColor: tooltipBg,
                            border: `1px solid ${tooltipBorder}`,
                            borderRadius: '0.5rem',
                            color: tooltipColor,
                            boxShadow: tooltipShadow,
                          }}
                          labelStyle={{ color: tooltipColor, fontWeight: 500 }}
                          formatter={(value, _name) => [value, '']}
                        />
                        <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </motion.div>

              <motion.div variants={itemVariants}>
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">{t('expenses.byStatus')}</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <ResponsiveContainer width="100%" height={300}>
                      <PieChart>
                        <Pie
                          data={statusChartData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          label={(entry) =>
                            (entry.value ?? 0) > 0
                              ? `${entry.name ?? ''}: ${((entry.percent ?? 0) * 100).toFixed(0)}%`
                              : ''
                          }
                          outerRadius={80}
                          fill="#8884d8"
                          dataKey="value"
                        >
                          {statusChartData.map((_entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                          ))}
                        </Pie>
                        <RechartsTooltip
                          contentStyle={{
                            backgroundColor: tooltipBg,
                            border: `1px solid ${tooltipBorder}`,
                            borderRadius: '0.5rem',
                            color: tooltipColor,
                            boxShadow: tooltipShadow,
                          }}
                          labelStyle={{ color: tooltipColor, fontWeight: 500 }}
                          formatter={(value, _name) => [value, '']}
                        />
                        <Legend
                          wrapperStyle={{ color: textColor, fontSize: '12px' }}
                          formatter={(value: string) => (
                            <span style={{ color: tooltipColor }}>{value}</span>
                          )}
                        />
                      </PieChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </motion.div>
            </div>
          )}
        </>
      )}
      {wizardOpen && orgId && user && (
        <ExpenseWizard
          open={wizardOpen}
          onOpenChange={setWizardOpen}
          organizationId={orgId}
          userId={user.id as Id<'users'>}
          onSuccess={() => {}}
        />
      )}
      {categoryWizardOpen && orgId && user && (
        <CategoryWizard
          open={categoryWizardOpen}
          onOpenChange={setCategoryWizardOpen}
          organizationId={orgId}
          userId={user.id as Id<'users'>}
          onSuccess={() => {}}
        />
      )}
      {reportWizardOpen && orgId && user && (
        <ReportWizard
          open={reportWizardOpen}
          onOpenChange={setReportWizardOpen}
          organizationId={orgId}
          userId={user.id as Id<'users'>}
          onSuccess={() => {}}
        />
      )}
      {policyWizardOpen && orgId && user && (
        <PolicyWizard
          open={policyWizardOpen}
          onOpenChange={setPolicyWizardOpen}
          organizationId={orgId}
          userId={user.id as Id<'users'>}
          onSuccess={() => {}}
        />
      )}
    </motion.div>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { useMutation } from 'convex/react';
import { api } from '@/convex/_generated/api';
import { Id } from '@/convex/_generated/dataModel';
import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Wizard, WizardStep } from '@/components/ui/wizard';
import { TextInputStep, TextareaStep, SelectStep } from '@/components/ui/wizard-step-components';
import { FileText, DollarSign, Calendar, Shield } from 'lucide-react';

interface PolicyWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizationId: Id<'organizations'>;
  userId: Id<'users'>;
  onSuccess?: () => void;
}

function PolicyInfoStep() {
  const { t } = useTranslation();

  return (
    <div className="space-y-4">
      <TextInputStep
        field="name"
        label={t('expenses.policyName')}
        placeholder={t('expenses.policyName')}
        required
      />
      <TextareaStep
        field="description"
        label={t('expenses.policyDescription')}
        placeholder={t('expenses.policyDescription')}
        rows={3}
      />
    </div>
  );
}

function ApprovalLimitsStep() {
  const { t } = useTranslation();

  return (
    <div className="space-y-4">
      <TextInputStep
        field="autoApprovalLimit"
        label={t('expenses.autoApprovalLimit')}
        placeholder="0"
        type="number"
      />
      <TextInputStep
        field="managerApprovalLimit"
        label={t('expenses.managerApprovalLimit')}
        placeholder="0"
        type="number"
      />
      <TextInputStep
        field="directorApprovalLimit"
        label={t('expenses.directorApprovalLimit')}
        placeholder="0"
        type="number"
      />
    </div>
  );
}

function ReceiptPolicyStep() {
  const { t } = useTranslation();

  return (
    <div className="space-y-4">
      <TextInputStep
        field="receiptRequiredAbove"
        label={t('expenses.receiptRequiredAbove')}
        placeholder="0"
        type="number"
      />
      <TextInputStep
        field="submissionDeadlineDays"
        label={t('expenses.submissionDeadline')}
        placeholder="30"
        type="number"
      />
      <SelectStep
        field="isActive"
        label={t('expenses.policyStatus')}
        options={[
          { value: 'true', label: t('common.active') },
          { value: 'false', label: t('common.inactive') },
        ]}
        defaultValue="true"
      />
    </div>
  );
}

export default function PolicyWizard({
  open,
  onOpenChange,
  organizationId,
  userId,
  onSuccess,
}: PolicyWizardProps) {
  const { t } = useTranslation();
  const [resetKey, setResetKey] = useState(0);
  const createPolicy = useMutation(api.expenses.createExpensePolicy);

  const steps: WizardStep[] = [
    {
      id: 'info',
      title: t('expenses.policyInfo'),
      description: t('expenses.enterPolicyInfo'),
      icon: <FileText className="w-5 h-5" />,
      content: <PolicyInfoStep />,
      validation: (data) => !!data.name && String(data.name).trim().length > 0,
    },
    {
      id: 'limits',
      title: t('expenses.approvalLimits'),
      description: t('expenses.setApprovalLimits'),
      icon: <DollarSign className="w-5 h-5" />,
      content: <ApprovalLimitsStep />,
      validation: () => true,
    },
    {
      id: 'receipt',
      title: t('expenses.receiptPolicy'),
      description: t('expenses.setReceiptPolicy'),
      icon: <Shield className="w-5 h-5" />,
      content: <ReceiptPolicyStep />,
      validation: () => true,
    },
  ];

  const handleComplete = async (
    data: Record<string, string | number | boolean | null | string[]>,
  ) => {
    try {
      await createPolicy({
        organizationId,
        name: String(data.name),
        description: (data.description as string) || '',
        autoApprovalLimit: data.autoApprovalLimit ? Number(data.autoApprovalLimit) : undefined,
        managerApprovalLimit: data.managerApprovalLimit
          ? Number(data.managerApprovalLimit)
          : undefined,
        directorApprovalLimit: data.directorApprovalLimit
          ? Number(data.directorApprovalLimit)
          : undefined,
        submissionDeadlineDays: data.submissionDeadlineDays
          ? Number(data.submissionDeadlineDays)
          : undefined,
        receiptRequiredAbove: data.receiptRequiredAbove
          ? Number(data.receiptRequiredAbove)
          : undefined,
        isActive: data.isActive === 'true',
        createdBy: userId,
      });

      toast.success(t('expenses.policyCreated'));
      onOpenChange(false);
      setResetKey((k) => k + 1);
      onSuccess?.();
    } catch (error) {
      console.error('Error creating policy:', error);
      toast.error(t('expenses.errorCreatingPolicy'));
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[640px] p-0 gap-0 max-h-[90vh] flex flex-col overflow-visible">
        <div className="px-5 py-4 border-b border-(--border) bg-gradient-to-r from-(--primary)/10 to-transparent shrink-0">
          <DialogTitle>{t('expenses.newPolicy')}</DialogTitle>
          <DialogDescription>{t('expenses.newPolicyDesc')}</DialogDescription>
        </div>
        <div className="flex-1 min-h-0 overflow-y-auto">
          <Wizard
            key={resetKey}
            steps={steps}
            onComplete={handleComplete}
            onCancel={() => onOpenChange(false)}
            submitLabel={t('expenses.createPolicy')}
            showStepper={false}
          />
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { useMutation } from 'convex/react';
import { api } from '@/convex/_generated/api';
import { Id } from '@/convex/_generated/dataModel';
import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Wizard, WizardStep } from '@/components/ui/wizard';
import { TextInputStep, TextareaStep, SelectStep } from '@/components/ui/wizard-step-components';
import { FileText, Calendar, DollarSign } from 'lucide-react';

interface ReportWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizationId: Id<'organizations'>;
  userId: Id<'users'>;
  onSuccess?: () => void;
}

function ReportDetailsStep() {
  const { t } = useTranslation();

  return (
    <div className="space-y-4">
      <TextInputStep
        field="name"
        label={t('expenses.reportName')}
        placeholder={t('expenses.reportName')}
        required
      />
      <TextareaStep
        field="description"
        label={t('expenses.reportDescription')}
        placeholder={t('expenses.reportDescription')}
        rows={3}
      />
    </div>
  );
}

function ReportPeriodStep() {
  const { t } = useTranslation();

  return (
    <div className="space-y-4">
      <TextInputStep field="periodStart" label={t('expenses.periodStart')} type="date" required />
      <TextInputStep field="periodEnd" label={t('expenses.periodEnd')} type="date" required />
      <SelectStep
        field="currency"
        label={t('expenses.currency')}
        options={[
          { value: 'AMD', label: 'AMD' },
          { value: 'USD', label: 'USD' },
          { value: 'EUR', label: 'EUR' },
          { value: 'RUB', label: 'RUB' },
        ]}
        defaultValue="AMD"
      />
    </div>
