                          isActive
                            ? 'bg-sidebar-item-active shadow-sm text-sidebar-item-active-text'
                            : cn(
                                'text-sidebar-text',
                                hoveredItem === item.href
                                  ? 'bg-sidebar-item-hover'
                                  : 'bg-transparent',
