type Lesson = {
  _id: Id<'lessons'>;
  _creationTime: number;
  courseId: Id<'courses'>;
  title: string;
  description?: string;
  order: number;
  contentType: 'video' | 'text' | 'quiz' | 'mixed';
  videoUrl?: string;
  textContent?: string;
  durationMinutes?: number;
  isPreview?: boolean;
};

type QuizQuestion = {
  _id: string;
  questionText: string;
  questionType: 'multiple_choice' | 'true_false' | 'short_answer';
  options?: string[];
  correctAnswer?: string;
};

type QuizData = {
  quiz: {
    _id: Id<'quizzes'>;
    title: string;
    description?: string;
    passingScore?: number;
    timeLimitMinutes?: number;
  };
  questions: QuizQuestion[];
};

type QuizResult = {
  passed: boolean;
  score: number;
  attemptNumber: number;
};

interface LessonPlayerDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  lessons: Lesson[];
  activeLessonIndex: number;
  setActiveLessonIndex: (index: number) => void;
  lessonProgress: Record<string, boolean>;
  onCompleteLesson: () => void;
  onNextLesson: () => void;
  onPrevLesson: () => void;
  quizData: QuizData | null | undefined;
  showQuiz: boolean;
  setShowQuiz: (show: boolean) => void;
  quizSubmitted: boolean;
  setQuizSubmitted: (submitted: boolean) => void;
  quizResult: QuizResult | null;
  onSubmitQuiz: () => void;
  onAnswerChange: (questionId: string, answer: string) => void;
  userAnswers: Record<string, string>;
  onRetryQuiz: () => void;
  onBackToLesson: () => void;
}

export function LessonPlayerDialog({
  open,
  onOpenChange,
  lessons,
  activeLessonIndex,
  setActiveLessonIndex,
  lessonProgress,
  onCompleteLesson,
  onNextLesson,
  onPrevLesson,
  quizData,
  showQuiz,
  setShowQuiz,
  quizSubmitted,
  setQuizSubmitted,
  quizResult,
  onSubmitQuiz,
  onAnswerChange,
  userAnswers,
  onRetryQuiz,
  onBackToLesson,
}: LessonPlayerDialogProps) {
  const { t } = useTranslation();
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const currentLesson = lessons[activeLessonIndex];
  if (!currentLesson) return null;

  const ContentTypeIcon =
    currentLesson.contentType === 'video'
      ? Video
      : currentLesson.contentType === 'quiz'
        ? HelpCircle
        : FileText;

  const handleNextQuestion = () => {
    if (quizData && currentQuestionIndex < quizData.questions.length - 1) {
      setCurrentQuestionIndex((prev) => prev + 1);
    }
  };

  const handlePrevQuestion = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex((prev) => prev - 1);
    }
  };

  const handleStartQuiz = () => {
    setShowQuiz(true);
    setCurrentQuestionIndex(0);
    setQuizSubmitted(false);
  };

  const handleBackToLesson = () => {
    setShowQuiz(false);
    setQuizSubmitted(false);
    onBackToLesson();
  };

  const getEmbedUrl = (url: string): string => {
    if (!url) return url;
    const youtubeMatch = url.match(
      /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/,
    );
    if (youtubeMatch) {
      return `https://www.youtube.com/embed/${youtubeMatch[1]}`;
    }
    return url;
  };

  const sanitizeHtml = (html: string): string => {
    if (!html) return '';
    return html
      .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
      .replace(/<script[^>]*>.*?<\/script>/gi, '')
      .replace(/<object[^>]*>.*?<\/object>/gi, '')
      .replace(/<embed[^>]*>.*?<\/embed>/gi, '');
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[95vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            <span>{currentLesson.title}</span>
            <Badge variant="outline">
              {activeLessonIndex + 1} / {lessons.length}
            </Badge>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          {/* Lesson Content */}
          <div className="rounded-lg border overflow-hidden">
            {currentLesson.contentType === 'video' && currentLesson.videoUrl ? (
              <div className="aspect-video bg-black flex items-center justify-center">
                <iframe
                  src={getEmbedUrl(currentLesson.videoUrl)}
                  className="w-full h-full"
                  allowFullScreen
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  title={currentLesson.title}
                />
              </div>
            ) : currentLesson.contentType === 'text' ? (
              <div className="p-6 prose prose-sm dark:prose-invert max-w-none">
                {currentLesson.textContent && currentLesson.textContent.trim() ? (
                  <div
                    dangerouslySetInnerHTML={{
                      __html: sanitizeHtml(currentLesson.textContent),
                    }}
                  />
                ) : (
                  <div className="text-center py-8">
                    <FileText className="h-12 w-12 mx-auto mb-4 text-muted-foreground" />
                    <p className="text-muted-foreground">
                      {t('learning.noContent', 'No content available')}
                    </p>
                    <p className="text-sm text-muted-foreground mt-2">
                      {t('learning.contactAdmin', 'Contact your administrator to add content')}
                    </p>
                  </div>
                )}
              </div>
            ) : currentLesson.contentType === 'quiz' ? (
              <div className="p-6">
                {!showQuiz ? (
                  <div className="text-center space-y-4">
                    <HelpCircle className="h-12 w-12 mx-auto text-muted-foreground" />
                    <h3 className="text-lg font-medium">
                      {quizData?.quiz?.title || t('learning.quiz', 'Quiz')}
                    </h3>
                    <p className="text-sm text-muted-foreground">
                      {quizData?.quiz?.description ||
                        t('learning.quizDescription', 'Test your knowledge')}
                    </p>
                    {quizData?.quiz && (
                      <div className="flex items-center justify-center gap-4 text-sm">
                        <span className="text-muted-foreground">
                          {quizData.questions?.length || 0} {t('learning.questions', 'Questions')}
                        </span>
                        {quizData.quiz.passingScore && (
                          <>
                            <span>•</span>
                            <span>
                              {t('learning.passingScore', 'Passing Score')}:{' '}
                              {quizData.quiz.passingScore}%
                            </span>
                          </>
                        )}
                        {quizData.quiz.timeLimitMinutes && (
                          <>
                            <span>•</span>
                            <span>
                              {quizData.quiz.timeLimitMinutes} {t('learning.minutes', 'minutes')}
                            </span>
                          </>
                        )}
                      </div>
                    )}
                    <Button onClick={handleStartQuiz} disabled={!quizData}>
                      <Play className="h-4 w-4 mr-2" />
                      {t('learning.startQuiz', 'Start Quiz')}
                    </Button>
                  </div>
                ) : quizSubmitted && quizResult ? (
                  <div className="text-center space-y-4">
                    <div
                      className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center ${
                        quizResult.passed
                          ? 'bg-green-100 text-green-600 dark:bg-green-900 dark:text-green-400'
                          : 'bg-red-100 text-red-600 dark:bg-red-900 dark:text-red-400'
                      }`}
                    >
                      {quizResult.passed ? (
                        <CheckCircle2 className="h-8 w-8" />
                      ) : (
                        <X className="h-8 w-8" />
                      )}
                    </div>
                    <h3 className="text-lg font-medium">
                      {quizResult.passed
                        ? t('learning.quizPassed', 'Congratulations! You passed')
                        : t('learning.quizFailed', 'You did not pass')}
                    </h3>
                    <p className="text-3xl font-bold">{quizResult.score}%</p>
                    <p className="text-sm text-muted-foreground">
                      {t('learning.attempt', 'Attempt')} #{quizResult.attemptNumber}
                    </p>
                    <div className="flex items-center justify-center gap-2">
                      <Button variant="outline" onClick={handleBackToLesson}>
                        {t('learning.backToLesson', 'Back to Lesson')}
                      </Button>
                      {!quizResult.passed && (
                        <Button onClick={onRetryQuiz}>{t('learning.tryAgain', 'Try Again')}</Button>
                      )}
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {/* Question Header */}
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">
                        {t('learning.question', 'Question')} {currentQuestionIndex + 1}{' '}
                        {t('common.of', 'of')} {quizData?.questions?.length || 0}
                      </span>
                      <div className="flex gap-1">
                        {quizData?.questions?.map((_: QuizQuestion, idx: number) => (
                          <div
                            key={idx}
                            className={`w-2 h-2 rounded-full ${
                              idx === currentQuestionIndex
                                ? 'bg-primary'
                                : idx < currentQuestionIndex
                                  ? 'bg-primary/50'
                                  : 'bg-muted'
                            }`}
                          />
                        ))}
                      </div>
                    </div>

                    {/* Question */}
                    {quizData?.questions?.[currentQuestionIndex] &&
                      (() => {
                        const question = quizData.questions[currentQuestionIndex];
                        return (
                          <div className="space-y-4">
                            <h3 className="text-lg font-medium">{question.questionText}</h3>

                            {question.questionType === 'multiple_choice' &&
                              question.options?.map((option: string, optIdx: number) => (
                                <div
                                  key={optIdx}
                                  className={`p-4 rounded-lg border cursor-pointer transition-colors ${
                                    userAnswers[question._id] === option
                                      ? 'border-primary bg-primary/5'
                                      : 'hover:bg-muted/50'
                                  }`}
                                  onClick={() => onAnswerChange(question._id, option)}
                                >
                                  <div className="flex items-center gap-3">
                                    <div
                                      className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                                        userAnswers[question._id] === option
                                          ? 'border-primary bg-primary'
                                          : 'border-muted-foreground'
                                      }`}
                                    >
                                      {userAnswers[question._id] === option && (
                                        <div className="w-2 h-2 rounded-full bg-white" />
                                      )}
                                    </div>
                                    <span>{option}</span>
                                  </div>
                                </div>
                              ))}

                            {question.questionType === 'true_false' && (
                              <div className="grid grid-cols-2 gap-4">
                                {['True', 'False'].map((option) => (
                                  <div
                                    key={option}
                                    className={`p-4 rounded-lg border cursor-pointer text-center transition-colors ${
                                      userAnswers[question._id] === option
                                        ? 'border-primary bg-primary/5'
                                        : 'hover:bg-muted/50'
                                    }`}
                                    onClick={() => onAnswerChange(question._id, option)}
                                  >
                                    {option}
                                  </div>
                                ))}
                              </div>
                            )}

                            {question.questionType === 'short_answer' && (
                              <Input
                                value={userAnswers[question._id] || ''}
                                onChange={(e) => onAnswerChange(question._id, e.target.value)}
                                placeholder={t('learning.enterAnswer', 'Enter your answer')}
                              />
                            )}
                          </div>
                        );
                      })()}

                    {/* Question Navigation */}
                    <div className="flex items-center justify-between">
                      <Button
                        variant="outline"
                        onClick={handlePrevQuestion}
                        disabled={currentQuestionIndex === 0}
                      >
                        <ChevronLeft className="h-4 w-4 mr-2" />
                        {t('learning.previous', 'Previous')}
                      </Button>

                      {currentQuestionIndex < (quizData?.questions?.length || 0) - 1 ? (
                        <Button onClick={handleNextQuestion}>
                          {t('learning.next', 'Next')}
                          <ChevronRight className="h-4 w-4 ml-2" />
                        </Button>
                      ) : (
                        <Button
                          onClick={onSubmitQuiz}
                          disabled={Object.keys(userAnswers).length === 0}
                        >
                          {t('learning.submitQuiz', 'Submit Quiz')}
                        </Button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="p-6 text-center">
                <ContentTypeIcon className="h-12 w-12 mx-auto mb-4 text-muted-foreground" />
                <p className="text-muted-foreground">
                  {t('learning.noContent', 'No content available')}
                </p>
              </div>
            )}
          </div>

          {/* Lesson Description */}
          {currentLesson.description && (
            <div>
              <h3 className="font-medium mb-2">{t('learning.aboutLesson', 'About this lesson')}</h3>
              <p className="text-sm text-muted-foreground">{currentLesson.description}</p>
            </div>
          )}

          {/* Navigation */}
          <div className="flex items-center justify-between">
            <Button variant="outline" onClick={onPrevLesson} disabled={activeLessonIndex === 0}>
              <ChevronLeft className="h-4 w-4 mr-2" />
              {t('learning.previousLesson', 'Previous')}
            </Button>

            <Button onClick={onCompleteLesson}>
              <CheckCircle2 className="h-4 w-4 mr-2" />
              {t('learning.completeLesson', 'Complete & Continue')}
            </Button>

            <Button
              variant="outline"
              onClick={onNextLesson}
              disabled={activeLessonIndex >= lessons.length - 1}
            >
              {t('learning.nextLesson', 'Next')}
              <ChevronRight className="h-4 w-4 ml-2" />
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useTranslation } from 'react-i18next';
import React from 'react';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Brain,
  TrendingUp,
  TrendingDown,
  AlertCircle,
  CheckCircle,
  Minus,
  Calendar,
  Users,
  Briefcase,
} from 'lucide-react';
import { Progress } from '@/components/ui/progress';
import type { Id } from '../../../convex/_generated/dataModel';

interface AILeaveAssistantProps {
  leaveRequestId: Id<'leaveRequests'>;
  userId: Id<'users'>;
  onApprove?: (comment?: string) => void;
  onReject?: (comment?: string) => void;
}

export default function AILeaveAssistant({
  leaveRequestId,
  userId,
  onApprove,
  onReject,
}: AILeaveAssistantProps) {
  const { t } = useTranslation();
  const evaluation = useQuery(api.aiEvaluator.evaluateLeaveRequest, { leaveRequestId });

  // Загружаем информацию о заявке на отпуск для проверки конфликтов
  const leaveRequest = useQuery(api.leaves.getAllLeaves, userId && userId !== '' ? {} : 'skip');
  const currentLeave = leaveRequest?.find((l) => l._id === leaveRequestId);

  // Проверяем конфликты через Conflict Service
  const conflicts = useQuery(
    api.conflicts.detectAllConflicts,
    currentLeave?.organizationId
      ? {
          organizationId: currentLeave.organizationId,
          startDate: new Date(currentLeave.startDate).getTime(),
          endDate: new Date(currentLeave.endDate).getTime(),
          userId: currentLeave.userId,
        }
      : 'skip',
  );

  if (!evaluation) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center gap-3">
            <Brain className="w-5 h-5 text-(--text-muted) animate-pulse" />
            <p className="text-sm text-(--text-muted)">
              {t('aiLeave.analyzing', 'AI analyzing request...')}
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  const { leaveEligibilityScore, breakdown, recommendation, confidence, reasoning } = evaluation;

  // Фильтруем конфликты, относящиеся к этой заявке
  const leaveConflicts =
    conflicts?.filter(
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (c: any) =>
        c.affectedUsers?.includes(currentLeave?.userId) ||
        c.affectedDepartments?.includes(currentLeave?.userDepartment),
    ) || [];

  const criticalConflicts = leaveConflicts.filter((c) => c.severity === 'critical');
  const warningConflicts = leaveConflicts.filter((c) => c.severity === 'warning');

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-600';
    if (score >= 60) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getRecommendationBadge = () => {
    if (recommendation === 'APPROVE') {
      return (
        <Badge variant="success" className="flex items-center gap-1">
          <CheckCircle className="w-3 h-3" /> {t('aiLeave.approve')}
        </Badge>
      );
    } else if (recommendation === 'REVIEW') {
      return (
        <Badge variant="warning" className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3" /> {t('aiLeave.review')}
        </Badge>
      );
    } else {
      return (
        <Badge variant="destructive" className="flex items-center gap-1">
          <Minus className="w-3 h-3" /> {t('aiLeave.reject')}
        </Badge>
      );
    }
  };

  return (
    <Card className="border-2 border-(--primary)/20">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <Brain className="w-5 h-5 text-(--primary)" />
            {t('aiFeatures.aiLeaveAssistant')}
          </CardTitle>
          {getRecommendationBadge()}
        </div>
        <div className="flex items-center gap-2 mt-2">
          <span className="text-sm text-(--text-muted)">{t('aiLeave.confidence')}:</span>
          <Badge
            variant={
              confidence === 'HIGH'
                ? 'success'
                : confidence === 'MEDIUM'
                  ? 'warning'
                  : 'destructive'
            }
          >
            {confidence}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* ═══════════════════════════════════════════════════════════════
            CONFLICT ALERTS — Новый раздел с конфликтами
            ═══════════════════════════════════════════════════════════════ */}
        {leaveConflicts.length > 0 && (
          <div className="space-y-3">
            {/* Critical Conflicts */}
            {criticalConflicts.length > 0 && (
              <div className="p-3 rounded-lg border-2 border-red-500/30 bg-red-500/5 space-y-2">
                <div className="flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 text-red-600" />
                  <span className="text-sm font-semibold text-red-700">
                    {t('aiLeave.criticalConflicts', { count: criticalConflicts.length })}
                  </span>
                </div>
                {criticalConflicts.map((conflict: any, idx: number) => (
                  <div key={idx} className="text-sm">
                    <p className="font-medium text-red-800">{conflict.title}</p>
                    <p className="text-red-700 mt-1">{conflict.message}</p>
                    <div className="flex items-start gap-1 mt-2 text-red-600">
                      <Briefcase className="w-3 h-3 mt-0.5 shrink-0" />
                      <p className="text-xs">{conflict.suggestion}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Warning Conflicts */}
            {warningConflicts.length > 0 && (
              <div className="p-3 rounded-lg border border-yellow-500/30 bg-yellow-500/5 space-y-2">
                <div className="flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 text-yellow-600" />
                  <span className="text-sm font-semibold text-yellow-700">
                    {t('aiLeave.warnings', { count: warningConflicts.length })}
                  </span>
                </div>
                {warningConflicts.map((conflict: any, idx: number) => (
                  <div key={idx} className="text-sm">
                    <p className="font-medium text-yellow-800">{conflict.title}</p>
                    <p className="text-yellow-700 mt-1">{conflict.message}</p>
                    <div className="flex items-start gap-1 mt-2 text-yellow-600">
                      <Briefcase className="w-3 h-3 mt-0.5 shrink-0" />
                      <p className="text-xs">{conflict.suggestion}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* No Conflicts Message */}
        {leaveConflicts.length === 0 && (
          <div className="p-3 rounded-lg border border-green-500/30 bg-green-500/5">
            <div className="flex items-center gap-2">
              <CheckCircle className="w-4 h-4 text-green-600" />
              <span className="text-sm font-medium text-green-700">{t('aiLeave.noConflicts')}</span>
            </div>
            <p className="text-xs text-green-600 mt-1">{t('aiLeave.noConflictsDesc')}</p>
          </div>
        )}

        {/* Overall Score */}
        <div>
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium">{t('aiLeave.eligibilityScore')}</span>
            <span className={`text-2xl font-bold ${getScoreColor(leaveEligibilityScore)}`}>
              {leaveEligibilityScore}/100
            </span>
          </div>
          <Progress value={leaveEligibilityScore} className="h-2" />
        </div>

        {/* Breakdown */}
        <div className="grid grid-cols-2 gap-3 text-sm">
          <div>
            <div className="flex items-center justify-between mb-1">
              <span className="text-(--text-muted)">{t('aiLeave.performance', 'Performance')}</span>
              <span className={`font-medium ${getScoreColor(breakdown.performance.score)}`}>
                {breakdown.performance.score}%
              </span>
            </div>
            <Progress value={breakdown.performance.score} className="h-1.5" />
          </div>
          <div>
            <div className="flex items-center justify-between mb-1">
              <span className="text-(--text-muted)">{t('aiLeave.attendance', 'Attendance')}</span>
              <span className={`font-medium ${getScoreColor(breakdown.attendance.score)}`}>
                {breakdown.attendance.score}%
              </span>
            </div>
            <Progress value={breakdown.attendance.score} className="h-1.5" />
          </div>
          <div>
            <div className="flex items-center justify-between mb-1">
              <span className="text-(--text-muted)">{t('aiLeave.behavior', 'Behavior')}</span>
              <span className={`font-medium ${getScoreColor(breakdown.behavior.score)}`}>
                {breakdown.behavior.score}%
              </span>
            </div>
            <Progress value={breakdown.behavior.score} className="h-1.5" />
          </div>
          <div>
            <div className="flex items-center justify-between mb-1">
              <span className="text-(--text-muted)">{t('aiLeave.workload', 'Workload')}</span>
              <span className={`font-medium ${getScoreColor(breakdown.workload.score)}`}>
                {breakdown.workload.score}%
              </span>
            </div>
            <Progress value={breakdown.workload.score} className="h-1.5" />
          </div>
        </div>

        {/* AI Reasoning */}
        <div className="pt-3 border-t border-(--border)">
          <h4 className="text-sm font-medium mb-2 flex items-center gap-1">
            <Brain className="w-4 h-4" />
            {t('aiFeatures.aiAnalysis')}
          </h4>
          <p className="text-sm text-(--text-muted) leading-relaxed">
            {t(`aiLeave.reasoning.${reasoning}`, reasoning)}
          </p>
        </div>

        {/* Key Factors */}
        <div className="space-y-2">
          <h4 className="text-sm font-medium">{t('aiLeave.keyFactors', 'Key Factors')}</h4>
          <div className="space-y-1.5">
            {(() => {
              const allFactors = [
                ...breakdown.performance.factors.slice(0, 2),
                ...breakdown.workload.factors.slice(0, 1),
              ];
              const negativeKeys = ['understaffed', 'disciplinaryConcerns'];
              const warningKeys = [
                'below',
                'some',
                'occasional',
                'attendanceConcerns',
                'lateArrivals',
                'highAbsence',
                'limited',
                'teamworkCould',
                'noLeave',
                'lowLeave',
                'teamMember',
              ];
              return allFactors.map((factor: string, i: number) => {
                let icon = <CheckCircle className="w-3 h-3 text-green-600 mt-0.5 shrink-0" />;
                if (negativeKeys.includes(factor)) {
                  icon = <Minus className="w-3 h-3 text-red-600 mt-0.5 shrink-0" />;
                } else if (warningKeys.some((k) => factor.includes(k))) {
                  icon = <AlertCircle className="w-3 h-3 text-yellow-600 mt-0.5 shrink-0" />;
                }
                return (
                  <div key={i} className="flex items-start gap-2 text-xs">
                    {icon}
                    <span className="text-(--text-muted)">
                      {t(`aiLeave.factors.${factor}`, factor)}
                    </span>
                  </div>
                );
              });
            })()}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * Create Leave Wizard - Пошаговая форма создания заявки на отпуск
 * Использует универсальный Wizard компонент
 */

'use client';

import React from 'react';
import { useTranslation } from 'react-i18next';
import { Wizard, WizardStep } from '@/components/ui/wizard';
import {
  CardSelectionStep,
  TextInputStep,
  TextareaStep,
} from '@/components/ui/wizard-step-components';
import {
  Calendar,
  Sun,
  Heart,
  Users,
  Briefcase,
  CheckCircle,
  Baby,
  BookOpen,
  Coffee,
} from 'lucide-react';
import { useMutation, useQuery } from 'convex/react';
import { api } from '@/convex/_generated/api';
import type { Id } from '@/convex/_generated/dataModel';
import { toast } from 'sonner';
import type { LeaveType } from '@/lib/types';

interface CreateLeaveWizardProps {
  userId: Id<'users'>;
  onComplete?: () => void;
  onCancel?: () => void;
}

export function CreateLeaveWizard({ userId, onComplete, onCancel }: CreateLeaveWizardProps) {
  const { t } = useTranslation();
