// ── Create Announcement Dialog ───────────────────────────────────────────────

function CreateAnnouncementDialog({
  open,
  onClose,
  organizationId,
  userId,
}: {
  open: boolean;
  onClose: () => void;
  organizationId: Id<'organizations'>;
  userId: Id<'users'>;
}) {
  const { t } = useTranslation();
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [category, setCategory] = useState<string>('announcement');
  const [isPinned, setIsPinned] = useState(false);
  const [isUrgent, setIsUrgent] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const createAnnouncement = useMutation(api.news.createAnnouncement);

  const handleSubmit = async () => {
    if (!title.trim() || !content.trim()) {
      toast.error(t('news.errors.fillRequired'));
      return;
    }
    setSubmitting(true);
    try {
      await createAnnouncement({
        organizationId,
        authorId: userId,
        title: title.trim(),
        content: content.trim(),
        category: category as
          | 'news'
          | 'announcement'
          | 'event'
          | 'birthday'
          | 'achievement'
          | 'policy'
          | 'general',
        isPinned,
        isUrgent,
      });
      toast.success(t('news.announcementCreated'));
      setTitle('');
      setContent('');
      setCategory('announcement');
      setIsPinned(false);
      setIsUrgent(false);
      onClose();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : t('common.error'));
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Megaphone className="w-5 h-5 text-purple-500" />
            {t('news.createAnnouncement')}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <label className="text-sm font-medium mb-1 block">{t('news.title')}</label>
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={t('news.titlePlaceholder')}
              maxLength={200}
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-sm font-medium mb-1 block">
                {t('news.selectCategory', 'Category')}
              </label>
              <Select value={category} onValueChange={setCategory}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(CATEGORY_CONFIG).map(([key, cfg]) => {
                    const Icon = cfg.icon;
                    return (
                      <SelectItem key={key} value={key}>
                        <div className="flex items-center gap-2">
                          <Icon className="w-4 h-4" style={{ color: cfg.color }} />
                          <span>{t(cfg.labelKey)}</span>
                        </div>
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">{t('news.options')}</label>
              <div className="flex gap-2 pt-1">
                <button
                  type="button"
                  onClick={() => setIsPinned(!isPinned)}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${
                    isPinned
                      ? 'bg-amber-500/10 border-amber-500/30 text-amber-600'
                      : 'border-border text-muted-foreground hover:bg-muted'
                  }`}
                >
                  <Pin className="w-3 h-3" />
                  {t('news.pin')}
                </button>
                <button
                  type="button"
                  onClick={() => setIsUrgent(!isUrgent)}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${
                    isUrgent
                      ? 'bg-red-500/10 border-red-500/30 text-red-600'
                      : 'border-border text-muted-foreground hover:bg-muted'
                  }`}
                >
                  <Zap className="w-3 h-3" />
                  {t('news.urgent')}
                </button>
              </div>
            </div>
          </div>

          <div>
            <label className="text-sm font-medium mb-1 block">{t('news.content')}</label>
            <Textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder={t('news.contentPlaceholder')}
              rows={6}
              maxLength={5000}
            />
            <p className="text-xs text-muted-foreground mt-1 text-right">{content.length}/5000</p>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={submitting}>
            {t('common.cancel')}
          </Button>
          <Button onClick={handleSubmit} disabled={submitting} className="gap-1.5">
            <Send className="w-4 h-4" />
            {submitting ? t('common.publishing') : t('news.publish')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ── Comment Section ─────────────────────────────────────────────────────────

function CommentSection({
  announcementId,
  comments,
  totalComments,
  organizationId,
  userId,
  isExpanded,
  onToggle,
  t,
}: {
  announcementId: Id<'announcements'>;
  comments: {
    _id: string;
    authorName: string;
    authorAvatar?: string;
    content: string;
    createdAt: number;
  }[];
  totalComments: number;
  organizationId: Id<'organizations'>;
  userId: Id<'users'>;
  isExpanded: boolean;
  onToggle: () => void;
  t: (key: string, options?: Record<string, unknown>) => string;
}) {
  const [newComment, setNewComment] = useState('');
  const addComment = useMutation(api.news.addComment);

  const handleSubmit = async () => {
    if (!newComment.trim()) return;
    try {
      await addComment({
        organizationId,
        announcementId,
        authorId: userId,
        content: newComment.trim(),
      });
      setNewComment('');
      toast.success(t('news.commentAdded'));
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : t('common.error'));
    }
  };

  return (
    <div className="mt-3">
      {/* Comment input */}
      <div className="flex gap-2">
        <Input
          value={newComment}
          onChange={(e) => setNewComment(e.target.value)}
          placeholder={t('news.writeComment')}
          className="text-sm h-9"
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              handleSubmit();
            }
          }}
        />
        <Button
          size="sm"
          variant="ghost"
          onClick={handleSubmit}
          disabled={!newComment.trim()}
          className="h-9 w-9 p-0"
        >
          <Send className="w-4 h-4" />
        </Button>
      </div>

      {/* Comments list */}
      {comments.length > 0 && (
        <div className="mt-2 space-y-2">
          {comments.map((comment) => (
            <div key={comment._id} className="flex gap-2 text-sm">
              <Avatar className="w-6 h-6 shrink-0 mt-0.5">
                <AvatarImage src={comment.authorAvatar} />
                <AvatarFallback className="text-[8px]">
                  {comment.authorName?.slice(0, 2).toUpperCase()}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <span className="font-medium text-xs">{comment.authorName}</span>
                  <span className="text-[10px] text-muted-foreground">
                    {format(comment.createdAt, 'MMM d, HH:mm')}
                  </span>
                </div>
                <p className="text-xs text-muted-foreground mt-0.5">{comment.content}</p>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Show more comments link */}
      {totalComments > comments.length && !isExpanded && (
        <button
          onClick={onToggle}
          className="text-xs text-primary hover:underline mt-1 flex items-center gap-1"
        >
          <MessageCircle className="w-3 h-3" />
          {t('news.viewAllComments', { count: totalComments })}
        </button>
      )}
    </div>
  );
}

