  },
  approved: {
    color: 'text-emerald-500',
    bg: 'bg-emerald-500/10',
    border: 'border-emerald-500/30',
    icon: CheckCircle2,
    labelKey: 'payroll.approved',
  },
  paid: {
    color: 'text-green-600',
    bg: 'bg-green-500/15',
    border: 'border-green-500/40',
    icon: CheckCircle2,
    labelKey: 'payroll.paid',
