// ── Urgency config ──
const URGENCY_CONFIG = {
  critical: {
    icon: XCircle,
    color: 'text-red-500',
    bg: 'bg-red-500/10 dark:bg-red-500/20',
    border: 'border-red-500/30 dark:border-red-500/40',
