              )}
              <Badge variant="outline" className="text-[10px]">
                {currency}
              </Badge>
            </div>
          </div>
        </div>
      </div>

      <div className="flex items-center gap-2 print:hidden">
        <Button variant="outline" size="sm" className="gap-2" onClick={() => window.print()}>
          <Printer className="w-4 h-4" />
          Print
