                  {t('settingsAdvancedSecurity.securityTip')}
                </p>
                <p className="text-xs text-(--text-muted) mt-1">
                  {t('settingsAdvancedSecurity.securityTipDesc')}
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
