'use client';

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Eye, RefreshCw, Home } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';

interface DashboardCustomizationProps {
  user: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  onSettingsChange: (settings: any) => void;
}

export function DashboardCustomization({ user, onSettingsChange }: DashboardCustomizationProps) {
  const { t } = useTranslation();

  const defaultWidgets = {
    quickStats: true,
    leaveCalendar: true,
    upcomingTasks: true,
    teamActivity: true,
    recentLeaves: false,
    analytics: true,
  };

  const [defaultView, setDefaultView] = useState(user?.defaultView ?? 'dashboard');
  const [refreshRate, setRefreshRate] = useState(user?.dataRefreshRate ?? 'realtime');
  const [compactMode, setCompactMode] = useState(user?.compactMode ?? false);

  const [widgets, setWidgets] = useState(user?.dashboardWidgets ?? defaultWidgets);

  // Update parent when settings change
  useEffect(() => {
    onSettingsChange({
      defaultView,
      dataRefreshRate: refreshRate,
      compactMode,
      dashboardWidgets: widgets,
    });
  }, [defaultView, refreshRate, compactMode, widgets]);

  // Sync when user data changes
  useEffect(() => {
    if (user) {
      setDefaultView(user.defaultView ?? 'dashboard');
      setRefreshRate(user.dataRefreshRate ?? 'realtime');
      setCompactMode(user.compactMode ?? false);
      setWidgets(user.dashboardWidgets ?? defaultWidgets);
    }
  }, [user?.defaultView, user?.dataRefreshRate, user?.compactMode, user?.dashboardWidgets]);

  const toggleWidget = (key: keyof typeof widgets) => {
    setWidgets((prev: Record<string, boolean>) => ({
      ...prev,
      [key as string]: !prev[key as string],
    }));
  };

  return (
    <div className="space-y-6">
      {/* Default View */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Home className="w-5 h-5 text-(--primary)" />
            <CardTitle>{t('settingsDashboard.defaultLandingPage')}</CardTitle>
          </div>
          <CardDescription>{t('settingsDashboard.defaultLandingPageDesc')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="default-view">{t('settingsDashboard.landingPage')}</Label>
            <Select value={defaultView} onValueChange={setDefaultView}>
              <SelectTrigger id="default-view">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="dashboard">📊 {t('nav.dashboard')}</SelectItem>
                <SelectItem value="tasks">✓ {t('nav.tasks')}</SelectItem>
                <SelectItem value="calendar">📅 {t('nav.calendar')}</SelectItem>
                <SelectItem value="leaves">📋 {t('nav.leaves')}</SelectItem>
                <SelectItem value="attendance">⏰ {t('nav.attendance')}</SelectItem>
                <SelectItem value="analytics">📈 {t('nav.analytics')}</SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-(--text-muted)">
              {t('settingsDashboard.redirectAfterLogin')}
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Widget Configuration */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <LayoutDashboard className="w-5 h-5 text-(--primary)" />
            <CardTitle>{t('settingsDashboard.dashboardWidgets')}</CardTitle>
          </div>
          <CardDescription>{t('settingsDashboard.dashboardWidgetsDesc')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {Object.entries(widgets).map(([key, enabled]) => {
            const widgetLabels: Record<string, { name: string; desc: string; emoji: string }> = {
              quickStats: {
                name: t('settingsDashboard.quickStatistics'),
                desc: t('settingsDashboard.quickStatisticsDesc'),
                emoji: '📊',
              },
              leaveCalendar: {
                name: t('settingsDashboard.leaveCalendar'),
                desc: t('settingsDashboard.leaveCalendarDesc'),
                emoji: '📅',
              },
              upcomingTasks: {
                name: t('settingsDashboard.upcomingTasks'),
                desc: t('settingsDashboard.upcomingTasksDesc'),
                emoji: '✓',
              },
              teamActivity: {
                name: t('settingsDashboard.teamActivity'),
                desc: t('settingsDashboard.teamActivityDesc'),
                emoji: '👥',
              },
              recentLeaves: {
                name: t('settingsDashboard.recentLeaves'),
                desc: t('settingsDashboard.recentLeavesDesc'),
                emoji: '📋',
              },
              analytics: {
                name: t('settingsDashboard.analyticsChart'),
                desc: t('settingsDashboard.analyticsChartDesc'),
                emoji: '📈',
              },
            };

            const widget = widgetLabels[key];
            if (!widget) return null;

            return (
              <div key={key}>
                <div className="flex items-center justify-between py-3">
                  <div className="flex items-start gap-3">
                    <span className="text-2xl">{widget.emoji}</span>
                    <div>
                      <p className="text-sm font-medium text-(--text-primary)">{widget.name}</p>
                      <p className="text-xs text-(--text-muted) mt-0.5">{widget.desc}</p>
                    </div>
                  </div>
                  <Switch
                    checked={enabled as boolean}
                    onCheckedChange={() => toggleWidget(key as keyof typeof widgets)}
                  />
                </div>
                {key !== 'analytics' && <div className="border-b border-(--border) mt-3" />}
              </div>
            );
          })}
        </CardContent>
      </Card>

      {/* Display & Performance */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Eye className="w-5 h-5 text-(--primary)" />
            <CardTitle>{t('settingsDashboard.displayPerformance')}</CardTitle>
          </div>
          <CardDescription>{t('settingsDashboard.displayPerformanceDesc')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between p-4 rounded-lg bg-(--surface-hover) border border-(--border)">
            <div className="flex items-start gap-3">
              <span className="text-2xl">📐</span>
              <div>
                <p className="text-sm font-medium text-(--text-primary)">
                  {t('settingsDashboard.compactMode')}
                </p>
                <p className="text-xs text-(--text-muted) mt-0.5">
                  {t('settingsDashboard.compactModeDesc')}
                </p>
              </div>
            </div>
            <Switch checked={compactMode} onCheckedChange={setCompactMode} />
          </div>

          <div className="space-y-2">
            <Label htmlFor="refresh-rate">{t('settingsDashboard.dataRefreshRate')}</Label>
            <Select value={refreshRate} onValueChange={setRefreshRate}>
              <SelectTrigger id="refresh-rate">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="realtime">
                  ⚡ {t('settingsDashboard.realtimeUpdates')}
                </SelectItem>
                <SelectItem value="5min">🔄 {t('settingsDashboard.every5Minutes')}</SelectItem>
                <SelectItem value="15min">⏱️ {t('settingsDashboard.every15Minutes')}</SelectItem>
                <SelectItem value="30min">⏰ {t('settingsDashboard.every30Minutes')}</SelectItem>
                <SelectItem value="manual">
                  🤚 {t('settingsDashboard.manualRefreshOnly')}
                </SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-(--text-muted)">
              {refreshRate === 'realtime'
                ? t('settingsDashboard.dataUpdatesInstantly')
                : refreshRate === 'manual'
                  ? t('settingsDashboard.refreshDataManually')
                  : t('settingsDashboard.dataRefreshesEvery', {
                      interval: refreshRate.replace('min', ' minutes'),
                    })}
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Calendar,
  Mail,
  MessageSquare,
  Download,
  Cloud,
  Check,
  Clock,
  Users,
  RefreshCw,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useSearchParams, useRouter } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { logger } from '@/lib/logger';
import { getGoogleCalendarAuthUrl } from '@/lib/calendar-sync';
import { ShieldLoader } from '@/components/ui/ShieldLoader';
import { useAuthStoreShallow } from '@/store/useAuthStore';
import { isRestrictedOrganization } from '@/lib/restricted-org';
import { useSelectedOrganization } from '@/hooks/useSelectedOrganization';

export function IntegrationSettings() {
  const { t } = useTranslation();
  const searchParams = useSearchParams();
  const router = useRouter();
  const { user } = useAuthStoreShallow();
  const selectedOrgId = useSelectedOrganization();
  const activeOrganizationId = selectedOrgId ?? user?.organizationId;

  const isRestrictedOrg = user?.organizationSlug
    ? isRestrictedOrganization(user.organizationSlug)
    : false;

  // Debug logging
  logger.log('[IntegrationSettings] User data:', {
    id: user?.id,
    name: user?.name,
    organizationId: user?.organizationId,
    organizationSlug: user?.organizationSlug,
    organizationName: user?.organizationName,
    isRestrictedOrg,
  });

  const [googleConnected, setGoogleConnected] = useState(false);
  const [googleEmail, setGoogleEmail] = useState<string | null>(null);
  const [googleLoading, setGoogleLoading] = useState(true);
  const [disconnecting, setDisconnecting] = useState(false);
  const [emailReports, setEmailReports] = useState(true);
  const [slackNotifications, setSlackNotifications] = useState(false);

  // SharePoint state
  const [sharepointConnected, setSharepointConnected] = useState(false);
  const [sharepointEmail, setSharepointEmail] = useState<string | null>(null);
  const [sharepointLoading, setSharepointLoading] = useState(true);
  const [sharepointSyncing, setSharepointSyncing] = useState(false);
  const [sharepointDisconnecting, setSharepointDisconnecting] = useState(false);

  // Check Google Calendar connection status
  const checkGoogleStatus = useCallback(async () => {
    try {
      const res = await fetch('/api/calendar/google/status');
      const data = await res.json();
      setGoogleConnected(data.connected);
      setGoogleEmail(data.email || null);
    } catch {
      setGoogleConnected(false);
    } finally {
      setGoogleLoading(false);
    }
  }, []);

  useEffect(() => {
    checkGoogleStatus();
  }, [checkGoogleStatus]);

  // Handle OAuth callback result
  useEffect(() => {
    const status = searchParams.get('google_calendar');
    if (status === 'connected') {
      toast.success(t('settingsIntegration.googleCalendarConnected'));
      checkGoogleStatus();
    } else if (status === 'error') {
      toast.error(t('settingsIntegration.googleCalendarError'));
    }
  }, [searchParams, t, checkGoogleStatus]);

  const handleGoogleConnect = () => {
    try {
      const redirectUri = `${window.location.origin}/api/calendar/google/callback`;
      const authUrl = getGoogleCalendarAuthUrl(redirectUri);
      window.location.href = authUrl;
    } catch {
      toast.error(t('settingsIntegration.googleNotConfigured'));
    }
  };

  const handleGoogleDisconnect = async () => {
    setDisconnecting(true);
    try {
      await fetch('/api/calendar/google/disconnect', { method: 'POST' });
      setGoogleConnected(false);
      setGoogleEmail(null);
      toast.success(t('settingsIntegration.googleCalendarDisconnected'));
    } catch {
      toast.error(t('settingsIntegration.disconnectError'));
    } finally {
      setDisconnecting(false);
    }
  };

  // ── SharePoint status & handlers ──────────────────────────────────────────
  const checkSharepointStatus = useCallback(async () => {
    try {
      const res = await fetch('/api/sharepoint/status');
      const data = await res.json();
      setSharepointConnected(data.connected);
      setSharepointEmail(data.email || null);
    } catch {
      setSharepointConnected(false);
    } finally {
      setSharepointLoading(false);
    }
  }, []);

  useEffect(() => {
    checkSharepointStatus();
  }, [checkSharepointStatus]);

  // Handle SharePoint OAuth callback result
  useEffect(() => {
    const status = searchParams.get('sharepoint');
    if (status === 'connected') {
      toast.success(t('toasts.sharePointConnected'));
      checkSharepointStatus();
    } else if (status === 'error') {
      toast.error(t('toasts.sharePointConnectFailed'));
    }
  }, [searchParams, checkSharepointStatus]);

  const handleSharepointConnect = () => {
    router.push('/api/sharepoint/auth');
  };

  const handleSharepointDisconnect = async () => {
    setSharepointDisconnecting(true);
    try {
      await fetch('/api/sharepoint/disconnect', { method: 'POST' });
      setSharepointConnected(false);
      setSharepointEmail(null);
      toast.success(t('toasts.sharePointDisconnected'));
    } catch {
      toast.error(t('toasts.sharePointDisconnectFailed'));
    } finally {
      setSharepointDisconnecting(false);
    }
  };

  const handleSharepointSync = async () => {
    setSharepointSyncing(true);
    try {
      // We need adminId and organizationId — read from localStorage or session
      const storedUser = localStorage.getItem('currentUser');
      if (!storedUser) {
        toast.error(t('toasts.pleaseLoginAgain'));
        return;
      }
      const user = JSON.parse(storedUser);
      const res = await fetch('/api/sharepoint/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          adminId: user._id,
          organizationId: activeOrganizationId ?? user.organizationId,
        }),
      });
      const data = await res.json();

      if (!res.ok) {
        toast.error(data.error || t('settings.syncFailed'));
        return;
      }

      toast.success(
        `Sync complete: ${data.created} created, ${data.updated} updated, ${data.deactivated} deactivated` +
          (data.errors?.length ? `, ${data.errors.length} errors` : ''),
      );
    } catch {
      toast.error(t('toasts.sharePointSyncFailed'));
    } finally {
      setSharepointSyncing(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Calendar Integrations */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Calendar className="w-5 h-5 text-(--primary)" />
            <CardTitle>{t('settingsIntegration.title')}</CardTitle>
          </div>
