                </div>
                <p className="text-xs text-(--text-muted) mt-1">
                  {t('settingsIntegration.googleCalendarDesc')}
                </p>
                {googleConnected && googleEmail && (
                  <p className="text-xs text-(--text-muted) mt-1">{googleEmail}</p>
                )}
              </div>
            </div>
            {googleLoading ? (
              <ShieldLoader size="xs" variant="inline" />
            ) : googleConnected ? (
              <Button
                variant="outline"
                size="sm"
                onClick={handleGoogleDisconnect}
                disabled={disconnecting}
              >
                {disconnecting ? <ShieldLoader size="xs" variant="inline" /> : null}
                {t('settingsIntegration.disconnect')}
              </Button>
            ) : (
              <Button variant="default" size="sm" onClick={handleGoogleConnect}>
                {t('settingsIntegration.connect')}
              </Button>
            )}
          </div>

          {/* Outlook Calendar — RESTRICTED TO ADB-ARRM ONLY */}
          {isRestrictedOrg && (
            <div className="flex flex-col sm:flex-row flex-wrap gap-3 items-start justify-between p-4 rounded-lg bg-(--surface-hover) border border-(--border) opacity-70">
              <div className="flex items-start gap-3 flex-1">
                <div className="w-10 h-10 rounded-lg bg-blue-600/10 flex items-center justify-center">
                  <Calendar className="w-5 h-5 text-blue-600" />
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm font-medium text-(--text-primary)">
                      {t('settingsIntegration.outlookCalendar')}
                    </p>
                    <Badge variant="outline" className="text-xs gap-1">
                      <Clock className="w-3 h-3" />
                      {t('settingsIntegration.comingSoon')}
                    </Badge>
                  </div>
                  <p className="text-xs text-(--text-muted) mt-1">
                    {t('settingsIntegration.outlookCalendarDesc')}
                  </p>
                </div>
              </div>
              <Button variant="default" size="sm" disabled>
                {t('settingsIntegration.connect')}
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* SharePoint Employee Sync — RESTRICTED TO ADB-ARRM ONLY */}
      {isRestrictedOrg && (
        <Card>
          <CardHeader>
            <div className="flex items-center gap-2">
              <Users className="w-5 h-5 text-(--primary)" />
              <CardTitle>
                {t('settingsIntegration.sharepointEmployeeSync') || 'SharePoint Employee Sync'}
              </CardTitle>
            </div>
            <CardDescription>
              {t('settingsIntegration.sharepointSyncDesc') ||
                'Sync employee list from SharePoint to keep your team roster up to date'}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex flex-col sm:flex-row flex-wrap gap-3 items-start justify-between p-4 rounded-lg bg-(--surface-hover) border border-(--border)">
              <div className="flex items-start gap-3 flex-1">
                <div className="w-10 h-10 rounded-lg bg-teal-500/10 flex items-center justify-center">
                  <Users className="w-5 h-5 text-teal-500" />
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm font-medium text-(--text-primary)">
                      {t('settingsIntegration.microsoftSharePoint') || 'Microsoft SharePoint'}
                    </p>
                    {sharepointConnected && (
                      <Badge variant="default" className="text-xs gap-1">
                        <Check className="w-3 h-3" />
                        {t('settingsIntegration.connected')}
                      </Badge>
                    )}
                  </div>
                  <p className="text-xs text-(--text-muted) mt-1">
                    {t('settingsIntegration.sharepointAutoSync') ||
                      'Automatically sync employees from your SharePoint List'}
                  </p>
                  {sharepointConnected && sharepointEmail && (
                    <p className="text-xs text-(--text-muted) mt-1">{sharepointEmail}</p>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-2">
                {sharepointLoading ? (
                  <ShieldLoader size="xs" variant="inline" />
                ) : sharepointConnected ? (
                  <>
                    <Button
                      variant="default"
                      size="sm"
                      onClick={handleSharepointSync}
                      disabled={sharepointSyncing}
                    >
                      {sharepointSyncing ? (
                        <ShieldLoader size="xs" variant="inline" />
                      ) : (
                        <RefreshCw className="w-3 h-3 mr-1" />
                      )}
                      {t('settings.syncEmployees')}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleSharepointDisconnect}
                      disabled={sharepointDisconnecting}
                    >
                      {sharepointDisconnecting ? <ShieldLoader size="xs" variant="inline" /> : null}
                      {t('settingsIntegration.disconnect')}
                    </Button>
                  </>
                ) : (
                  <Button variant="default" size="sm" onClick={handleSharepointConnect}>
                    {t('settingsIntegration.connect')}
                  </Button>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Email Integration */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Mail className="w-5 h-5 text-(--primary)" />
            <CardTitle>{t('settingsIntegration.title')}</CardTitle>
          </div>
          <CardDescription>{t('settingsIntegration.emailReports')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-col sm:flex-row flex-wrap gap-3 items-center justify-between p-4 rounded-lg bg-(--surface-hover) border border-(--border)">
            <div className="flex items-start gap-3">
              <span className="text-2xl">📧</span>
              <div>
                <p className="text-sm font-medium text-(--text-primary)">
                  {t('settingsIntegration.automatedReports')}
                </p>
                <p className="text-xs text-(--text-muted) mt-0.5">
                  {t('settingsIntegration.automatedReportsDesc')}
                </p>
              </div>
            </div>
            <Switch checked={emailReports} onCheckedChange={setEmailReports} />
          </div>

          {emailReports && (
            <div className="p-4 rounded-lg border border-(--primary)/20 bg-(--primary)/5 space-y-2">
              <p className="text-sm font-medium text-(--text-primary)">
                {t('settingsIntegration.reportSchedule')}
              </p>
              <div className="space-y-1 text-xs text-(--text-muted)">
                <p>• {t('settingsIntegration.weeklySummary')}</p>
                <p>• {t('settingsIntegration.monthlyAnalytics')}</p>
                <p>• {t('settingsIntegration.leaveApprovals')}</p>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Messaging Integrations */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <MessageSquare className="w-5 h-5 text-(--primary)" />
            <CardTitle>{t('settingsIntegration.title')}</CardTitle>
          </div>
          <CardDescription>{t('settingsIntegration.teamCommunication')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          {/* Slack */}
          <div className="flex flex-col sm:flex-row flex-wrap gap-3 items-start justify-between p-4 rounded-lg bg-(--surface-hover) border border-(--border)">
            <div className="flex items-start gap-3 flex-1">
              <div className="w-10 h-10 rounded-lg bg-purple-500/10 flex items-center justify-center">
                <MessageSquare className="w-5 h-5 text-purple-500" />
              </div>
              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <p className="text-sm font-medium text-(--text-primary)">
                    {t('settingsIntegration.slack')}
                  </p>
                  {slackNotifications && (
                    <Badge variant="default" className="text-xs">
                      {t('settingsIntegration.connected')}
                    </Badge>
                  )}
                </div>
                <p className="text-xs text-(--text-muted) mt-1">
                  {t('settingsIntegration.slackDesc')}
                </p>
              </div>
            </div>
            {slackNotifications ? (
              <Button variant="outline" size="sm" onClick={() => setSlackNotifications(false)}>
                {t('settingsIntegration.disconnect')}
              </Button>
            ) : (
              <Button variant="default" size="sm" onClick={() => setSlackNotifications(true)}>
                {t('settingsIntegration.connect')}
              </Button>
            )}
          </div>

          {/* Microsoft Teams — coming soon */}
          <div className="flex flex-wrap gap-3 items-start justify-between p-4 rounded-lg bg-(--surface-hover) border border-(--border) opacity-70">
            <div className="flex items-start gap-3 flex-1">
              <div className="w-10 h-10 rounded-lg bg-indigo-500/10 flex items-center justify-center">
                <MessageSquare className="w-5 h-5 text-indigo-500" />
