      title: t('subscriptionWizard.steps.plan.title'),
      description: t('subscriptionWizard.steps.plan.description'),
      icon: <Crown className="w-5 h-5" />,
      content: (
        <CardSelectionStep
          field="plan"
          label={t('subscriptionWizard.steps.plan.planLabel')}
