    try {
      await createManual({
        organizationId: String(data.organizationId) as Id<'organizations'>,
        plan: String(data.plan) as 'starter' | 'professional' | 'enterprise',
        customPrice: data.customPrice ? parseFloat(String(data.customPrice)) : undefined,
