              .then(() => {
                toast.success(
                  t('tasks.status.moved', { status: t(STATUS_CONFIG[newStatus].labelKey) }),
                  { duration: 2000 },
                );
                setOptimisticStatuses((prev) => {
                  const next = new Map(prev);
                  next.delete(task._id as string);
                  return next;
                });
