                  />
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* Modals */}
      <Dialog open={showCreate} onOpenChange={setShowCreate}>
        <DialogContent
          className="w-[95vw] sm:w-[90vw] md:w-[85vw] max-w-2xl max-h-[95vh] flex flex-col"
          aria-describedby={undefined}
        >
