              </div>
            ) : (
              sortedTasks.map((task, idx) => (
                <div
                  key={task._id}
                  className="flex items-center gap-3 px-4 cursor-pointer hover:bg-(--background-subtle)/50 transition-colors border-b border-(--border)/50 group"
                  style={{ height: ROW_HEIGHT }}
                  onClick={() => onOpen(task)}
                >
                  {statusIcon(task.status)}
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-(--text-primary) truncate group-hover:text-blue-400 transition-colors">
