                    <p className="text-[10px] text-(--text-muted) truncate">
                      {task.assignedToUser?.name ?? '—'}
                    </p>
                  </div>
                  <span
                    className={`w-2 h-2 rounded-full shrink-0 ${PRIORITY_DOT[task.priority]}`}
                  />
