        {/* Timeline area (scrollable) */}
        <div ref={scrollRef} className="flex-1 overflow-x-auto overflow-y-hidden">
          <div
            style={{
              width: Math.max(totalWidth, 600),
              position: 'relative',
              minHeight: HEADER_HEIGHT + sortedTasks.length * ROW_HEIGHT,
