                        style={{
                          left: leftOffset,
                          width: Math.max(barWidth, 20),
                          background: isOverdue
                            ? 'linear-gradient(90deg, #f43f5e, #e11d48)'
                            : task.status === 'completed'
                              ? 'linear-gradient(90deg, #10b981, #059669)'
                              : task.status === 'in_progress'
                                ? 'linear-gradient(90deg, #3b82f6, #2563eb)'
                                : task.status === 'review'
                                  ? 'linear-gradient(90deg, #f59e0b, #d97706)'
                                  : 'linear-gradient(90deg, #6b7280, #4b5563)',
                        }}
                      >
                        {/* Progress fill */}
                        <div
                          className="absolute inset-y-0 left-0 rounded-lg bg-white/20 transition-all duration-500"
                          style={{ width: `${completionPercent}%` }}
                        />
                        {/* Task title on bar */}
                        <div className="absolute inset-0 flex items-center px-2 overflow-hidden">
                          <span className="text-[11px] font-semibold text-white truncate drop-shadow-sm">
                            {task.title}
                          </span>
                        </div>
                      </div>

                      {/* Hover tooltip */}
                      <div className="absolute -top-1 left-1/2 -translate-x-1/2 -translate-y-full opacity-0 group-hover:opacity-100 transition-opacity duration-150 pointer-events-none z-30">
                        <div className="bg-(--card) border border-(--border) rounded-xl shadow-2xl p-3 whitespace-nowrap backdrop-blur-sm">
                          <p className="text-sm font-bold text-(--text-primary)">{task.title}</p>
                          <div className="flex items-center gap-2 mt-1 text-xs text-(--text-muted)">
                            <span>{task.assignedToUser?.name ?? '—'}</span>
                            {task.deadline && (
                              <>
                                <span>·</span>
                                <span className={isOverdue ? 'text-rose-500 font-medium' : ''}>
                                  {formatShort(new Date(task.deadline), locale)}
                                </span>
                              </>
                            )}
                          </div>
                          {task.tags && task.tags.length > 0 && (
                            <div className="flex gap-1 mt-1.5">
                              {task.tags.slice(0, 3).map((tag) => (
                                <span
                                  key={tag}
                                  className="text-[10px] bg-blue-500/10 text-blue-400 px-1.5 py-0.5 rounded"
                                >
                                  #{tag}
                                </span>
                              ))}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                },
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap items-center gap-4 px-4 py-2.5 border-t border-(--border) bg-(--background-subtle)/30">
        {(['pending', 'in_progress', 'review', 'completed', 'cancelled'] as Status[]).map((s) => (
          <div key={s} className="flex items-center gap-1.5">
            <div className={`w-3 h-3 rounded-sm ${STATUS_COLORS[s].bar}`} />
