          </div>
        ))}
        <div className="w-px h-3 bg-(--border)" />
        <div className="flex items-center gap-1.5">
          <div className="w-0.5 h-3 bg-blue-500/60 rounded" />
          <span className="text-[10px] text-(--text-muted)">{t('tasksClient.today', 'Today')}</span>
        </div>
      </div>
    </div>
  );
}

