// ═══════════════════════════════════════════════════════════════
// Checkbox Step
// ═══════════════════════════════════════════════════════════════
interface CheckboxStepProps {
  stepData?: Record<string, string | number | boolean | null | string[]>;
  updateStepData?: (key: string, value: string | number | boolean | null | string[]) => void;
  field: string;
  label: string;
  options: { value: string; label: string; description?: string }[];
  description?: string;
}

export function CheckboxStep({
  stepData,
  updateStepData,
  field,
  label,
  options,
  description,
}: CheckboxStepProps) {
  const context = useWizardContext();
  const data = stepData ?? context.stepData;
  const update = updateStepData ?? context.updateStepData;
  const values = (data[field] as string[] | undefined) || [];

  const toggleValue = (value: string) => {
    const newValues = values.includes(value)
      ? values.filter((v: string) => v !== value)
      : [...values, value];
    update(field, newValues);
  };

  return (
    <div className="space-y-2 md:space-y-3">
      <div>
        <Label className="text-(--text-primary) text-sm md:text-base">{label}</Label>
        {description && (
          <p className="text-[10px] md:text-xs text-(--text-muted) mt-1">{description}</p>
        )}
      </div>

      <div className="space-y-2">
        {options.map((option) => {
          const isChecked = values.includes(option.value);

          return (
            <div
              key={option.value}
              className="flex items-start space-x-2 md:space-x-3 p-2 md:p-3 rounded-lg border border-(--border) bg-(--background) hover:bg-(--background-subtle) transition-colors cursor-pointer"
              onClick={() => toggleValue(option.value)}
            >
              <Checkbox
                checked={isChecked}
                onCheckedChange={() => toggleValue(option.value)}
                id={`${field}-${option.value}`}
                className="shrink-0 mt-0.5"
              />
              <Label htmlFor={`${field}-${option.value}`} className="flex-1 cursor-pointer">
                <p className="font-medium text-sm md:text-base text-(--text-primary)">
                  {option.label}
                </p>
                {option.description && (
                  <p className="text-[10px] md:text-xs text-(--text-muted) mt-0.5 md:mt-1">
                    {option.description}
                  </p>
                )}
              </Label>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// File Upload Step
// ═══════════════════════════════════════════════════════════════

interface FileUploadStepProps {
  stepData?: Record<string, string | number | boolean | null | string[]>;
  updateStepData?: (key: string, value: string | number | boolean | null | string[]) => void;
  field: string;
  label: string;
  description?: string;
  maxFiles?: number;
  maxSizeMB?: number;
}

interface AttachmentData {
  url: string;
  name: string;
  type: string;
  size: number;
}

interface LocalFile {
  id: string;
  name: string;
  type: string;
  size: number;
  preview?: string;
  base64?: string;
}

const FILE_ICONS: Record<string, React.ReactNode> = {
  'application/pdf': <FileText className="w-8 h-8 text-red-400" />,
  'image/': <ImageIcon className="w-8 h-8 text-blue-400" />,
  'video/': <Video className="w-8 h-8 text-purple-400" />,
  'audio/': <Music className="w-8 h-8 text-green-400" />,
};

function getFileIcon(type: string): React.ReactNode {
  for (const [key, icon] of Object.entries(FILE_ICONS)) {
    if (type.startsWith(key)) return icon;
  }
  return <File className="w-8 h-8 text-gray-400" />;
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function FileUploadStep({
  stepData,
  updateStepData,
  field,
  label,
  description,
  maxFiles = 5,
  maxSizeMB = 1,
}: FileUploadStepProps) {
  const context = useWizardContext();
  const data = stepData ?? context.stepData;
  const update = updateStepData ?? context.updateStepData;

  const [localFiles, setLocalFiles] = useState<LocalFile[]>([]);
  const [uploading, setUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const storedJson = (data[field] as string | undefined) || '[]';
  const storedAttachments: AttachmentData[] = JSON.parse(storedJson);

  const handleFileSelect = useCallback(
    async (files: FileList | File[]) => {
      const fileArray = Array.from(files);
      const validFiles = fileArray
        .filter((f) => {
          const sizeMB = f.size / (1024 * 1024);
          if (sizeMB > maxSizeMB) {
            toast.error(`File "${f.name}" exceeds ${maxSizeMB}MB limit`);
            return false;
          }
          return true;
        })
        .slice(0, maxFiles - localFiles.length);

      if (validFiles.length === 0) return;

      const newFiles: LocalFile[] = await Promise.all(
        validFiles.map(async (file) => {
          let preview: string | undefined;
          if (file.type.startsWith('image/')) {
            preview = await new Promise<string>((resolve) => {
              const reader = new FileReader();
              reader.onload = () => resolve(reader.result as string);
              reader.readAsDataURL(file);
            });
          }

          const base64 = await new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result as string);
            reader.readAsDataURL(file);
          });

          return {
            id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            name: file.name,
            type: file.type,
            size: file.size,
            preview,
            base64,
          };
        }),
      );

      setLocalFiles((prev) => [...prev, ...newFiles]);

      // Auto-upload files immediately after selection
      await uploadFiles([...localFiles, ...newFiles]);
    },
    [localFiles.length, maxFiles, maxSizeMB, storedAttachments, update],
  );

  const uploadFiles = async (filesToUpload: LocalFile[]) => {
    if (filesToUpload.length === 0) return;

    setUploading(true);
    try {
      const newAttachments: AttachmentData[] = [];

      for (const file of filesToUpload) {
        if (file.base64) {
          const url = await uploadTaskAttachment(file.base64, file.name);
          newAttachments.push({
            url,
            name: file.name,
            type: file.type,
            size: file.size,
          });
        }
      }

      const allAttachments = [...storedAttachments, ...newAttachments];
      update(field as string, JSON.stringify(allAttachments) as string);
      setLocalFiles([]);

      toast.success(`Uploaded ${newAttachments.length} file(s)`);
    } catch (error) {
      console.error('Upload error:', error);
      toast.error('Failed to upload files');
    } finally {
      setUploading(false);
    }
  };

  const handleRemoveLocal = (id: string) => {
    setLocalFiles((prev) => prev.filter((f) => f.id !== id));
  };

  const handleRemoveUploaded = (url: string) => {
    const filtered = storedAttachments.filter((a) => a.url !== url);
    update(field as string, JSON.stringify(filtered) as string);
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files);
    }
  };

  return (
    <div className="space-y-3 md:space-y-4">
      <div>
        <Label className="text-(--text-primary) text-sm md:text-base">{label}</Label>
        {description && (
          <p className="text-[10px] md:text-xs text-(--text-muted) mt-1">{description}</p>
        )}
      </div>

      {/* Drop zone */}
      <div
        className={cn(
          'border-2 border-dashed rounded-xl p-4 md:p-6 text-center transition-colors cursor-pointer',
          dragActive
            ? 'border-(--primary) bg-(--primary)/5'
            : 'border-(--border) hover:border-(--primary)/50 hover:bg-(--background-subtle)',
        )}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept="*/*"
          className="hidden"
          onChange={(e) => e.target.files && handleFileSelect(e.target.files)}
        />
        <Upload className="w-8 h-8 mx-auto mb-2 text-(--text-muted)" />
        <p className="text-sm text-(--text-secondary)">Drag files here or click to select</p>
        <p className="text-xs text-(--text-muted) mt-1">
          Max {maxFiles} files, up to {maxSizeMB}MB each
        </p>
      </div>

      {/* Local files preview (not yet uploaded) */}
      <AnimatePresence>
        {localFiles.length > 0 && (
          <div className="space-y-2">
            <p className="text-xs font-medium text-(--text-muted)">Uploading...</p>
            <div className="grid grid-cols-2 gap-2">
              {localFiles.map((file) => (
                <motion.div
                  key={file.id}
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  className="relative rounded-lg border border-(--border) overflow-hidden bg-(--background-subtle)"
                >
                  {file.preview ? (
                    <img src={file.preview} alt={file.name} className="w-full h-20 object-cover" />
                  ) : (
                    <div className="h-20 flex items-center justify-center">
                      {getFileIcon(file.type)}
                    </div>
                  )}
                  <div className="p-2">
                    <p className="text-xs font-medium text-(--text-primary) truncate">
                      {file.name}
                    </p>
                    <p className="text-[10px] text-(--text-muted)">{formatSize(file.size)}</p>
                  </div>
                </motion.div>
              ))}
            </div>
            {uploading && (
              <p className="text-xs text-(--text-muted) text-center">Uploading to Cloudinary...</p>
            )}
          </div>
        )}
      </AnimatePresence>

      {/* Already uploaded files */}
      <AnimatePresence>
        {storedAttachments.length > 0 && (
          <div className="space-y-2">
            <p className="text-xs font-medium text-(--text-muted)">Uploaded:</p>
            <div className="grid grid-cols-2 gap-2">
              {storedAttachments.map((attachment) => {
                const isImage = attachment.type.startsWith('image/');

                return (
                  <motion.div
                    key={attachment.url}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.95 }}
                    className="relative rounded-lg border border-(--border) overflow-hidden bg-(--background-subtle)"
                  >
                    {isImage ? (
                      <img
                        src={attachment.url}
                        alt={attachment.name}
                        className="w-full h-20 object-cover"
                      />
                    ) : (
                      <div className="h-20 flex items-center justify-center">
                        {getFileIcon(attachment.type)}
                      </div>
                    )}
                    <div className="p-2">
                      <p className="text-xs font-medium text-(--text-primary) truncate">
                        {attachment.name}
                      </p>
                      <p className="text-[10px] text-(--text-muted)">
                        {formatSize(attachment.size)}
                      </p>
                    </div>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRemoveUploaded(attachment.url);
                      }}
                      className="absolute top-1 right-1 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center text-xs hover:bg-red-600"
                    >
                      ×
                    </button>
                  </motion.div>
                );
              })}
            </div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

/**
 * Multi-step Wizard Component
 * Универсальный компонент для пошаговых форм
 */

'use client';

import React, { useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from '@/lib/cssMotion';
import { cn } from '@/lib/utils';
import { ChevronLeft, ChevronRight, CheckCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';

const WizardContext = React.createContext<{
  stepData: Record<string, string | number | boolean | null | string[]>;
  updateStepData: (key: string, value: string | number | boolean | null | string[]) => void;
} | null>(null);

export function useWizardContext() {
  const context = React.useContext(WizardContext);
  if (!context) {
    throw new Error('useWizardContext must be used within a Wizard');
  }
  return context;
}

interface StepContent {
  stepData: Record<string, string | number | boolean | null | string[]>;
  updateStepData: (key: string, value: unknown) => void;
}

export interface WizardStep {
  id: string;
  title: string;
  description?: string;
  icon?: React.ReactNode;
  content: React.ReactElement;
  validation?: (data: Record<string, string | number | boolean | null | string[]>) => boolean;
}

interface WizardProps {
  steps: WizardStep[];
  onComplete?: (data: Record<string, string | number | boolean | null | string[]>) => void;
  onCancel?: () => void;
  submitLabel?: string;
  cancelLabel?: string;
  showStepper?: boolean;
  className?: string;
  defaultStepData?: Record<string, string | number | boolean | null | string[]>;
}

export function Wizard({
  steps,
  onComplete,
  onCancel,
  submitLabel,
  cancelLabel,
  showStepper = true,
  className,
  defaultStepData = {},
}: WizardProps): React.ReactElement {
  const { t } = useTranslation();
  const [currentStep, setCurrentStep] = useState(0);
  const [stepData, setStepData] =
    useState<Record<string, string | number | boolean | null | string[]>>(defaultStepData);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const prevDefaultRef = React.useRef(defaultStepData);

  React.useEffect(() => {
    const prevJson = JSON.stringify(prevDefaultRef.current);
    const currJson = JSON.stringify(defaultStepData);
    if (prevJson !== currJson) {
      prevDefaultRef.current = defaultStepData;
      setStepData((prev) => ({ ...prev, ...defaultStepData }));
    }
  }, [defaultStepData]);

  const currentStepData = steps[currentStep];

  const canGoNext = useCallback(() => {
    if (!currentStepData?.validation) return true;
    return currentStepData.validation(stepData);
  }, [currentStepData, stepData]);

  const handleNext = () => {
    if (currentStep < steps.length - 1 && canGoNext()) {
      setCurrentStep((prev) => prev + 1);
    } else if (currentStep === steps.length - 1) {
      handleSubmit();
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      await onComplete?.(stepData);
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateStepData = (key: string, value: string | number | boolean | null | string[]) => {
    setStepData((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const progress = ((currentStep + 1) / steps.length) * 100;

  return (
    <div className={cn('flex flex-col', className)}>
      {/* Scrollable Content Area */}
      <div className="flex-1 overflow-y-auto overflow-x-clip px-0 py-4 md:px-6 md:py-5 scrollbar-hide">
        {/* Stepper */}
        {showStepper && (
          <div className="mb-5 md:mb-6">
            {/* Progress Bar */}
            <div className="relative h-1.5 md:h-2 bg-(--background-subtle) rounded-full overflow-hidden mb-4 md:mb-5">
              <motion.div
                className="absolute inset-y-0 left-0 bg-(--primary)"
                initial={{ width: 0 }}
                animate={{ width: `${progress}%` }}
                transition={{ duration: 0.3, ease: 'easeInOut' }}
              />
            </div>

            {/* Steps — each step is an equal-width column. The connector is
                pinned to the circle's vertical centre (top-[14px]/[18px] = half
                the circle height) and drawn *behind* the circle, so it never
                crosses the labels no matter how many steps there are or how many
                lines a title wraps to. */}
            <div className="flex items-start">
              {steps.map((step, index) => {
                const isCompleted = index < currentStep;
                const isCurrent = index === currentStep;

                return (
                  <div key={step.id} className="relative flex flex-col items-center flex-1 min-w-0">
                    {index < steps.length - 1 && (
                      <div className="absolute top-[14px] md:top-[18px] left-1/2 w-full h-0.5 bg-(--border) overflow-hidden">
                        <motion.div
                          className={cn(
                            'h-full transition-colors',
                            isCompleted ? 'bg-blue-500' : 'bg-(--border)',
                          )}
                          initial={{ width: '0%' }}
                          animate={{ width: isCompleted ? '100%' : '0%' }}
                          transition={{ duration: 0.3 }}
                        />
                      </div>
                    )}
                    <motion.div
                      className={cn(
                        'relative z-10 w-7 h-7 md:w-9 md:h-9 rounded-full flex items-center justify-center border-2 transition-colors shrink-0',
                        isCompleted
                          ? 'bg-blue-500 border-blue-500 text-white'
                          : isCurrent
                            ? 'border-blue-500 bg-(--background) text-blue-500'
                            : 'border-(--border) bg-(--background) text-(--muted-foreground)',
                      )}
                      initial={{ scale: 1 }}
                      animate={{ scale: isCurrent ? 1.1 : 1 }}
                      transition={{ duration: 0.2 }}
                    >
                      {isCompleted ? (
                        <CheckCircle className="w-3.5 h-3.5 md:w-4 md:h-4" />
                      ) : (
                        <span className="text-[11px] md:text-xs font-semibold">{index + 1}</span>
                      )}
                    </motion.div>
                    <div className="mt-1.5 md:mt-2 text-center w-full px-0.5 md:px-1">
                      <p
                        className={cn(
                          'text-[10px] md:text-xs font-medium transition-colors leading-tight line-clamp-2',
                          isCurrent
                            ? 'text-(--primary)'
                            : isCompleted
                              ? 'text-(--text-primary)'
                              : 'text-(--muted-foreground)',
                        )}
                      >
                        {step.title}
                      </p>
                      {step.description && (
                        <p className="text-[9px] md:text-[10px] text-(--muted-foreground) mt-0.5 hidden sm:block line-clamp-1">
                          {step.description}
                        </p>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Step Content */}
        <AnimatePresence mode="wait">
          <motion.div
            key={currentStep}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.2, ease: 'easeOut' }}
          >
            <div className="mb-4 md:mb-6">
              <h2 className="text-lg md:text-xl font-bold text-(--text-primary) mb-1.5 md:mb-2">
                {currentStepData?.title}
              </h2>
              {currentStepData?.description && (
                <p className="text-sm md:text-base text-(--text-muted)">
                  {currentStepData?.description}
                </p>
              )}
            </div>

            <WizardContext.Provider value={{ stepData, updateStepData }}>
              <div className="space-y-3 md:space-y-4">{currentStepData?.content}</div>
            </WizardContext.Provider>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Navigation Buttons - Fixed at bottom */}
      <div className="shrink-0 px-4 py-4 md:px-6 md:py-5 border-t border-(--border) bg-(--background) rounded-xl">
        <div className="flex flex-col-reverse sm:flex-row items-stretch sm:items-center justify-between gap-2 sm:gap-3">
          <Button
            variant="outline"
            onClick={handleBack}
            disabled={currentStep === 0 || isSubmitting}
            className="border-(--border) bg-(--background) hover:bg-(--background-subtle) text-(--foreground) w-full sm:w-auto text-sm"
          >
            <ChevronLeft className="w-4 h-4 mr-1" />
            {t('wizard.back', 'Back')}
          </Button>

          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 sm:gap-3 w-full sm:w-auto">
            {onCancel && (
              <Button
                variant="outline"
                onClick={onCancel}
                disabled={isSubmitting}
                className="border-(--border) bg-(--background) hover:bg-(--background-subtle) text-(--foreground) w-full sm:w-auto text-sm"
              >
                {cancelLabel || t('wizard.cancel', 'Cancel')}
              </Button>
            )}

            <Button
              onClick={handleNext}
              disabled={!canGoNext() || isSubmitting}
              className="bg-(--primary) hover:bg-(--primary-hover) text-white gap-2 w-full sm:w-auto text-sm"
            >
              {isSubmitting ? (
                t('wizard.processing', 'Processing...')
              ) : currentStep === steps.length - 1 ? (
                submitLabel || t('wizard.submit', 'Submit')
              ) : (
                <>
                  {t('wizard.next', 'Next')}
                  <ChevronRight className="w-4 h-4" />
                </>
              )}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

